def log(msg=""):
    print(f"[XDZR8 Sabershader] {msg}")


def _xdzr8_build_progress_redraw(context, force=False):
    """Request lightweight UI redraws so progress is visible during synchronous builds."""
    try:
        wm = context.window_manager
        for window in getattr(wm, 'windows', []):
            screen = getattr(window, 'screen', None)
            if screen is None:
                continue
            for area in getattr(screen, 'areas', []):
                if getattr(area, 'type', '') == 'VIEW_3D':
                    area.tag_redraw()
    except Exception:
        pass
    if force and not getattr(bpy.app, 'background', False):
        try:
            if getattr(context, 'window', None) is not None:
                bpy.ops.wm.redraw_timer(type='DRAW_WIN_SWAP', iterations=1)
        except Exception:
            pass


def _xdzr8_build_progress_update(context, percent, stage, force_redraw=False):
    """Publish one progress checkpoint to Blender UI, status bar and scene telemetry."""
    pct = max(0.0, min(100.0, float(percent)))
    stage = str(stage or 'Working')
    try:
        context.scene['XDZR8_BuildRunning'] = True
        context.scene['XDZR8_BuildProgress'] = pct
        context.scene['XDZR8_BuildStage'] = stage
    except Exception:
        pass
    try:
        context.window_manager.progress_update(pct)
    except Exception:
        pass
    try:
        if getattr(context, 'workspace', None) is not None:
            context.workspace.status_text_set(f'XDZR8 Build Shaders • {pct:.0f}% • {stage}')
    except Exception:
        pass
    log(f'Build progress: {pct:.0f}% • {stage}')
    _xdzr8_build_progress_redraw(context, force=bool(force_redraw))


def _xdzr8_build_progress_begin(context):
    try:
        context.window_manager.progress_begin(0.0, 100.0)
    except Exception:
        pass
    try:
        context.scene['XDZR8_BuildRunning'] = True
        context.scene['XDZR8_BuildProgress'] = 0.0
        context.scene['XDZR8_BuildStage'] = 'Starting'
        context.scene['XDZR8_BuildLastResult'] = 'RUNNING'
    except Exception:
        pass
    _xdzr8_build_progress_update(context, 0.0, 'Starting', force_redraw=True)


def _xdzr8_build_progress_finish(context, success=True, stage=None):
    final_stage = str(stage or ('Complete' if success else 'Stopped'))
    try:
        if success:
            context.scene['XDZR8_BuildProgress'] = 100.0
        context.scene['XDZR8_BuildStage'] = final_stage
        context.scene['XDZR8_BuildRunning'] = False
        context.scene['XDZR8_BuildLastResult'] = 'FINISHED' if success else 'CANCELLED'
    except Exception:
        pass
    try:
        if success:
            context.window_manager.progress_update(100.0)
        context.window_manager.progress_end()
    except Exception:
        pass
    try:
        if getattr(context, 'workspace', None) is not None:
            context.workspace.status_text_set(None)
    except Exception:
        pass
    log(f'Build progress: {100 if success else float(context.scene.get("XDZR8_BuildProgress", 0.0)):.0f}% • {final_stage}')
    _xdzr8_build_progress_redraw(context, force=True)


def norm(value):
    return re.sub(r"[\s_.]+", "", str(value).lower())


def safe_name(value):
    return re.sub(r"[^\w\u0080-\uffff.-]+", "_", str(value))


def find_material(name):
    exact = bpy.data.materials.get(name)
    if exact:
        return exact

    backup = bpy.data.materials.get(f"AEF_BACKUP_{name}")
    if backup:
        return backup

    target = norm(name)
    for mat in bpy.data.materials:
        if norm(mat.name) == target:
            return mat

    return None


def users_of(mat):
    if not mat:
        return []
    out = []
    for obj in bpy.context.scene.objects:
        if obj.type != "MESH":
            continue
        if any(slot.material == mat for slot in obj.material_slots):
            out.append(obj)
    return out


def image_nodes(mat):
    if not mat or not mat.use_nodes or not mat.node_tree:
        return []
    return [n for n in mat.node_tree.nodes if n.bl_idname == "ShaderNodeTexImage"]


def images_in_material(mat):
    return [n.image for n in image_nodes(mat) if n.image]


def find_image_by_name_candidates(names):
    for name in names:
        img = bpy.data.images.get(name)
        if img:
            return img
    normalized = {norm(n): n for n in names}
    for img in bpy.data.images:
        if norm(img.name) in normalized:
            return img
    return None


def first_source_image(mat):
    nodes = image_nodes(mat)
    return nodes[0].image if nodes else None


def resolve_base_image(source_mat, category, source_name):
    """Resolve only the base/diffuse image. Returns (image, reason)."""

    # V8.3: si tenemos una textura CONFIRMADA (no adivinada) para este
    # material exacto, esa gana siempre -- da igual si el material trae
    # 0 Image Texture propias (caso Doloris) o si trajera alguna que no
    # fuera la correcta. Solo si el nombre confirmado no existe en el
    # archivo (no debería pasar, pero por si acaso) se avisa y se sigue
    # con el comportamiento anterior en vez de fallar en silencio.
    known_name = KNOWN_FACE_BASE_IMAGE.get(source_name) or KNOWN_MASK_BASE_IMAGE.get(source_name)
    if known_name:
        img = find_image_by_name_candidates((known_name,))
        if img:
            return img, f"confirmed:{known_name}"
        log(
            f"  AVISO: textura confirmada '{known_name}' para "
            f"'{source_name}' no está en bpy.data.images; "
            f"cayendo al comportamiento anterior"
        )

    # V10.5B.1 RECOVERY: after a previous AEF build, Blender can purge the
    # original zero-user MMD material on save/reopen. AEF outputs already store
    # the resolved base image name, so use that as a deterministic recovery
    # source before inspecting the material node tree.
    if source_mat:
        try:
            recovered_name = str(source_mat.get("AEF_V8_BaseImage", "") or "")
        except Exception:
            recovered_name = ""
        if recovered_name:
            img = find_image_by_name_candidates((recovered_name,))
            if img:
                return img, f"recovered:AEF_V8_BaseImage:{recovered_name}"

    imgs = images_in_material(source_mat)
    if imgs:
        # Original MMD materials in the real diagnostic have base first.
        # Explicitly prefer a node named mmd_base_tex.
        for node in image_nodes(source_mat):
            if node.name == "mmd_base_tex" and node.image:
                return node.image, "source:mmd_base_tex"
        return imgs[0], "source:first_image_fallback"

    # Doloris Face: material really has no texture. Use a controlled
    # face-related fallback so the XDZR8 Face group does not remain black.
    if source_name == "Face" and category == "face":
        img = find_image_by_name_candidates(DOLORIS_FACE_FALLBACKS)
        if img:
            return img, "fallback:Doloris Face2/expression texture"

    return None, "none"


def duplicate_group(template_name, suffix):
    source = bpy.data.node_groups.get(template_name)
    if not source:
        log(f"MISSING NODE GROUP: {template_name}")
        return None

    local_name = f"{template_name}__V8_{safe_name(suffix)}"
    old = bpy.data.node_groups.get(local_name)
    if old:
        # Only remove our exact V8 duplicate. Never touch the master.
        bpy.data.node_groups.remove(old)

    local = source.copy()
    local.name = local_name
    return local


def clean_face_master_contamination():
    """V8.4: alguien asignó FC_1.jpg a mano directamente en los nodos
    mmd_base_tex / mmd_base_tex.001 del MASTER 'Face_XDZR8EndfieldShader'
    (probando en el Shader Editor), en vez de en una copia. build_material()
    ya no depende de ese valor -- resolve_base_image() encuentra FC_1.jpg
    por sí mismo (KNOWN_FACE_BASE_IMAGE) y configure_face() lo reasigna
    explícitamente en la copia -- pero dejamos el master sin ese dato
    igualmente, para que quede como plantilla neutra y no arrastre la
    textura de un personaje concreto de cara a futuras inspecciones o
    compilaciones. mmd_toon_tex NO se toca: toon02.bmp ahí es un ramp
    genérico compartido por varios grupos (Body, Eyes5 lo usan también),
    no algo específico de un personaje.
    """
    group = bpy.data.node_groups.get("Face_XDZR8EndfieldShader")
    if not group:
        return []

    cleaned = []
    for node_name in ("mmd_base_tex", "mmd_base_tex.001"):
        node = group.nodes.get(node_name)
        if node and node.bl_idname == "ShaderNodeTexImage" and node.image:
            log(f"LIMPIANDO MASTER: Face_XDZR8EndfieldShader.{node_name} tenía '{node.image.name}' asignado a mano -> None")
            node.image = None
            cleaned.append(node_name)
    return cleaned


def clear_and_make_material(mat_name):
    old = bpy.data.materials.get(mat_name)
    if old:
        bpy.data.materials.remove(old, do_unlink=True)

    mat = bpy.data.materials.new(mat_name)
    mat.use_nodes = True
    nodes = mat.node_tree.nodes
    nodes.clear()
    return mat


# ---------------------------------------------------------------------
# V8.12/V8.13 — ver changelog al principio del archivo para el
# diagnóstico completo (verificado con bpy 5.1.1 real, no supuesto).
# ---------------------------------------------------------------------

def _relink(links, from_socket, to_socket):
    for l in list(to_socket.links):
        links.remove(l)
    links.new(from_socket, to_socket)


def fix_face_master_emission_routing():
    """V8.13 — CORRIGE EL FIX DE V8.12 (que dejaba la cara negra).

    V8.12 diagnosticó bien el mecanismo (Group Output colgaba de Mix
    Shader.001, cuyo Fac = mmd_base_tex.Alpha sale SIEMPRE 1.0 -> siempre
    Emission, nunca la otra rama, que además estaba vacía) pero la
    "solución" -- sustituir Emission por un Principled BSDF real -- fue un
    error: esta escena tiene el World en negro puro (sin luz ambiente) y
    solo 3 luces de área dramáticas tipo teatro (dos fuertes a los lados,
    una débil de relleno). Un shader realmente reactivo a la luz se queda
    a oscuras en las zonas de cara que esas luces no golpean de lleno --
    de ahí que se pusiera negra. Emission es inmune a la intensidad real
    de la luz por diseño (por eso los tutoriales de toon-shading en
    Blender lo usan como etapa final); solo la cadena interna Diffuse
    BSDF -> Shader to RGB -> ColorRamp usa la DIRECCIÓN de la luz para
    decidir qué tono mostrar, que es el efecto que sí se quiere.

    Este fix deja el Mix (banding tonal, intacto) -> Emission.Color como
    ya estaba, y conecta Emission DIRECTAMENTE a Group Output -- sin pasar
    por el Mix Shader.001 (que era un no-op matemático: Fac=1 constante +
    rama vacía = 100% Emission de todas formas, así que quitarlo de en
    medio no cambia el resultado, solo limpia un cableado engañoso). Si
    encuentra el Principled BSDF que añadió V8.12, lo quita y reconecta.
    Esto SÍ recupera el aspecto original (el que se quería cambiar al
    principio de esta conversación) -- ver el mensaje de después del
    changelog para next steps sobre el tono/brillo en sí.

    Se aplica al MASTER y a cualquier copia por-material de Face que ya
    exista (Face, Face2, 表情, 表情2, 表情2.001, 面, 口内, 口内.001),
    exactamente igual que V8.12. Idempotente: si un grupo ya está en el
    estado correcto (Emission -> Group Output, sin Principled), no hace
    nada.
    """
    template_name = GROUPS["face"]
    fixed, skipped = [], []

    master = bpy.data.node_groups.get(template_name)
    if master:
        ok, why = _apply_face_output_fix(master)
        (fixed if ok else skipped).append((template_name, why))
    else:
        log(f"V8.13 face-fix: no se encontró el master {template_name}")

    prefix = f"{template_name}__V8_"
    for g in list(bpy.data.node_groups):
        if g is master or not g.name.startswith(prefix):
            continue
        ok, why = _apply_face_output_fix(g)
        (fixed if ok else skipped).append((g.name, why))

    for name, why in fixed:
        log(f"V8.13 face-fix: {name}: {why}")
    for name, why in skipped:
        log(f"V8.13 face-fix: {name} sin cambios ({why})")

    return fixed


def _apply_face_output_fix(g):
    """Asegura que UN node group (master o copia) termine en Emission
    conectado DIRECTAMENTE a Group Output. Si encuentra el Principled BSDF
    que añadía V8.12, lo quita. Devuelve (cambiado: bool, motivo: str)."""
    nodes, links = g.nodes, g.links

    emission = nodes.get("Emission")
    group_output = nodes.get("Group Output")
    if not (emission and group_output):
        return False, "faltan nodos esperados (Emission / Group Output)"

    shader_out = next((s for s in group_output.inputs if s.type == 'SHADER'), None)
    if not shader_out:
        return False, "Group Output no expone una salida tipo SHADER"

    stray_principled = nodes.get("Principled BSDF")
    if stray_principled:
        nodes.remove(stray_principled)

    # "Correcto" significa: la salida cuelga de Emission, O cuelga del
    # Add Shader del rim highlight de V8.17 (que a su vez mete Emission
    # como una de sus dos ramas) -- si no reconociéramos también este
    # segundo caso, correr esta función después de añadir el rim en una
    # build anterior lo desconectaría de Group Output sin querer.
    rim_add = nodes.get("AEF Rim Add")
    feeder = shader_out.links[0].from_node if shader_out.is_linked else None
    already_ok = (
        not stray_principled
        and feeder is not None
        and (feeder == emission or feeder == rim_add)
    )
    if already_ok:
        return False, "ya está correcto (Emission -> Group Output, directo o vía el rim de V8.17)"

    _relink(links, emission.outputs["Emission"], shader_out)

    mix_shader = nodes.get("Mix Shader.001")
    if mix_shader:
        mix_shader.label = "SIN USAR (Emission va directo a Group Output)"
    emission.label = ""

    return True, ("Principled BSDF (V8.12) quitado, Emission reconectado directo" if stray_principled
                  else "Emission conectado directo a Group Output (bypass del Mix Shader roto)")


# ---------------------------------------------------------------------
# V8.17 — RIM LIGHT TEATRAL SOBRE EMISSION (no lo reemplaza)
#   Petición: sustituir Emission por otro nodo que acerque más el look a
#   la serie. Un reemplazo 1:1 por OTRO shader real (Toon BSDF, Diffuse,
#   Principled...) no es seguro aquí: ese nodo multiplicaría OTRA VEZ el
#   color final ya calculado (Mix) por la luz real que llegue a ese punto,
#   y esta escena solo tiene 2 luces de área fuertes a los lados + una
#   débil de relleno y CERO luz ambiente (World negro, visto en V8.13) --
#   eso reabriría el problema de cara negra que se acaba de arreglar, y
#   con Toon BSDF probablemente peor: su componente difuso es un escalón
#   duro (0 o 1 según N·L), no una caída suave como Principled, así que
#   las zonas fuera del cono de luz se irían a negro puro, no a un gris
#   oscuro. Emission y Background son los únicos nodos de Blender que
#   muestran un color sin condicionarlo a la luz real -- cambiar uno por
#   el otro no produciría ninguna diferencia visual.
#
#   Lo que sí puede acercar el resultado a la serie sin ese riesgo: dejar
#   Emission como piso garantizado (nunca se va a negro) y SUMARLE (Add
#   Shader, no Mix -- solo puede sumar brillo, nunca restarlo) un Glossy
#   BSDF que sí reacciona a la posición/color de las 2 luces de escena.
#   Ahora mismo la cara no muestra ningún rim light aunque las luces estén
#   ahí (Emission es ciego a la posición de la luz); con esto, el lado
#   cálido y el lado frío deberían empezar a insinuarse en la piel como
#   brillo, que es justo el efecto de iluminación de teatro que describe
#   el informe y que la serie usa para las caras en escenas dramáticas.
#   Roughness 0.35 (sheen suave, no plástico) y Color casi blanco (0.8)
#   para que el tono del brillo lo den las luces de escena, no el nodo.
#
#   No se puede renderizar para comprobarlo en este entorno (sin GPU) --
#   esto es una propuesta razonada, no un resultado verificado a ojo.
#   Idempotente: si ya existe "AEF Rim Glossy" no hace nada. Se aplica al
#   master y a las copias ya existentes, igual que fix_face_master_
#   emission_routing().
# ---------------------------------------------------------------------

def add_face_rim_highlight():
    template_name = GROUPS["face"]
    changed, skipped = [], []

    master = bpy.data.node_groups.get(template_name)
    if master:
        ok, why = _apply_rim_highlight(master)
        (changed if ok else skipped).append((template_name, why))
    else:
        log(f"V8.17 rim: no se encontró el master {template_name}")

    prefix = f"{template_name}__V8_"
    for g in list(bpy.data.node_groups):
        if g is master or not g.name.startswith(prefix):
            continue
        ok, why = _apply_rim_highlight(g)
        (changed if ok else skipped).append((g.name, why))

    for name, why in changed:
        log(f"V8.17 rim: {name}: {why}")
    for name, why in skipped:
        log(f"V8.17 rim: {name} sin cambios ({why})")

    return changed


def _apply_rim_highlight(g):
    nodes, links = g.nodes, g.links

    if nodes.get("AEF Rim Glossy"):
        return False, "ya tiene el rim highlight"

    emission = nodes.get("Emission")
    group_output = nodes.get("Group Output")
    if not (emission and group_output):
        return False, "faltan nodos esperados (Emission / Group Output)"

    shader_out = next((s for s in group_output.inputs if s.type == 'SHADER'), None)
    if not shader_out or not shader_out.is_linked or shader_out.links[0].from_node != emission:
        return False, "Group Output no cuelga de Emission (correr fix_face_master_emission_routing primero)"

    glossy = nodes.new("ShaderNodeBsdfGlossy")
    glossy.name = "AEF Rim Glossy"
    glossy.label = "Rim (V8.17, encima de Emission)"
    glossy.location = (emission.location.x, emission.location.y - 200)
    glossy.inputs["Color"].default_value = (0.8, 0.8, 0.8, 1.0)
    glossy.inputs["Roughness"].default_value = 0.35

    add_shader = nodes.new("ShaderNodeAddShader")
    add_shader.name = "AEF Rim Add"
    add_shader.location = (emission.location.x + 180, emission.location.y - 100)

    links.new(emission.outputs["Emission"], add_shader.inputs[0])
    links.new(glossy.outputs["BSDF"], add_shader.inputs[1])
    _relink(links, add_shader.outputs["Shader"], shader_out)

    return True, "Glossy (rim) sumado sobre Emission via Add Shader"


def protect_master_templates():
    """V8.12: los 7 masters de GROUPS solo se usan vía .copy() en
    duplicate_group() -- ninguna material los referencia directamente.
    Comprobado con bpy real que 6 de los 7 tenían 0 usuarios reales y
    desaparecían SILENCIOSAMENTE al guardar+reabrir el archivo. Activar
    Fake User evita que Blender los descarte; no cambia nada visual.
    """
    protected = []
    for template_name in GROUPS.values():
        g = bpy.data.node_groups.get(template_name)
        if g and not g.use_fake_user:
            g.use_fake_user = True
            protected.append(template_name)
    if protected:
        log(f"V8.12 fake-user: protegidos {len(protected)} masters -> {protected}")
    return protected


def connect_group_output(mat, group_node):
    nodes = mat.node_tree.nodes
    links = mat.node_tree.links
    output = nodes.new("ShaderNodeOutputMaterial")
    output.name = "Material Output"
    output.location = (420, 0)

    if group_node.outputs.get("Shader"):
        links.new(group_node.outputs["Shader"], output.inputs["Surface"])
    elif group_node.outputs.get("BSDF"):
        links.new(group_node.outputs["BSDF"], output.inputs["Surface"])
    else:
        raise RuntimeError(f"XDZR8 group '{group_node.name}' has no Shader/BSDF output")

    # One and only one Material Output in V8.
    for node in nodes:
        if node.bl_idname == "ShaderNodeOutputMaterial":
            node.is_active_output = (node is output)

    return output



def connect_group_uv(mat, group_node):
    """Connect the mesh UVs to the XDZR8 group Vector input.

    This is critical for Cloth/Face/Eyes/Body groups whose internal
    mmd_base_tex nodes explicitly read Group Input.Vector. Without this
    connection Blender feeds the unconnected vector default (0,0,0), so
    the texture is sampled at a single point instead of the mesh UVs.
    """
    if not mat or not mat.node_tree or not group_node:
        return False

    vector_in = group_node.inputs.get("Vector")
    if not vector_in:
        return False

    nodes = mat.node_tree.nodes
    links = mat.node_tree.links

    texcoord = nodes.get("AEF_V8_UV")
    if not texcoord:
        texcoord = nodes.new("ShaderNodeTexCoord")
        texcoord.name = "AEF_V8_UV"
        texcoord.label = "AEF V8 UV (UVMap)"
        texcoord.location = (-360, -220)

    for link in list(vector_in.links):
        links.remove(link)

    links.new(texcoord.outputs["UV"], vector_in)
    return True


def remove_external_face_uv(mat):
    """Elimina el Texture Coordinate/AEF_V8_UV externo de Face."""
    if not mat or not mat.node_tree:
        return False
    nodes = mat.node_tree.nodes
    links = mat.node_tree.links
    changed = False
    group_node = nodes.get("XDZR8_V8")
    if group_node:
        vector_in = group_node.inputs.get("Vector")
        if vector_in:
            for link in list(vector_in.links):
                links.remove(link)
                changed = True
    texcoord = nodes.get("AEF_V8_UV")
    if texcoord:
        nodes.remove(texcoord)
        changed = True
    return changed


def connect_face_mmdtexuv(mat, group_node):
    """V8.11 — reproduce the MMD Face UV routing:

        MMDTexUV.Base UV -> first Vector input of Face_XDZR8
        MMDTexUV.Toon UV -> second Vector input of Face_XDZR8 (when present)

    The exact Face master uses two UV streams. Do not feed the Face group from
    Blender's raw Texture Coordinate node. We resolve the vector inputs by
    interface order first, then by common names for robustness across copies.
    """
    if not mat or not mat.node_tree or not group_node:
        return False

    mmd_group = bpy.data.node_groups.get("MMDTexUV")
    if not mmd_group:
        target = norm("MMDTexUV")
        for ng in bpy.data.node_groups:
            if norm(ng.name) == target:
                mmd_group = ng
                break
    if not mmd_group:
        log("  [face-mmdtexuv] MISSING node group 'MMDTexUV'")
        return False

    nodes = mat.node_tree.nodes
    links = mat.node_tree.links
    node = nodes.get("AEF_MMDTexUV")
    if not node:
        node = nodes.new("ShaderNodeGroup")
        node.name = "AEF_MMDTexUV"
        node.label = "MMDTexUV • Face Base/Toon UV"
        node.location = (-360, -80)
    node.node_tree = mmd_group

    base_out = node.outputs.get("Base UV")
    toon_out = node.outputs.get("Toon UV")

    vector_inputs = [sock for sock in group_node.inputs if sock.type == 'VECTOR']
    if not vector_inputs:
        log("  [face-mmdtexuv] Face group no tiene inputs VECTOR")
        return False

    # Prefer semantic names when they exist, otherwise preserve interface order:
    # first vector = Base UV, second vector = Toon UV.
    first = group_node.inputs.get("Vector")
    if not first or first.type != 'VECTOR':
        first = vector_inputs[0]

    second = None
    for candidate_name in ("Toon UV", "Vector.001", "Vector 2", "ToonVector", "Toon"):
        candidate = group_node.inputs.get(candidate_name)
        if candidate and candidate.type == 'VECTOR' and candidate != first:
            second = candidate
            break
    if second is None and len(vector_inputs) >= 2:
        second = vector_inputs[1]

    changed = False

    if base_out:
        for link in list(first.links):
            links.remove(link)
        links.new(base_out, first)
        log(f"  [face-mmdtexuv] {node.name}.Base UV -> {group_node.name}.{first.name}")
        changed = True
    else:
        log("  [face-mmdtexuv] MMDTexUV no tiene salida 'Base UV'")

    if toon_out and second:
        for link in list(second.links):
            links.remove(link)
        links.new(toon_out, second)
        log(f"  [face-mmdtexuv] {node.name}.Toon UV -> {group_node.name}.{second.name}")
        changed = True
    elif toon_out and not second:
        log("  [face-mmdtexuv] MMDTexUV tiene 'Toon UV', pero Face no expone un segundo input VECTOR")
    else:
        log("  [face-mmdtexuv] MMDTexUV no tiene salida 'Toon UV' (se omite esa ruta)")

    return changed


def connect_face_secondary_uv(group):
    """Face XDZR8 has mmd_base_tex.001 with no Vector link in the master.
    It participates in the face logic, so make it sample the same UV as the
    main mmd_base_tex instead of sampling its default (0,0,0)."""
    if not group:
        return False
    base1 = group.nodes.get("mmd_base_tex")
    base2 = group.nodes.get("mmd_base_tex.001")
    gin = group.nodes.get("Group Input")
    if not base1 or not base2 or not gin:
        return False
    src = gin.outputs.get("Vector")
    dst = base2.inputs.get("Vector")
    if not src or not dst:
        return False
    for link in list(dst.links):
        group.links.remove(link)
    group.links.new(src, dst)
    return True

def set_group_image(group, node_name, image):
    if not image:
        return False
    node = group.nodes.get(node_name)
    if not node or node.bl_idname != "ShaderNodeTexImage":
        return False
    node.image = image
    return True


def disconnect_input(node, socket_name):
    socket = node.inputs.get(socket_name)
    if not socket:
        return False
    for link in list(socket.links):
        node.id_data.links.remove(link)
    return True


def disconnect_outputs(node_tree, node):
    for link in list(node_tree.links):
        if link.from_node == node:
            node_tree.links.remove(link)


def force_principled_value(group, socket_name, value):
    pb = group.nodes.get("Principled BSDF")
    if not pb:
        return False
    sock = pb.inputs.get(socket_name)
    if not sock:
        return False
    disconnect_input(pb, socket_name)
    sock.default_value = value
    return True


def neutralize_cloth_aux(group):
    """Remove Wulfa/Rossi-specific auxiliary maps from Cloth without touching
    the Base Color branch. Replace them with stable scalar settings."""
    if not group:
        return

    for node_name, role in CLOTH_AUX_NODES.items():
        node = group.nodes.get(node_name)
        if node:
            disconnect_outputs(group, node)
            log(f"  Cloth aux neutralized: {node_name} ({role})")

    force_principled_value(group, "Roughness", 0.48)
    force_principled_value(group, "Specular IOR Level", 0.5)
    force_principled_value(group, "Metallic", 0.0)

    pb = group.nodes.get("Principled BSDF")
    if pb and pb.inputs.get("Normal"):
        disconnect_input(pb, "Normal")


def neutralize_hair_aux(group):
    """Remove Rossi/Wulfa HN/P/ST/RS and keep a clean Hair base-color path.
    V8.1 deliberately does not invent replacement normal/P/ST/RS maps."""
    if not group:
        return

    for node_name, role in HAIR_AUX_NODES.items():
        node = group.nodes.get(node_name)
        if node:
            disconnect_outputs(group, node)
            log(f"  Hair aux neutralized: {node_name} ({role})")

    force_principled_value(group, "Roughness", 0.43)
    force_principled_value(group, "Specular IOR Level", 0.5)
    force_principled_value(group, "Metallic", 0.0)

    pb = group.nodes.get("Principled BSDF")
    if pb and pb.inputs.get("Normal"):
        disconnect_input(pb, "Normal")


def configure_alpha(mat, group, category):
    """Use the source base texture alpha for transparent categories."""
    if category not in TRANSPARENT_CATEGORIES:
        return

    mat.surface_render_method = 'DITHERED'

    pb = group.nodes.get("Principled BSDF")
    base = group.nodes.get("mmd_base_tex")
    if pb and base and base.image and pb.inputs.get("Alpha"):
        # Alpha is safe here because the source diagnostic confirms the
        # relevant textures are RGBA and these materials are rendered as
        # DITHERED/HASHED in the originals.
        disconnect_input(pb, "Alpha")
        group.links.new(base.outputs["Alpha"], pb.inputs["Alpha"])
        log(f"  Alpha enabled from mmd_base_tex for {category}")
    else:
        log(f"  Alpha could not be connected for {category}")


# =====================================================================
# V8.2 — TRANSPARENCIA REAL DE 裙透 / Clothes4
#
# Diagnóstico (AEF_XDZR8_CLOTH4_TRANSPARENCY_DIAGNOSTIC.txt) + verificación
# propia contra Escenaepica.blend:
#
#   - Operaciones exactas de MMDShaderDev: Math.003/.004/.005 = MULTIPLY
#     encadenados -> alpha_final = Alpha(PMX) x Base_Alpha x Toon_Alpha x
#     Sphere_Alpha (Math.001/Math.002 con Double Sided=1.0 no cambian esto).
#   - Htn_tou.jpg (Clothes4) y YF_Tou.png (裙透) se abrieron con PIL:
#     AMBOS son RGB puro, sin canal alfa. Blender los rellena con alfa=255
#     (opaco) al leerlos. O sea: la conexión mmd_base_tex.Alpha -> Alpha
#     que hacía configure_alpha() (V8.1) no produce transparencia real —
#     Base_Alpha es 1.0 en los dos casos, no hay ninguna máscara que usar.
#   - La transparencia real está horneada como un único valor por-material
#     en el input 'Alpha' de mmd_shader: Clothes4=0.7, 裙透=0.5, mientras
#     que Clothes/Clothes2/Clothes3/丝袜/面具 = 1.0 (opacos, no necesitan
#     nada especial).
#
# Por eso V8.2 deja de intentar "adivinar" por nombre de categoría qué es
# transparente (V8.1 ni siquiera cubría Clothes4, porque su categoría
# colapsada es "cloth", la misma que Clothes/Clothes2/Clothes3 que SÍ son
# opacas) y en su lugar lee el valor real del material MMD de origen.
#
# 'mask' se deja fuera a propósito: sigue con el camino viejo
# (configure_alpha, texture alpha) sin tocar, tal como se pidió.
# =====================================================================

def get_pmx_alpha_factor(source_mat):
    """
    Lee el factor de opacidad horneado en el PMX original (el input
    'Alpha' del grupo mmd_shader del material MMD de origen), NO el
    canal alfa de ninguna textura. Devuelve 1.0 (opaco) si no se
    encuentra nada, para que el llamador pueda ignorarlo con
    seguridad.
    """
    if not source_mat:
        return 1.0

    # V10.5B.1 RECOVERY: AEF outputs store the PMX factor only when it was
    # non-opaque. This lets a recovery copy preserve Clothes4/裙透 behavior
    # even if the original MMD material datablock was purged by Blender.
    try:
        if source_mat.get("AEF_V8_PMXAlphaFactor") is not None:
            return float(source_mat.get("AEF_V8_PMXAlphaFactor"))
    except Exception:
        pass

    if not source_mat.node_tree:
        return 1.0
    shader = source_mat.node_tree.nodes.get("mmd_shader")
    if not shader:
        return 1.0
    sock = shader.inputs.get("Alpha")
    if not sock:
        return 1.0
    try:
        return float(sock.default_value)
    except Exception:
        return 1.0


# V8.11 — MASK/面具 YA NO USA TRANSPARENCIA REAL
#   Investigado con bpy real (offset test + visible_shadow test): el
#   hueco de encaje NO se ve por culpa de sombra/oclusión (desactivar
#   visible_shadow en la malla de Mask, a su distancia original, no
#   cambia nada). Es un problema de proximidad/precisión de ray-tracing:
#   Mask flota a solo 3-7mm de Face (confirmado midiendo vértices), y
#   hace falta ~4cm de separación real para que la transparencia revele
#   la piel de detrás con fiabilidad -- demasiado para que la máscara
#   siga pareciendo puesta sobre la cara.
#   Fix: en vez de depender de la geometría de detrás, se mezcla el
#   color directamente DENTRO del propio shader de Mask: donde el Alpha
#   de mmd_base_tex es alto (tela sólida del encaje) sale el color
#   normal de Cloth1; donde es bajo (hueco) se mezcla hacia un tono de
#   piel constante. Ya no hace falta transparencia real -> Alpha del
#   Principled BSDF se deja fijo en 1.0 (opaco), así que esto funciona
#   a cualquier distancia entre las dos mallas.
#   MASK_SKIN_COLOR sale de muestrear literalmente FC_1.jpg (Doloris) y
#   face.png (Oblivionis) en zonas de piel ya confirmadas (sección V8.3/
#   V8.4): (0.9961, 0.9294, 0.8902) en los dos, prácticamente idéntico.
MASK_SKIN_COLOR = {
    "Doloris": (0.9961, 0.9294, 0.8902, 1.0),
    "Oblivionis": (0.9961, 0.9294, 0.8902, 1.0),
}


def configure_mask_texture_alpha(mat, group, base_image):
    """V8.11: usa el canal Alpha real de Htn_MJ.png / MianJu_透.png."""
    if not group or not base_image:
        return False
    base_tex = group.nodes.get("mmd_base_tex")
    pb = group.nodes.get("Principled BSDF")
    if not base_tex or not pb:
        return False
    base_tex.image = base_image
    alpha_in = pb.inputs.get("Alpha")
    if not alpha_in:
        return False
    disconnect_input(pb, "Alpha")
    group.links.new(base_tex.outputs["Alpha"], alpha_in)
    try:
        mat.surface_render_method = 'DITHERED'
    except Exception:
        pass
    mat["AEF_V8_MaskTextureAlpha"] = base_image.name
    return True


def reinforce_face_direct_texture(group, base_image):
    """V8.11: garantiza que la textura facial confirmada llegue al Base Color final.

    El grupo Face XDZR8 sigue siendo el shader usado; solo se evita que una
    rama auxiliar negra/heredada del master vuelva a anular la textura real.
    """
    if not group or not base_image:
        return False
    tex = group.nodes.get("mmd_base_tex")
    pb = group.nodes.get("Principled BSDF")
    if not tex or not pb:
        return False
    tex.image = base_image
    base = pb.inputs.get("Base Color")
    color = tex.outputs.get("Color")
    if not base or not color:
        return False
    for link in list(base.links):
        group.links.remove(link)
    group.links.new(color, base)
    return True


def configure_alpha_from_pmx_factor(mat, group, source_mat, category):
    """
    Fix V8.2. Sustituye/complementa a configure_alpha() para todo lo
    que no sea 'mask'. En vez de asumir qué categorías son
    transparentes, comprueba el valor real por-material y solo actúa
    si de verdad hace falta (factor < 1.0). Así Clothes4 queda
    cubierto automáticamente sin tener que enumerarlo a mano, y
    Clothes/Clothes2/Clothes3/丝袜 no se tocan porque su factor real es
    1.0.
    """
    if category == "mask":
        return

    factor = get_pmx_alpha_factor(source_mat)

    if factor >= 0.995:
        return

    pb = group.nodes.get("Principled BSDF")
    if not pb or not pb.inputs.get("Alpha"):
        log(f"  Alpha PMX no se pudo aplicar para {source_mat.name} ({category}): sin socket Alpha")
        return

    disconnect_input(pb, "Alpha")
    pb.inputs["Alpha"].default_value = factor

    # V10.6C.1 Cloth Final Polish: the Series Match transparent shader already
    # performs the PMX/luma opacity mix explicitly. DITHERED adds visible grain
    # to fine lace in viewport/render, so prefer smooth BLENDED transparency.
    # Fallback keeps compatibility if Blender/API rejects the enum.
    smooth_transparency = bool(group.get("AEF_V10_6C1_ClothFinalPolish", False)) and \
        str(group.get("AEF_V10_6B_Family", "")) == "transparent"
    try:
        mat.surface_render_method = 'BLENDED' if smooth_transparency else 'DITHERED'
    except Exception:
        try:
            mat.surface_render_method = 'DITHERED'
        except Exception:
            pass

    mat["AEF_V8_PMXAlphaFactor"] = factor
    mat["AEF_V10_6C1_SmoothTransparency"] = bool(smooth_transparency)
    log(f"  Alpha PMX aplicado: {source_mat.name} -> {factor:.3f} ({category}) render={'BLENDED' if smooth_transparency else 'DITHERED'}")


def configure_face(group, base_image):
    """V8.11 — Configure the Face XDZR8 group.

    The Face group uses three Image Texture nodes in this order:
        1) base face texture
        2) toon texture
        3) second face texture

    Only the 1st and 3rd Image Texture nodes receive ``base_image``.
    The middle/toon texture is deliberately preserved.

    This fixes Oblivionis ``AEF_V8_Oblivionis_表情2`` by resolving its
    confirmed base image to ``face.png`` instead of ``BQ_2.png``.
    """
    if not group or not base_image:
        return False

    changed = False

    # Explicit names used by the current inspected XDZR8 master.
    for node_name in ("mmd_base_tex", "mmd_base_tex.002"):
        node = group.nodes.get(node_name)
        if node and node.bl_idname == "ShaderNodeTexImage":
            if node.image != base_image:
                node.image = base_image
                changed = True

    # Robust fallback/verification by Image Texture order: first + third.
    image_tex_nodes = [n for n in group.nodes if n.bl_idname == "ShaderNodeTexImage"]

    if len(image_tex_nodes) >= 1 and image_tex_nodes[0].image != base_image:
        image_tex_nodes[0].image = base_image
        changed = True

    if len(image_tex_nodes) >= 3 and image_tex_nodes[2].image != base_image:
        image_tex_nodes[2].image = base_image
        changed = True

    return changed


def audit_face_image_slots(group, base_image, label="Face"):
    if not group or not base_image:
        return
    tex_nodes = [n for n in group.nodes if n.bl_idname == "ShaderNodeTexImage"]
    slots = []
    for i, node in enumerate(tex_nodes, start=1):
        slots.append(f"#{i}:{node.name}={node.image.name if node.image else 'NONE'}")
    log(f"  [face-image-slots] {label}: " + " | ".join(slots))


def configure_simple_base(group, base_image):
    node = group.nodes.get("mmd_base_tex")
    if node and base_image:
        node.image = base_image


def template_for_category(category):
    if category in {"face", "mouth", "expression", "expression2"}:
        return GROUPS["face"]
    if category == "eyes":
        return GROUPS["eyes"]
    if category == "eyes3":
        return GROUPS["eyes3"]
    if category == "eyes5":
        return GROUPS["eyes5"]
    if category == "hair":
        return GROUPS["hair"]
    if category == "body":
        return GROUPS["body"]
    if category in {
        "cloth", "cloth1", "cloth2", "cloth3", "cloth4",
        "stockings", "transparent_cloth", "mask", "accessory", "skirt",
        "tie", "glove", "bow", "boots",
    }:
        return GROUPS["cloth"]
    return None



