V105B_NODE_PREFIX = "AEF V10.6C.1 • Cloth • "

V105A_NODE_PREFIX = V105B_NODE_PREFIX  # compatibilidad nominal


def _aef105a_normalize3(v):
    x, y, z = (float(v[0]), float(v[1]), float(v[2]))
    m = max((x*x + y*y + z*z) ** 0.5, 1e-8)
    return (x/m, y/m, z/m)


def _aef105a_profile():
    settings = getattr(bpy.context.scene, "aef_sabershader_v8", None)
    p = getattr(settings, "shot_profile", "AVE") if settings else "AVE"
    return p if p in V105B_CLOTH_STYLE else "AVE"


def _aef105a_remove_nodes(group):
    if not group:
        return
    prefixes = (
        V105A_NODE_PREFIX,
        "AEF V10.5A • Cloth • ",
        "AEF V10.5B • Cloth • ",
        "AEF V10.6A • Cloth • ",
        "AEF V10.6B.1 • Cloth • ",
        "AEF V10.6C • Cloth • ",
        "AEF V10.6C.1 • Cloth • ",
    )
    for node in list(group.nodes):
        if any(node.name.startswith(p) for p in prefixes):
            group.nodes.remove(node)


def _aef105a_color_source(group):
    pb = _aef15_get_principled(group)
    if pb:
        base = pb.inputs.get("Base Color")
        if base:
            if base.is_linked:
                lk = base.links[0]
                return lk.from_socket, None, f"Principled.Base Color <- {lk.from_node.name}", lk.from_node
            try:
                return None, tuple(base.default_value), "Principled.Base Color default", None
            except Exception:
                pass
    em = _aef15_find_existing_emission(group)
    if em:
        col = em.inputs.get("Color")
        if col:
            if col.is_linked:
                lk = col.links[0]
                return lk.from_socket, None, f"Emission.Color <- {lk.from_node.name}", lk.from_node
            try:
                return None, tuple(col.default_value), "Emission.Color default", None
            except Exception:
                pass
    tex = group.nodes.get("mmd_base_tex")
    if tex and tex.bl_idname == "ShaderNodeTexImage" and tex.image and tex.outputs.get("Color"):
        return tex.outputs["Color"], None, f"fallback:{tex.name}.Color", tex
    return None, (1.0, 1.0, 1.0, 1.0), "fallback:white", None


def _aef105a_config_band_ramp(node, style):
    cr = node.color_ramp
    while len(cr.elements) > 1:
        cr.elements.remove(cr.elements[-1])
    s = float(style["shadow_mul"]); m = float(style["mid_mul"]); l = float(style["light_mul"])
    e0 = cr.elements[0]; e0.position = 0.0; e0.color = (s, s, s, 1.0)
    e1 = cr.elements.new(float(style["mid_pos"])); e1.color = (m, m, m, 1.0)
    e2 = cr.elements.new(float(style["light_pos"])); e2.color = (l, l, l, 1.0)
    cr.interpolation = 'CONSTANT'


def _aef105b_material_family(source_name, category, alpha_factor=1.0):
    name = (source_name or "").lower()
    try:
        alpha_factor = float(alpha_factor)
    except Exception:
        alpha_factor = 1.0
    if category == "stockings":
        return "stockings"
    if category == "transparent_cloth" or alpha_factor < 0.995:
        return "transparent"
    if category == "accessory":
        return "ornament"
    if category in {"boots", "glove"}:
        return "hard"
    if category in {"tie", "bow"}:
        return "accent"
    corset_tokens = ("corset", "bodice", "bustier", "胴", "コルセット", "身頃", "ビスチェ")
    if any(tok in name for tok in corset_tokens):
        return "corset"
    if "clothes2" in name or name.endswith("_2"):
        return "corset"
    return "main"


def _aef105b_resolve_style(profile, family):
    data = V105B_CLOTH_STYLE.get(profile, V105B_CLOTH_STYLE["AVE"])
    style = dict(data["base"])
    style.update(data.get("families", {}).get(family, {}))
    return style


def _aef105a_apply_designed_cloth(group, category, profile="AVE", source_name="", alpha_factor=1.0):
    """V10.6C Gold/Trim/Lace Finish: Series Match + transparency + ornamental texture masks."""
    if not group:
        return False, "grupo inexistente"
    if category not in V105A_OPAQUE_CLOTH_CATEGORIES:
        return False, f"categoría fuera de V10.6C ({category})"

    profile = profile if profile in V105B_CLOTH_STYLE else "AVE"
    family = _aef105b_material_family(source_name, category, alpha_factor)
    style = _aef105b_resolve_style(profile, family)
    settings = getattr(bpy.context.scene, 'aef_sabershader_v8', None)
    style = _aef108b1_refine_cloth_style(style, profile, family, source_name, settings)
    style = _aef108b2_final_balance_cloth_style(style, profile, family, source_name, settings)
    style = _aef108c_series_lock_cloth_style(style, profile, family, source_name, settings)
    style = _aef108c1_final_micro_polish_cloth_style(style, profile, family, source_name, settings)
    style = _aef108c2_final_lock_cloth_style(style, profile, family, source_name, settings)

    # V10.6C.1: Doloris uses the literal MMD material name "Stocks". In the
    # series reference her hosiery reads a touch darker than the generic
    # stockings profile, so apply a tiny source-local value adjustment only.
    if family == "stockings" and (source_name or "").strip().lower() == "stocks":
        style = dict(style)
        style["shadow_mul"] = float(style.get("shadow_mul", 1.0)) * 0.97
        style["mid_mul"] = float(style.get("mid_mul", 1.0)) * 0.96
        style["light_mul"] = float(style.get("light_mul", 1.0)) * 0.97
        style["value"] = float(style.get("value", 1.0)) * 0.97
        style["emission_strength"] = float(style.get("emission_strength", 1.0)) * 0.98

    before = _aef15_image_link_signature(group)
    _aef105a_remove_nodes(group)

    nodes, links = group.nodes, group.links
    output = nodes.get("Group Output")
    if not output:
        return False, "sin Group Output"
    shader_out = next((s for s in output.inputs if s.type == 'SHADER'), None)
    if not shader_out:
        return False, "Group Output sin socket SHADER"

    source_socket, source_value, source_reason, source_node = _aef105a_color_source(group)

    base = nodes.new("ShaderNodeMixRGB")
    base.name = V105A_NODE_PREFIX + "Base Preserve"
    base.label = "V10.6C.1 • ORIGINAL COLOR PRESERVE"
    base.blend_type = 'MIX'; base.inputs["Fac"].default_value = 0.0; base.location = (-1260, 230)
    if source_socket is not None:
        links.new(source_socket, base.inputs["Color1"])
    else:
        base.inputs["Color1"].default_value = source_value

    geo = nodes.new("ShaderNodeNewGeometry")
    geo.name = V105A_NODE_PREFIX + "Geometry"; geo.label = "V10.6C.1 • Graphic normal mask"; geo.location = (-1260, 20)
    dot = nodes.new("ShaderNodeVectorMath")
    dot.name = V105A_NODE_PREFIX + "Designed Dot"; dot.label = "V10.6C.1 • Designed Shadow Direction"
    dot.operation = 'DOT_PRODUCT'; dot.location = (-1035, 20); dot.inputs[1].default_value = _aef105a_normalize3(style["key_dir"])
    links.new(geo.outputs["Normal"], dot.inputs[0])
    remap = nodes.new("ShaderNodeMapRange")
    remap.name = V105A_NODE_PREFIX + "Band Remap"; remap.label = "V10.6C.1 • Shadow placement"
    remap.location = (-835, 20); remap.clamp = True
    remap.inputs["From Min"].default_value = float(style["remap_min"]); remap.inputs["From Max"].default_value = float(style["remap_max"])
    remap.inputs["To Min"].default_value = 0.0; remap.inputs["To Max"].default_value = 1.0
    links.new(dot.outputs["Value"], remap.inputs["Value"])

    bands = nodes.new("ShaderNodeValToRGB")
    bands.name = V105A_NODE_PREFIX + "3 Band Ramp"; bands.label = f"V10.6C.1 • {profile} {family} neutral 3-band"
    bands.location = (-610, 40); _aef105a_config_band_ramp(bands, style)
    links.new(remap.outputs["Result"], bands.inputs["Fac"])

    cel = nodes.new("ShaderNodeMixRGB")
    cel.name = V105A_NODE_PREFIX + "Cel Multiply"; cel.label = "V10.6C.1 • Texture × Neutral Bands"
    cel.blend_type = 'MULTIPLY'; cel.inputs["Fac"].default_value = 1.0; cel.location = (-350, 210)
    links.new(base.outputs["Color"], cel.inputs["Color1"]); links.new(bands.outputs["Color"], cel.inputs["Color2"])

    shadow_inv = nodes.new("ShaderNodeMath")
    shadow_inv.name = V105A_NODE_PREFIX + "Shadow Invert"; shadow_inv.label = "V10.6C.1 • Shadow mask"
    shadow_inv.operation = 'SUBTRACT'; shadow_inv.location = (-600, -125)
    shadow_inv.inputs[0].default_value = 1.0; links.new(remap.outputs["Result"], shadow_inv.inputs[1])
    shadow_strength = nodes.new("ShaderNodeMath")
    shadow_strength.name = V105A_NODE_PREFIX + "Shadow Tint Strength"; shadow_strength.operation = 'MULTIPLY'
    shadow_strength.location = (-380, -125); shadow_strength.inputs[1].default_value = float(style["shadow_tint_strength"])
    links.new(shadow_inv.outputs["Value"], shadow_strength.inputs[0])
    shadow_tint = nodes.new("ShaderNodeMixRGB")
    shadow_tint.name = V105A_NODE_PREFIX + "Shadow Tint"; shadow_tint.label = "V10.6C.1 • Subtle cool shadow tint"
    shadow_tint.blend_type = 'MULTIPLY'; shadow_tint.location = (-80, 180); shadow_tint.inputs["Color2"].default_value = style["shadow_tint"]
    links.new(shadow_strength.outputs["Value"], shadow_tint.inputs["Fac"]); links.new(cel.outputs["Color"], shadow_tint.inputs["Color1"])

    inner_dot = nodes.new("ShaderNodeVectorMath")
    inner_dot.name = V105A_NODE_PREFIX + "Inner Dot"; inner_dot.label = "V10.6C.1 • Inner / Underside"
    inner_dot.operation = 'DOT_PRODUCT'; inner_dot.location = (-610, -330)
    inner_dot.inputs[1].default_value = (0.0, 0.0, -1.0); links.new(geo.outputs["Normal"], inner_dot.inputs[0])
    inner_map = nodes.new("ShaderNodeMapRange")
    inner_map.name = V105A_NODE_PREFIX + "Inner Mask"; inner_map.label = "V10.6C.1 • Inner shade mask"
    inner_map.location = (-390, -330); inner_map.clamp = True
    try: inner_map.interpolation_type = 'SMOOTHERSTEP'
    except Exception: pass
    inner_map.inputs["From Min"].default_value = float(style["inner_from"]); inner_map.inputs["From Max"].default_value = float(style["inner_to"])
    inner_map.inputs["To Min"].default_value = 0.0; inner_map.inputs["To Max"].default_value = 1.0
    links.new(inner_dot.outputs["Value"], inner_map.inputs["Value"])
    inner_strength = nodes.new("ShaderNodeMath")
    inner_strength.name = V105A_NODE_PREFIX + "Inner Strength"; inner_strength.operation = 'MULTIPLY'; inner_strength.location = (-170, -330)
    inner_strength.inputs[1].default_value = float(style["inner_strength"]); links.new(inner_map.outputs["Result"], inner_strength.inputs[0])
    inner_mix = nodes.new("ShaderNodeMixRGB")
    inner_mix.name = V105A_NODE_PREFIX + "Inner Multiply"; inner_mix.label = "V10.6C.1 • Designed Inner Shade"
    inner_mix.blend_type = 'MULTIPLY'; inner_mix.location = (190, 160); inner_mix.inputs["Color2"].default_value = style["inner_color"]
    links.new(inner_strength.outputs["Value"], inner_mix.inputs["Fac"]); links.new(shadow_tint.outputs["Color"], inner_mix.inputs["Color1"])

    recover_map = nodes.new("ShaderNodeMapRange")
    recover_map.name = V105A_NODE_PREFIX + "Mid Recover Mask"; recover_map.label = "V10.6C.1 • Chroma/detail recovery"
    recover_map.location = (-80, -470); recover_map.clamp = True
    try: recover_map.interpolation_type = 'SMOOTHERSTEP'
    except Exception: pass
    recover_map.inputs["From Min"].default_value = float(style["recover_from"]); recover_map.inputs["From Max"].default_value = float(style["recover_to"])
    recover_map.inputs["To Min"].default_value = 0.0; recover_map.inputs["To Max"].default_value = 1.0
    links.new(remap.outputs["Result"], recover_map.inputs["Value"])
    recover_strength = nodes.new("ShaderNodeMath")
    recover_strength.name = V105A_NODE_PREFIX + "Mid Recover Strength"; recover_strength.operation = 'MULTIPLY'; recover_strength.location = (140, -470)
    recover_strength.inputs[1].default_value = float(style["recover_strength"]); links.new(recover_map.outputs["Result"], recover_strength.inputs[0])
    recover = nodes.new("ShaderNodeMixRGB")
    recover.name = V105A_NODE_PREFIX + "Mid Recover"; recover.label = "V10.6C.1 • Recover source colour"
    recover.blend_type = 'MIX'; recover.location = (440, 140)
    links.new(recover_strength.outputs["Value"], recover.inputs["Fac"]); links.new(inner_mix.outputs["Color"], recover.inputs["Color1"]); links.new(base.outputs["Color"], recover.inputs["Color2"])

    bw = nodes.new("ShaderNodeRGBToBW")
    bw.name = V105A_NODE_PREFIX + "Base Luma"; bw.label = "V10.6C.1 • Source luminance"; bw.location = (-70, -610)
    links.new(base.outputs["Color"], bw.inputs["Color"])
    bright_map = nodes.new("ShaderNodeMapRange")
    bright_map.name = V105A_NODE_PREFIX + "Bright Protect Mask"; bright_map.label = "V10.6C.1 • Bright trim protect"
    bright_map.location = (160, -610); bright_map.clamp = True
    try: bright_map.interpolation_type = 'SMOOTHERSTEP'
    except Exception: pass
    bright_map.inputs["From Min"].default_value = float(style["bright_from"]); bright_map.inputs["From Max"].default_value = float(style["bright_to"])
    bright_map.inputs["To Min"].default_value = 0.0; bright_map.inputs["To Max"].default_value = 1.0
    links.new(bw.outputs["Val"], bright_map.inputs["Value"])
    bright_strength = nodes.new("ShaderNodeMath")
    bright_strength.name = V105A_NODE_PREFIX + "Bright Protect Strength"; bright_strength.operation = 'MULTIPLY'; bright_strength.location = (380, -610)
    bright_strength.inputs[1].default_value = float(style["bright_protect"]); links.new(bright_map.outputs["Result"], bright_strength.inputs[0])
    bright = nodes.new("ShaderNodeMixRGB")
    bright.name = V105A_NODE_PREFIX + "Bright Protect"; bright.label = "V10.6C.1 • Preserve lace / gold / whites"
    bright.blend_type = 'MIX'; bright.location = (700, 130)
    links.new(bright_strength.outputs["Value"], bright.inputs["Fac"]); links.new(recover.outputs["Color"], bright.inputs["Color1"]); links.new(base.outputs["Color"], bright.inputs["Color2"])

    # V10.6B.2: transparent cloth should preserve lace structure without
    # reading as chalky white. Compress high-value regions toward a smoky tint.
    white_map = nodes.new("ShaderNodeMapRange")
    white_map.name = V105A_NODE_PREFIX + "White Compress Mask"; white_map.label = "V10.6C.1 • White compression mask"
    white_map.location = (650, -420); white_map.clamp = True
    try: white_map.interpolation_type = 'SMOOTHERSTEP'
    except Exception: pass
    white_map.inputs["From Min"].default_value = float(style.get("white_compress_from", 1.0))
    white_map.inputs["From Max"].default_value = float(style.get("white_compress_to", 1.0))
    white_map.inputs["To Min"].default_value = 0.0
    white_map.inputs["To Max"].default_value = 1.0
    links.new(bw.outputs["Val"], white_map.inputs["Value"])

    white_strength = nodes.new("ShaderNodeMath")
    white_strength.name = V105A_NODE_PREFIX + "White Compress Strength"; white_strength.label = "V10.6C.1 • White compression strength"
    white_strength.operation = 'MULTIPLY'; white_strength.location = (900, -420)
    white_strength.inputs[1].default_value = float(style.get("white_compress_strength", 0.0))
    links.new(white_map.outputs["Result"], white_strength.inputs[0])

    white_compress = nodes.new("ShaderNodeMixRGB")
    white_compress.name = V105A_NODE_PREFIX + "White Compress"; white_compress.label = "V10.6C.1 • Smoke down lace whites"
    white_compress.blend_type = 'MULTIPLY'; white_compress.location = (950, 130)
    white_compress.inputs["Color2"].default_value = style.get("white_compress_color", (1.0, 1.0, 1.0, 1.0))
    links.new(white_strength.outputs["Value"], white_compress.inputs["Fac"])
    links.new(bright.outputs["Color"], white_compress.inputs["Color1"])

    sat = nodes.new("ShaderNodeHueSaturation")
    sat.name = V105A_NODE_PREFIX + "Color Restore"; sat.label = "V10.6C.1 • Series colour restore"; sat.location = (1200, 130)
    sat.inputs["Hue"].default_value = 0.5; sat.inputs["Saturation"].default_value = float(style["saturation"]); sat.inputs["Value"].default_value = float(style["value"]); sat.inputs["Fac"].default_value = 1.0
    links.new(white_compress.outputs["Color"], sat.inputs["Color"])

    # ---------------------------------------------------------------
    # V10.6C ORNAMENT FINISH
    # Detect warm bright pixels from the ORIGINAL texture for gold trim,
    # and bright low-chroma pixels for lace/ivory trim. No UV/image links
    # are replaced; all masks fan out from Base Preserve.
    # ---------------------------------------------------------------
    sep = nodes.new("ShaderNodeSeparateColor")
    sep.name = V105A_NODE_PREFIX + "Ornament RGB"; sep.label = "V10.6C.1 • Ornament RGB detect"
    sep.mode = 'RGB'; sep.location = (980, -760)
    links.new(base.outputs["Color"], sep.inputs["Color"])

    rb = nodes.new("ShaderNodeMath")
    rb.name = V105A_NODE_PREFIX + "Gold R-B"; rb.operation = 'SUBTRACT'; rb.location = (1190, -820)
    links.new(sep.outputs["Red"], rb.inputs[0]); links.new(sep.outputs["Blue"], rb.inputs[1])
    rb_map = nodes.new("ShaderNodeMapRange")
    rb_map.name = V105A_NODE_PREFIX + "Gold RB Map"; rb_map.clamp = True; rb_map.location = (1390, -820)
    rb_map.inputs["From Min"].default_value = float(style.get("gold_rb_from", 0.08)); rb_map.inputs["From Max"].default_value = float(style.get("gold_rb_to", 0.42))
    rb_map.inputs["To Min"].default_value = 0.0; rb_map.inputs["To Max"].default_value = 1.0
    links.new(rb.outputs[0], rb_map.inputs["Value"])

    gb = nodes.new("ShaderNodeMath")
    gb.name = V105A_NODE_PREFIX + "Gold G-B"; gb.operation = 'SUBTRACT'; gb.location = (1190, -900)
    links.new(sep.outputs["Green"], gb.inputs[0]); links.new(sep.outputs["Blue"], gb.inputs[1])
    gb_map = nodes.new("ShaderNodeMapRange")
    gb_map.name = V105A_NODE_PREFIX + "Gold GB Map"; gb_map.clamp = True; gb_map.location = (1390, -900)
    gb_map.inputs["From Min"].default_value = float(style.get("gold_gb_from", 0.035)); gb_map.inputs["From Max"].default_value = float(style.get("gold_gb_to", 0.30))
    gb_map.inputs["To Min"].default_value = 0.0; gb_map.inputs["To Max"].default_value = 1.0
    links.new(gb.outputs[0], gb_map.inputs["Value"])

    gold_luma = nodes.new("ShaderNodeMapRange")
    gold_luma.name = V105A_NODE_PREFIX + "Gold Luma"; gold_luma.clamp = True; gold_luma.location = (1390, -990)
    gold_luma.inputs["From Min"].default_value = float(style.get("gold_luma_from", 0.18)); gold_luma.inputs["From Max"].default_value = float(style.get("gold_luma_to", 0.82))
    gold_luma.inputs["To Min"].default_value = 0.0; gold_luma.inputs["To Max"].default_value = 1.0
    links.new(bw.outputs["Val"], gold_luma.inputs["Value"])

    gold_rg = nodes.new("ShaderNodeMath")
    gold_rg.name = V105A_NODE_PREFIX + "Gold Warm Mask"; gold_rg.operation = 'MULTIPLY'; gold_rg.location = (1600, -860)
    links.new(rb_map.outputs["Result"], gold_rg.inputs[0]); links.new(gb_map.outputs["Result"], gold_rg.inputs[1])
    gold_mask = nodes.new("ShaderNodeMath")
    gold_mask.name = V105A_NODE_PREFIX + "Gold Mask"; gold_mask.operation = 'MULTIPLY'; gold_mask.location = (1790, -860)
    links.new(gold_rg.outputs[0], gold_mask.inputs[0]); links.new(gold_luma.outputs["Result"], gold_mask.inputs[1])
    gold_strength = nodes.new("ShaderNodeMath")
    gold_strength.name = V105A_NODE_PREFIX + "Gold Strength"; gold_strength.operation = 'MULTIPLY'; gold_strength.location = (1970, -860)
    gold_strength.inputs[1].default_value = float(style.get("gold_strength", 0.0)); links.new(gold_mask.outputs[0], gold_strength.inputs[0])

    gold_mix = nodes.new("ShaderNodeMixRGB")
    gold_mix.name = V105A_NODE_PREFIX + "Gold Finish"; gold_mix.label = "V10.6C.1 • Antique gold trim"
    gold_mix.blend_type = 'MIX'; gold_mix.location = (1450, 130)
    gold_mix.inputs["Color2"].default_value = style.get("gold_color", (0.95, 0.62, 0.18, 1.0))
    links.new(gold_strength.outputs[0], gold_mix.inputs["Fac"]); links.new(sat.outputs["Color"], gold_mix.inputs["Color1"])

    # Neutral bright lace/ivory detection: high luma + low RGB chroma.
    rg_abs = nodes.new("ShaderNodeMath")
    rg_abs.name = V105A_NODE_PREFIX + "Lace |R-G|"; rg_abs.operation = 'SUBTRACT'; rg_abs.location = (1180, -1080)
    links.new(sep.outputs["Red"], rg_abs.inputs[0]); links.new(sep.outputs["Green"], rg_abs.inputs[1])
    rg_abs2 = nodes.new("ShaderNodeMath")
    rg_abs2.name = V105A_NODE_PREFIX + "Lace RG Abs"; rg_abs2.operation = 'ABSOLUTE'; rg_abs2.location = (1370, -1080); links.new(rg_abs.outputs[0], rg_abs2.inputs[0])
    gb_abs = nodes.new("ShaderNodeMath")
    gb_abs.name = V105A_NODE_PREFIX + "Lace |G-B|"; gb_abs.operation = 'SUBTRACT'; gb_abs.location = (1180, -1160)
    links.new(sep.outputs["Green"], gb_abs.inputs[0]); links.new(sep.outputs["Blue"], gb_abs.inputs[1])
    gb_abs2 = nodes.new("ShaderNodeMath")
    gb_abs2.name = V105A_NODE_PREFIX + "Lace GB Abs"; gb_abs2.operation = 'ABSOLUTE'; gb_abs2.location = (1370, -1160); links.new(gb_abs.outputs[0], gb_abs2.inputs[0])
    chroma = nodes.new("ShaderNodeMath")
    chroma.name = V105A_NODE_PREFIX + "Lace Chroma"; chroma.operation = 'MAXIMUM'; chroma.location = (1560, -1120)
    links.new(rg_abs2.outputs[0], chroma.inputs[0]); links.new(gb_abs2.outputs[0], chroma.inputs[1])
    neutral = nodes.new("ShaderNodeMapRange")
    neutral.name = V105A_NODE_PREFIX + "Lace Neutral Mask"; neutral.clamp = True; neutral.location = (1740, -1120)
    neutral.inputs["From Min"].default_value = 0.0; neutral.inputs["From Max"].default_value = float(style.get("lace_chroma_to", 0.12))
    neutral.inputs["To Min"].default_value = 1.0; neutral.inputs["To Max"].default_value = 0.0
    links.new(chroma.outputs[0], neutral.inputs["Value"])
    lace_luma = nodes.new("ShaderNodeMapRange")
    lace_luma.name = V105A_NODE_PREFIX + "Lace Luma"; lace_luma.clamp = True; lace_luma.location = (1560, -1230)
    lace_luma.inputs["From Min"].default_value = float(style.get("lace_luma_from", 0.62)); lace_luma.inputs["From Max"].default_value = float(style.get("lace_luma_to", 0.96))
    lace_luma.inputs["To Min"].default_value = 0.0; lace_luma.inputs["To Max"].default_value = 1.0
    links.new(bw.outputs["Val"], lace_luma.inputs["Value"])
    lace_mask = nodes.new("ShaderNodeMath")
    lace_mask.name = V105A_NODE_PREFIX + "Lace Mask"; lace_mask.operation = 'MULTIPLY'; lace_mask.location = (1940, -1150)
    links.new(neutral.outputs["Result"], lace_mask.inputs[0]); links.new(lace_luma.outputs["Result"], lace_mask.inputs[1])
    lace_strength = nodes.new("ShaderNodeMath")
    lace_strength.name = V105A_NODE_PREFIX + "Lace Strength"; lace_strength.operation = 'MULTIPLY'; lace_strength.location = (2120, -1150)
    lace_strength.inputs[1].default_value = float(style.get("lace_strength", 0.0)); links.new(lace_mask.outputs[0], lace_strength.inputs[0])

    lace_mix = nodes.new("ShaderNodeMixRGB")
    lace_mix.name = V105A_NODE_PREFIX + "Lace Finish"; lace_mix.label = "V10.6C.1 • Ivory/smoke lace finish"
    lace_mix.blend_type = 'MIX'; lace_mix.location = (1700, 130)
    lace_mix.inputs["Color2"].default_value = style.get("lace_color", (0.93, 0.90, 0.84, 1.0))
    links.new(lace_strength.outputs[0], lace_mix.inputs["Fac"]); links.new(gold_mix.outputs["Color"], lace_mix.inputs["Color1"])

    emission = nodes.new("ShaderNodeEmission")
    emission.name = V105A_NODE_PREFIX + "Emission"; emission.label = "V10.6C.1 • FINAL SERIES MATCH CLOTH"; emission.location = (1950, 130)
    links.new(lace_mix.outputs["Color"], emission.inputs["Color"]); emission.inputs["Strength"].default_value = float(style["emission_strength"])

    for lk in list(shader_out.links):
        links.remove(lk)

    try:
        alpha_factor = float(alpha_factor)
    except Exception:
        alpha_factor = 1.0
    effective_alpha = max(0.0, min(1.0, alpha_factor * float(style.get("opacity_scale", 1.0))))
    if family == "transparent" or effective_alpha < 0.995:
        transparent = nodes.new("ShaderNodeBsdfTransparent")
        transparent.name = V105A_NODE_PREFIX + "Transparent"; transparent.label = "V10.6C.1 • PMX transparency"; transparent.location = (1950, -60)

        # V10.6B.2: the PMX factor remains the opacity authority, but source
        # luminance modulates it artistically. Bright lace/pattern regions become
        # a little more transparent, dark regions a little more solid. This
        # avoids the chalky/white veil seen in V10.6B without inventing texture alpha.
        alpha_luma = nodes.new("ShaderNodeMapRange")
        alpha_luma.name = V105A_NODE_PREFIX + "Alpha Luma Mod"
        alpha_luma.label = "V10.6C.1 • Luma opacity modulation"
        alpha_luma.location = (760, -360); alpha_luma.clamp = True
        try: alpha_luma.interpolation_type = 'SMOOTHERSTEP'
        except Exception: pass
        alpha_luma.inputs["From Min"].default_value = float(style.get("alpha_luma_from", 0.16))
        alpha_luma.inputs["From Max"].default_value = float(style.get("alpha_luma_to", 0.84))
        alpha_luma.inputs["To Min"].default_value = float(style.get("alpha_luma_dark", 1.0))
        alpha_luma.inputs["To Max"].default_value = float(style.get("alpha_luma_bright", 1.0))
        links.new(bw.outputs["Val"], alpha_luma.inputs["Value"])

        alpha_mul = nodes.new("ShaderNodeMath")
        alpha_mul.name = V105A_NODE_PREFIX + "Alpha PMX x Luma"
        alpha_mul.label = f"V10.6C.1 • PMX {effective_alpha:.3f} × Luma"
        alpha_mul.operation = 'MULTIPLY'; alpha_mul.use_clamp = True; alpha_mul.location = (1010, -320)
        alpha_mul.inputs[1].default_value = effective_alpha
        links.new(alpha_luma.outputs["Result"], alpha_mul.inputs[0])

        mix = nodes.new("ShaderNodeMixShader")
        mix.name = V105A_NODE_PREFIX + "Transparent Mix"; mix.label = f"V10.6C.1 • PMX Alpha {effective_alpha:.3f}"; mix.location = (2200, 80)
        links.new(alpha_mul.outputs["Value"], mix.inputs[0])
        links.new(transparent.outputs[0], mix.inputs[1])
        links.new(emission.outputs[0], mix.inputs[2])
        links.new(mix.outputs[0], shader_out)
    else:
        links.new(emission.outputs[0], shader_out)

    after = _aef15_image_link_signature(group)
    removed = before - after
    if removed:
        raise RuntimeError(f"V10.6C safety FAILED on {group.name}: se eliminaron Image Texture links {sorted(removed)}")
    added = after - before
    allowed = set()
    if source_node and source_node.bl_idname == 'ShaderNodeTexImage':
        allowed.add((source_node.name, source_socket.name, base.name, "Color1"))
    unexpected = added - allowed
    if unexpected:
        raise RuntimeError(f"V10.6C safety FAILED on {group.name}: Image Texture links inesperados {sorted(unexpected)}")

    group["AEF_V10_5A_DesignedCloth"] = True
    group["AEF_V10_5B_RefinedCloth"] = True
    group["AEF_V10_6A_SeriesMatchCloth"] = True
    group["AEF_V10_6B_SeriesMatchCloth"] = True
    group["AEF_V10_6B1_TransparentRebalance"] = True
    group["AEF_V10_5A_Profile"] = profile; group["AEF_V10_5B_Profile"] = profile
    group["AEF_V10_5B_Family"] = family; group["AEF_V10_6A_Family"] = family; group["AEF_V10_6B_Family"] = family
    group["AEF_V10_5A_Source"] = source_reason; group["AEF_V10_5B_Source"] = source_reason
    group["AEF_V10_6A_Source"] = source_reason; group["AEF_V10_6B_Source"] = source_reason
    group["AEF_V10_5A_KeyDirection"] = tuple(float(x) for x in style["key_dir"])
    group["AEF_V10_5A_InnerStrength"] = float(style["inner_strength"])
    group["AEF_V10_5A_EmissionStrength"] = float(style["emission_strength"])
    group["AEF_V10_6A_Saturation"] = float(style["saturation"])
    group["AEF_V10_6A_BrightProtect"] = float(style["bright_protect"])
    group["AEF_V10_6B_Alpha"] = float(effective_alpha)
    group["AEF_V10_6B2_TransparentDeepening"] = True
    group["AEF_V10_6C_GoldTrimLace"] = True
    group["AEF_V10_6C_GoldStrength"] = float(style.get("gold_strength", 0.0))
    group["AEF_V10_6C_LaceStrength"] = float(style.get("lace_strength", 0.0))
    group["AEF_V10_6C1_ClothFinalPolish"] = True
    group["AEF_V10_6B1_TransparentRebalanceFamily"] = family
    return True, f"Gold/Trim/Lace {profile}/{family}: Series Match + transparent deepening + gold/trim/lace masks + PMX/luma alpha {effective_alpha:.3f} + Emission NPR | source={source_reason}"


def _aef105a_is_eligible(source_mat, category):


    settings = getattr(bpy.context.scene, "aef_sabershader_v8", None)
    if settings and not bool(getattr(settings, "build_designed_cloth_v105a", True)):
        return False, "disabled_A/B"
    if category not in V105A_OPAQUE_CLOTH_CATEGORIES:
        return False, "category"
    alpha = get_pmx_alpha_factor(source_mat)
    if category == "transparent_cloth" or alpha < 0.995:
        return True, f"transparent(alpha={alpha:.3f})"
    if category == "stockings":
        return True, "stockings"
    return True, "opaque"

def apply_anime_toon_finish(group, category):
    """Public wrapper used by setup_group/build_material."""
    try:
        return _aef15_apply_to_group(group, category)
    except Exception as exc:
        log(f"  V8.17 SAFE ABORT on {group.name}: {exc}")
        return False, f"SAFE ABORT: {exc}"


def setup_group(local, category, base_image):
    if category in {"face", "mouth", "expression", "expression2"}:
        configure_face(local, base_image)
    elif category == "hair":
        configure_simple_base(local, base_image)
        neutralize_hair_aux(local)
    elif category in {"cloth", "cloth1", "cloth2", "cloth3", "cloth4", "stockings", "transparent_cloth", "mask", "accessory", "tie", "glove", "bow", "boots", "skirt"}:
        configure_simple_base(local, base_image)
        neutralize_cloth_aux(local)
    elif category in {"body", "eyes", "eyes3", "eyes5"}:
        configure_simple_base(local, base_image)
        # Body/Eyes masters do not receive the cloth Wulfa fix.
        if category == "body":
            toon = bpy.data.images.get("toon02.bmp") or bpy.data.images.get("toon_defo.bmp")
            if toon and local.nodes.get("mmd_toon_tex"):
                local.nodes["mmd_toon_tex"].image = toon
        if category == "eyes5":
            toon = bpy.data.images.get("toon02.bmp") or bpy.data.images.get("toon_defo.bmp")
            if toon and local.nodes.get("mmd_toon_tex"):
                local.nodes["mmd_toon_tex"].image = toon
    return


def build_material(char_name, source_name, category, source_mat):
    template = template_for_category(category)
    if not template:
        log(f"SKIP {source_name}: no template for category={category}")
        return None

    base_image, reason = resolve_base_image(source_mat, category, source_name)
    safe = safe_name(source_name)
    mat_name = f"AEF_V8_{safe_name(char_name)}_{safe}"

    # V10.1 FACE PATCH: forzar la destrucción del material facial anterior
    # justo antes de crear el nuevo. process_character() ya ha capturado
    # previamente los (objeto, slot) que apuntaban a este material para poder
    # reasignarlos después del build. El resto de categorías conserva el
    # comportamiento existente.
    if category in FORCE_REBUILD_FACE_CATEGORIES:
        old_mat = bpy.data.materials.get(mat_name)
        if old_mat:
            log(
                f"FORCE REBUILD FACE: eliminando material anterior "
                f"'{old_mat.name}' ({char_name}/{source_name}/{category})"
            )
            bpy.data.materials.remove(old_mat, do_unlink=True)

    mat = clear_and_make_material(mat_name)

    local = duplicate_group(template, f"{char_name}_{safe}")
    if not local:
        bpy.data.materials.remove(mat, do_unlink=True)
        return None

    group_node = mat.node_tree.nodes.new("ShaderNodeGroup")
    group_node.name = "XDZR8_V8"
    group_node.label = f"XDZR8 V8 • {category}"
    group_node.node_tree = local
    group_node.location = (0, 0)

    output = connect_group_output(mat, group_node)

    # V8.11 — FACE: MMDTexUV.Base UV + Toon UV -> Face_XDZR8. No usamos el UV bruto.
    if category in {"face", "mouth", "expression", "expression2"}:
        remove_external_face_uv(mat)
        uv_connected = connect_face_mmdtexuv(mat, group_node)
        log(f"  Face UV = MMDTexUV Base UV + Toon UV: {char_name}/{source_name}")
    else:
        uv_connected = connect_group_uv(mat, group_node)

    setup_group(local, category, base_image)

    # V10.6B: ropa opaca + stockings + transparencias PMX (Clothes4/裙透)
    # usan Series Match+. Mask y categorías no soportadas continúan por el
    # camino V10.4/V8.17.
    cloth_eligible, cloth_why = _aef105a_is_eligible(source_mat, category)
    if cloth_eligible:
        profile = _aef105a_profile()
        toon_ok, toon_why = _aef105a_apply_designed_cloth(local, category, profile, source_name, get_pmx_alpha_factor(source_mat))
        log(f"  [V10.6C cloth] {char_name}/{source_name}: {toon_why}")
    else:
        toon_ok, toon_why = apply_anime_toon_finish(local, category)
        log(f"  [V8.17 toon] {char_name}/{source_name}: {toon_why} | V10.6C skip={cloth_why}")

    if category in {"face", "mouth", "expression", "expression2"}:
        audit_face_image_slots(local, base_image, source_name)
    face_secondary_uv = False
    if category in {"face", "mouth", "expression", "expression2"}:
        face_secondary_uv = connect_face_secondary_uv(local)
    configure_alpha(mat, local, category)
    configure_alpha_from_pmx_factor(mat, local, source_mat, category)

    mask_skin_blend = False
    mask_texture_alpha = False
    face_direct_texture = False
    if category == "mask":
        mask_texture_alpha = configure_mask_texture_alpha(mat, local, base_image)
        if mask_texture_alpha:
            log(f"      [mask-alpha] {char_name}/{source_name}: Alpha real de textura activo")
        else:
            log(f"      [mask-alpha] {char_name}/{source_name}: NO se pudo conectar el Alpha de la textura")
    elif category in {"face", "mouth", "expression", "expression2"}:
        face_direct_texture = reinforce_face_direct_texture(local, base_image)
        if face_direct_texture:
            log(f"      [face-direct] {char_name}/{source_name}: Base Color reforzado con {base_image.name}")

    try:
        logical_source_name = str(source_mat.get("AEF_RECOVERY_OriginalName", "") or source_mat.name)
    except Exception:
        logical_source_name = source_mat.name
    mat["AEF_V8_SourceMaterial"] = logical_source_name
    mat["AEF_V8_Category"] = category
    mat["AEF_V8_Template"] = template
    mat["AEF_V8_BaseImage"] = base_image.name if base_image else ""
    mat["AEF_V8_BaseImageReason"] = reason
    mat["AEF_V8_Output"] = output.name
    mat["AEF_V8_UVConnected"] = uv_connected
    mat["AEF_V8_FaceUVSource"] = ("MMDTexUV.Base UV + Toon UV" if category in {"face", "mouth", "expression", "expression2"} else "Texture Coordinate UV")
    mat["AEF_V8_FaceSecondaryUV"] = face_secondary_uv
    mat["AEF_V8_SphereTexture"] = "NOT_IMPLEMENTED_V8_0"
    mat["AEF_V8_WulfaAux"] = "NEUTRALIZED"
    mat["AEF_V8_MaskSkinBlend"] = mask_skin_blend
    mat["AEF_V8_MaskTextureAlpha"] = base_image.name if (category == "mask" and mask_texture_alpha) else ""
    mat["AEF_V8_FaceDirectTexture"] = bool(face_direct_texture)
    mat["AEF_V10_5A_DesignedCloth"] = bool(local.get("AEF_V10_5A_DesignedCloth", False))
    mat["AEF_V10_5A_Profile"] = str(local.get("AEF_V10_5A_Profile", ""))
    mat["AEF_V10_5B_RefinedCloth"] = bool(local.get("AEF_V10_5B_RefinedCloth", False))
    mat["AEF_V10_5B_Profile"] = str(local.get("AEF_V10_5B_Profile", ""))
    mat["AEF_V10_5B_Family"] = str(local.get("AEF_V10_5B_Family", ""))
    mat["AEF_V10_5B2_DarkRebalance"] = bool(local.get("AEF_V10_5B2_DarkRebalance", False))
    mat["AEF_V10_6A_SeriesMatchCloth"] = bool(local.get("AEF_V10_6A_SeriesMatchCloth", False))
    mat["AEF_V10_6A_Family"] = str(local.get("AEF_V10_6A_Family", ""))
    mat["AEF_V10_6B_SeriesMatchCloth"] = bool(local.get("AEF_V10_6B_SeriesMatchCloth", False))
    mat["AEF_V10_6B_Family"] = str(local.get("AEF_V10_6B_Family", ""))
    mat["AEF_V10_6B2_TransparentDeepening"] = bool(local.get("AEF_V10_6B2_TransparentDeepening", False))
    mat["AEF_V10_6C_GoldTrimLace"] = bool(local.get("AEF_V10_6C_GoldTrimLace", False))
    mat["AEF_V10_6C_Family"] = str(local.get("AEF_V10_6B_Family", ""))
    mat["AEF_V10_6C1_ClothFinalPolish"] = bool(local.get("AEF_V10_6C1_ClothFinalPolish", False))
    mat["AEF_V10_6B1_TransparentRebalance"] = bool(local.get("AEF_V10_6B1_TransparentRebalance", False))

    log(
        f"BUILD {char_name:10s} | {source_name:16s} -> {category:18s} | "
        f"base={base_image.name if base_image else 'NONE'} ({reason}) | "
        f"material={mat.name} | uv={uv_connected} | face2uv={face_secondary_uv}"
    )
    return mat


def assign_material(obj, source_mat, new_mat):
    changed = False
    for slot in obj.material_slots:
        if slot.material == source_mat:
            slot.material = new_mat
            changed = True
    return changed


def restore_guitars_from_v4():
    # Preserve V4 behavior: restore original guitar materials if a previous
    # V4 pass had replaced them. V8 itself does not build guitar shaders.
    restored = 0
    for source_name in ("Guitar1", "Guitar2", "Guitar3"):
        original = bpy.data.materials.get(source_name)
        backup = bpy.data.materials.get(f"AEF_BACKUP_{source_name}")
        target = backup or original
        if not target:
            continue
        for obj in bpy.context.scene.objects:
            if obj.type != "MESH":
                continue
            for slot in obj.material_slots:
                mat = slot.material
                if not mat:
                    continue
                if mat.get("AEF_V4_SourceMaterial") == source_name:
                    slot.material = target
                    restored += 1
    if restored:
        log(f"Restored V4 guitar slots: {restored}")
    return restored


def process_character(char_name, mapping, assign=True):
    """Build/rebuild one character, including recovery after source purge.

    V10.5B.1 fixes a long-running repeat-build weakness: once AEF_V8_* replaces
    a source MMD material in all slots, the original can have zero users. Blender
    may purge that datablock on save/reopen. Older builds then reported MISS for
    almost every material and only rebuilt the few originals that happened to
    survive.

    Recovery path:
      original/AEF_BACKUP -> preferred source;
      previous AEF_V8_* output -> temporary source snapshot when original is gone.
    The snapshot is used only for stored base-image/alpha metadata and is removed
    after the new material is built. Existing object slots are captured before
    the old AEF output is deleted.
    """
    processed = 0
    assigned = 0
    skipped_guitar = 0
    recovered = 0

    log("")
    log("=" * 96)
    log(char_name.upper())
    log("=" * 96)

    for source_name, category in mapping.items():
        safe = safe_name(source_name)
        mat_name = f"AEF_V8_{safe_name(char_name)}_{safe}"
        previous_output = bpy.data.materials.get(mat_name)

        source = find_material(source_name)
        recovery_source = None

        if not source and previous_output:
            # Copy before build_material() removes/replaces previous_output.
            # We intentionally do NOT keep this temp material in the file.
            try:
                recovery_source = previous_output.copy()
                recovery_source.name = f"AEF_RECOVERY_SOURCE_{safe_name(char_name)}_{safe}"
                recovery_source["AEF_RECOVERY_OriginalName"] = source_name
                recovery_source.use_fake_user = False
                source = recovery_source
                recovered += 1
                log(
                    f"RECOVER {source_name} -> {category}: original MMD material missing; "
                    f"using snapshot of '{previous_output.name}' "
                    f"(base={previous_output.get('AEF_V8_BaseImage', '') or 'NONE'})"
                )
            except Exception as exc:
                log(f"RECOVERY FAILED {source_name}: {exc}")
                source = None

        if not source:
            log(f"MISS {source_name} -> {category}: source material not found and no previous AEF output")
            continue

        # Protect real surviving MMD/backup sources from being purged after AEF
        # takes over all object slots. This prevents the same problem on future
        # saves/reopens.
        if recovery_source is None:
            try:
                source.use_fake_user = True
            except Exception:
                pass

        if category == "guitar":
            skipped_guitar += 1
            log(f"KEEP {source_name} -> ORIGINAL GUITAR")
            if recovery_source:
                try:
                    bpy.data.materials.remove(recovery_source, do_unlink=True)
                except Exception:
                    pass
            continue

        targets = set()
        for candidate in (source if recovery_source is None else None, previous_output):
            if not candidate:
                continue
            for obj in users_of(candidate):
                for i, slot in enumerate(obj.material_slots):
                    if slot.material == candidate:
                        targets.add((obj, i))

        new_mat = None
        try:
            new_mat = build_material(char_name, source_name, category, source)
        finally:
            if recovery_source:
                try:
                    bpy.data.materials.remove(recovery_source, do_unlink=True)
                except Exception as exc:
                    log(f"RECOVERY cleanup warning {source_name}: {exc}")

        if not new_mat:
            continue

        processed += 1
        if assign:
            touched = set()
            for obj, i in targets:
                try:
                    obj.material_slots[i].material = new_mat
                    touched.add(obj)
                except Exception as exc:
                    log(f"ASSIGN warning {obj.name}[{i}] <- {new_mat.name}: {exc}")
            assigned += len(touched)

    log(f"{char_name}: recovery_sources={recovered}")
    return processed, assigned, skipped_guitar




def apply_ave_face_profile(settings):
    """V10.2 — Tune SOLO el acabado facial cuando el perfil activo es AVE.

    Valores AVE documentados aquí (no cambian MYGO ni el comportamiento
    genérico de otros perfiles):
      - Face Shadow effective strength: 0.38.
      - Toon Fac: 0.54 (menos multiplicación extrema sobre la textura).
      - Toon Ramp: shadow=(0.58,0.60,0.68), mid=(0.94,0.93,0.96),
        light=(1.00,0.995,0.99), interpolación EASE.
      - Face Emission Strength: 0.075 (ligero lift de legibilidad).
      - Face Fresnel edge mask: 0.66 -> 0.91 con transición EASE.
      - Face Rim Tint: (0.34, 0.46, 0.70), sutilmente frío/azulado.
    El objetivo es aproximar el efecto Tertiary de Sanzigen en el shader base:
    frente/mejillas legibles, laterales y barbilla controlados y rim teatral.

    No crea ni elimina Image Texture, no cambia UVs ni toca masters.
    """
    profile = getattr(settings, 'shot_profile', 'AVE') if settings else 'AVE'
    if profile != 'AVE':
        return 0

    count = 0
    face_categories = FORCE_REBUILD_FACE_CATEGORIES
    for mat in bpy.data.materials:
        if not mat or mat.get('AEF_V8_Category') not in face_categories:
            continue
        if not mat.use_nodes or not mat.node_tree:
            continue
        group_node = mat.node_tree.nodes.get('XDZR8_V8')
        group = group_node.node_tree if group_node and group_node.node_tree else None
        if not group:
            continue

        changed = False

        # Toon banding: keep the real texture primary, lift mid/light and
        # reduce the multiply weight so the face does not collapse toward black.
        toon_mix = group.nodes.get('AEF Anime Toon Mix')
        toon_ramp = group.nodes.get('AEF Face Toon Ramp') or group.nodes.get('AEF Anime Toon Ramp')
        if toon_mix:
            toon_mix.inputs['Fac'].default_value = 0.54
            changed = True
        if toon_ramp:
            cr = toon_ramp.color_ramp
            while len(cr.elements) > 3:
                cr.elements.remove(cr.elements[-1])
            if len(cr.elements) < 3:
                while len(cr.elements) < 3:
                    cr.elements.new(0.75 if len(cr.elements) == 1 else 0.92)
            elems = sorted(list(cr.elements), key=lambda e: e.position)
            elems[0].position = 0.34
            elems[0].color = (0.58, 0.60, 0.68, 1.0)
            elems[1].position = 0.66
            elems[1].color = (0.94, 0.93, 0.96, 1.0)
            elems[2].position = 0.91
            elems[2].color = (1.00, 0.995, 0.99, 1.0)
            cr.interpolation = 'EASE'
            changed = True

        # Slight general readability lift, without replacing Base Color.
        final = group.nodes.get('AEF Face Principled')
        if final:
            eco = final.inputs.get('Emission Color') or final.inputs.get('Emission')
            estr = final.inputs.get('Emission Strength')
            if eco and not eco.is_linked and toon_mix:
                for lk in list(eco.links):
                    group.links.remove(lk)
                group.links.new(toon_mix.outputs['Color'], eco)
                changed = True
            if estr and not estr.is_linked:
                estr.default_value = 0.075
                changed = True

            # V4 face Fresnel: stronger at cheeks/jaw, but still gated.
            fresnel = group.nodes.get('AEF Face Fresnel')
            rim_ramp = group.nodes.get('AEF Face Rim Ramp')
            if fresnel:
                fresnel.inputs['IOR'].default_value = 1.22
                changed = True
            if rim_ramp:
                cr = rim_ramp.color_ramp
                while len(cr.elements) > 2:
                    cr.elements.remove(cr.elements[-1])
                while len(cr.elements) < 2:
                    cr.elements.new(0.90)
                elems = sorted(list(cr.elements), key=lambda e: e.position)
                elems[0].position = 0.66
                elems[0].color = (0.0, 0.0, 0.0, 1.0)
                elems[1].position = 0.91
                elems[1].color = (1.0, 1.0, 1.0, 1.0)
                cr.interpolation = 'EASE'
                changed = True
            rim_mix = group.nodes.get('AEF Face Rim Mix')
            if rim_mix:
                rim_mix.blend_type = 'ADD'
                rim_mix.inputs[2].default_value = (0.34, 0.46, 0.70, 1.0)
                changed = True

        if changed:
            group['AEF_V10_2_AVE_Profile'] = True
            group['AEF_V10_3_AVE_ToonFac'] = 0.54
            group['AEF_V10_3_AVE_EmissionStrength'] = 0.075
            group['AEF_V10_3_AVE_RimTint'] = (0.34, 0.46, 0.70, 1.0)
            count += 1
            log(f"  [V10.3 AVE FACE] tuned {group.name}: toon=0.54 shadow=0.38 emission=0.075 cool-rim")

    return count


def force_final_face_output():
    """V10.4 final face output: designed NPR color -> Emission, no physical relight."""
    forced = 0
    skipped = 0
    face_categories = FORCE_REBUILD_FACE_CATEGORIES

    for mat in bpy.data.materials:
        if not mat or not mat.get("AEF_V8_Category"):
            continue
        category = mat.get("AEF_V8_Category")
        if category not in face_categories:
            continue
        if not mat.use_nodes or not mat.node_tree:
            skipped += 1
            continue

        group_node = mat.node_tree.nodes.get("XDZR8_V8")
        if not group_node or not group_node.node_tree:
            log(f"  [FINAL FACE NPR] SKIP {mat.name}: no se encontró XDZR8_V8")
            skipped += 1
            continue

        group = group_node.node_tree
        nodes = group.nodes
        links = group.links
        output = nodes.get("Group Output")
        principled = nodes.get("AEF Face Principled")
        if not output or not principled:
            log(f"  [FINAL FACE NPR] SKIP {mat.name}: group incompleto ({group.name})")
            skipped += 1
            continue

        shader_out = next((sock for sock in output.inputs if sock.type == 'SHADER'), None)
        base = principled.inputs.get("Base Color")
        if not shader_out or not base:
            skipped += 1
            continue

        final = nodes.get("AEF Face NPR Final")
        if final is None or final.bl_idname != 'ShaderNodeEmission':
            if final:
                nodes.remove(final)
            final = nodes.new('ShaderNodeEmission')
            final.name = "AEF Face NPR Final"
            final.label = "V10.4 Face NPR Final • no local nose relight"
            final.location = (principled.location.x + 260, principled.location.y + 120)

        color_in = final.inputs.get("Color")
        strength_in = final.inputs.get("Strength")
        if color_in:
            for lk in list(color_in.links):
                links.remove(lk)
            if base.is_linked:
                links.new(base.links[0].from_socket, color_in)
            else:
                color_in.default_value = tuple(base.default_value)
        if strength_in and not strength_in.is_linked:
            strength_in.default_value = 0.92

        for lk in list(shader_out.links):
            links.remove(lk)
        links.new(final.outputs["Emission"], shader_out)

        principled.label = "V10.4 STAGING — color source, no final physical shading"
        group['AEF_V10_4_FaceNPRFinal'] = True
        group['AEF_V10_4_FaceNPRStrength'] = 0.92
        forced += 1
        log(f"  [FINAL FACE NPR] Group Output <- AEF Face NPR Final ({group.name})")

    log(f"V10.4 FINAL FACE NPR: forced={forced} skipped={skipped}")
    return forced


# =====================================================================
# V10.7A — SAFE SILHOUETTE (shell / inverted-hull, sin LINEART)
# ---------------------------------------------------------------------
# Objetivo: recuperar una silueta tipo Ave Mujica / MyGO sin tocar el
# evaluador nativo de Grease Pencil Line Art que causó crashes en 5.1.1.
#
# Estrategia: duplicados de malla regenerables + material invisible en las
# caras originales + Solidify con normales invertidas + material de emisión
# con backface culling. Así solo se leen los backfaces periféricos del shell.
# =====================================================================
AEF107A_COLLECTION_PREFIX = "AEF_V10_7A_Silhouette_"
AEF107A_OBJECT_PREFIX = "AEF_V10_7A_Shell__"
AEF107A_MAT_PREFIX = "AEF_V10_7A_"
AEF107A_FAMILY_BASE = {
    'AVE':  {'face': 0.00170, 'hair': 0.00235, 'cloth': 0.00230, 'skin': 0.00115, 'stockings': 0.00180, 'transparent': 0.00130, 'prop': 0.00110},
    'MYGO': {'face': 0.00155, 'hair': 0.00210, 'cloth': 0.00205, 'skin': 0.00105, 'stockings': 0.00165, 'transparent': 0.00120, 'prop': 0.00095},
}
AEF107A_TINY_DIM_THRESHOLD = 0.040
AEF107A_TINY_POLY_THRESHOLD = 800
AEF107A_PROP_SKIP_TOKENS = {
    'string', 'strings', 'peg', 'tuner', 'pickup', 'bridge', 'screw', 'cable',
    'knob', 'lever', 'switch', 'strap', 'pin', 'jack', 'arm', 'rod', 'wire'
}
AEF107A_TRANSPARENT_TOKENS = {'clothes4', '裙透', 'transparent', 'sheer', 'lace'}
AEF107A_STOCKINGS_TOKENS = {'stockings', 'stocks', '靴下', 'hosiery'}


def _aef109b35_chromatic_ink_color(char_name, family, settings=None):
    """V10.9B3.5: subtle chromatic ink for Doloris, series-reference pass.

    Ave Mujica rarely reads as absolute RGB black around Doloris' pale hair/skin.
    This keeps clothing near-black while shifting face/hair/skin outlines toward a
    very dark plum/rose ink. Oblivionis remains untouched as the established
    reference character.
    """
    base = _aef9_outline_color(char_name)
    if not settings or not bool(getattr(settings, 'build_series_ink_clean_preview_v109b35', True)):
        return base
    if not str(char_name).lower().startswith('doloris'):
        return base
    if not bool(getattr(settings, 'doloris_chromatic_ink_v109b35', True)):
        return base

    blend = max(0.0, min(1.0, float(getattr(settings, 'doloris_chromatic_ink_strength_v109b35', 0.82))))
    target = {
        'face':        (0.026, 0.012, 0.027, 1.0),
        'hair':        (0.036, 0.016, 0.034, 1.0),
        'skin':        (0.043, 0.020, 0.029, 1.0),
        'cloth':       (0.012, 0.008, 0.017, 1.0),
        'stockings':   (0.016, 0.010, 0.020, 1.0),
        'transparent': (0.024, 0.013, 0.025, 1.0),
        'prop':        (0.010, 0.007, 0.015, 1.0),
    }.get(str(family), (0.015, 0.009, 0.020, 1.0))
    rgb = tuple((1.0 - blend) * float(base[i]) + blend * float(target[i]) for i in range(3))
    return rgb + (1.0,)


def _aef107a_outline_color(char_name, family='cloth', settings=None):
    base = _aef109b35_chromatic_ink_color(char_name, family, settings)
    mul_map = {
        'face': 1.04,
        'hair': 0.96,
        'cloth': 1.00,
        'skin': 1.00,
        'stockings': 0.92,
        'transparent': 0.86,
        'prop': 0.88,
    }
    mul = mul_map.get(family, 1.0)
    return tuple(max(0.0, min(1.0, c * mul)) for c in base[:3]) + (1.0,)


def _aef107a_get_material(char_name, family='cloth', invisible=False, settings=None):
    suffix = 'Invisible' if invisible else f'Outline_{family}'
    name = f"{AEF107A_MAT_PREFIX}{char_name}_{suffix}"
    mat = bpy.data.materials.get(name)
    if not mat:
        mat = bpy.data.materials.new(name)
    mat.use_nodes = True
    nt = mat.node_tree
    nodes = nt.nodes
    links = nt.links
    nodes.clear()
    out = nodes.new('ShaderNodeOutputMaterial')
    out.location = (220, 0)
    if invisible:
        node = nodes.new('ShaderNodeBsdfTransparent')
        node.location = (0, 0)
        links.new(node.outputs['BSDF'], out.inputs['Surface'])
        if hasattr(mat, 'blend_method'):
            mat.blend_method = 'BLEND'
        if hasattr(mat, 'shadow_method'):
            try: mat.shadow_method = 'NONE'
            except Exception: pass
        if hasattr(mat, 'use_backface_culling'):
            mat.use_backface_culling = False
        mat.diffuse_color = (0.0, 0.0, 0.0, 0.0)
    else:
        node = nodes.new('ShaderNodeEmission')
        node.location = (0, 0)
        color = _aef107a_outline_color(char_name, family, settings)
        node.inputs['Color'].default_value = color
        strength_map = {'face': 0.94, 'hair': 1.0, 'cloth': 1.0, 'skin': 0.90, 'stockings': 0.92, 'transparent': 0.84, 'prop': 0.88}
        node.inputs['Strength'].default_value = float(strength_map.get(family, 1.0))
        links.new(node.outputs['Emission'], out.inputs['Surface'])
        if hasattr(mat, 'blend_method'):
            mat.blend_method = 'OPAQUE'
        if hasattr(mat, 'shadow_method'):
            try: mat.shadow_method = 'OPAQUE'
            except Exception: pass
        if hasattr(mat, 'use_backface_culling'):
            mat.use_backface_culling = True
        mat.diffuse_color = color
    mat['AEF_V10_7A_SafeSilhouette'] = True
    mat['AEF_V10_7A_Character'] = char_name
    mat['AEF_V10_7A_Family'] = family if not invisible else 'invisible'
    mat['AEF_V10_7A_NoLineArt'] = True
    return mat


def _aef107a_cleanup(char_name=None):
    removed = 0
    for obj in list(bpy.data.objects):
        if not obj or obj.type != 'MESH':
            continue
        if not bool(obj.get('AEF_V10_7A_SafeSilhouette', False)):
            continue
        if char_name and str(obj.get('AEF_V10_7A_Character', '')) != str(char_name):
            continue
        bpy.data.objects.remove(obj, do_unlink=True)
        removed += 1
    for col in list(bpy.data.collections):
        if not col.name.startswith(AEF107A_COLLECTION_PREFIX):
            continue
        if char_name and col.name != f"{AEF107A_COLLECTION_PREFIX}{char_name}":
            continue
        try:
            bpy.data.collections.remove(col)
        except Exception:
            pass
    return removed


def _aef107a_get_collection(char_name):
    name = f"{AEF107A_COLLECTION_PREFIX}{char_name}"
    col = bpy.data.collections.get(name)
    if not col:
        col = bpy.data.collections.new(name)
        bpy.context.scene.collection.children.link(col)
    col['AEF_V10_7A_SafeSilhouette'] = True
    col['AEF_V10_7A_Character'] = char_name
    return col


def _aef107a_collect_source_meshes(char_name):
    prefix = f"AEF_V8_{char_name}_"
    eye_only = {'eyes', 'eyes2', 'eyes3', 'eyes4', 'eyes5', 'mouth', 'expression', 'expression2', '口内'}
    items = []
    for obj in bpy.context.scene.objects:
        if obj.type != 'MESH':
            continue
        if obj.name.startswith(AEF107A_OBJECT_PREFIX):
            continue
        mats = [slot.material for slot in obj.material_slots if slot.material and slot.material.name.startswith(prefix)]
        if not mats:
            continue
        cats = [str(m.get('AEF_V8_Category', '')).lower() for m in mats if m]
        catset = {c for c in cats if c}
        if catset and catset.issubset(eye_only):
            continue
        items.append((obj, mats, catset, cats))
    return items


def _aef107a_name_tokens(obj, mats=None):
    tokens = []
    try:
        tokens.append(obj.name.lower())
    except Exception:
        pass
    for m in (mats or []):
        try:
            tokens.append(m.name.lower())
        except Exception:
            pass
    return ' '.join(tokens)


def _aef107a_family_from_material(mat):
    if not mat:
        return 'cloth'
    try:
        name = mat.name.lower()
    except Exception:
        name = ''
    try:
        category = str(mat.get('AEF_V8_Category', '')).lower()
    except Exception:
        category = ''

    if any(tok in name for tok in AEF107A_STOCKINGS_TOKENS) or category in AEF107A_STOCKINGS_TOKENS:
        return 'stockings'
    if any(tok in name for tok in AEF107A_TRANSPARENT_TOKENS) or category in AEF107A_TRANSPARENT_TOKENS:
        return 'transparent'

    face_tokens = {'face', 'face2', '面', '表情', '表情2'}
    hair_tokens = {'hair'}
    prop_tokens = {'guitar', 'instrument', 'deco1', 'deco2'}
    skin_tokens = {'body', 'skin', 'arm', 'arms', 'hand', 'hands', '肌', '手'}
    cloth_tokens = {'clothes', 'clothes2', 'clothes3', 'cloth', 'mask', 'skirt'}

    if category in skin_tokens or any(tok in name for tok in ('hands', 'hand', 'arms', 'arm_skin', 'body_skin')):
        return 'skin'

    score = {'face': 0, 'hair': 0, 'cloth': 0, 'prop': 0}
    if category in face_tokens:
        score['face'] += 4
    elif category in hair_tokens:
        score['hair'] += 4
    elif category in prop_tokens:
        score['prop'] += 4
    elif category in cloth_tokens or 'cloth' in category or 'mask' in category:
        score['cloth'] += 3
    elif category:
        score['cloth'] += 1

    if any(tok in name for tok in ('face', 'head', '表情', '面')):
        score['face'] += 3
    if any(tok in name for tok in ('hair', 'bang', 'twintail', 'fringe', 'front hair', 'back hair')):
        score['hair'] += 4
    if any(tok in name for tok in ('guitar', 'bass', 'instrument', 'pickup', 'bridge', 'strap', 'string')):
        score['prop'] += 5
    if any(tok in name for tok in ('clothes', 'dress', 'corset', 'sleeve', 'skirt', 'mask', 'lace', 'frill', 'ribbon')):
        score['cloth'] += 2

    family = max(score.items(), key=lambda kv: kv[1])[0]
    if max(score.values()) <= 0:
        family = 'cloth'
    return family


def _aef107a_group_should_skip(obj, group, settings=None):
    family = str(group.get('family', 'cloth'))
    mat_names = ' '.join(group.get('material_names', []))
    token_blob = f"{getattr(obj, 'name', '')} {mat_names}".lower()
    if family == 'prop' and settings and not bool(getattr(settings, 'safe_silhouette_include_props', False)):
        return True, 'prop material group skipped (cleanup mode)'
    if family == 'prop' and any(tok in token_blob for tok in AEF107A_PROP_SKIP_TOKENS):
        return True, 'micro-prop material group filtered'
    if family == 'transparent' and 'mask' in token_blob:
        return True, 'mask transparency skipped for silhouette cleanup'
    if not group.get('material_indices'):
        return True, 'empty material group'
    return False, ''


def _aef107a_material_groups_for_object(obj, mats=None, settings=None):
    data = getattr(obj, 'data', None)
    if not data or not getattr(data, 'polygons', None):
        return []

    slot_face_counts = {}
    for poly in data.polygons:
        slot_face_counts[poly.material_index] = slot_face_counts.get(poly.material_index, 0) + 1

    groups = {}
    slots = getattr(obj, 'material_slots', [])
    for slot_index, slot in enumerate(slots):
        if slot_index not in slot_face_counts:
            continue
        mat = getattr(slot, 'material', None)
        if not mat:
            continue
        family = _aef107a_family_from_material(mat)
        bucket = groups.setdefault(family, {
            'family': family,
            'material_indices': [],
            'material_names': [],
            'poly_count': 0,
        })
        bucket['material_indices'].append(slot_index)
        bucket['material_names'].append(mat.name)
        bucket['poly_count'] += int(slot_face_counts.get(slot_index, 0))

    order = {'face': 0, 'hair': 1, 'skin': 2, 'cloth': 3, 'stockings': 4, 'transparent': 5, 'prop': 6}
    result = []
    for family, group in sorted(groups.items(), key=lambda kv: order.get(kv[0], 99)):
        skip, why = _aef107a_group_should_skip(obj, group, settings)
        group['skip'] = bool(skip)
        group['skip_reason'] = str(why)
        label_names = ', '.join(group.get('material_names', []))
        group['label'] = f"{family}: {label_names}" if label_names else family
        result.append(group)
    return result


# =====================================================================
# V10.9B3.9 — REMOTE SHELL SPIKE CULL
# ---------------------------------------------------------------------
# B3.8 proved the two giant diagonals are not V10.7B Curve accents: they
# remain even with every internal-accent collection hidden. At this point
# the most plausible source is real per-material shell geometry: a few
# remote/helper vertices or long thin islands copied from the MMD mesh and
# made visible by the inverted hull. B3.9 removes only extreme outlier
# geometry before Solidify, keeping normal character topology intact.
# =====================================================================
def _aef109b39_percentile(sorted_values, p):
    if not sorted_values:
        return 0.0
    idx = int(max(0, min(len(sorted_values) - 1, round((len(sorted_values) - 1) * float(p)))))
    return float(sorted_values[idx])


def _aef109b39_cull_remote_shell_spikes(bm, settings=None):
    if settings and not bool(getattr(settings, 'build_remote_shell_spike_cull_v109b39', True)):
        return 0
    verts = [v for v in bm.verts if v.link_faces]
    faces = list(bm.faces)
    if len(verts) < 24 or not faces:
        return 0

    # Robust center: coordinate-wise medians, resistant to a handful of
    # vertices tens of units away from the character.
    xs = sorted(float(v.co.x) for v in verts)
    ys = sorted(float(v.co.y) for v in verts)
    zs = sorted(float(v.co.z) for v in verts)
    mid = len(verts) // 2
    center = Vector((xs[mid], ys[mid], zs[mid]))

    dists = sorted(float((v.co - center).length) for v in verts)
    q80 = max(1e-8, _aef109b39_percentile(dists, 0.80))
    q95 = max(q80, _aef109b39_percentile(dists, 0.95))

    edge_lengths = sorted(float(e.calc_length()) for e in bm.edges if e.link_faces and e.calc_length() > 1e-9)
    median_edge = edge_lengths[len(edge_lengths)//2] if edge_lengths else 1e-4

    radius_factor = float(getattr(settings, 'remote_shell_radius_factor_v109b39', 3.25)) if settings else 3.25
    long_ratio = float(getattr(settings, 'remote_shell_long_edge_ratio_v109b39', 14.0)) if settings else 14.0
    component_aspect_limit = float(getattr(settings, 'remote_shell_component_aspect_v109b39', 12.0)) if settings else 12.0

    # Radius must be much larger than the normal 80th-percentile body radius,
    # but never so small that legitimate tiny materials are clipped.
    radius_limit = max(q80 * max(2.0, radius_factor), q95 * 1.55, median_edge * 55.0)
    long_limit = max(median_edge * max(8.0, long_ratio), q80 * 1.35)

    bad = set()
    for f in faces:
        fd = [float((v.co - center).length) for v in f.verts]
        if not fd:
            continue
        longest = max((float(e.calc_length()) for e in f.edges), default=0.0)
        centroid_d = float((f.calc_center_median() - center).length)
        # Fully remote islands are never part of the visible character shell.
        if min(fd) > radius_limit or centroid_d > radius_limit * 1.08:
            bad.add(f)
            continue
        # A face connecting the character to a far-away helper vertex creates
        # precisely the huge diagonal ribbon seen in the screenshots.
        if max(fd) > radius_limit and longest > long_limit:
            bad.add(f)

    # Extra guard for separate long, needle-like components. This catches
    # subdivided strips where no individual edge is extreme enough.
    remaining = [f for f in faces if f not in bad]
    unseen = set(remaining)
    comps = []
    while unseen:
        seed = unseen.pop()
        stack = [seed]
        comp = [seed]
        while stack:
            f = stack.pop()
            for e in f.edges:
                for nf in e.link_faces:
                    if nf in unseen:
                        unseen.remove(nf)
                        stack.append(nf)
                        comp.append(nf)
        comps.append(comp)

    total_faces = max(1, len(remaining))
    for comp in comps:
        cv = {v for f in comp for v in f.verts}
        if len(cv) < 3:
            continue
        minx = min(float(v.co.x) for v in cv); maxx = max(float(v.co.x) for v in cv)
        miny = min(float(v.co.y) for v in cv); maxy = max(float(v.co.y) for v in cv)
        minz = min(float(v.co.z) for v in cv); maxz = max(float(v.co.z) for v in cv)
        ext = sorted((maxx-minx, maxy-miny, maxz-minz), reverse=True)
        largest = max(ext[0], 1e-9)
        second = max(ext[1], median_edge * 0.25, 1e-9)
        aspect = largest / second
        small_component = len(comp) <= max(900, int(total_faces * 0.12))
        oversized = largest > max(q80 * 3.0, median_edge * 70.0)
        if small_component and oversized and aspect > component_aspect_limit:
            bad.update(comp)

    if bad:
        bmesh.ops.delete(bm, geom=list(bad), context='FACES')
    return len(bad)


def _aef107a_prune_mesh_to_material_indices(mesh, keep_indices, settings=None):
    keep = {int(i) for i in (keep_indices or [])}
    if not keep:
        return False
    removed_pathological = 0
    removed_remote = 0
    bm = bmesh.new()
    try:
        bm.from_mesh(mesh)
        doomed = [f for f in bm.faces if int(f.material_index) not in keep]
        if doomed:
            bmesh.ops.delete(bm, geom=doomed, context='FACES')

        # B3.9: robust outlier cull before the older thin-triangle guard.
        removed_remote = _aef109b39_cull_remote_shell_spikes(bm, settings)

        # B3.7 artifact guard. Per-material shells make texture-alpha cards
        # geometrically opaque. A single extremely long/thin triangle can then
        # become the giant diagonal ink stroke seen in viewport. Reject only
        # severe edge/area outliers, leaving normal character topology intact.
        if not settings or bool(getattr(settings, 'build_outline_artifact_cleanup_v109b37', True)):
            edge_lengths = [float(e.calc_length()) for e in bm.edges if e.link_faces and e.calc_length() > 1e-9]
            if edge_lengths:
                edge_lengths.sort()
                median_edge = edge_lengths[len(edge_lengths) // 2]
                ratio = float(getattr(settings, 'artifact_long_edge_ratio_v109b37', 28.0)) if settings else 28.0
                thin_limit = float(getattr(settings, 'artifact_thin_triangle_ratio_v109b37', 0.010)) if settings else 0.010
                bad_faces = []
                threshold = max(1e-8, median_edge * max(8.0, ratio))
                for f in list(bm.faces):
                    lengths = [float(e.calc_length()) for e in f.edges]
                    if not lengths:
                        continue
                    longest = max(lengths)
                    if longest <= threshold:
                        continue
                    area_ratio = float(f.calc_area()) / max(longest * longest, 1e-12)
                    if area_ratio < thin_limit:
                        bad_faces.append(f)
                if bad_faces:
                    removed_pathological = len(bad_faces)
                    bmesh.ops.delete(bm, geom=bad_faces, context='FACES')

        loose = [v for v in bm.verts if not v.link_faces]
        if loose:
            bmesh.ops.delete(bm, geom=loose, context='VERTS')
        bm.to_mesh(mesh)
    finally:
        bm.free()
    mesh.update()
    try:
        mesh.validate(clean_customdata=False)
    except Exception:
        pass
    try:
        mesh['AEF_V10_9B3_7_PathologicalFacesRemoved'] = int(removed_pathological)
        mesh['AEF_V10_9B3_9_RemoteSpikeFacesRemoved'] = int(removed_remote)
    except Exception:
        pass
    return len(getattr(mesh, 'polygons', [])) > 0


def _aef107a_family_from_categories(obj, mats, catset, cats):
    name = _aef107a_name_tokens(obj, mats)
    if any(tok in name for tok in AEF107A_STOCKINGS_TOKENS) or any(tok in catset for tok in AEF107A_STOCKINGS_TOKENS):
        return 'stockings'
    if any(tok in name for tok in AEF107A_TRANSPARENT_TOKENS) or any(tok in catset for tok in AEF107A_TRANSPARENT_TOKENS):
        return 'transparent'

    score = {'face': 0, 'hair': 0, 'cloth': 0, 'prop': 0}
    face_tokens = {'face', 'face2', '面', '表情', '表情2'}
    hair_tokens = {'hair'}
    prop_tokens = {'guitar', 'instrument', 'deco1', 'deco2'}
    cloth_tokens = {'clothes', 'clothes2', 'clothes3', 'cloth', 'mask', 'skirt'}
    for c in cats:
        lc = str(c).lower()
        if lc in face_tokens:
            score['face'] += 3
        elif lc in hair_tokens:
            score['hair'] += 3
        elif lc in prop_tokens:
            score['prop'] += 3
        elif lc in cloth_tokens or 'cloth' in lc or 'mask' in lc:
            score['cloth'] += 2
        else:
            score['cloth'] += 1
    if 'guitar' in name or 'bass' in name or 'instrument' in name:
        score['prop'] += 5
    if 'hair' in name or 'bang' in name or 'twintail' in name:
        score['hair'] += 4
    if 'face' in name or 'head' in name:
        score['face'] += 3
    family = max(score.items(), key=lambda kv: kv[1])[0]
    if max(score.values()) <= 0:
        family = 'cloth'
    return family


def _aef107a_character_scale(items):
    extent = 1.65
    for obj, _mats, _catset, _cats in items:
        try:
            extent = max(extent, max(float(v) for v in obj.dimensions))
        except Exception:
            pass
    return max(0.85, min(1.25, extent / 1.65))


def _aef107a_camera_factor(obj):
    cam = getattr(bpy.context.scene, 'camera', None)
    if not cam:
        return 1.0
    try:
        if getattr(cam.data, 'type', '') == 'ORTHO':
            return 1.0
    except Exception:
        pass
    try:
        dist = (cam.matrix_world.translation - obj.matrix_world.translation).length
        return max(0.85, min(1.35, dist / 8.0))
    except Exception:
        return 1.0


def _aef107a_should_skip(obj, mats, family, catset, cats, settings=None):
    token_blob = _aef107a_name_tokens(obj, mats)
    if family == 'prop' and settings and not bool(getattr(settings, 'safe_silhouette_include_props', False)):
        return True, 'props disabled (cleanup mode)'
    if any(tok in token_blob for tok in AEF107A_PROP_SKIP_TOKENS):
        return True, 'micro-prop token filtered'
    try:
        max_dim = max(float(v) for v in obj.dimensions)
    except Exception:
        max_dim = 999.0
    poly_count = len(getattr(obj.data, 'polygons', [])) if getattr(obj, 'data', None) else 0
    if family in {'prop', 'transparent'} and max_dim < AEF107A_TINY_DIM_THRESHOLD and poly_count < AEF107A_TINY_POLY_THRESHOLD:
        return True, f'tiny {family} mesh filtered'
    if family == 'transparent' and 'mask' in catset:
        return True, 'mask transparency skipped for silhouette cleanup'
    return False, ''


def _aef109b3_doloris_outline_multiplier(char_name, family, settings):
    """V10.9B3: normalize Doloris' safe shell without touching Oblivionis.

    Native Blender Line Art remains quarantined. This only scales the safe
    Solidify/inverted-hull thickness that is already used by V10.7A.1.
    """
    if not settings or not bool(getattr(settings, 'build_doloris_outline_equalization_v109b3', True)):
        return 1.0
    if not str(char_name).lower().startswith('doloris'):
        return 1.0

    global_gain = float(getattr(settings, 'doloris_outline_gain_v109b3', 1.28))
    family_gain = {
        'face': float(getattr(settings, 'doloris_face_outline_gain_v109b3', 1.20)),
        'hair': float(getattr(settings, 'doloris_hair_outline_gain_v109b3', 1.34)),
        'cloth': float(getattr(settings, 'doloris_cloth_outline_gain_v109b3', 1.15)),
        'skin': 0.92,
        'stockings': 1.06,
        'transparent': float(getattr(settings, 'doloris_transparent_outline_gain_v109b3', 1.04)),
        # Guitar/props are intentionally held near baseline: B3 is a character
        # outline equalization pass, not a prop-thickening pass.
        'prop': 0.96,
    }.get(str(family), 1.0)
    return max(0.50, min(2.40, global_gain * family_gain))


# =====================================================================
# V10.9B3.3 — DOLORIS OUTLINE THICKNESS TUNING
# ---------------------------------------------------------------------
# Una vez corregido V10.9B3.2 para que Doloris sí reciba el Safe
# Silhouette, esta pasada afina el grosor final para acercarlo mejor al
# acabado de la serie: rostro/máscara y flequillo bajan un poco más que
# ropa, manteniendo a Oblivionis como referencia y sin reactivar LINEART.
# =====================================================================
def _aef109b33_doloris_outline_tuning_multiplier(char_name, family, settings):
    if not settings or not bool(getattr(settings, 'build_doloris_outline_thickness_tuning_v109b33', True)):
        return 1.0
    if not str(char_name).lower().startswith('doloris'):
        return 1.0

    global_trim = float(getattr(settings, 'doloris_outline_global_trim_v109b33', 0.92))
    family_trim = {
        # Face/mask gets the strongest trim so the expression does not look boxed in.
        'face': float(getattr(settings, 'doloris_face_outline_trim_v109b33', 0.82)),
        # Hair still needs presence, but less than the raw B3.2 result.
        'hair': float(getattr(settings, 'doloris_hair_outline_trim_v109b33', 0.88)),
        # Cloth stays slightly more present than the face to preserve readability.
        'cloth': float(getattr(settings, 'doloris_cloth_outline_trim_v109b33', 0.92)),
        'skin': 0.72,
        'stockings': float(getattr(settings, 'doloris_stockings_outline_trim_v109b33', 0.88)),
        'transparent': float(getattr(settings, 'doloris_transparent_outline_trim_v109b33', 0.84)),
        'prop': float(getattr(settings, 'doloris_prop_outline_trim_v109b33', 1.00)),
    }.get(str(family), 1.0)
    return max(0.35, min(1.15, global_trim * family_trim))


# =====================================================================
# V10.9B3.4 — AVE MUJICA OUTLINE REFERENCE CLEANUP
# ---------------------------------------------------------------------
# Reference pass based on the supplied series stills. The series keeps
# Doloris' outer contour present but distinctly slimmer than B3.2/B3.3,
# especially in bangs, face/mask and fingers. This multiplier is applied
# after B3 equalization + B3.3 trim, so it also works on scenes that keep
# the previous saved PropertyGroup values.
#
# Native Blender Line Art remains quarantined. V10.7B internal accents are
# Curve objects (not Grease Pencil strokes); B3.4 disables them for Doloris
# by default because they were generating hand/cloth line noise.
# =====================================================================
def _aef109b34_series_outline_multiplier(char_name, family, settings):
    if not settings or not bool(getattr(settings, 'build_ave_outline_reference_match_v109b34', True)):
        return 1.0
    if not str(char_name).lower().startswith('doloris'):
        return 1.0
    family_gain = {
        'face': float(getattr(settings, 'doloris_series_face_outline_v109b34', 0.75)),
        'hair': float(getattr(settings, 'doloris_series_hair_outline_v109b34', 0.62)),
        'skin': float(getattr(settings, 'doloris_series_skin_outline_v109b34', 0.62)),
        'cloth': float(getattr(settings, 'doloris_series_cloth_outline_v109b34', 0.72)),
        'stockings': float(getattr(settings, 'doloris_series_stockings_outline_v109b34', 0.74)),
        'transparent': float(getattr(settings, 'doloris_series_transparent_outline_v109b34', 0.68)),
        'prop': 1.0,
    }.get(str(family), 0.72)
    return max(0.30, min(1.10, family_gain))


# =====================================================================
# V10.9B3.5 — SERIES INK & CLEAN PREVIEW
# ---------------------------------------------------------------------
# Final outline calibration from the supplied Ave Mujica references.
# These are FINAL series factors that replace B3.4's factor when enabled,
# not an extra multiplier stacked on top. Effective target vs base shell:
#   face/hair ~0.64x, skin/hands ~0.25x, cloth ~0.72x.
# This matches the observed hierarchy: delicate face/hair/hands, slightly
# firmer wardrobe silhouette, and very restrained sheer/stocking contours.
# =====================================================================
def _aef109b35_series_ink_multiplier(char_name, family, settings):
    if not settings or not bool(getattr(settings, 'build_series_ink_clean_preview_v109b35', True)):
        return _aef109b34_series_outline_multiplier(char_name, family, settings)
    if not str(char_name).lower().startswith('doloris'):
        return 1.0
    family_gain = {
        'face': float(getattr(settings, 'doloris_series_face_ink_v109b35', 0.55)),
        'hair': float(getattr(settings, 'doloris_series_hair_ink_v109b35', 0.46)),
        'skin': float(getattr(settings, 'doloris_series_skin_ink_v109b35', 0.32)),
        'cloth': float(getattr(settings, 'doloris_series_cloth_ink_v109b35', 0.58)),
        'stockings': float(getattr(settings, 'doloris_series_stockings_ink_v109b35', 0.60)),
        'transparent': float(getattr(settings, 'doloris_series_transparent_ink_v109b35', 0.48)),
        'prop': 1.0,
    }.get(str(family), 0.58)
    return max(0.18, min(1.05, family_gain))


# =====================================================================
# V10.9B3.6 — ULTRA-FINE SERIES OUTLINE
# ---------------------------------------------------------------------
# B3.5 ya corrigió la arquitectura y la tinta, pero las referencias de la
# serie muestran un borde exterior todavía más fino. Esta pasada usa
# propiedades NUEVAS para que los valores se apliquen incluso al abrir un
# .blend que conserve sliders antiguos de B3.5. Los factores de B3.6
# REEMPLAZAN el factor final B3.5, no se acumulan encima.
#
# Objetivo efectivo aprox. frente al shell base previo a B3.x:
#   face ~0.39x | hair ~0.39x | skin/hands ~0.21x | cloth ~0.47x
# =====================================================================
def _aef109b36_ultrafine_series_multiplier(char_name, family, settings):
    if not settings or not bool(getattr(settings, 'build_ultrafine_series_outline_v109b36', True)):
        return _aef109b35_series_ink_multiplier(char_name, family, settings)
    if not str(char_name).lower().startswith('doloris'):
        return 1.0
    family_gain = {
        'face': float(getattr(settings, 'doloris_ultrafine_face_v109b36', 0.34)),
        'hair': float(getattr(settings, 'doloris_ultrafine_hair_v109b36', 0.28)),
        'skin': float(getattr(settings, 'doloris_ultrafine_skin_v109b36', 0.18)),
        'cloth': float(getattr(settings, 'doloris_ultrafine_cloth_v109b36', 0.38)),
        'stockings': float(getattr(settings, 'doloris_ultrafine_stockings_v109b36', 0.40)),
        'transparent': float(getattr(settings, 'doloris_ultrafine_transparent_v109b36', 0.30)),
        'prop': 1.0,
    }.get(str(family), 0.38)
    return max(0.10, min(1.05, family_gain))


# =====================================================================
# V10.9B3.7 — ARTIFACT CLEANUP + OBLIVIONIS OUTLINE MATCH
# ---------------------------------------------------------------------
# B3.6 locks Doloris' series-like thickness. B3.7 does not reopen that
# look except for a hand/skin micro-trim used to suppress inverted-hull
# wedges between fingers. It also:
#   - rejects pathological long/thin shell triangles that can become giant
#     diagonal ink strokes when alpha-card/helper geometry is outlined;
#   - quarantines old renderable Curve/Grease Pencil helper strokes for
#     Doloris without deleting them;
#   - trims Oblivionis moderately so both characters share the same visual
#     ink hierarchy. Native Blender Line Art stays quarantined.
# =====================================================================
def _aef109b37_doloris_artifact_multiplier(char_name, family, settings):
    if not settings or not bool(getattr(settings, 'build_outline_artifact_cleanup_v109b37', True)):
        return 1.0
    if not str(char_name).lower().startswith('doloris'):
        return 1.0
    if str(family) == 'skin':
        return float(getattr(settings, 'doloris_skin_artifact_trim_v109b37', 0.55))
    return 1.0


def _aef109b37_oblivionis_match_multiplier(char_name, family, settings):
    if not settings or not bool(getattr(settings, 'build_oblivionis_outline_match_v109b37', True)):
        return 1.0
    if not str(char_name).lower().startswith('oblivionis'):
        return 1.0
    global_trim = float(getattr(settings, 'oblivionis_outline_global_trim_v109b37', 0.84))
    family_trim = {
        'face': float(getattr(settings, 'oblivionis_face_outline_trim_v109b37', 0.95)),
        'hair': float(getattr(settings, 'oblivionis_hair_outline_trim_v109b37', 0.92)),
        'skin': float(getattr(settings, 'oblivionis_skin_outline_trim_v109b37', 0.88)),
        'cloth': float(getattr(settings, 'oblivionis_cloth_outline_trim_v109b37', 1.00)),
        'stockings': float(getattr(settings, 'oblivionis_stockings_outline_trim_v109b37', 1.00)),
        'transparent': float(getattr(settings, 'oblivionis_transparent_outline_trim_v109b37', 0.92)),
        'prop': 1.0,
    }.get(str(family), 1.0)
    return max(0.40, min(1.05, global_trim * family_trim))


def _aef109b37_quarantine_stray_doloris_strokes(settings=None):
    """Hide old renderable line helpers that can masquerade as outline spikes.

    Nothing is deleted. Safe Silhouette objects are MESH and are untouched.
    """
    if settings and not bool(getattr(settings, 'quarantine_stray_strokes_v109b37', True)):
        return 0
    changed = 0
    for obj in bpy.data.objects:
        if not obj or obj.type not in {'CURVE', 'GREASEPENCIL', 'GPENCIL'}:
            continue
        name = str(getattr(obj, 'name', ''))
        lname = name.lower()
        char_tag = str(obj.get('AEF_V9_1_Character', obj.get('AEF_V10_7B_Character', ''))).lower()
        is_doloris = ('doloris' in lname) or char_tag.startswith('doloris')
        if not is_doloris:
            continue
        is_line_helper = (
            bool(obj.get('AEF_V10_7B_InternalAccent', False))
            or bool(obj.get('AEF_V9_1_Tertiary', False))
            or bool(obj.get('AEF_V9_3_Tertiary', False))
            or bool(obj.get('AEF_V9_4_TertiaryArtist2', False))
            or 'lineart' in lname
            or 'tertiary' in lname
            or 'accent' in lname
        )
        if not is_line_helper:
            continue
        try:
            if not obj.hide_viewport:
                obj.hide_viewport = True
                changed += 1
        except Exception:
            pass
        try:
            if not obj.hide_render:
                obj.hide_render = True
                changed += 1
        except Exception:
            pass
        try:
            obj.hide_set(True)
        except Exception:
            pass
        try:
            obj['AEF_V10_9B3_7_StrayStrokeQuarantined'] = True
        except Exception:
            pass
    return changed


# =====================================================================
# V10.9B3.8 — FINAL STRAY-LINE CLEANUP + OBLIVIONIS MICRO-TRIM
# ---------------------------------------------------------------------
# B3.7 solved the hand wedge. The two remaining giant diagonals match the
# two V10.7B internal-accent segments that Oblivionis could still rebuild.
# B3.8 removes that last ambiguity by disabling/quarantining ALL AEF V10.7B
# curve accents for the final series look. It also gives Oblivionis one last
# very small global outline reduction without reopening Doloris.
# =====================================================================
def _aef109b38_oblivionis_final_multiplier(char_name, settings):
    if not settings or not bool(getattr(settings, 'build_final_series_cleanup_v109b38', True)):
        return 1.0
    if not str(char_name).lower().startswith('oblivionis'):
        return 1.0
    return max(0.70, min(1.00, float(getattr(settings, 'oblivionis_final_outline_trim_v109b38', 0.94))))


def _aef109b38_quarantine_internal_accents(settings=None):
    """Hide every AEF V10.7B internal-accent Curve in viewport and render.

    These are procedural Curve strokes, not native Grease Pencil Line Art.
    They are kept in the .blend for reversibility but are not part of the
    final Ave Mujica-style ink pass.
    """
    if settings and not bool(getattr(settings, 'quarantine_all_internal_accents_v109b38', True)):
        return 0
    changed = 0
    for obj in bpy.data.objects:
        if not obj:
            continue
        is_internal = bool(obj.get('AEF_V10_7B_InternalAccent', False)) or str(getattr(obj, 'name', '')).startswith(AEF107B_OBJECT_PREFIX)
        if not is_internal:
            continue
        try:
            if not obj.hide_viewport:
                obj.hide_viewport = True
                changed += 1
        except Exception:
            pass
        try:
            if not obj.hide_render:
                obj.hide_render = True
                changed += 1
        except Exception:
            pass
        try:
            obj.hide_set(True)
        except Exception:
            pass
        try:
            obj['AEF_V10_9B3_8_FinalAccentQuarantine'] = True
        except Exception:
            pass

    # Hide the dedicated accent collections as an additional viewport guard.
    for col in bpy.data.collections:
        if not col.name.startswith(AEF107B_COLLECTION_PREFIX):
            continue
        try:
            if not col.hide_viewport:
                col.hide_viewport = True
                changed += 1
        except Exception:
            pass
        try:
            if not col.hide_render:
                col.hide_render = True
                changed += 1
        except Exception:
            pass
    return changed


def _aef109b35_apply_clean_preview(settings=None):
    """Hide viewport-only clutter without deleting rigs, cameras or helpers.

    This is intentionally a presentation toggle. It only changes 3D View
    overlays/gizmos and viewport visibility of AEF tertiary guide helpers.
    Rendering and source rig data are untouched.
    """
    enabled = bool(getattr(settings, 'clean_preview_viewport_v109b35', True)) if settings else True
    changed = 0

    wm = getattr(bpy.context, 'window_manager', None)
    if wm:
        for win in getattr(wm, 'windows', []):
            screen = getattr(win, 'screen', None)
            if not screen:
                continue
            for area in screen.areas:
                if area.type != 'VIEW_3D':
                    continue
                for space in area.spaces:
                    if space.type != 'VIEW_3D':
                        continue
                    overlay = getattr(space, 'overlay', None)
                    if overlay:
                        targets = {
                            'show_relationship_lines': not enabled,
                            'show_extras': not enabled,
                            'show_bones': not enabled,
                            'show_motion_paths': not enabled,
                            'show_object_origins': not enabled,
                            'show_object_origins_all': not enabled,
                            'show_outline_selected': not enabled,
                            'show_wireframes': not enabled,
                            'show_text': not enabled,
                        }
                        for attr, value in targets.items():
                            if hasattr(overlay, attr):
                                try:
                                    if bool(getattr(overlay, attr)) != bool(value):
                                        setattr(overlay, attr, bool(value))
                                        changed += 1
                                except Exception:
                                    pass
                    if hasattr(space, 'show_gizmo'):
                        try:
                            desired = not enabled
                            if bool(space.show_gizmo) != desired:
                                space.show_gizmo = desired
                                changed += 1
                        except Exception:
                            pass

    # AEF tertiary markers are viewport helpers, never render content.
    show_guides = bool(getattr(settings, 'show_tertiary_guides_v107c1', True)) if settings else True
    for col in bpy.data.collections:
        if col.name.startswith('AEF_V10_7C_Tertiary_'):
            desired_hide = bool(enabled) or (not show_guides)
            try:
                if bool(col.hide_viewport) != desired_hide:
                    col.hide_viewport = desired_hide
                    changed += 1
            except Exception:
                pass

    for obj in bpy.data.objects:
        is_tertiary = (
            obj.name.startswith('AEF_V10_7C_Marker__')
            or bool(obj.get('AEF_V9_4_TertiaryGuide', False))
        )
        if not is_tertiary:
            continue
        desired_hide = bool(enabled) or (not show_guides)
        try:
            if bool(obj.hide_viewport) != desired_hide:
                obj.hide_viewport = desired_hide
                changed += 1
        except Exception:
            pass

    return changed


def _aef109b34_cleanup_viewport_relationship_lines(settings=None):
    if settings and not bool(getattr(settings, 'hide_relationship_lines_v109b34', True)):
        return 0
    changed = 0
    wm = getattr(bpy.context, 'window_manager', None)
    if not wm:
        return 0
    for win in getattr(wm, 'windows', []):
        screen = getattr(win, 'screen', None)
        if not screen:
            continue
        for area in screen.areas:
            if area.type != 'VIEW_3D':
                continue
            for space in area.spaces:
                if space.type != 'VIEW_3D':
                    continue
                overlay = getattr(space, 'overlay', None)
                if overlay and hasattr(overlay, 'show_relationship_lines'):
                    if overlay.show_relationship_lines:
                        overlay.show_relationship_lines = False
                        changed += 1
    return changed


# =====================================================================
# V10.9B3.10 — SHELL GEOMETRY SANITATION
# ---------------------------------------------------------------------
# Confirmado en viewport: las dos diagonales pertenecen a
# AEF_V10_7A_Silhouette_Doloris. La causa más peligrosa del pipeline es
# copiar una malla con Shape Keys y luego cambiar su topología por material:
# los KeyBlocks conservan la topología original y pueden evaluar vértices
# contra índices que ya no corresponden, generando triángulos/ribbons
# kilométricos. B3.10 hornea SOLO la deformación actual de Shape Keys en una
# malla base limpia antes de podar por material y conserva únicamente los
# modificadores ARMATURE necesarios para que la shell siga a la pose.
# =====================================================================
def _aef109b310_make_sanitized_shell_mesh(src_obj, settings=None):
    """Return (mesh, info) with current shape deformation baked and no Key data.

    Primary path: evaluate a temporary copy with every modifier removed. This
    applies Shape Keys/drivers in local mesh space but does not bake Armature or
    topology-changing modifiers. The real shell object later keeps only Armature
    modifiers, so it remains pose-aware without inheriting unsafe modifier stacks.
    """
    info = {
        'mode': 'raw_copy',
        'shape_keys': 0,
        'source_modifiers': [],
        'kept_modifiers': [],
        'stripped_modifiers': [],
    }
    if not src_obj or getattr(src_obj, 'type', None) != 'MESH' or not getattr(src_obj, 'data', None):
        return None, info

    try:
        keys = getattr(src_obj.data, 'shape_keys', None)
        if keys and getattr(keys, 'key_blocks', None):
            info['shape_keys'] = max(0, len(keys.key_blocks) - 1)
    except Exception:
        pass
    try:
        info['source_modifiers'] = [f'{m.name}:{m.type}' for m in src_obj.modifiers]
    except Exception:
        pass

    enabled = bool(getattr(settings, 'build_shell_geometry_sanitation_v109b310', True)) if settings else True
    if not enabled:
        return src_obj.data.copy(), info

    temp = None
    temp_mesh = None
    try:
        temp = src_obj.copy()
        temp.data = src_obj.data.copy()
        temp.name = f'AEF_TEMP_B310__{src_obj.name}'
        temp_mesh = temp.data
        # Shape Keys are evaluated, but modifiers are intentionally not.
        for mod in list(temp.modifiers):
            temp.modifiers.remove(mod)
        bpy.context.scene.collection.objects.link(temp)
        depsgraph = bpy.context.evaluated_depsgraph_get()
        try:
            depsgraph.update()
        except Exception:
            pass
        eval_temp = temp.evaluated_get(depsgraph)
        mesh = bpy.data.meshes.new_from_object(
            eval_temp,
            preserve_all_data_layers=True,
            depsgraph=depsgraph,
        )
        mesh.name = f'AEF_B310_Sanitized__{src_obj.data.name}'
        info['mode'] = 'shape_baked_local'
        # new_from_object returns a normal Mesh without the source Key datablock.
        return mesh, info
    except Exception as exc:
        log(f'  [V10.9B3.10 sanitize fallback] {src_obj.name}: local shape bake failed: {exc}')
        # Safety fallback: fully evaluated mesh. This freezes current pose, but is
        # still preferable to emitting kilometer-long shell triangles.
        try:
            depsgraph = bpy.context.evaluated_depsgraph_get()
            eval_src = src_obj.evaluated_get(depsgraph)
            mesh = bpy.data.meshes.new_from_object(
                eval_src,
                preserve_all_data_layers=True,
                depsgraph=depsgraph,
            )
            mesh.name = f'AEF_B310_FrozenEval__{src_obj.data.name}'
            info['mode'] = 'full_eval_fallback'
            return mesh, info
        except Exception as exc2:
            log(f'  [V10.9B3.10 sanitize fallback] {src_obj.name}: full eval failed: {exc2}')
            info['mode'] = 'raw_copy_fallback'
            return src_obj.data.copy(), info
    finally:
        if temp is not None:
            try:
                bpy.data.objects.remove(temp, do_unlink=True)
            except Exception:
                pass
        if temp_mesh is not None and getattr(temp_mesh, 'users', 1) == 0:
            try:
                bpy.data.meshes.remove(temp_mesh)
            except Exception:
                pass


def _aef109b310_sanitize_shell_modifiers(dup, info, settings=None):
    """Keep only Armature on shape-baked shells; full-eval fallback keeps none."""
    enabled = bool(getattr(settings, 'build_shell_geometry_sanitation_v109b310', True)) if settings else True
    if not enabled or not dup:
        return
    mode = str(info.get('mode', 'raw_copy'))
    keep_armature = bool(getattr(settings, 'shell_sanitation_keep_armature_v109b310', True)) if settings else True
    for mod in list(dup.modifiers):
        keep = keep_armature and mode == 'shape_baked_local' and mod.type == 'ARMATURE'
        if keep:
            info['kept_modifiers'].append(f'{mod.name}:{mod.type}')
            continue
        info['stripped_modifiers'].append(f'{mod.name}:{mod.type}')
        try:
            dup.modifiers.remove(mod)
        except Exception:
            pass


# =====================================================================
# V10.9B3.11 — POST-ARMATURE SHELL FREEZE + HARD LONG-EDGE CULL
# ---------------------------------------------------------------------
# Las dos diagonales viven en Silhouette_Doloris y sobreviven a los culls
# pre-deformación. B3.11 congela la shell DESPUÉS del Armature, elimina los
# modifiers ya horneados y poda outliers en la geometría realmente evaluada.
# La shell queda ligada al shot actual; tras cambiar pose basta reconstruir.
# =====================================================================
def _aef109b311_post_eval_hard_cull(mesh, settings=None):
    if not mesh or not getattr(mesh, 'polygons', None):
        return 0, 0
    bm = bmesh.new()
    removed_faces = 0
    removed_edges = 0
    try:
        bm.from_mesh(mesh)
        verts = [v for v in bm.verts if v.link_faces]
        if len(verts) < 8:
            return 0, 0
        xs = sorted(float(v.co.x) for v in verts)
        ys = sorted(float(v.co.y) for v in verts)
        zs = sorted(float(v.co.z) for v in verts)
        mid = len(verts) // 2
        center = Vector((xs[mid], ys[mid], zs[mid]))
        dists = sorted(float((v.co - center).length) for v in verts)
        q90 = max(1e-8, _aef109b39_percentile(dists, 0.90))
        lengths_all = sorted(float(e.calc_length()) for e in bm.edges if e.calc_length() > 1e-9)
        if not lengths_all:
            return 0, 0
        median_edge = max(1e-9, lengths_all[len(lengths_all)//2])
        long_ratio = float(getattr(settings, 'post_eval_long_edge_ratio_v109b311', 16.0)) if settings else 16.0
        radius_factor = float(getattr(settings, 'post_eval_remote_radius_v109b311', 2.35)) if settings else 2.35
        long_limit = max(median_edge * max(10.0, long_ratio), q90 * 0.82)
        radius_limit = max(q90 * max(1.8, radius_factor), median_edge * 70.0)
        bad_faces = set()
        for f in list(bm.faces):
            fd = [float((v.co - center).length) for v in f.verts]
            fl = [float(e.calc_length()) for e in f.edges]
            if not fd or not fl:
                continue
            longest = max(fl)
            centroid_d = float((f.calc_center_median() - center).length)
            if longest > long_limit or (max(fd) > radius_limit and centroid_d > radius_limit * 0.72):
                bad_faces.add(f)
        if bad_faces:
            removed_faces = len(bad_faces)
            bmesh.ops.delete(bm, geom=list(bad_faces), context='FACES')
        loose_edges = [e for e in bm.edges if not e.link_faces]
        if loose_edges:
            removed_edges = len(loose_edges)
            bmesh.ops.delete(bm, geom=loose_edges, context='EDGES')
        loose_verts = [v for v in bm.verts if not v.link_faces and not v.link_edges]
        if loose_verts:
            bmesh.ops.delete(bm, geom=loose_verts, context='VERTS')
        bm.to_mesh(mesh)
    finally:
        bm.free()
    mesh.update()
    try:
        mesh.validate(clean_customdata=False)
    except Exception:
        pass
    return removed_faces, removed_edges


def _aef109b311_freeze_shell_after_armature(dup, char_name, settings=None):
    info = {'frozen': False, 'faces_removed': 0, 'edges_removed': 0, 'mode': 'off'}
    enabled = bool(getattr(settings, 'build_post_armature_shell_freeze_v109b311', True)) if settings else True
    if not enabled or not dup or not str(char_name).lower().startswith('doloris'):
        return info
    depsgraph = bpy.context.evaluated_depsgraph_get()
    old_mesh = getattr(dup, 'data', None)
    try:
        try:
            depsgraph.update()
        except Exception:
            pass
        eval_dup = dup.evaluated_get(depsgraph)
        frozen = bpy.data.meshes.new_from_object(eval_dup, preserve_all_data_layers=True, depsgraph=depsgraph)
        frozen.name = f'AEF_B311_PostArmature__{old_mesh.name if old_mesh else dup.name}'
        dup.data = frozen
        for mod in list(dup.modifiers):
            try:
                dup.modifiers.remove(mod)
            except Exception:
                pass
        rf, re_ = _aef109b311_post_eval_hard_cull(frozen, settings)
        info.update({'frozen': True, 'faces_removed': int(rf), 'edges_removed': int(re_), 'mode': 'post_armature_frozen'})
        if old_mesh is not None and getattr(old_mesh, 'users', 1) == 0:
            try:
                bpy.data.meshes.remove(old_mesh)
            except Exception:
                pass
    except Exception as exc:
        info['mode'] = 'freeze_failed'
        log(f'  [V10.9B3.11 freeze warning] {dup.name}: {exc}')
    return info


# =====================================================================
# V10.9B3.12 — POST-SOLIDIFY CHARACTER ENVELOPE CLAMP
# ---------------------------------------------------------------------
# B3.11 confirmó que las dos diagonales NO están en la geometría base
# saneada ni en el resultado post-Armature. Por descarte, el punto que aún
# podía fabricarlas era SOLIDIFY sobre alguna frontera/no-manifold del shell.
# B3.12 evalúa y HORNEA Solidify, y después elimina cualquier cara generada
# que salga fuera de la envolvente world-space real del personaje fuente.
# De este modo no depende de longitudes/percentiles internos del shell: una
# diagonal kilométrica simplemente no puede sobrevivir fuera del volumen
# ocupado por Doloris. El original y la guitarra NO se modifican.
# =====================================================================
def _aef109b312_character_world_envelope(items, settings=None):
    points = []
    for entry in (items or []):
        try:
            obj = entry[0]
        except Exception:
            continue
        if not obj or getattr(obj, 'type', None) != 'MESH':
            continue
        try:
            for corner in obj.bound_box:
                points.append(obj.matrix_world @ Vector(corner))
        except Exception:
            pass
    if not points:
        return None
    mn = Vector((min(p.x for p in points), min(p.y for p in points), min(p.z for p in points)))
    mx = Vector((max(p.x for p in points), max(p.y for p in points), max(p.z for p in points)))
    span = mx - mn
    margin = float(getattr(settings, 'post_solidify_envelope_margin_v109b312', 0.16)) if settings else 0.16
    # Axis-relative margin plus a tiny absolute pad for the inverted hull.
    pad = Vector((
        max(0.015, abs(span.x) * margin),
        max(0.015, abs(span.y) * margin),
        max(0.015, abs(span.z) * margin),
    ))
    return (mn - pad, mx + pad)


def _aef109b312_world_outside(co_world, envelope):
    if not envelope:
        return False
    mn, mx = envelope
    return (
        co_world.x < mn.x or co_world.x > mx.x or
        co_world.y < mn.y or co_world.y > mx.y or
        co_world.z < mn.z or co_world.z > mx.z
    )


def _aef109b312_bake_solidify_and_clip(dup, char_name, family, envelope, settings=None):
    info = {
        'baked': False,
        'faces_removed': 0,
        'edges_removed': 0,
        'verts_removed': 0,
        'outside_before': 0,
        'mode': 'off',
    }
    enabled = bool(getattr(settings, 'build_post_solidify_envelope_clamp_v109b312', True)) if settings else True
    if not enabled or not dup or not str(char_name).lower().startswith('doloris') or not envelope:
        return info

    depsgraph = bpy.context.evaluated_depsgraph_get()
    old_mesh = getattr(dup, 'data', None)
    try:
        try:
            depsgraph.update()
        except Exception:
            pass
        eval_dup = dup.evaluated_get(depsgraph)
        baked = bpy.data.meshes.new_from_object(
            eval_dup,
            preserve_all_data_layers=True,
            depsgraph=depsgraph,
        )
        baked.name = f'AEF_B312_PostSolidify__{old_mesh.name if old_mesh else dup.name}'
        dup.data = baked
        for mod in list(dup.modifiers):
            try:
                dup.modifiers.remove(mod)
            except Exception:
                pass

        bm = bmesh.new()
        try:
            bm.from_mesh(baked)
            mw = dup.matrix_world.copy()
            bad_faces = set()
            outside_verts = set()
            for f in list(bm.faces):
                face_outside = False
                for v in f.verts:
                    try:
                        wco = mw @ v.co
                    except Exception:
                        wco = v.co
                    if _aef109b312_world_outside(wco, envelope):
                        outside_verts.add(v)
                        face_outside = True
                if face_outside:
                    bad_faces.add(f)
            info['outside_before'] = len(outside_verts)
            if bad_faces:
                info['faces_removed'] = len(bad_faces)
                bmesh.ops.delete(bm, geom=list(bad_faces), context='FACES')

            loose_edges = [e for e in bm.edges if not e.link_faces]
            if loose_edges:
                info['edges_removed'] = len(loose_edges)
                bmesh.ops.delete(bm, geom=loose_edges, context='EDGES')
            loose_verts = [v for v in bm.verts if not v.link_faces and not v.link_edges]
            if loose_verts:
                info['verts_removed'] = len(loose_verts)
                bmesh.ops.delete(bm, geom=loose_verts, context='VERTS')
            bm.to_mesh(baked)
        finally:
            bm.free()

        baked.update()
        try:
            baked.validate(clean_customdata=False)
        except Exception:
            pass
        info['baked'] = True
        info['mode'] = 'post_solidify_envelope_clamped'
        if old_mesh is not None and getattr(old_mesh, 'users', 1) == 0:
            try:
                bpy.data.meshes.remove(old_mesh)
            except Exception:
                pass
        if info['faces_removed'] or info['outside_before']:
            log(
                f"  [V10.9B3.12 clamp] {dup.name}: family={family} "
                f"outsideVerts={info['outside_before']} facesRemoved={info['faces_removed']} "
                f"edgesRemoved={info['edges_removed']} vertsRemoved={info['verts_removed']}"
            )
    except Exception as exc:
        info['mode'] = 'post_solidify_clamp_failed'
        log(f'  [V10.9B3.12 clamp warning] {dup.name}: {exc}')
    return info


def _aef107a_shell_thickness(profile, family, obj, settings, char_scale, char_name=None):
    base = AEF107A_FAMILY_BASE.get(profile, AEF107A_FAMILY_BASE['AVE']).get(family, 0.0022)
    strength = float(getattr(settings, 'safe_silhouette_strength', 1.0)) if settings else 1.0
    equalize = _aef109b3_doloris_outline_multiplier(char_name, family, settings)
    tuning = _aef109b33_doloris_outline_tuning_multiplier(char_name, family, settings)
    series_match = _aef109b36_ultrafine_series_multiplier(char_name, family, settings)
    artifact_trim = _aef109b37_doloris_artifact_multiplier(char_name, family, settings)
    oblivionis_match = _aef109b37_oblivionis_match_multiplier(char_name, family, settings)
    oblivionis_final = _aef109b38_oblivionis_final_multiplier(char_name, settings)
    return base * char_scale * _aef107a_camera_factor(obj) * strength * equalize * tuning * series_match * artifact_trim * oblivionis_match * oblivionis_final


def _aef107a_build_shell_object(src_obj, char_name, family, profile, settings, target_collection, char_scale, material_indices=None, source_label=None, character_envelope=None):
    dup = src_obj.copy()
    sanitized_mesh, sanitation_info = _aef109b310_make_sanitized_shell_mesh(src_obj, settings)
    if sanitized_mesh is None:
        return None
    dup.data = sanitized_mesh
    dup.animation_data_clear()
    source_tag = source_label or src_obj.name
    dup.name = f"{AEF107A_OBJECT_PREFIX}{char_name}__{src_obj.name}__{family}"
    dup.matrix_world = src_obj.matrix_world.copy()
    dup.parent = src_obj.parent
    dup.parent_type = src_obj.parent_type
    dup.parent_bone = src_obj.parent_bone
    target_collection.objects.link(dup)

    # B3.10: the per-material shell must not inherit Shape Keys/topology-changing
    # modifier stacks. Keep only Armature on the locally shape-baked path.
    _aef109b310_sanitize_shell_modifiers(dup, sanitation_info, settings)

    mesh = dup.data
    if material_indices:
        ok = _aef107a_prune_mesh_to_material_indices(mesh, material_indices, settings)
        if not ok:
            bpy.data.objects.remove(dup, do_unlink=True)
            return None

    # B3.11: freeze Doloris after Armature, then cull post-deformation spikes.
    freeze311 = _aef109b311_freeze_shell_after_armature(dup, char_name, settings)
    mesh = dup.data

    inv = _aef107a_get_material(char_name, invisible=True, settings=settings)
    outline = _aef107a_get_material(char_name, family=family, invisible=False, settings=settings)
    try:
        mesh.materials.clear()
    except Exception:
        while len(mesh.materials):
            mesh.materials.pop(index=len(mesh.materials)-1)
    mesh.materials.append(inv)
    mesh.materials.append(outline)
    for poly in mesh.polygons:
        poly.material_index = 0

    for mod in list(dup.modifiers):
        if mod.type in {'LINEART', 'GREASEPENCIL_LINEART'}:
            dup.modifiers.remove(mod)

    solid = dup.modifiers.new(name='AEF V10.7A.1 • Safe Silhouette Cleanup', type='SOLIDIFY')
    solid.thickness = _aef107a_shell_thickness(profile, family, src_obj, settings, char_scale, char_name=char_name)
    solid.offset = 1.0
    solid.material_offset = 1
    if hasattr(solid, 'use_flip_normals'):
        solid.use_flip_normals = True
    b37_skin_cleanup = (
        settings
        and bool(getattr(settings, 'build_outline_artifact_cleanup_v109b37', True))
        and str(char_name).lower().startswith('doloris')
        and str(family) == 'skin'
    )
    if hasattr(solid, 'use_even_offset'):
        # Even Offset exaggerates acute finger-web corners. Disable it only on
        # Doloris skin shells; all other families retain the established look.
        solid.use_even_offset = not bool(b37_skin_cleanup)
    if hasattr(solid, 'use_quality_normals'):
        solid.use_quality_normals = True
    if hasattr(solid, 'use_rim'):
        solid.use_rim = False
    if hasattr(solid, 'thickness_clamp'):
        solid.thickness_clamp = float(getattr(settings, 'doloris_skin_solidify_clamp_v109b37', 0.55)) if b37_skin_cleanup else 0.0

    # B3.12: the remaining diagonals survive every pre-Solidify sanitation.
    # Bake Solidify itself, then clip generated faces against the source
    # character's world-space envelope. This targets the actual last stage.
    solid_thickness = float(solid.thickness)
    clamp312 = _aef109b312_bake_solidify_and_clip(
        dup, char_name, family, character_envelope, settings
    )
    mesh = dup.data

    dup.hide_select = True
    dup.show_name = False
    dup.show_in_front = False
    try:
        dup.visible_shadow = False
    except Exception:
        pass
    dup['AEF_V10_7A_SafeSilhouette'] = True
    dup['AEF_V10_7A_Character'] = char_name
    dup['AEF_V10_7A_Family'] = family
    dup['AEF_V10_7A_SourceObject'] = src_obj.name
    dup['AEF_V10_7A_SourceGroup'] = source_tag
    dup['AEF_V10_7A_SourceMaterialIndices'] = ','.join(str(int(i)) for i in (material_indices or []))
    dup['AEF_V10_7A_Thickness'] = solid_thickness
    dup['AEF_V10_9B3_OutlineEqualization'] = float(_aef109b3_doloris_outline_multiplier(char_name, family, settings))
    dup['AEF_V10_9B3_3_ThicknessTuning'] = float(_aef109b33_doloris_outline_tuning_multiplier(char_name, family, settings))
    dup['AEF_V10_9B3_4_SeriesOutlineMatch'] = float(_aef109b34_series_outline_multiplier(char_name, family, settings))
    dup['AEF_V10_9B3_5_SeriesInkFinal'] = float(_aef109b35_series_ink_multiplier(char_name, family, settings))
    dup['AEF_V10_9B3_6_UltraFineSeries'] = float(_aef109b36_ultrafine_series_multiplier(char_name, family, settings))
    dup['AEF_V10_9B3_7_DolorisArtifactTrim'] = float(_aef109b37_doloris_artifact_multiplier(char_name, family, settings))
    dup['AEF_V10_9B3_7_OblivionisMatch'] = float(_aef109b37_oblivionis_match_multiplier(char_name, family, settings))
    dup['AEF_V10_9B3_8_OblivionisFinalTrim'] = float(_aef109b38_oblivionis_final_multiplier(char_name, settings))
    dup['AEF_V10_9B3_9_RemoteSpikeFacesRemoved'] = int(mesh.get('AEF_V10_9B3_9_RemoteSpikeFacesRemoved', 0))
    dup['AEF_V10_9B3_7_PathologicalFacesRemoved'] = int(mesh.get('AEF_V10_9B3_7_PathologicalFacesRemoved', 0))
    dup['AEF_V10_9B3_10_ShellSanitation'] = True
    dup['AEF_V10_9B3_10_SanitationMode'] = str(sanitation_info.get('mode', 'unknown'))
    dup['AEF_V10_9B3_10_SourceShapeKeys'] = int(sanitation_info.get('shape_keys', 0))
    dup['AEF_V10_9B3_10_KeptModifiers'] = ' | '.join(sanitation_info.get('kept_modifiers', []))
    dup['AEF_V10_9B3_10_StrippedModifiers'] = ' | '.join(sanitation_info.get('stripped_modifiers', []))
    dup['AEF_V10_9B3_11_PostArmatureFreeze'] = bool(freeze311.get('frozen', False))
    dup['AEF_V10_9B3_11_FreezeMode'] = str(freeze311.get('mode', 'off'))
    dup['AEF_V10_9B3_11_PostFacesRemoved'] = int(freeze311.get('faces_removed', 0))
    dup['AEF_V10_9B3_11_PostEdgesRemoved'] = int(freeze311.get('edges_removed', 0))
    dup['AEF_V10_9B3_12_PostSolidifyClamp'] = bool(clamp312.get('baked', False))
    dup['AEF_V10_9B3_12_ClampMode'] = str(clamp312.get('mode', 'off'))
    dup['AEF_V10_9B3_12_OutsideVerts'] = int(clamp312.get('outside_before', 0))
    dup['AEF_V10_9B3_12_FacesRemoved'] = int(clamp312.get('faces_removed', 0))
    dup['AEF_V10_9B3_12_EdgesRemoved'] = int(clamp312.get('edges_removed', 0))
    dup['AEF_V10_9B3_12_VertsRemoved'] = int(clamp312.get('verts_removed', 0))
    return dup


def apply_v107a_safe_silhouette(char_name, settings=None, enabled=True):
    if not enabled:
        _aef107a_cleanup(char_name)
        return 0, 0
    removed = _aef107a_cleanup(char_name)
    if removed:
        log(f"V10.7A.1 Safe Silhouette Cleanup {char_name}: removed {removed} previous shell objects")
    items = _aef107a_collect_source_meshes(char_name)
    if not items:
        log(f"V10.7A.1 Safe Silhouette Cleanup {char_name}: no source meshes found")
        return 0, 0
    target = _aef107a_get_collection(char_name)
    profile = getattr(settings, 'shot_profile', 'AVE') if settings else 'AVE'
    char_scale = _aef107a_character_scale(items)
    character_envelope = _aef109b312_character_world_envelope(items, settings)
    built = 0
    skipped = 0
    for src_obj, mats, catset, cats in items:
        groups = _aef107a_material_groups_for_object(src_obj, mats, settings)
        used_per_material = False
        if groups:
            for group in groups:
                used_per_material = True
                family = group.get('family', 'cloth')
                if group.get('skip'):
                    skipped += 1
                    log(f"  [V10.9B3.2 skip] {char_name}/{src_obj.name}: group={group.get('label', family)} family={family} why={group.get('skip_reason', '')}")
                    continue
                dup = _aef107a_build_shell_object(
                    src_obj,
                    char_name,
                    family,
                    profile,
                    settings,
                    target,
                    char_scale,
                    material_indices=group.get('material_indices', []),
                    source_label=group.get('label', family),
                    character_envelope=character_envelope,
                )
                if dup is None:
                    skipped += 1
                    log(f"  [V10.9B3.2 skip] {char_name}/{src_obj.name}: group={group.get('label', family)} family={family} why=empty mesh after per-material prune")
                    continue
                built += 1
                log(
                    f"  [V10.9B3.2 shell] {char_name}/{src_obj.name}: group={group.get('label', family)} "
                    f"family={family} faces={group.get('poly_count', 0)} thickness={dup.get('AEF_V10_7A_Thickness', 0.0):.5f} "
                    f"eq={dup.get('AEF_V10_9B3_OutlineEqualization', 1.0):.2f}x trim={dup.get('AEF_V10_9B3_3_ThicknessTuning', 1.0):.2f}x series={dup.get('AEF_V10_9B3_4_SeriesOutlineMatch', 1.0):.2f}x ink35={dup.get('AEF_V10_9B3_5_SeriesInkFinal', 1.0):.2f}x ultra36={dup.get('AEF_V10_9B3_6_UltraFineSeries', 1.0):.2f}x art37={dup.get('AEF_V10_9B3_7_DolorisArtifactTrim', 1.0):.2f}x O37={dup.get('AEF_V10_9B3_7_OblivionisMatch', 1.0):.2f}x O38={dup.get('AEF_V10_9B3_8_OblivionisFinalTrim', 1.0):.2f}x removed37={int(dup.get('AEF_V10_9B3_7_PathologicalFacesRemoved', 0))} removed39={int(dup.get('AEF_V10_9B3_9_RemoteSpikeFacesRemoved', 0))} san310={dup.get('AEF_V10_9B3_10_SanitationMode', 'off')} keys310={int(dup.get('AEF_V10_9B3_10_SourceShapeKeys', 0))}"
                )
        if used_per_material:
            continue

        family = _aef107a_family_from_categories(src_obj, mats, catset, cats)
        skip, why = _aef107a_should_skip(src_obj, mats, family, catset, cats, settings)
        if skip:
            skipped += 1
            log(f"  [V10.7A.1 skip] {char_name}/{src_obj.name}: family={family} why={why}")
            continue
        dup = _aef107a_build_shell_object(src_obj, char_name, family, profile, settings, target, char_scale, character_envelope=character_envelope)
        if dup is None:
            skipped += 1
            log(f"  [V10.9B3.2 skip] {char_name}/{src_obj.name}: family={family} why=empty mesh in fallback build")
            continue
        built += 1
        log(f"  [V10.9B3.2 fallback shell] {char_name}/{src_obj.name}: family={family} thickness={dup.get('AEF_V10_7A_Thickness', 0.0):.5f} eq={dup.get('AEF_V10_9B3_OutlineEqualization', 1.0):.2f}x trim={dup.get('AEF_V10_9B3_3_ThicknessTuning', 1.0):.2f}x series={dup.get('AEF_V10_9B3_4_SeriesOutlineMatch', 1.0):.2f}x ink35={dup.get('AEF_V10_9B3_5_SeriesInkFinal', 1.0):.2f}x ultra36={dup.get('AEF_V10_9B3_6_UltraFineSeries', 1.0):.2f}x art37={dup.get('AEF_V10_9B3_7_DolorisArtifactTrim', 1.0):.2f}x O37={dup.get('AEF_V10_9B3_7_OblivionisMatch', 1.0):.2f}x O38={dup.get('AEF_V10_9B3_8_OblivionisFinalTrim', 1.0):.2f}x removed37={int(dup.get('AEF_V10_9B3_7_PathologicalFacesRemoved', 0))} removed39={int(dup.get('AEF_V10_9B3_9_RemoteSpikeFacesRemoved', 0))} san310={dup.get('AEF_V10_9B3_10_SanitationMode', 'off')} keys310={int(dup.get('AEF_V10_9B3_10_SourceShapeKeys', 0))}")
    target.hide_viewport = False
    target.hide_render = False
    return built, skipped


# =====================================================================
# V10.9B3.1 — OUTLINE PIPELINE AUDIT (READ-ONLY DIAGNOSTIC)
# ---------------------------------------------------------------------
# Esta fase NO intenta arreglar el outline. Su objetivo es comparar lo que
# realmente existe en Blender para Doloris y Oblivionis después del build:
#   source mesh -> materiales/categorías -> familia/skip -> transforms ->
#   shell regenerada -> Solidify -> material outline -> visibilidad.
#
# El informe se guarda en un Text datablock y, opcionalmente, como .txt junto
# al .blend. No cambia thickness, normals, materiales, UV ni Image Texture.
# =====================================================================
AEF109B31_AUDIT_TEXT = "AEF V10.9B3.1 • Outline Pipeline Audit"
AEF109B31_AUDIT_FILENAME = "AEF_V10_9B3_1_OutlinePipelineAudit.txt"


def _aef109b31_fmt_vec(vec, digits=5):
    try:
        return '(' + ', '.join(f'{float(v):.{digits}f}' for v in vec[:3]) + ')'
    except Exception:
        try:
            return str(tuple(vec))
        except Exception:
            return str(vec)


def _aef109b31_world_scale(obj):
    try:
        sc = obj.matrix_world.to_scale()
        vals = [abs(float(sc.x)), abs(float(sc.y)), abs(float(sc.z))]
    except Exception:
        try:
            vals = [abs(float(v)) for v in obj.scale[:3]]
        except Exception:
            vals = [1.0, 1.0, 1.0]
    vals = [max(1e-8, v) for v in vals]
    return vals


def _aef109b31_det(obj):
    try:
        return float(obj.matrix_world.to_3x3().determinant())
    except Exception:
        return 0.0


def _aef109b31_eval_poly_count(obj):
    try:
        depsgraph = bpy.context.evaluated_depsgraph_get()
        eo = obj.evaluated_get(depsgraph)
        mesh = eo.to_mesh()
        try:
            return len(mesh.polygons)
        finally:
            eo.to_mesh_clear()
    except Exception:
        try:
            return len(obj.data.polygons)
        except Exception:
            return -1


def _aef109b31_collection_flags(obj):
    flags = []
    try:
        for col in obj.users_collection:
            flags.append(
                f"{col.name}[viewport={getattr(col, 'hide_viewport', False)}, render={getattr(col, 'hide_render', False)}]"
            )
    except Exception:
        pass
    return ', '.join(flags) if flags else '<no collection>'


def _aef109b31_mat_summary(mat):
    if mat is None:
        return '<None>'
    bits = [mat.name]
    try:
        bits.append(f"cat={mat.get('AEF_V8_Category', '')}")
    except Exception:
        pass
    try:
        bits.append(f"cull={bool(getattr(mat, 'use_backface_culling', False))}")
    except Exception:
        pass
    try:
        bits.append(f"blend={getattr(mat, 'surface_render_method', getattr(mat, 'blend_method', 'n/a'))}")
    except Exception:
        pass
    return '{' + ', '.join(bits) + '}'


def _aef109b31_modifier_summary(obj):
    rows = []
    for mod in getattr(obj, 'modifiers', []):
        try:
            row = f"{mod.name}:{mod.type}[viewport={mod.show_viewport}, render={mod.show_render}]"
            if mod.type == 'SOLIDIFY':
                row += (
                    f" thickness={float(mod.thickness):.7f} offset={float(mod.offset):.3f}"
                    f" matOff={int(mod.material_offset)} flip={bool(getattr(mod, 'use_flip_normals', False))}"
                    f" even={bool(getattr(mod, 'use_even_offset', False))} rim={bool(getattr(mod, 'use_rim', True))}"
                )
            rows.append(row)
        except Exception as exc:
            rows.append(f"<modifier read error: {exc}>")
    return rows


def _aef109b31_shells_for_source(char_name, source_name):
    out = []
    for obj in bpy.data.objects:
        if obj.type != 'MESH':
            continue
        if not bool(obj.get('AEF_V10_7A_SafeSilhouette', False)):
            continue
        if str(obj.get('AEF_V10_7A_Character', '')) != str(char_name):
            continue
        if str(obj.get('AEF_V10_7A_SourceObject', '')) == str(source_name):
            out.append(obj)
    return out


def _aef109b31_find_solidify(shell):
    for mod in getattr(shell, 'modifiers', []):
        if mod.type == 'SOLIDIFY' and ('Safe Silhouette' in mod.name or 'Silhouette' in mod.name):
            return mod
    for mod in getattr(shell, 'modifiers', []):
        if mod.type == 'SOLIDIFY':
            return mod
    return None


def _aef109b31_outline_material(shell):
    try:
        for slot in shell.material_slots:
            mat = slot.material
            if mat and bool(mat.get('AEF_V10_7A_SafeSilhouette', False)) and str(mat.get('AEF_V10_7A_Family', '')) != 'invisible':
                return mat
    except Exception:
        pass
    try:
        return shell.material_slots[1].material if len(shell.material_slots) > 1 else None
    except Exception:
        return None


def _aef109b31_source_edge_candidates(src_obj):
    hits = []
    for mod in getattr(src_obj, 'modifiers', []):
        name = str(getattr(mod, 'name', '')).lower()
        if mod.type == 'SOLIDIFY' or 'edge' in name or 'outline' in name or 'toon' in name:
            hits.append(f"modifier:{mod.name}:{mod.type}")
    for slot in getattr(src_obj, 'material_slots', []):
        mat = slot.material
        if not mat:
            continue
        n = mat.name.lower()
        if 'edge' in n or 'outline' in n or 'toon' in n:
            hits.append(f"material:{mat.name}")
    return hits


def _aef109b31_text_datablock(report):
    txt = bpy.data.texts.get(AEF109B31_AUDIT_TEXT)
    if txt is None:
        txt = bpy.data.texts.new(AEF109B31_AUDIT_TEXT)
    try:
        txt.clear()
        txt.write(report)
    except Exception:
        try:
            txt.from_string(report)
        except Exception:
            pass
    return txt


def _aef109b31_write_report_file(report, settings):
    if not bool(getattr(settings, 'outline_audit_write_file_v109b31', True)):
        return None
    if not bpy.data.filepath:
        return None
    try:
        out = Path(bpy.data.filepath).with_name(AEF109B31_AUDIT_FILENAME)
        out.write_text(report, encoding='utf-8')
        return out
    except Exception as exc:
        log(f"V10.9B3.1 audit file warning: {exc}")
        return None


def _aef109b31_outline_pipeline_audit(settings, write_disk=True):
    verbose = bool(getattr(settings, 'outline_audit_verbose_v109b31', True)) if settings else True
    lines = []
    warnings = []
    metrics = {}

    def add(s=''):
        lines.append(str(s))

    add('=' * 100)
    add('AEF SABERSHADER — V10.9B3.1 OUTLINE PIPELINE AUDIT')
    add('READ-ONLY DIAGNOSTIC: no thickness / normals / material / UV fixes are applied here')
    add(f'Blender: {bpy.app.version_string}')
    add(f'Blend: {bpy.data.filepath or "<unsaved>"}')
    try:
        cam = bpy.context.scene.camera
        add(f'Camera: {cam.name if cam else "<none>"}')
    except Exception:
        add('Camera: <error>')
    if settings:
        add(
            'Current silhouette settings: '
            f'strength={float(getattr(settings, "safe_silhouette_strength", 1.0)):.3f}, '
            f'props={bool(getattr(settings, "safe_silhouette_include_props", False))}, '
            f'B3_equalize={bool(getattr(settings, "build_doloris_outline_equalization_v109b3", True))}, '
            f'D_global={float(getattr(settings, "doloris_outline_gain_v109b3", 1.0)):.3f}, '
            f'B3_3_tune={bool(getattr(settings, "build_doloris_outline_thickness_tuning_v109b33", True))}, '
            f'D_trim={float(getattr(settings, "doloris_outline_global_trim_v109b33", 1.0)):.3f}, ' f'B3_4_series={bool(getattr(settings, "build_ave_outline_reference_match_v109b34", True))}, ' f'B3_5_ink={bool(getattr(settings, "build_series_ink_clean_preview_v109b35", True))}, ' f'B3_6_ultrafine={bool(getattr(settings, "build_ultrafine_series_outline_v109b36", True))}, ' f'B3_7_cleanup={bool(getattr(settings, "build_outline_artifact_cleanup_v109b37", True))}, ' f'B3_7_Oblivionis={bool(getattr(settings, "build_oblivionis_outline_match_v109b37", True))}'
        )
    add('=' * 100)

    for char_name in ('Doloris', 'Oblivionis'):
        items = _aef107a_collect_source_meshes(char_name)
        char_scale = _aef107a_character_scale(items) if items else 1.0
        profile = getattr(settings, 'shot_profile', 'AVE') if settings else 'AVE'
        all_shells = [
            obj for obj in bpy.data.objects
            if obj.type == 'MESH'
            and bool(obj.get('AEF_V10_7A_SafeSilhouette', False))
            and str(obj.get('AEF_V10_7A_Character', '')) == char_name
        ]
        col = bpy.data.collections.get(f"{AEF107A_COLLECTION_PREFIX}{char_name}")
        add()
        add(f'### {char_name.upper()} ###')
        add(f'source_items={len(items)} shell_objects={len(all_shells)} char_scale={char_scale:.6f}')
        add(
            'silhouette_collection=' + (
                f'{col.name} viewport={getattr(col, "hide_viewport", False)} render={getattr(col, "hide_render", False)}'
                if col else '<MISSING>'
            )
        )
        if col is None:
            warnings.append(f'{char_name}: Safe Silhouette collection missing')

        family_counts = {}
        expected_shells = 0
        actual_expected_shells = 0
        thickness_rows = []
        missing = []

        for idx, (src_obj, mats, catset, cats) in enumerate(items, 1):
            family = _aef107a_family_from_categories(src_obj, mats, catset, cats)
            family_counts[family] = family_counts.get(family, 0) + 1
            skip, why = _aef107a_should_skip(src_obj, mats, family, catset, cats, settings)
            expected_local = _aef107a_shell_thickness(profile, family, src_obj, settings, char_scale, char_name=char_name)
            shells = _aef109b31_shells_for_source(char_name, src_obj.name)
            if not skip:
                expected_shells += 1
                if shells:
                    actual_expected_shells += 1
                else:
                    missing.append(src_obj.name)
                    warnings.append(f'{char_name}/{src_obj.name}: expected shell is missing')

            sc = _aef109b31_world_scale(src_obj)
            det = _aef109b31_det(src_obj)
            try:
                dims = tuple(float(v) for v in src_obj.dimensions[:3])
            except Exception:
                dims = (0.0, 0.0, 0.0)
            try:
                loc = tuple(float(v) for v in src_obj.matrix_world.translation[:3])
            except Exception:
                loc = (0.0, 0.0, 0.0)
            poly_count = len(src_obj.data.polygons) if getattr(src_obj, 'data', None) else -1
            eval_polys = _aef109b31_eval_poly_count(src_obj)

            add('-' * 100)
            add(
                f'[{idx:02d}] SOURCE {src_obj.name} | family={family} | '
                f'skip={skip}{(" (" + why + ")") if why else ""} | expected_local_thickness={expected_local:.7f}'
            )
            add(
                f'     local_scale={_aef109b31_fmt_vec(src_obj.scale)} world_scale={_aef109b31_fmt_vec(sc)} '
                f'det={det:.8f} mirrored={det < 0.0}'
            )
            add(f'     world_loc={_aef109b31_fmt_vec(loc)} dimensions={_aef109b31_fmt_vec(dims)} polys={poly_count} eval_polys={eval_polys}')
            add(
                f'     visible: hide_viewport={src_obj.hide_viewport} hide_render={src_obj.hide_render} '
                f'hide_get={src_obj.hide_get()} collections={_aef109b31_collection_flags(src_obj)}'
            )
            add(f'     parent={src_obj.parent.name if src_obj.parent else "<none>"} parent_type={getattr(src_obj, "parent_type", "") or "<none>"}')
            add(f'     categories={sorted(catset)}')
            if verbose:
                add('     materials=' + ', '.join(_aef109b31_mat_summary(m) for m in mats))
                mods = _aef109b31_modifier_summary(src_obj)
                add('     source_modifiers=' + (' | '.join(mods) if mods else '<none>'))
                edges = _aef109b31_source_edge_candidates(src_obj)
                add('     preexisting_edge_candidates=' + (' | '.join(edges) if edges else '<none>'))

            if not shells:
                add('     SHELL: <none>')
            for shell in shells:
                solid = _aef109b31_find_solidify(shell)
                outline_mat = _aef109b31_outline_material(shell)
                ssc = _aef109b31_world_scale(shell)
                sdet = _aef109b31_det(shell)
                local_th = float(solid.thickness) if solid else float(shell.get('AEF_V10_7A_Thickness', 0.0))
                world_min = abs(local_th) * min(ssc)
                world_avg = abs(local_th) * (sum(ssc) / 3.0)
                world_max = abs(local_th) * max(ssc)
                thickness_rows.append((family, local_th, world_min, world_avg, world_max))
                add(f'     SHELL {shell.name}')
                add(
                    f'       family_tag={shell.get("AEF_V10_7A_Family", "")} source_tag={shell.get("AEF_V10_7A_SourceObject", "")} '
                    f'B3_eq={float(shell.get("AEF_V10_9B3_OutlineEqualization", 1.0)):.3f}, ' f'B3_3_trim={float(shell.get("AEF_V10_9B3_3_ThicknessTuning", 1.0)):.3f}, ' f'B3_4_series={float(shell.get("AEF_V10_9B3_4_SeriesOutlineMatch", 1.0)):.3f}, ' f'B3_5_ink={float(shell.get("AEF_V10_9B3_5_SeriesInkFinal", 1.0)):.3f}, ' f'B3_6_ultra={float(shell.get("AEF_V10_9B3_6_UltraFineSeries", 1.0)):.3f}, ' f'B3_7_Dart={float(shell.get("AEF_V10_9B3_7_DolorisArtifactTrim", 1.0)):.3f}, ' f'B3_7_Omatch={float(shell.get("AEF_V10_9B3_7_OblivionisMatch", 1.0)):.3f}, ' f'B3_7_removed={int(shell.get("AEF_V10_9B3_7_PathologicalFacesRemoved", 0))}'
                )
                add(
                    f'       local_scale={_aef109b31_fmt_vec(shell.scale)} world_scale={_aef109b31_fmt_vec(ssc)} '
                    f'det={sdet:.8f} mirrored={sdet < 0.0}'
                )
                add(
                    f'       visibility: hide_viewport={shell.hide_viewport} hide_render={shell.hide_render} '
                    f'hide_get={shell.hide_get()} collections={_aef109b31_collection_flags(shell)}'
                )
                if solid:
                    add(
                        f'       SOLIDIFY thickness={local_th:.7f} offset={float(solid.offset):.3f} '
                        f'matOff={int(solid.material_offset)} flip={bool(getattr(solid, "use_flip_normals", False))} '
                        f'even={bool(getattr(solid, "use_even_offset", False))} rim={bool(getattr(solid, "use_rim", True))} '
                        f'viewport={solid.show_viewport} render={solid.show_render}'
                    )
                else:
                    add('       SOLIDIFY: <MISSING>')
                    warnings.append(f'{char_name}/{src_obj.name}: shell exists but Solidify modifier missing')
                add(
                    f'       approx_world_thickness[min/avg/max]={world_min:.7f}/{world_avg:.7f}/{world_max:.7f} '
                    f'(diagnostic range; non-uniform scale is normal-direction dependent)'
                )
                add(f'       outline_material={_aef109b31_mat_summary(outline_mat)}')
                if outline_mat is None:
                    warnings.append(f'{char_name}/{src_obj.name}: outline material missing')
                else:
                    if not bool(getattr(outline_mat, 'use_backface_culling', False)):
                        warnings.append(f'{char_name}/{src_obj.name}: outline material backface culling is OFF')
                if verbose:
                    smods = _aef109b31_modifier_summary(shell)
                    add('       shell_modifiers=' + (' | '.join(smods) if smods else '<none>'))
                    try:
                        slot_names = [slot.material.name if slot.material else '<None>' for slot in shell.material_slots]
                        add('       shell_material_slots=' + repr(slot_names))
                        dist = {}
                        for poly in shell.data.polygons:
                            dist[poly.material_index] = dist.get(poly.material_index, 0) + 1
                        add('       source_face_material_index_distribution=' + repr(dist))
                    except Exception as exc:
                        add(f'       material distribution read error: {exc}')

        metrics[char_name] = {
            'source_items': len(items),
            'shell_objects': len(all_shells),
            'expected_shells': expected_shells,
            'actual_expected_shells': actual_expected_shells,
            'family_counts': family_counts,
            'thickness_rows': thickness_rows,
            'missing': missing,
        }
        add('-' * 100)
        add(f'{char_name} FAMILY COUNTS: {family_counts}')
        add(f'{char_name} EXPECTED SHELLS: {expected_shells} | PRESENT: {actual_expected_shells} | MISSING: {missing or "none"}')
        if thickness_rows:
            av_local = sum(abs(r[1]) for r in thickness_rows) / len(thickness_rows)
            av_world = sum(r[3] for r in thickness_rows) / len(thickness_rows)
            add(f'{char_name} AVG SHELL THICKNESS: local={av_local:.7f} approx_world_avg={av_world:.7f}')
            metrics[char_name]['avg_local'] = av_local
            metrics[char_name]['avg_world'] = av_world

    add()
    add('=' * 100)
    add('CROSS-CHARACTER COMPARISON')
    d = metrics.get('Doloris', {})
    o = metrics.get('Oblivionis', {})
    add(f'Doloris source/shell/expected-present: {d.get("source_items",0)}/{d.get("shell_objects",0)}/{d.get("actual_expected_shells",0)}')
    add(f'Oblivionis source/shell/expected-present: {o.get("source_items",0)}/{o.get("shell_objects",0)}/{o.get("actual_expected_shells",0)}')
    if d.get('avg_world') is not None and o.get('avg_world') not in (None, 0.0):
        ratio = d['avg_world'] / o['avg_world']
        add(f'Approx average world-thickness ratio D/O = {ratio:.4f}')
        if ratio < 0.80:
            warnings.append(f'Doloris approx world shell thickness is substantially lower than Oblivionis (ratio={ratio:.3f})')
        elif ratio > 1.25:
            add('NOTE: Doloris approx shell thickness is already larger than Oblivionis; lack of visible outline is unlikely to be solved by more raw thickness alone.')
    add(f'Doloris families: {d.get("family_counts", {})}')
    add(f'Oblivionis families: {o.get("family_counts", {})}')

    add()
    add('=' * 100)
    add('WARNINGS / HIGH-VALUE CLUES')
    if warnings:
        for w in warnings:
            add('WARN: ' + w)
    else:
        add('No structural warning was detected by the audit. Compare source/shell family mapping and material/visibility rows above.')
    add('=' * 100)

    report = '\n'.join(lines) + '\n'
    _aef109b31_text_datablock(report)
    path = _aef109b31_write_report_file(report, settings) if write_disk else None
    scene = bpy.context.scene
    scene['AEF_V10_9B3_1_OutlineAudit'] = True
    scene['AEF_V10_9B3_1_AuditText'] = AEF109B31_AUDIT_TEXT
    scene['AEF_V10_9B3_1_AuditWarnings'] = len(warnings)
    if path:
        scene['AEF_V10_9B3_1_AuditFile'] = str(path)
    log(f'V10.9B3.1 Outline Pipeline Audit: report={AEF109B31_AUDIT_TEXT} warnings={len(warnings)} file={path if path else "Text datablock only"}')
    return {
        'report': report,
        'warnings': warnings,
        'metrics': metrics,
        'path': path,
        'text_name': AEF109B31_AUDIT_TEXT,
    }


# =====================================================================
# V10.7B — SELECTIVE INTERNAL ACCENTS (curvas 3D por shot, sin LINEART)
# ---------------------------------------------------------------------
# No intenta reproducir todos los creases geométricos. Muestrea únicamente
# bordes internos importantes del mesh EVALUADO en el frame actual:
#   - cambios de material dentro de ropa;
#   - ángulos suficientemente fuertes en ropa/cabello/manos;
#   - solo superficies front-facing para la cámara actual;
#   - nunca boundaries exteriores (ya los resuelve V10.7A.1);
#   - Face / transparent / stockings / props quedan fuera.
# El resultado es una colección de Curve objects regenerables por shot.
# =====================================================================
AEF107B_COLLECTION_PREFIX = "AEF_V10_7B_Internal_"
AEF107B_OBJECT_PREFIX = "AEF_V10_7B_Accent__"
AEF107B_MAT_PREFIX = "AEF_V10_7B_Line_"
AEF107B_ELIGIBLE = {'hair', 'cloth', 'hand'}
AEF107B_ANGLE_DEG = {'hair': 34.0, 'cloth': 48.0, 'hand': 42.0}
AEF107B_BASE_CAP = {'hair': 48, 'cloth': 40, 'hand': 20}
AEF107B_BEVEL = {
    'AVE':  {'hair': 0.00034, 'cloth': 0.00038, 'hand': 0.00030},
    'MYGO': {'hair': 0.00030, 'cloth': 0.00033, 'hand': 0.00027},
}


def _aef107b_cleanup(char_name=None):
    removed = 0
    for obj in list(bpy.data.objects):
        if not obj or obj.type != 'CURVE':
            continue
        if not bool(obj.get('AEF_V10_7B_InternalAccent', False)):
            continue
        if char_name and str(obj.get('AEF_V10_7B_Character', '')) != str(char_name):
            continue
        bpy.data.objects.remove(obj, do_unlink=True)
        removed += 1
    for col in list(bpy.data.collections):
        if not col.name.startswith(AEF107B_COLLECTION_PREFIX):
            continue
        if char_name and col.name != f"{AEF107B_COLLECTION_PREFIX}{char_name}":
            continue
        try:
            bpy.data.collections.remove(col)
        except Exception:
            pass
    return removed


def _aef107b_get_collection(char_name):
    name = f"{AEF107B_COLLECTION_PREFIX}{char_name}"
    col = bpy.data.collections.get(name)
    if not col:
        col = bpy.data.collections.new(name)
        bpy.context.scene.collection.children.link(col)
    col['AEF_V10_7B_InternalAccent'] = True
    col['AEF_V10_7B_Character'] = char_name
    return col


def _aef107b_material_family(mat):
    if not mat:
        return 'skip'
    cat = str(mat.get('AEF_V8_Category', '')).lower()
    name = mat.name.lower()
    blob = f"{cat} {name}"

    if any(tok in blob for tok in ('face', 'face2', 'eyes', 'mouth', 'expression', '表情', '面具')):
        return 'face'
    if 'hair' in blob:
        return 'hair'
    if any(tok in blob for tok in ('clothes4', '裙透', 'transparent', 'sheer', 'lace')):
        return 'transparent'
    if any(tok in blob for tok in ('stockings', 'stocks', '靴下', 'hosiery')):
        return 'stockings'
    if any(tok in blob for tok in ('guitar', 'instrument', 'deco1', 'deco2')):
        return 'prop'
    if any(tok in blob for tok in ('glove', 'hands', 'hand')):
        return 'hand'
    if any(tok in blob for tok in ('cloth', 'clothes', 'skirt', 'bow', 'tie', 'accessory', 'boots', '服', '裙')):
        return 'cloth'
    return 'skip'


def _aef107b_poly_family(src_obj, poly):
    try:
        idx = int(poly.material_index)
        if idx < 0 or idx >= len(src_obj.material_slots):
            return 'skip'
        return _aef107b_material_family(src_obj.material_slots[idx].material)
    except Exception:
        return 'skip'


def _aef107b_view_dir(world_point):
    cam = getattr(bpy.context.scene, 'camera', None)
    if not cam:
        return Vector((0.0, 0.0, 1.0))
    try:
        if getattr(cam.data, 'type', '') == 'ORTHO':
            return (cam.matrix_world.to_quaternion() @ Vector((0.0, 0.0, 1.0))).normalized()
    except Exception:
        pass
    try:
        return (cam.matrix_world.translation - world_point).normalized()
    except Exception:
        return Vector((0.0, 0.0, 1.0))


def _aef107b_line_color(char_name, family):
    base = _aef9_outline_color(char_name)
    # Líneas internas ligeramente menos negras que la silueta exterior.
    mul = {'hair': 1.75, 'cloth': 1.60, 'hand': 1.55}.get(family, 1.6)
    rgb = tuple(max(0.0, min(0.08, float(c) * mul)) for c in base[:3])
    return rgb + (1.0,)


def _aef107b_get_material(char_name, family):
    name = f"{AEF107B_MAT_PREFIX}{char_name}_{family}"
    mat = bpy.data.materials.get(name)
    if not mat:
        mat = bpy.data.materials.new(name)
    mat.use_nodes = True
    nodes = mat.node_tree.nodes
    links = mat.node_tree.links
    nodes.clear()
    out = nodes.new('ShaderNodeOutputMaterial')
    em = nodes.new('ShaderNodeEmission')
    out.location = (220, 0)
    em.location = (0, 0)
    color = _aef107b_line_color(char_name, family)
    em.inputs['Color'].default_value = color
    em.inputs['Strength'].default_value = {'hair': 0.92, 'cloth': 0.95, 'hand': 0.90}.get(family, 0.92)
    links.new(em.outputs['Emission'], out.inputs['Surface'])
    mat.diffuse_color = color
    if hasattr(mat, 'blend_method'):
        mat.blend_method = 'OPAQUE'
    if hasattr(mat, 'use_backface_culling'):
        mat.use_backface_culling = True
    mat['AEF_V10_7B_InternalAccent'] = True
    mat['AEF_V10_7B_Character'] = char_name
    mat['AEF_V10_7B_Family'] = family
    mat['AEF_V10_7B_NoLineArt'] = True
    return mat


def _aef107b_edge_face_map(mesh):
    mapping = [[] for _ in mesh.edges]
    for p in mesh.polygons:
        for li in p.loop_indices:
            try:
                ei = mesh.loops[li].edge_index
                mapping[ei].append(p.index)
            except Exception:
                pass
    return mapping


def _aef107b_candidate_segments(src_obj, char_scale, profile, settings):
    """Returns {family: [(score, p1, p2), ...]} from evaluated shot mesh."""
    deps = bpy.context.evaluated_depsgraph_get()
    eval_obj = src_obj.evaluated_get(deps)
    mesh = None
    out = {k: [] for k in AEF107B_ELIGIBLE}
    try:
        mesh = eval_obj.to_mesh()
        if not mesh or len(mesh.edges) == 0:
            return out
        face_map = _aef107b_edge_face_map(mesh)
        mw = eval_obj.matrix_world
        normal_mx = mw.to_3x3().inverted().transposed()
        min_len = 0.012 * char_scale
        depth_offset = 0.00055 * char_scale

        for edge in mesh.edges:
            faces = face_map[edge.index] if edge.index < len(face_map) else []
            # Boundaries / silhouette edges are intentionally excluded.
            if len(faces) != 2:
                continue
            p1 = mesh.polygons[faces[0]]
            p2 = mesh.polygons[faces[1]]
            f1 = _aef107b_poly_family(src_obj, p1)
            f2 = _aef107b_poly_family(src_obj, p2)

            if f1 not in AEF107B_ELIGIBLE or f2 not in AEF107B_ELIGIBLE:
                continue
            # Hair stays hair. Cloth + hand seams are allowed but assigned to
            # hand only when both sides are hand; otherwise they are cloth.
            if f1 == 'hair' or f2 == 'hair':
                if f1 != 'hair' or f2 != 'hair':
                    continue
                family = 'hair'
            elif f1 == 'hand' and f2 == 'hand':
                family = 'hand'
            else:
                family = 'cloth'

            v0, v1 = edge.vertices
            a = mw @ mesh.vertices[v0].co
            b = mw @ mesh.vertices[v1].co
            length = (b - a).length
            if length < min_len:
                continue

            n1 = (normal_mx @ p1.normal).normalized()
            n2 = (normal_mx @ p2.normal).normalized()
            try:
                angle = math.degrees(n1.angle(n2))
            except Exception:
                continue
            material_boundary = int(p1.material_index) != int(p2.material_index)
            sharp = bool(getattr(edge, 'use_edge_sharp', False))
            threshold = float(AEF107B_ANGLE_DEG.get(family, 48.0))
            # Material seams are artistically valuable even when nearly flat,
            # but require a small angle to avoid tracing arbitrary UV-like grids.
            if not material_boundary and angle < threshold:
                continue
            if material_boundary and angle < 7.0:
                continue

            mid = (a + b) * 0.5
            view = _aef107b_view_dir(mid)
            d1 = max(-1.0, min(1.0, n1.dot(view)))
            d2 = max(-1.0, min(1.0, n2.dot(view)))
            # Only accents that genuinely belong to the camera-facing drawing.
            if max(d1, d2) < 0.10:
                continue

            score = angle
            if material_boundary:
                score += 34.0
            if sharp:
                score += 12.0
            score += min(14.0, length * 45.0)
            # Prefer edges whose two faces are both visible, avoiding near-backside noise.
            score += max(0.0, min(d1, d2)) * 10.0

            va = (a + _aef107b_view_dir(a) * depth_offset).copy()
            vb = (b + _aef107b_view_dir(b) * depth_offset).copy()
            out[family].append((score, va, vb))
        return out
    finally:
        if mesh is not None:
            try:
                eval_obj.to_mesh_clear()
            except Exception:
                pass


def _aef107b_make_curve(char_name, family, segments, profile, settings, target_collection, char_scale):
    if not segments:
        return None
    curve_data = bpy.data.curves.new(f"{AEF107B_OBJECT_PREFIX}{char_name}_{family}_DATA", type='CURVE')
    curve_data.dimensions = '3D'
    curve_data.resolution_u = 1
    curve_data.resolution_v = 0
    curve_data.bevel_resolution = 0
    curve_data.fill_mode = 'FULL'
    if hasattr(curve_data, 'use_fill_caps'):
        curve_data.use_fill_caps = True
    strength = float(getattr(settings, 'internal_accent_strength', 1.0)) if settings else 1.0
    base = AEF107B_BEVEL.get(profile, AEF107B_BEVEL['AVE']).get(family, 0.00034)
    curve_data.bevel_depth = base * char_scale * strength
    curve_data.materials.append(_aef107b_get_material(char_name, family))

    for _score, a, b in segments:
        spline = curve_data.splines.new('POLY')
        spline.points.add(1)
        spline.points[0].co = (a.x, a.y, a.z, 1.0)
        spline.points[1].co = (b.x, b.y, b.z, 1.0)

    obj = bpy.data.objects.new(f"{AEF107B_OBJECT_PREFIX}{char_name}_{family}", curve_data)
    target_collection.objects.link(obj)
    obj.hide_select = True
    obj.show_in_front = False
    obj['AEF_V10_7B_InternalAccent'] = True
    obj['AEF_V10_7B_Character'] = char_name
    obj['AEF_V10_7B_Family'] = family
    obj['AEF_V10_7B_Segments'] = len(segments)
    obj['AEF_V10_7B_Bevel'] = float(curve_data.bevel_depth)
    obj['AEF_V10_7B_Frame'] = int(bpy.context.scene.frame_current)
    return obj


def apply_v107b_internal_accents(char_name, settings=None, enabled=True):
    if not enabled:
        _aef107b_cleanup(char_name)
        return 0, 0, 0
    removed = _aef107b_cleanup(char_name)
    if removed:
        log(f"V10.7B Internal {char_name}: removed {removed} previous curve objects")

    items = _aef107a_collect_source_meshes(char_name)
    if not items:
        log(f"V10.7B Internal {char_name}: no source meshes found")
        return 0, 0, 0
    profile = getattr(settings, 'shot_profile', 'AVE') if settings else 'AVE'
    density = float(getattr(settings, 'internal_accent_density', 0.62)) if settings else 0.62
    char_scale = _aef107a_character_scale(items)
    candidates = {k: [] for k in AEF107B_ELIGIBLE}
    source_count = 0

    for src_obj, _mats, _catset, _cats in items:
        source_count += 1
        try:
            found = _aef107b_candidate_segments(src_obj, char_scale, profile, settings)
        except Exception as exc:
            log(f"  [V10.7B skip source] {char_name}/{src_obj.name}: {exc}")
            continue
        for family, vals in found.items():
            candidates[family].extend(vals)

    target = _aef107b_get_collection(char_name)
    built_objects = 0
    total_segments = 0
    for family in ('hair', 'cloth', 'hand'):
        vals = candidates.get(family, [])
        vals.sort(key=lambda item: item[0], reverse=True)
        cap = max(1, int(round(AEF107B_BASE_CAP[family] * density)))
        selected = vals[:cap]
        if not selected:
            continue
        obj = _aef107b_make_curve(char_name, family, selected, profile, settings, target, char_scale)
        if obj:
            built_objects += 1
            total_segments += len(selected)
            log(f"  [V10.7B internal] {char_name}/{family}: candidates={len(vals)} kept={len(selected)} bevel={obj.get('AEF_V10_7B_Bevel', 0.0):.6f}")

    target.hide_viewport = False
    target.hide_render = False
    return built_objects, total_segments, source_count


# ---------------------------------------------------------------------
# V10.7C — TERTIARY FINISH (guías y marcadores por plano)
# ---------------------------------------------------------------------
AEF107C_COLLECTION_PREFIX = "AEF_V10_7C_Tertiary_"
AEF107C_OBJECT_PREFIX = "AEF_V10_7C_Marker__"


def _aef107c_cleanup(char_name=None):
    removed = 0
    for obj in list(bpy.data.objects):
        if not obj or not bool(obj.get('AEF_V10_7C_TertiaryFinish', False)):
            continue
        if char_name and str(obj.get('AEF_V10_7C_Character', '')) != str(char_name):
            continue
        bpy.data.objects.remove(obj, do_unlink=True)
        removed += 1
    for col in list(bpy.data.collections):
        if not col.name.startswith(AEF107C_COLLECTION_PREFIX):
            continue
        if char_name and col.name != f"{AEF107C_COLLECTION_PREFIX}{char_name}":
            continue
        try:
            bpy.data.collections.remove(col)
        except Exception:
            pass
    return removed


def _aef107c_collection(char_name):
    name = f"{AEF107C_COLLECTION_PREFIX}{char_name}"
    col = bpy.data.collections.get(name)
    if col is None:
        col = bpy.data.collections.new(name)
        bpy.context.scene.collection.children.link(col)
    col['AEF_V10_7C_TertiaryFinish'] = True
    col['AEF_V10_7C_Character'] = char_name
    return col


def _aef107c_obj_world_bounds(obj):
    try:
        pts = [obj.matrix_world @ Vector(v) for v in obj.bound_box]
    except Exception:
        return None
    if not pts:
        return None
    mn = Vector((min(p.x for p in pts), min(p.y for p in pts), min(p.z for p in pts)))
    mx = Vector((max(p.x for p in pts), max(p.y for p in pts), max(p.z for p in pts)))
    return mn, mx


def _aef107c_family_bounds(char_name, target_family):
    items = _aef107a_collect_source_meshes(char_name)
    bounds = []
    for src_obj, mats, catset, cats in items:
        family = _aef107a_family_from_categories(src_obj, mats, catset, cats)
        if target_family == 'clothing':
            ok = family in {'cloth', 'stockings', 'transparent'}
        else:
            ok = family == target_family
        if not ok:
            continue
        bb = _aef107c_obj_world_bounds(src_obj)
        if bb is not None:
            bounds.append(bb)
    if not bounds:
        allb = _aef94_character_world_bounds(char_name)
        return allb
    mn = Vector((min(b[0].x for b in bounds), min(b[0].y for b in bounds), min(b[0].z for b in bounds)))
    mx = Vector((max(b[1].x for b in bounds), max(b[1].y for b in bounds), max(b[1].z for b in bounds)))
    return mn, mx


def _aef107c_zone_location(char_name, zone):
    all_bounds = _aef94_character_world_bounds(char_name)
    if all_bounds is None:
        return Vector((0.0, 0.0, 0.0))
    mn, mx = all_bounds
    center = (mn + mx) * 0.5
    span = mx - mn
    if zone == 'Face':
        bb = _aef107c_family_bounds(char_name, 'face') or all_bounds
        fmn, fmx = bb
        return Vector(((fmn.x + fmx.x) * 0.5, (fmn.y + fmx.y) * 0.5, fmn.z * 0.28 + fmx.z * 0.72))
    if zone == 'Hair':
        bb = _aef107c_family_bounds(char_name, 'hair') or all_bounds
        hmn, hmx = bb
        return Vector(((hmn.x + hmx.x) * 0.5, (hmn.y + hmx.y) * 0.5, hmn.z * 0.20 + hmx.z * 0.80))
    if zone == 'Clothing':
        bb = _aef107c_family_bounds(char_name, 'clothing') or all_bounds
        cmn, cmx = bb
        return Vector(((cmn.x + cmx.x) * 0.5, (cmn.y + cmx.y) * 0.5, cmn.z * 0.55 + cmx.z * 0.45))
    if zone == 'Silhouette':
        return Vector((center.x, center.y, mn.z * 0.40 + mx.z * 0.60))
    if zone == 'Skirt':
        bb = _aef107c_family_bounds(char_name, 'clothing') or all_bounds
        cmn, cmx = bb
        return Vector(((cmn.x + cmx.x) * 0.5, (cmn.y + cmx.y) * 0.5, cmn.z * 0.72 + cmx.z * 0.28))
    return center


def _aef107c_marker_size(char_name, zone, strength, guide_scale=0.35):
    bounds = _aef94_character_world_bounds(char_name)
    if bounds is None:
        base = 0.08
    else:
        span = bounds[1] - bounds[0]
        base = max(0.05, min(0.16, max(span.x, span.z) * 0.08))
    # V10.7C.1: los marcadores son una guía de trabajo, no parte del dibujo.
    # Los hacemos bastante más pequeños y con ligeras diferencias por zona.
    mul = {'Face': 0.72, 'Hair': 0.78, 'Clothing': 0.84, 'Silhouette': 0.90, 'Skirt': 0.82}.get(zone, 0.82)
    scale = max(0.10, min(1.00, float(guide_scale)))
    return base * mul * max(0.7, min(1.4, float(strength))) * scale


def _aef107c_make_marker(col, char_name, zone, location, size, strength, profile, visible=True):
    # CIRCLE da una lectura de zona mucho más limpia que la esfera wireframe de V10.7C.
    bpy.ops.object.empty_add(type='CIRCLE', location=location)
    obj = bpy.context.view_layer.objects.active
    if obj is None:
        return None
    obj.name = f"{AEF107C_OBJECT_PREFIX}{char_name}__{zone}"
    try:
        obj.empty_display_size = size
        obj.show_in_front = False
        obj.hide_render = True
        obj.hide_viewport = not bool(visible)
    except Exception:
        pass
    # move to dedicated collection only
    for c in list(obj.users_collection):
        try:
            c.objects.unlink(obj)
        except Exception:
            pass
    col.objects.link(obj)
    obj['AEF_V10_7C_TertiaryFinish'] = True
    obj['AEF_V10_7C_Character'] = char_name
    obj['AEF_V10_7C_Zone'] = zone
    obj['AEF_V10_7C_Profile'] = profile
    obj['AEF_V10_7C_Strength'] = float(strength)
    obj['AEF_V10_7C_GuideVisible'] = bool(visible)
    obj['AEF_V10_7C_GuideSize'] = float(size)
    instruction_map = {
        'Face': 'Face: prioriza pequeños lift/shadow en mejilla, puente nasal y borde inferior del flequillo. Mantén el dibujo mínimo.',
        'Hair': 'Hair: acentos ligeros en flequillo, separación de mechones clave y brillo de cinta; evita convertir todo el pelo en líneas.',
        'Clothing': 'Clothing: diseña sombra/luz en corsé, mangas y unión de capas. Prioriza lectura clara por planos.',
        'Skirt': 'Skirt: enfatiza sólo pliegues principales y transición entre capa opaca y tul transparente.',
        'Silhouette': 'Silhouette: revisa contorno general del plano; usa el shell como base y sólo corrige si algo se pierde contra el fondo.',
    }
    obj['AEF_V10_7C_Instruction'] = instruction_map.get(zone, 'Tertiary zone marker')
    return obj


def _aef107c_tag_gp_objects(char_name, settings):
    profile = getattr(settings, 'shot_profile', 'AVE') if settings else 'AVE'
    strength = float(getattr(settings, 'tertiary_finish_strength', 1.0)) if settings else 1.0
    tagged = 0
    kind_defaults = {
        'Light':  {'hint': 0.72 if profile == 'MYGO' else 0.86, 'zones': 'Face/Hair/Clothing'},
        'Shadow': {'hint': 0.74 if profile == 'MYGO' else 0.90, 'zones': 'Face/Clothing/Silhouette'},
        'Accent': {'hint': 0.58 if profile == 'MYGO' else 0.72, 'zones': 'Hair/Clothing/Silhouette'},
    }
    for kind in ('Light', 'Shadow', 'Accent'):
        obj = bpy.data.objects.get(f'{AEF93_TERT_PREFIX}{char_name} • {kind}')
        if not obj or obj.type != 'GREASEPENCIL':
            continue
        cfg = kind_defaults[kind]
        obj['AEF_V10_7C_TertiaryFinish'] = True
        obj['AEF_V10_7C_Character'] = char_name
        obj['AEF_V10_7C_Kind'] = kind
        obj['AEF_V10_7C_Profile'] = profile
        obj['AEF_V10_7C_Strength'] = strength
        obj['AEF_V10_7C_OpacityHint'] = float(max(0.20, min(1.0, cfg['hint'] * strength)))
        obj['AEF_V10_7C_Zones'] = cfg['zones']
        obj['AEF_V10_7C_Instruction'] = f'V10.7C {kind}: draw sparse, camera-specific tertiary accents. Prioritize {cfg["zones"]}.'
        tagged += 1
    return tagged


def apply_v107c_tertiary_finish(char_name, settings=None, enabled=True):
    if not enabled:
        _aef107c_cleanup(char_name)
        return 0, 0
    removed = _aef107c_cleanup(char_name)
    if removed:
        log(f"V10.7C Tertiary Finish {char_name}: removed {removed} previous markers")
    # Ensure the editable GP structure exists even if the base toggle is OFF.
    old = None
    created_layers = 0
    if settings is not None:
        try:
            old = bool(settings.build_tertiary_artist)
            settings.build_tertiary_artist = True
        except Exception:
            old = None
    try:
        created_layers = build_v94_tertiary_artist(char_name, settings)
    finally:
        if settings is not None and old is not None:
            try:
                settings.build_tertiary_artist = old
            except Exception:
                pass
    tagged = _aef107c_tag_gp_objects(char_name, settings)
    profile = getattr(settings, 'shot_profile', 'AVE') if settings else 'AVE'
    strength = float(getattr(settings, 'tertiary_finish_strength', 1.0)) if settings else 1.0
    guide_scale = float(getattr(settings, 'tertiary_guide_scale_v107c1', 0.35)) if settings else 0.35
    show_guides = bool(getattr(settings, 'show_tertiary_guides_v107c1', True)) if settings else True
    col = _aef107c_collection(char_name)
    try:
        col.hide_render = True
        col.hide_viewport = False
    except Exception:
        pass
    markers = 0
    for zone in ('Face', 'Hair', 'Clothing', 'Skirt', 'Silhouette'):
        loc = _aef107c_zone_location(char_name, zone)
        size = _aef107c_marker_size(char_name, zone, strength, guide_scale)
        obj = _aef107c_make_marker(col, char_name, zone, loc, size, strength, profile, show_guides)
        if obj is not None:
            markers += 1
            log(f"  [V10.7C.1 marker] {char_name}/{zone}: size={size:.4f} visible={show_guides}")
    scene = bpy.context.scene
    scene[f'AEF_V10_7C_{char_name}_Profile'] = profile
    scene[f'AEF_V10_7C_{char_name}_Strength'] = strength
    scene[f'AEF_V10_7C_{char_name}_Markers'] = markers
    scene[f'AEF_V10_7C_{char_name}_TaggedGP'] = tagged
    scene[f'AEF_V10_7C_{char_name}_GuideScale'] = guide_scale
    scene[f'AEF_V10_7C_{char_name}_GuidesVisible'] = show_guides
    return markers, created_layers + tagged


def save_copy():
    if not bpy.data.filepath:
        log("No copy saved: the current .blend has no filepath")
        return None
    src = Path(bpy.data.filepath)
    out = src.with_name("XDZR8_Sabershader_V11_9_Universal_Target_NPR_Core.blend")
    bpy.ops.wm.save_as_mainfile(filepath=str(out), copy=True)
    log(f"SAVED COPY: {out}")
    return out


