def _xdzr8_v11931_uma_character_diagnostics(material_names=None, image_names=None):
    """Resolve human-readable UMA labels from explicit chr#### namespaces only.

    This function is deliberately side-channel telemetry. Its output is never read
    by the role classifier, shader builder, outline logic, or profile gating.
    Body/outfit IDs (bdy####) and tail IDs are excluded because they are not a safe
    character-identity authority.
    """
    evidence = {}

    def record(raw_id, source):
        cid = str(raw_id or '').strip()
        if not cid:
            return
        rows = evidence.setdefault(cid, [])
        if source not in rows:
            rows.append(source)

    for raw in material_names or []:
        name = _xdzr8_v1193_normalize_source_material_name(raw)
        m = re.match(r'^mtl_chr(\d+)_', name)
        if m:
            record(m.group(1), f'material:{name}')

    for raw in image_names or []:
        name = Path(str(raw or '')).name.casefold()
        stem = Path(name).stem.casefold()
        m = re.match(r'^tex_chr(\d+)_', stem)
        if m:
            record(m.group(1), f'texture:{name}')

    ids = sorted(evidence)
    rows = []
    for cid in ids:
        if cid in XDZR8_V11931_UMA_CHARACTER_ID_DICTIONARY:
            rows.append({
                'id': cid,
                'name': XDZR8_V11931_UMA_CHARACTER_ID_DICTIONARY[cid],
                'category': 'UMA_CHARACTER',
                'status': 'AUDITED',
                'evidence': list(evidence.get(cid, [])),
            })
        elif cid in XDZR8_V11931_UMA_AUXILIARY_ID_DICTIONARY:
            label, category = XDZR8_V11931_UMA_AUXILIARY_ID_DICTIONARY[cid]
            rows.append({
                'id': cid, 'name': label, 'category': category,
                'status': 'AUDITED_AUXILIARY',
                'evidence': list(evidence.get(cid, [])),
            })
        else:
            rows.append({
                'id': cid, 'name': 'Unknown / unmapped', 'category': 'UNKNOWN',
                'status': 'UNKNOWN', 'evidence': list(evidence.get(cid, [])),
            })

    if not rows:
        status = 'NO_CHR_ID'
        primary_id = ''
        primary_name = ''
    elif len(rows) == 1:
        status = rows[0]['status']
        primary_id = rows[0]['id']
        primary_name = rows[0]['name']
    else:
        # Multiple explicit chr namespaces may occur in composite/reference scenes.
        # Never guess which identity is authoritative.
        status = 'AMBIGUOUS_MULTIPLE_CHR_IDS'
        primary_id = ''
        primary_name = ''

    return {
        'ids': ids,
        'rows': rows,
        'primary_id': primary_id,
        'primary_name': primary_name,
        'status': status,
        'labels': [f"{row['id']}:{row['name']}" for row in rows],
        'classification_authority': 'STRUCTURE_NOT_ID',
        'id_drives_shader_roles': False,
        'dictionary_revision': 'AUDITED_2026_09_23',
    }


XDZR8_V11932_UMA_TEXTURE_EXTENSIONS = {
    '.png', '.dds', '.tga', '.jpg', '.jpeg', '.bmp', '.tif', '.tiff',
    '.exr', '.webp', '.hdr', '.ktx', '.ktx2',
}

XDZR8_V11932_GENERIC_SUFFIX_HINTS = (
    (re.compile(r'_(?:d|diffuse|albedo|color|colour|col)$'), 'base_color'),
    (re.compile(r'_(?:n|nm|normal|norm)$'), 'normal'),
    (re.compile(r'_(?:s|spec|specular)$'), 'specular'),
    (re.compile(r'_(?:r|rough|roughness)$'), 'roughness'),
    (re.compile(r'_(?:m|metal|metallic|metalness)$'), 'metallic'),
    (re.compile(r'_(?:a|alpha|opacity|transparency)$'), 'opacity'),
    (re.compile(r'_(?:ao|occlusion)$'), 'ambient_occlusion'),
    (re.compile(r'_(?:e|emit|emission|emissive)$'), 'emission'),
    (re.compile(r'_(?:mask|mask\d+|detail|detail\d+)$'), 'mask_or_detail'),
)


def _xdzr8_v11932_classify_uma_texture_filename(filename):
    """Classify one filename without opening or interpreting the image payload.

    KNOWN means the filename matches semantics already proven by the V11.9.3
    structural UMA dictionary. PARTIAL means an explicit UMA namespace is present
    and a generic naming hint or known anatomy token exists, but SaberShader has
    not proven the exact UMA semantic. UNKNOWN keeps explicit UMA namespaces that
    do not match either set. AMBIGUOUS is fail-closed when multiple incompatible
    anatomy/hint signals appear. Other texture filenames are IGNORED.
    """
    name = Path(str(filename or '')).name.casefold()
    stem = Path(name).stem.casefold()
    base = {
        'filename': name,
        'stem': stem,
        'status': 'IGNORED',
        'family': '',
        'component': '',
        'semantic': '',
        'semantic_authority': 'NONE',
        'pattern': '',
        'character_id': '',
        'asset_id': '',
        'variant': '',
        'evidence': [],
    }
    if not stem:
        return base

    # Proven V11.9.3 patterns. Keep these deliberately narrow.
    m = re.match(r'^tex_chr(?P<cid>\d+)_(?P<variant>\d+)_(?P<component>face|hair)_(?P<semantic>diff|shad_c|base|ctrl)$', stem)
    if m:
        semantic = m.group('semantic')
        return {**base, 'status': 'KNOWN', 'family': 'chr', 'component': m.group('component'),
                'semantic': semantic, 'semantic_authority': 'UMA_PROVEN',
                'pattern': f'tex_chr<ID>_<VAR>_{m.group("component")}_{semantic}',
                'character_id': m.group('cid'), 'variant': m.group('variant'),
                'evidence': ['V11.9.3 proven chr face/hair companion grammar']}

    m = re.match(r'^tex_chr(?P<cid>\d+)_(?P<variant>\d+)_eye0$', stem)
    if m:
        return {**base, 'status': 'KNOWN', 'family': 'chr', 'component': 'eye',
                'semantic': 'eye_base', 'semantic_authority': 'UMA_PROVEN',
                'pattern': 'tex_chr<ID>_<VAR>_eye0', 'character_id': m.group('cid'),
                'variant': m.group('variant'), 'evidence': ['V11.9.3 proven eye0 base grammar']}

    m = re.match(r'^tex_chr(?P<cid>\d+)_(?P<variant>\d+)_eyehi(?P<layer>\d+)$', stem)
    if m:
        return {**base, 'status': 'KNOWN', 'family': 'chr', 'component': 'eye',
                'semantic': 'eye_highlight', 'semantic_authority': 'UMA_PROVEN',
                'pattern': 'tex_chr<ID>_<VAR>_eyehiXX', 'character_id': m.group('cid'),
                'variant': m.group('variant'), 'evidence': [f'V11.9.3 proven eye highlight layer {m.group("layer")}']}

    m = re.match(r'^tex_bdy(?P<asset>\d+)_(?P<variant>\d+)_(?P<semantic>diff|shad_c|base|ctrl)$', stem)
    if m:
        semantic = m.group('semantic')
        return {**base, 'status': 'KNOWN', 'family': 'bdy', 'component': 'body',
                'semantic': semantic, 'semantic_authority': 'UMA_PROVEN',
                'pattern': f'tex_bdy<ID>_<VAR>_{semantic}', 'asset_id': m.group('asset'),
                'variant': m.group('variant'), 'evidence': ['V11.9.3 proven body companion grammar']}

    m = re.match(r'^tex_tail(?P<tail>\d+)_(?P<variant>\d+)_(?P<asset>\d+)_diff$', stem)
    if m:
        return {**base, 'status': 'KNOWN', 'family': 'tail', 'component': 'tail',
                'semantic': 'diff', 'semantic_authority': 'UMA_PROVEN',
                'pattern': 'tex_tail<ID>_<VAR>_<ASSET>_diff', 'asset_id': m.group('asset'),
                'variant': m.group('variant'),
                'evidence': ['V11.9.3 proven tail Diff grammar; tail IDs are not character-identity authority']}

    m = re.match(r'^tex_tail(?P<tail>\d+)_(?P<variant>\d+)_0000_(?P<semantic>base|ctrl)$', stem)
    if m:
        semantic = m.group('semantic')
        return {**base, 'status': 'KNOWN', 'family': 'tail', 'component': 'tail',
                'semantic': semantic, 'semantic_authority': 'UMA_PROVEN',
                'pattern': f'tex_tail<ID>_<VAR>_0000_{semantic}', 'asset_id': '0000',
                'variant': m.group('variant'),
                'evidence': ['V11.9.3 proven neutral 0000 tail auxiliary grammar']}

    # Explicit UMA namespace, but not a proven exact grammar.
    chr_match = re.match(r'^tex_chr(?P<cid>\d+)_(?P<variant>\d+)_(?P<rest>.+)$', stem)
    bdy_match = re.match(r'^tex_bdy(?P<asset>\d+)_(?P<variant>\d+)_(?P<rest>.+)$', stem)
    tail_match = re.match(r'^tex_tail(?P<tail>\d+)_(?P<variant>\d+)_(?P<rest>.+)$', stem)
    m = chr_match or bdy_match or tail_match
    if m:
        family = 'chr' if chr_match else ('bdy' if bdy_match else 'tail')
        rest = str(m.group('rest') or '')
        anatomy = [token for token in ('face', 'hair', 'eye', 'mayu', 'tail', 'body', 'bdy') if re.search(rf'(?:^|_){token}(?:_|$)', rest)]
        hints = []
        for pattern, label in XDZR8_V11932_GENERIC_SUFFIX_HINTS:
            if pattern.search(stem):
                hints.append(label)
        anatomy = sorted(set(anatomy))
        hints = sorted(set(hints))
        evidence = []
        if anatomy:
            evidence.append('known anatomy token(s): ' + ','.join(anatomy))
        if hints:
            evidence.append('generic suffix hint(s), not UMA-proven: ' + ','.join(hints))
        ambiguous = len(anatomy) > 1 or len(hints) > 1
        status = 'AMBIGUOUS' if ambiguous else ('PARTIAL' if (anatomy or hints) else 'UNKNOWN')
        semantic = hints[0] if len(hints) == 1 else ''
        component = anatomy[0] if len(anatomy) == 1 else ''
        # Preserve the unproven suffix shape in the catalogue signature so a
        # future audit can distinguish genuinely new conventions instead of
        # collapsing every unknown file into one generic bucket. Numeric payloads
        # are normalized so character/variant IDs do not create false patterns.
        rest_pattern = re.sub(r'\d{4,}', '<ID>', rest)
        rest_pattern = re.sub(r'\d+', 'XX', rest_pattern)
        row = {**base, 'status': status, 'family': family, 'component': component,
               'semantic': semantic, 'semantic_authority': 'GENERIC_HINT_ONLY' if hints else 'UNRESOLVED',
               'pattern': f'tex_{family}<ID>_<VAR>_{rest_pattern}', 'variant': m.group('variant'),
               'evidence': evidence or ['explicit UMA namespace with unresolved naming']}
        if chr_match:
            row['character_id'] = chr_match.group('cid')
        elif bdy_match:
            row['asset_id'] = bdy_match.group('asset')
        else:
            row['asset_id'] = tail_match.group('tail')
        return row

    # A malformed/novel tex_chr/tex_bdy/tex_tail prefix is still worth surfacing.
    if re.match(r'^tex_(?:chr|bdy|tail)', stem):
        normalized = re.sub(r'\d{4,}', '<ID>', stem)
        normalized = re.sub(r'\d+', 'XX', normalized)
        return {**base, 'status': 'UNKNOWN', 'semantic_authority': 'UNRESOLVED',
                'pattern': normalized,
                'evidence': ['UMA-like namespace present but grammar is unresolved']}
    return base


def _xdzr8_v11932_explicit_chr_ids_from_path(relative_path):
    """Return explicit chr#### namespaces from path components only.

    This deliberately excludes bare bdy/tail numeric IDs. A texture can therefore
    be grouped under a character only when its own filename or its containing path
    explicitly says chr####.
    """
    raw = str(relative_path or '').replace('\\', '/').casefold()
    return sorted(set(re.findall(r'(?<![a-z0-9])chr(\d{4})(?!\d)', raw)))


def _xdzr8_v11932_character_label(cid):
    cid = str(cid or '')
    if cid in XDZR8_V11931_UMA_CHARACTER_ID_DICTIONARY:
        return XDZR8_V11931_UMA_CHARACTER_ID_DICTIONARY[cid], 'AUDITED'
    if cid in XDZR8_V11931_UMA_AUXILIARY_ID_DICTIONARY:
        label, category = XDZR8_V11931_UMA_AUXILIARY_ID_DICTIONARY[cid]
        return label, f'AUDITED_{category}'
    return 'Unknown / unmapped', 'UNKNOWN'


def _xdzr8_v11932_audit_uma_texture_library(root_path, progress_callback=None):
    """Read-only recursive naming audit for a local UMA texture library."""
    root = Path(str(root_path or '')).expanduser()
    if not root.exists() or not root.is_dir():
        raise ValueError(f'UMA Texture Library folder is not a directory: {root}')

    texture_paths = []
    scan_errors = []
    max_files = 250000
    for dirpath, dirnames, filenames in os.walk(str(root), followlinks=False):
        # Deterministic traversal and no hidden symlink recursion.
        dirnames[:] = sorted(d for d in dirnames if not Path(dirpath, d).is_symlink())
        for filename in sorted(filenames):
            path = Path(dirpath) / filename
            if path.suffix.casefold() not in XDZR8_V11932_UMA_TEXTURE_EXTENSIONS:
                continue
            texture_paths.append(path)
            if len(texture_paths) >= max_files:
                scan_errors.append(f'Scan capped at {max_files} texture files for safety.')
                break
        if len(texture_paths) >= max_files:
            break

    counts = {k: 0 for k in ('KNOWN', 'PARTIAL', 'UNKNOWN', 'AMBIGUOUS', 'IGNORED')}
    patterns = {}
    characters = {}
    findings = []
    manifest = []
    digest = hashlib.sha256()

    total = len(texture_paths)
    for index, path in enumerate(texture_paths, 1):
        if progress_callback is not None:
            try:
                progress_callback(index, max(total, 1))
            except Exception:
                pass
        try:
            rel = path.relative_to(root).as_posix()
        except Exception:
            rel = path.name
        row = _xdzr8_v11932_classify_uma_texture_filename(path.name)
        explicit_ids = set(_xdzr8_v11932_explicit_chr_ids_from_path(rel))
        if row.get('character_id'):
            explicit_ids.add(str(row['character_id']))
        explicit_ids = sorted(explicit_ids)
        identity_status = 'NONE'
        identity_id = ''
        if len(explicit_ids) == 1:
            identity_status = 'EXPLICIT_CHR_NAMESPACE'
            identity_id = explicit_ids[0]
        elif len(explicit_ids) > 1:
            identity_status = 'AMBIGUOUS_MULTIPLE_CHR_IDS'
            # A naming row that would otherwise be KNOWN/PARTIAL cannot be safely
            # attached to one character when the path itself has conflicting chr IDs.
            if row.get('status') != 'IGNORED':
                row['status'] = 'AMBIGUOUS'
                row['evidence'] = list(row.get('evidence') or []) + ['multiple explicit chr#### namespaces in relative path']

        status = str(row.get('status') or 'UNKNOWN')
        counts[status] = counts.get(status, 0) + 1
        pattern = str(row.get('pattern') or '')
        if pattern and status != 'IGNORED':
            patterns[pattern] = patterns.get(pattern, 0) + 1

        try:
            size = int(path.stat().st_size)
        except Exception as exc:
            size = -1
            scan_errors.append(f'{rel}: stat failed: {exc}')
        digest.update(rel.casefold().encode('utf-8', errors='replace'))
        digest.update(b'\0')
        digest.update(str(size).encode('ascii', errors='replace'))
        digest.update(b'\n')

        label = ''
        label_status = ''
        if identity_id:
            label, label_status = _xdzr8_v11932_character_label(identity_id)
            bucket = characters.setdefault(identity_id, {
                'id': identity_id, 'name': label, 'label_status': label_status,
                'total': 0, 'KNOWN': 0, 'PARTIAL': 0, 'UNKNOWN': 0,
                'AMBIGUOUS': 0, 'IGNORED': 0,
            })
            bucket['total'] += 1
            bucket[status] = bucket.get(status, 0) + 1

        item = {
            'relative_path': rel,
            'size_bytes': size,
            'status': status,
            'family': row.get('family', ''),
            'component': row.get('component', ''),
            'semantic': row.get('semantic', ''),
            'semantic_authority': row.get('semantic_authority', 'NONE'),
            'pattern': pattern,
            'explicit_chr_ids': explicit_ids,
            'identity_status': identity_status,
            'character_id': identity_id,
            'character_name': label,
            'character_label_status': label_status,
            'evidence': list(row.get('evidence') or []),
        }
        manifest.append(item)
        if status in {'PARTIAL', 'UNKNOWN', 'AMBIGUOUS'}:
            findings.append(item)

    return {
        'schema': 'SaberShader_UMA_Texture_Library_Audit_v11932',
        'version': '11.9.3.2',
        'root': str(root),
        'scanned_at_local': time.strftime('%Y-%m-%d %H:%M:%S'),
        'texture_extensions': sorted(XDZR8_V11932_UMA_TEXTURE_EXTENSIONS),
        'texture_files_scanned': total,
        'counts': counts,
        'uma_namespace_files': counts.get('KNOWN', 0) + counts.get('PARTIAL', 0) + counts.get('UNKNOWN', 0) + counts.get('AMBIGUOUS', 0),
        'characters_detected': len(characters),
        'characters': [characters[cid] for cid in sorted(characters)],
        'patterns_detected': len(patterns),
        'patterns': [{'pattern': key, 'count': patterns[key]} for key in sorted(patterns)],
        'findings': findings,
        'manifest': manifest,
        'fingerprint_sha256': digest.hexdigest(),
        'scan_errors': scan_errors[:1000],
        'scan_error_count': len(scan_errors),
        'classification_authority': 'NAMING_ONLY_READ_ONLY',
        'character_identity_authority': 'EXPLICIT_CHR_NAMESPACE_ONLY',
        'id_drives_shader_roles': False,
        'assets_copied_or_modified': False,
    }



def _xdzr8_v11932_normalize_image_source_name(value):
    """Return a stable source-like image name while ignoring Blender .001 collisions."""
    raw = str(value or '').strip().replace('\\', '/')
    raw = raw.rsplit('/', 1)[-1]
    if not raw:
        return ''
    # Blender can turn "foo.png" into datablock name "foo.png.001".
    raw = re.sub(r'(?i)(\.(?:png|dds|tga|jpg|jpeg|bmp|tif|tiff|exr|webp|hdr|ktx|ktx2))\.\d{3}$', r'\1', raw)
    raw = re.sub(r'\.\d{3}$', '', raw)
    return raw


def _xdzr8_v11932_best_image_name_classification(candidates):
    """Choose the strongest naming classification without inspecting image pixels."""
    priority = {'KNOWN': 5, 'AMBIGUOUS': 4, 'PARTIAL': 3, 'UNKNOWN': 2, 'IGNORED': 1}
    best = None
    best_name = ''
    seen = set()
    for value in candidates or []:
        name = _xdzr8_v11932_normalize_image_source_name(value)
        key = name.casefold()
        if not name or key in seen:
            continue
        seen.add(key)
        row = _xdzr8_v11932_classify_uma_texture_filename(name)
        if best is None or priority.get(row.get('status', 'IGNORED'), 0) > priority.get(best.get('status', 'IGNORED'), 0):
            best = row
            best_name = name
    if best is None:
        best = _xdzr8_v11932_classify_uma_texture_filename('')
    best = dict(best)
    best['classification_name'] = best_name
    return best


def _xdzr8_v11932_image_key(image):
    try:
        return int(image.as_pointer())
    except Exception:
        return str(getattr(image, 'name_full', '') or getattr(image, 'name', '') or id(image))


def _xdzr8_v11932_collect_blend_image_usage():
    """Map Image datablocks to material/node/object users without mutating any datablock."""
    usage = {}
    material_objects = {}
    try:
        for obj in bpy.data.objects:
            if getattr(obj, 'type', '') != 'MESH':
                continue
            for slot in getattr(obj, 'material_slots', []) or []:
                mat = getattr(slot, 'material', None)
                if mat is not None:
                    material_objects.setdefault(str(mat.name), set()).add(str(obj.name))
    except Exception:
        pass

    def walk_tree(tree, material_name, prefix, seen_trees):
        if tree is None:
            return
        try:
            key = int(tree.as_pointer())
        except Exception:
            key = id(tree)
        if key in seen_trees:
            return
        seen_trees.add(key)
        try:
            nodes = list(tree.nodes)
        except Exception:
            nodes = []
        for node in nodes:
            image = getattr(node, 'image', None)
            if image is not None:
                ikey = _xdzr8_v11932_image_key(image)
                rec = usage.setdefault(ikey, {'materials': set(), 'objects': set(), 'nodes': []})
                rec['materials'].add(material_name)
                rec['objects'].update(material_objects.get(material_name, set()))
                rec['nodes'].append({
                    'material': material_name,
                    'node': str(getattr(node, 'name', '') or ''),
                    'label': str(getattr(node, 'label', '') or ''),
                    'tree_path': prefix,
                })
            sub_tree = getattr(node, 'node_tree', None)
            if sub_tree is not None:
                node_name = str(getattr(node, 'name', '') or 'Group')
                walk_tree(sub_tree, material_name, f'{prefix}/{node_name}', seen_trees)

    try:
        materials = list(bpy.data.materials)
    except Exception:
        materials = []
    for mat in materials:
        if not bool(getattr(mat, 'use_nodes', False)):
            continue
        tree = getattr(mat, 'node_tree', None)
        walk_tree(tree, str(mat.name), str(mat.name), set())
    return usage


def _xdzr8_v11932_audit_current_blend(progress_callback=None):
    """Audit Image datablocks in the current .blend, including packed images.

    This is metadata-only: no unpack, save, reload, pixel access or material edits.
    """
    try:
        images = list(bpy.data.images)
    except Exception:
        images = []
    usage_map = _xdzr8_v11932_collect_blend_image_usage()
    counts = {k: 0 for k in ('KNOWN', 'PARTIAL', 'UNKNOWN', 'AMBIGUOUS', 'IGNORED')}
    patterns = {}
    characters = {}
    findings = []
    manifest = []
    scan_errors = []
    digest = hashlib.sha256()
    blend_stats = {
        'images': 0,
        'packed': 0,
        'external': 0,
        'generated': 0,
        'render_result': 0,
        'used_by_model': 0,
        'used_by_material': 0,
        'unused': 0,
        'material_bindings': 0,
    }

    total = len(images)
    for index, image in enumerate(images, 1):
        if progress_callback is not None:
            try:
                progress_callback(index, max(total, 1))
            except Exception:
                pass
        blend_stats['images'] += 1
        name = str(getattr(image, 'name', '') or '')
        filepath = str(getattr(image, 'filepath_raw', '') or getattr(image, 'filepath', '') or '')
        source = str(getattr(image, 'source', '') or '')
        image_type = str(getattr(image, 'type', '') or '')
        ikey = _xdzr8_v11932_image_key(image)
        usage = usage_map.get(ikey, {'materials': set(), 'objects': set(), 'nodes': []})
        materials = sorted(str(v) for v in usage.get('materials', set()))
        objects = sorted(str(v) for v in usage.get('objects', set()))
        nodes = list(usage.get('nodes', []))
        blend_stats['material_bindings'] += len(nodes)

        packed = False
        try:
            packed = bool(getattr(image, 'packed_file', None))
        except Exception:
            packed = False
        try:
            packed_files = getattr(image, 'packed_files', None)
            if packed_files is not None:
                packed = packed or len(packed_files) > 0
        except Exception:
            pass

        if packed:
            storage = 'PACKED_IN_BLEND'
            blend_stats['packed'] += 1
        elif source == 'GENERATED':
            storage = 'GENERATED'
            blend_stats['generated'] += 1
        elif image_type in {'RENDER_RESULT', 'COMPOSITING'} or name in {'Render Result', 'Viewer Node'}:
            storage = 'RENDER_RESULT'
            blend_stats['render_result'] += 1
        elif filepath:
            storage = 'EXTERNAL_FILE'
            blend_stats['external'] += 1
        else:
            storage = 'DATABLOCK_ONLY'

        if objects:
            usage_status = 'USED_BY_MODEL'
            blend_stats['used_by_model'] += 1
        elif materials:
            usage_status = 'USED_BY_MATERIAL'
            blend_stats['used_by_material'] += 1
        elif storage == 'PACKED_IN_BLEND':
            usage_status = 'PACKED_UNUSED'
            blend_stats['unused'] += 1
        elif storage == 'GENERATED':
            usage_status = 'GENERATED'
            blend_stats['unused'] += 1
        elif storage == 'RENDER_RESULT':
            usage_status = 'RENDER_RESULT'
            blend_stats['unused'] += 1
        else:
            usage_status = 'UNUSED'
            blend_stats['unused'] += 1

        candidates = [name, filepath]
        row = _xdzr8_v11932_best_image_name_classification(candidates)
        explicit_ids = set()
        for value in candidates + materials:
            explicit_ids.update(_xdzr8_v11932_explicit_chr_ids_from_path(value))
        if row.get('character_id'):
            explicit_ids.add(str(row['character_id']))
        explicit_ids = sorted(explicit_ids)
        identity_status = 'NONE'
        identity_id = ''
        if len(explicit_ids) == 1:
            identity_status = 'EXPLICIT_CHR_NAMESPACE'
            identity_id = explicit_ids[0]
        elif len(explicit_ids) > 1:
            identity_status = 'AMBIGUOUS_MULTIPLE_CHR_IDS'
            if row.get('status') != 'IGNORED':
                row['status'] = 'AMBIGUOUS'
                row['evidence'] = list(row.get('evidence') or []) + ['multiple explicit chr#### namespaces across image/material bindings']

        status = str(row.get('status') or 'UNKNOWN')
        counts[status] = counts.get(status, 0) + 1
        pattern = str(row.get('pattern') or '')
        if pattern and status != 'IGNORED':
            patterns[pattern] = patterns.get(pattern, 0) + 1

        label = ''
        label_status = ''
        if identity_id:
            label, label_status = _xdzr8_v11932_character_label(identity_id)
            bucket = characters.setdefault(identity_id, {
                'id': identity_id, 'name': label, 'label_status': label_status,
                'total': 0, 'KNOWN': 0, 'PARTIAL': 0, 'UNKNOWN': 0,
                'AMBIGUOUS': 0, 'IGNORED': 0,
            })
            bucket['total'] += 1
            bucket[status] = bucket.get(status, 0) + 1

        try:
            dims = list(getattr(image, 'size', (0, 0)))
            width = int(dims[0]) if len(dims) > 0 else 0
            height = int(dims[1]) if len(dims) > 1 else 0
        except Exception:
            width = height = 0
        try:
            colorspace = str(image.colorspace_settings.name)
        except Exception:
            colorspace = ''

        source_name = _xdzr8_v11932_normalize_image_source_name(row.get('classification_name') or name or filepath)
        catalogue_key = source_name.casefold()
        digest_fields = [name, filepath, source, image_type, storage, str(width), str(height), colorspace,
                         '|'.join(materials), '|'.join(objects), catalogue_key]
        digest.update(('\0'.join(digest_fields) + '\n').encode('utf-8', errors='replace'))

        item = {
            'audit_source': 'CURRENT_BLEND',
            'entry_type': 'BLEND_IMAGE_DATABLOCK',
            'relative_path': f'BLEND::{name}',
            'image_name': name,
            'source_name': source_name,
            'catalogue_key': catalogue_key,
            'filepath': filepath,
            'storage': storage,
            'packed': bool(packed),
            'image_source': source,
            'image_type': image_type,
            'width': width,
            'height': height,
            'colorspace': colorspace,
            'usage_status': usage_status,
            'used_by_materials': materials,
            'used_by_objects': objects,
            'used_by_nodes': nodes,
            'material_binding_count': len(nodes),
            'size_bytes': -1,
            'status': status,
            'family': row.get('family', ''),
            'component': row.get('component', ''),
            'semantic': row.get('semantic', ''),
            'semantic_authority': row.get('semantic_authority', 'NONE'),
            'pattern': pattern,
            'explicit_chr_ids': explicit_ids,
            'identity_status': identity_status,
            'character_id': identity_id,
            'character_name': label,
            'character_label_status': label_status,
            'evidence': list(row.get('evidence') or []),
        }
        manifest.append(item)
        if status in {'PARTIAL', 'UNKNOWN', 'AMBIGUOUS'}:
            findings.append(item)

    return {
        'schema': 'SaberShader_UMA_Packed_Blend_Audit_v11932',
        'version': '11.9.3.2',
        'audit_source': 'CURRENT_BLEND',
        'root': str(bpy.data.filepath or '<unsaved .blend>'),
        'scanned_at_local': time.strftime('%Y-%m-%d %H:%M:%S'),
        'texture_entries_scanned': total,
        'texture_files_scanned': total,
        'folder_texture_files_scanned': 0,
        'blend_images_scanned': total,
        'blend_stats': blend_stats,
        'counts': counts,
        'uma_namespace_files': counts.get('KNOWN', 0) + counts.get('PARTIAL', 0) + counts.get('UNKNOWN', 0) + counts.get('AMBIGUOUS', 0),
        'characters_detected': len(characters),
        'characters': [characters[cid] for cid in sorted(characters)],
        'patterns_detected': len(patterns),
        'patterns': [{'pattern': key, 'count': patterns[key]} for key in sorted(patterns)],
        'findings': findings,
        'manifest': manifest,
        'fingerprint_sha256': digest.hexdigest(),
        'scan_errors': scan_errors,
        'scan_error_count': len(scan_errors),
        'classification_authority': 'NAMING_AND_BINDING_METADATA_ONLY_READ_ONLY',
        'character_identity_authority': 'EXPLICIT_CHR_NAMESPACE_ONLY',
        'id_drives_shader_roles': False,
        'assets_copied_or_modified': False,
        'images_unpacked_or_exported': False,
        'pixels_read': False,
    }


def _xdzr8_v11932_prepare_folder_audit_report(report):
    """Add uniform source metadata to the legacy folder audit manifest."""
    report = dict(report or {})
    report['audit_source'] = 'EXTERNAL_FOLDER'
    report['texture_entries_scanned'] = int(report.get('texture_files_scanned', 0) or 0)
    report['folder_texture_files_scanned'] = int(report.get('texture_files_scanned', 0) or 0)
    report['blend_images_scanned'] = 0
    report['blend_stats'] = {}
    for item in report.get('manifest') or []:
        item['audit_source'] = 'EXTERNAL_FOLDER'
        item['entry_type'] = 'EXTERNAL_FILE'
        rel = str(item.get('relative_path') or '')
        source_name = _xdzr8_v11932_normalize_image_source_name(rel)
        item['source_name'] = source_name
        item['catalogue_key'] = source_name.casefold()
        item['storage'] = 'EXTERNAL_FILE'
        item['packed'] = False
        item['usage_status'] = 'NOT_EVALUATED'
        item['used_by_materials'] = []
        item['used_by_objects'] = []
        item['used_by_nodes'] = []
        item['material_binding_count'] = 0
    return report


def _xdzr8_v11932_merge_audit_reports(reports, audit_source):
    """Merge current-blend and/or folder audits into one deterministic catalogue."""
    reports = [r for r in (reports or []) if r]
    if not reports:
        raise ValueError('No UMA audit source was available.')
    counts = {k: 0 for k in ('KNOWN', 'PARTIAL', 'UNKNOWN', 'AMBIGUOUS', 'IGNORED')}
    patterns = {}
    characters = {}
    manifest = []
    findings = []
    scan_errors = []
    blend_stats = {
        'images': 0, 'packed': 0, 'external': 0, 'generated': 0,
        'render_result': 0, 'used_by_model': 0, 'used_by_material': 0,
        'unused': 0, 'material_bindings': 0,
    }
    folder_count = 0
    blend_count = 0
    roots = []
    for report in reports:
        roots.append(str(report.get('root', '')))
        folder_count += int(report.get('folder_texture_files_scanned', 0) or 0)
        blend_count += int(report.get('blend_images_scanned', 0) or 0)
        for key in blend_stats:
            blend_stats[key] += int((report.get('blend_stats') or {}).get(key, 0) or 0)
        scan_errors.extend(report.get('scan_errors') or [])
        for item in report.get('manifest') or []:
            row = dict(item)
            manifest.append(row)
            status = str(row.get('status') or 'UNKNOWN')
            counts[status] = counts.get(status, 0) + 1
            pattern = str(row.get('pattern') or '')
            if pattern and status != 'IGNORED':
                patterns[pattern] = patterns.get(pattern, 0) + 1
            cid = str(row.get('character_id') or '')
            if cid:
                label = str(row.get('character_name') or '')
                label_status = str(row.get('character_label_status') or '')
                bucket = characters.setdefault(cid, {
                    'id': cid, 'name': label, 'label_status': label_status,
                    'total': 0, 'KNOWN': 0, 'PARTIAL': 0, 'UNKNOWN': 0,
                    'AMBIGUOUS': 0, 'IGNORED': 0,
                })
                bucket['total'] += 1
                bucket[status] = bucket.get(status, 0) + 1
            if status in {'PARTIAL', 'UNKNOWN', 'AMBIGUOUS'}:
                findings.append(row)

    source_keys = {'CURRENT_BLEND': set(), 'EXTERNAL_FOLDER': set()}
    for row in manifest:
        key = str(row.get('catalogue_key') or '').casefold()
        src = str(row.get('audit_source') or '')
        if key and src in source_keys:
            source_keys[src].add(key)
    present_in_both = sorted(source_keys['CURRENT_BLEND'] & source_keys['EXTERNAL_FOLDER'])
    only_in_blend = sorted(source_keys['CURRENT_BLEND'] - source_keys['EXTERNAL_FOLDER'])
    only_in_folder = sorted(source_keys['EXTERNAL_FOLDER'] - source_keys['CURRENT_BLEND'])

    digest = hashlib.sha256()
    for row in sorted(manifest, key=lambda v: (str(v.get('audit_source','')), str(v.get('relative_path','')).casefold())):
        signature = [
            str(row.get('audit_source','')), str(row.get('relative_path','')).casefold(),
            str(row.get('catalogue_key','')), str(row.get('size_bytes','')),
            str(row.get('width','')), str(row.get('height','')), str(row.get('storage','')),
            '|'.join(row.get('used_by_materials') or []), '|'.join(row.get('used_by_objects') or []),
        ]
        digest.update(('\0'.join(signature) + '\n').encode('utf-8', errors='replace'))

    total = len(manifest)
    return {
        'schema': 'SaberShader_UMA_Texture_Library_And_Packed_Blend_Audit_v11932',
        'version': '11.9.3.2',
        'audit_source': audit_source,
        'root': ' + '.join(v for v in roots if v),
        'roots': roots,
        'scanned_at_local': time.strftime('%Y-%m-%d %H:%M:%S'),
        'texture_entries_scanned': total,
        'texture_files_scanned': total,
        'folder_texture_files_scanned': folder_count,
        'blend_images_scanned': blend_count,
        'blend_stats': blend_stats,
        'counts': counts,
        'uma_namespace_files': counts.get('KNOWN', 0) + counts.get('PARTIAL', 0) + counts.get('UNKNOWN', 0) + counts.get('AMBIGUOUS', 0),
        'characters_detected': len(characters),
        'characters': [characters[cid] for cid in sorted(characters)],
        'patterns_detected': len(patterns),
        'patterns': [{'pattern': key, 'count': patterns[key]} for key in sorted(patterns)],
        'cross_source': {
            'present_in_both_count': len(present_in_both),
            'only_in_blend_count': len(only_in_blend),
            'only_in_folder_count': len(only_in_folder),
            'present_in_both': present_in_both[:5000],
            'only_in_blend': only_in_blend[:5000],
            'only_in_folder': only_in_folder[:5000],
        },
        'findings': findings,
        'manifest': manifest,
        'fingerprint_sha256': digest.hexdigest(),
        'scan_errors': scan_errors[:1000],
        'scan_error_count': len(scan_errors),
        'classification_authority': 'NAMING_AND_BINDING_METADATA_ONLY_READ_ONLY',
        'character_identity_authority': 'EXPLICIT_CHR_NAMESPACE_ONLY',
        'id_drives_shader_roles': False,
        'assets_copied_or_modified': False,
        'images_unpacked_or_exported': False,
        'pixels_read': False,
    }

def _xdzr8_v11932_audit_text_report(report):
    counts = report.get('counts') or {}
    comparison = report.get('comparison') or {}
    blend_stats = report.get('blend_stats') or {}
    cross = report.get('cross_source') or {}
    lines = [
        'SABERSHADER V11.9.3.2 — UMA TEXTURE LIBRARY & PACKED BLEND AUDIT',
        '=' * 76,
        f"Audit source: {report.get('audit_source', '')}",
        f"Root/source: {report.get('root', '')}",
        f"Scanned: {report.get('scanned_at_local', '')}",
        f"Fingerprint SHA-256: {report.get('fingerprint_sha256', '')}",
        '',
        'SUMMARY',
        f"Texture entries scanned: {report.get('texture_entries_scanned', report.get('texture_files_scanned', 0))}",
        f"External folder files: {report.get('folder_texture_files_scanned', 0)}",
        f"Current .blend Image datablocks: {report.get('blend_images_scanned', 0)}",
        f"UMA namespace entries: {report.get('uma_namespace_files', 0)}",
        f"KNOWN: {counts.get('KNOWN', 0)}",
        f"PARTIAL: {counts.get('PARTIAL', 0)}",
        f"UNKNOWN: {counts.get('UNKNOWN', 0)}",
        f"AMBIGUOUS: {counts.get('AMBIGUOUS', 0)}",
        f"IGNORED: {counts.get('IGNORED', 0)}",
        f"Characters detected by explicit chr#### namespace: {report.get('characters_detected', 0)}",
        f"Naming patterns detected: {report.get('patterns_detected', 0)}",
        f"Scan errors: {report.get('scan_error_count', 0)}",
    ]
    if report.get('blend_images_scanned', 0):
        lines.extend([
            '', 'CURRENT .BLEND IMAGE METADATA',
            f"Packed images: {blend_stats.get('packed', 0)}",
            f"External-file images: {blend_stats.get('external', 0)}",
            f"Generated images: {blend_stats.get('generated', 0)}",
            f"Render-result/viewer images: {blend_stats.get('render_result', 0)}",
            f"Used by model objects: {blend_stats.get('used_by_model', 0)}",
            f"Used by materials only: {blend_stats.get('used_by_material', 0)}",
            f"Unused/non-model images: {blend_stats.get('unused', 0)}",
            f"Material/node image bindings: {blend_stats.get('material_bindings', 0)}",
        ])
    if report.get('audit_source') == 'BLEND_AND_FOLDER':
        lines.extend([
            '', 'BLEND / FOLDER CROSS-CHECK',
            f"Texture names present in both: {cross.get('present_in_both_count', 0)}",
            f"Texture names only in current .blend: {cross.get('only_in_blend_count', 0)}",
            f"Texture names only in external folder: {cross.get('only_in_folder_count', 0)}",
        ])
    lines.extend([
        '',
        'PREVIOUS-AUDIT COMPARISON',
        f"Previous source mode: {comparison.get('previous_source', 'none') or 'none'}",
        f"Previous fingerprint: {comparison.get('previous_fingerprint', 'none') or 'none'}",
        f"Texture delta: {comparison.get('texture_delta', 0):+d}",
        f"Character delta: {comparison.get('character_delta', 0):+d}",
        f"Pattern delta: {comparison.get('pattern_delta', 0):+d}",
        f"Catalogue changed: {bool(comparison.get('catalogue_changed', False))}",
        f"Comparison reset: {comparison.get('reset_reason', '') or 'none'}",
        '',
        'CHARACTERS',
    ])
    for row in report.get('characters') or []:
        lines.append(
            f"[{row.get('id')}] {row.get('name')} ({row.get('label_status')}) — "
            f"entries={row.get('total',0)} known={row.get('KNOWN',0)} partial={row.get('PARTIAL',0)} "
            f"unknown={row.get('UNKNOWN',0)} ambiguous={row.get('AMBIGUOUS',0)}"
        )
    lines.extend(['', 'PATTERNS'])
    for row in report.get('patterns') or []:
        lines.append(f"{row.get('count',0):6d}  {row.get('pattern','')}")

    if report.get('blend_images_scanned', 0):
        lines.extend(['', 'CURRENT .BLEND IMAGE BINDINGS'])
        blend_rows = [r for r in (report.get('manifest') or []) if r.get('audit_source') == 'CURRENT_BLEND']
        max_blend_rows = 5000
        for row in blend_rows[:max_blend_rows]:
            mats = ', '.join(row.get('used_by_materials') or []) or '-'
            objs = ', '.join(row.get('used_by_objects') or []) or '-'
            size = f"{row.get('width',0)}x{row.get('height',0)}"
            lines.append(
                f"[{row.get('storage','')}/{row.get('usage_status','')}/{row.get('status','')}] "
                f"{row.get('image_name','')} | {size} | colorspace={row.get('colorspace','') or '-'} | "
                f"semantic={row.get('component') or '-'}:{row.get('semantic') or '-'} | materials={mats} | objects={objs}"
            )
        if len(blend_rows) > max_blend_rows:
            lines.append(f'... {len(blend_rows) - max_blend_rows} additional .blend images omitted from TXT; JSON contains the complete manifest.')

    lines.extend(['', 'FINDINGS — PARTIAL / UNKNOWN / AMBIGUOUS'])
    findings = report.get('findings') or []
    max_text_findings = 5000
    for row in findings[:max_text_findings]:
        cid = row.get('character_id') or '-'
        cname = row.get('character_name') or 'unmapped'
        evidence = '; '.join(row.get('evidence') or [])
        location = row.get('relative_path') or row.get('image_name') or ''
        lines.append(
            f"[{row.get('status')}] source={row.get('audit_source','')} chr={cid}:{cname} semantic={row.get('semantic') or '-'} "
            f"authority={row.get('semantic_authority')} :: {location} :: {evidence}"
        )
    if len(findings) > max_text_findings:
        lines.append(f'... {len(findings) - max_text_findings} additional findings omitted from TXT view; JSON contains the complete audit manifest.')
    if report.get('scan_errors'):
        lines.extend(['', 'SCAN WARNINGS'])
        lines.extend(str(v) for v in report.get('scan_errors') or [])
    lines.extend([
        '',
        'SAFETY / AUTHORITY',
        'Current-.blend audit reads Image datablock metadata and material/node/object bindings only.',
        'Packed images are NOT unpacked, exported, saved, reloaded or sampled for pixels.',
        'External-folder audit reads filenames and filesystem metadata only.',
        'No source texture or shader material is copied or modified.',
        'KNOWN means proven naming grammar, not visual inspection of image contents.',
        'Character labels use explicit chr#### namespaces only.',
        'Character IDs never drive material roles or shader selection.',
    ])
    return '\n'.join(lines) + '\n'

def _xdzr8_v11932_write_text_datablock(name, content):
    text_block = bpy.data.texts.get(name)
    if text_block is None:
        text_block = bpy.data.texts.new(name)
    else:
        text_block.clear()
    text_block.write(str(content or ''))
    return text_block


def _xdzr8_v1193_normalize_source_material_name(name):
    """Normalize exporter/Blender collision suffixes without erasing source semantics."""
    raw = str(name or '').strip().casefold()
    return re.sub(r'\.\d{3}$', '', raw)


def _xdzr8_v1193_detect_uma_source_naming(materials=None, image_paths=None):
    """Detect recurring Uma source naming without character-specific IDs.

    This dictionary is intentionally structural. Numeric character/outfit IDs are
    captured but never used as identity evidence. A pack may be Diff-only and
    still qualify as an Uma naming source; advanced Uma shading remains separately
    gated by the proven companion-map/profile detector.
    """
    material_names=[]
    for mat in materials or []:
        try:
            material_names.append(_xdzr8_v1193_normalize_source_material_name(getattr(mat, 'name', '')))
        except Exception:
            pass
    image_names=[]
    for path in image_paths or []:
        try:
            image_names.append(Path(str(path)).name.casefold())
        except Exception:
            pass
    # Loaded image datablocks preserve useful source names even when their paths
    # are broken or the configured texture folder is not yet available.
    try:
        for img in bpy.data.images:
            name=Path(str(getattr(img,'name','') or '')).name.casefold()
            if name:
                image_names.append(name)
            fp=str(getattr(img,'filepath','') or '')
            if fp:
                image_names.append(Path(fp.replace('\\','/')).name.casefold())
    except Exception:
        pass

    # V11.9.3.1: character identity labels are computed in a strictly diagnostic
    # side channel from explicit chr#### namespaces. The classifier never consumes
    # this dictionary.
    character_diagnostics = _xdzr8_v11931_uma_character_diagnostics(material_names, image_names)

    material_hits=[]
    roles=set()
    ids=set()
    for name in sorted(set(n for n in material_names if n)):
        m=re.match(r'^mtl_chr(\d+)_([0-9]+)_(face|hair|eye|mayu)$', name)
        if m:
            roles.add(m.group(3)); ids.add(m.group(1)); material_hits.append(name); continue
        m=re.match(r'^mtl_bdy(\d+)_([0-9]+)$', name)
        if m:
            roles.add('bdy'); ids.add(m.group(1)); material_hits.append(name); continue
        m=re.match(r'^mtl_tail(\d+)_([0-9]+)(?:_(\d+))?$', name)
        if m:
            roles.add('tail'); material_hits.append(name); continue

    texture_hits=[]
    tex_roles=set()
    diff_only_candidates=0
    tail_neutral_aux=False
    for name in sorted(set(n for n in image_names if n)):
        stem=Path(name).stem.casefold()
        if re.match(r'^tex_chr\d+_\d+_(?:face|hair)_diff$', stem):
            tex_roles.add('diff'); texture_hits.append(name); diff_only_candidates += 1; continue
        if re.match(r'^tex_chr\d+_\d+_eye0$', stem):
            tex_roles.add('eye0'); texture_hits.append(name); continue
        if re.match(r'^tex_chr\d+_\d+_eyehi\d+$', stem):
            tex_roles.add('eyehi'); texture_hits.append(name); continue
        if re.match(r'^tex_bdy\d+_\d+_diff$', stem):
            tex_roles.add('diff'); texture_hits.append(name); diff_only_candidates += 1; continue
        if re.match(r'^tex_(?:chr\d+_\d+_(?:face|hair)|bdy\d+_\d+)_(?:shad_c|base|ctrl)$', stem):
            suffix=stem.rsplit('_',1)[-1]
            if stem.endswith('_shad_c'): suffix='shad_c'
            tex_roles.add(suffix); texture_hits.append(name); continue
        if re.match(r'^tex_tail\d+_\d+_\d+_diff$', stem):
            tex_roles.add('tail_diff'); texture_hits.append(name); diff_only_candidates += 1; continue
        if re.match(r'^tex_tail\d+_\d+_0000_(?:base|ctrl)$', stem):
            tex_roles.add('tail_neutral_aux'); texture_hits.append(name); tail_neutral_aux=True; continue

    score=0.0
    evidence=[]
    head_roles=len(roles & {'face','hair','eye','mayu'})
    if head_roles >= 3:
        score += 5.0; evidence.append(f'UMA chr material-role bundle={sorted(roles & {"face","hair","eye","mayu"})}')
    elif head_roles == 2:
        score += 3.0; evidence.append(f'partial UMA chr material roles={sorted(roles & {"face","hair","eye","mayu"})}')
    elif head_roles == 1:
        score += 1.0; evidence.append(f'single UMA chr material role={sorted(roles & {"face","hair","eye","mayu"})}')
    if 'bdy' in roles:
        score += 2.0; evidence.append('UMA mtl_bdy family')
    if 'tail' in roles:
        score += 1.2; evidence.append('UMA mtl_tail family')
    if 'mayu' in roles:
        score += 1.0; evidence.append('UMA romanized mayu/eyebrow material')
    if 'diff' in tex_roles:
        score += 1.4; evidence.append('UMA tex_*_diff family')
    if 'eye0' in tex_roles:
        score += 1.2; evidence.append('UMA eye0 texture')
    if 'eyehi' in tex_roles:
        score += 1.5; evidence.append('UMA eyehiXX highlight stack')
    if {'shad_c','base','ctrl'} & tex_roles:
        score += 1.0 + 0.45 * len({'shad_c','base','ctrl'} & tex_roles)
        evidence.append('UMA authored companion semantics=' + '/'.join(sorted({'shad_c','base','ctrl'} & tex_roles)))
    if tail_neutral_aux:
        score += 0.8; evidence.append('UMA tail neutral 0000 Base/Ctrl convention')

    confidence='HIGH' if score >= 7.0 and (head_roles >= 2 or ('bdy' in roles and 'tail' in roles)) else ('MEDIUM' if score >= 4.5 else ('LOW' if score >= 2.0 else 'NONE'))
    enabled=bool(score >= 4.5 and (head_roles >= 2 or ('bdy' in roles and bool(texture_hits))))
    has_companions=bool({'shad_c','base','ctrl'} & tex_roles)
    diff_only=bool(enabled and 'diff' in tex_roles and not has_companions)
    return {
        'enabled': enabled, 'score': float(score), 'confidence': confidence,
        'roles': sorted(roles), 'texture_roles': sorted(tex_roles),
        'material_hits': material_hits[:64], 'texture_hits': texture_hits[:96],
        'character_ids': sorted(ids), 'diff_only': diff_only,
        'tail_neutral_aux': bool(tail_neutral_aux), 'evidence': evidence,
        'character_diagnostics': character_diagnostics,
        'diagnostic_character_id': character_diagnostics.get('primary_id', ''),
        'diagnostic_character_name': character_diagnostics.get('primary_name', ''),
        'diagnostic_character_status': character_diagnostics.get('status', 'NO_CHR_ID'),
    }


def _xdzr8_v1183_build_companion_family_lookup(image_paths, families, cross_id_aliases=None, intelligence=None):
    """Build an exact-root -> companion-family lookup from detected authored bundles.

    Each family remains tied to its own primary Diff root. Shared cross-ID
    auxiliaries are exposed only through the explicit alias table recorded for
    that primary family. The result is deterministic and model-agnostic.
    """
    catalog = _xdzr8_v113_texture_catalog(
        _xdzr8_v11821_texture_index_from_paths(image_paths, intelligence), intelligence
    )
    alias_table = cross_id_aliases or {}
    family_rows = []
    lookup = {}
    for row in families or []:
        primary_root = _aef11_key(row.get('root', ''))
        roots = []
        for value in list(row.get('exact_roots', []) or []) + [row.get('root', '')]:
            key = _aef11_key(value)
            if key and key not in roots:
                roots.append(key)
        roles = {}
        for root in roots:
            for role, paths in (catalog.get(root) or {}).items():
                dsts = roles.setdefault(role, [])
                for path in paths or []:
                    if path not in dsts:
                        dsts.append(path)
        for role, path in (alias_table.get(primary_root) or {}).items():
            if path is None:
                continue
            dsts = roles.setdefault(role, [])
            if path not in dsts:
                dsts.append(path)
        family = {
            'primary_root': primary_root,
            'roots': roots,
            'roles': {role: list(paths) for role, paths in roles.items()},
            'cross_id': bool(row.get('cross_id', False)),
            'shared_aux_root': _aef11_key(row.get('shared_aux_root', '')),
            'members': list(row.get('members', []) or []),
        }
        family_rows.append(family)
        for root in roots or ([primary_root] if primary_root else []):
            lookup[root] = family
    return {'families': family_rows, 'lookup': lookup, 'catalog': catalog}


def _xdzr8_v1183_material_bound_companion_context(mat, source_ref, existing=None, intelligence=None):
    """Resolve the authored companion family actually bound to this material."""
    info = intelligence if isinstance(intelligence, dict) else {}
    contextual = dict(existing or {})
    if source_ref is not None:
        contextual = _xdzr8_v1122_contextual_existing_images(
            source_ref,
            _aef11_existing_role_images(source_ref) if source_ref else contextual,
            info,
        )
        for role, img in (existing or {}).items():
            contextual.setdefault(role, img)

    scored = {}
    reasons = {}

    def add_root(root, weight, reason):
        root = _aef11_key(root)
        if not root:
            return
        weight = float(weight)
        if weight > scored.get(root, -1.0):
            scored[root] = weight
        reasons.setdefault(root, []).append(str(reason))

    role_priority = {
        'base': 225.0,
        'face_map': 215.0,
        'control_map': 208.0,
        'region_map': 206.0,
        'shadow_color': 204.0,
        'toon_control': 198.0,
        'opacity': 194.0,
        'highlight': 188.0,
        'derived_eye_atlas': 186.0,
        'normal': 180.0,
    }

    for role, image in contextual.items():
        if not image:
            continue
        try:
            semantic = _xdzr8_v1122_semantic_role(image.name, info)
            root = _xdzr8_v1122_texture_family_root(image.name, semantic, info)
        except Exception:
            continue
        add_root(root, role_priority.get(semantic or role, 170.0), f'contextual {semantic or role} binding')

    for rec in _xdzr8_v1181_match_binding_records(mat, source_ref, info):
        for role, tex_names in (rec.get('roles') or {}).items():
            for tex_name in tex_names:
                semantic = role or _xdzr8_v1122_semantic_role(tex_name, info)
                root = _xdzr8_v1122_texture_family_root(tex_name, semantic, info)
                add_root(root, role_priority.get(semantic, 235.0) + 12.0, f'explicit source slot {semantic}: {Path(tex_name).name}')

    for rec in _xdzr8_v1123_match_pmx_records(mat, source_ref, info):
        tex_name = Path(str(rec.get('texture') or '').replace('\\', '/')).name
        if not tex_name:
            continue
        semantic = _xdzr8_v1122_semantic_role(tex_name, info)
        root = _xdzr8_v1122_texture_family_root(tex_name, semantic, info)
        add_root(root, 242.0, f'PMX texture binding {tex_name}')

    ranked = sorted(scored.items(), key=lambda kv: (-kv[1], kv[0]))
    primary_root = ranked[0][0] if ranked else ''
    family_lookup = (info.get('companion_family_lookup') or {})
    family = family_lookup.get(primary_root) if primary_root else None

    family_images = {}
    family_roles = set()
    family_roots = []
    if family:
        family_roots = list(family.get('roots', []) or [])
        for role, paths in (family.get('roles') or {}).items():
            if not paths:
                continue
            family_roles.add(role)
            family_images[role] = paths[0]
    elif primary_root:
        family_roots = [primary_root]
        catalog = info.get('texture_catalog') or {}
        for role, paths in (catalog.get(primary_root) or {}).items():
            if not paths:
                continue
            family_roles.add(role)
            family_images[role] = paths[0]

    hints = []
    seen_hints = set()
    def add_hint(text, weight, reason):
        text = str(text or '').strip()
        if not text:
            return
        key = (text.casefold(), str(reason))
        if key in seen_hints:
            return
        seen_hints.add(key)
        hints.append({'text': text, 'weight': float(weight), 'reason': str(reason)})

    for root, score in ranked[:4]:
        add_hint(root, 0.52 + min(0.48, score / 260.0), f'bound companion root {root}')
    for rec in _xdzr8_v1123_match_pmx_records(mat, source_ref, info):
        local_name = str(rec.get('local_name', '') or '').strip()
        english_name = str(rec.get('english_name', '') or '').strip()
        memo = str(rec.get('memo', '') or '').strip()
        texture = Path(str(rec.get('texture', '') or '').replace('\\', '/')).stem
        if texture:
            add_hint(texture, 0.82, 'PMX bound texture stem')
        if local_name:
            add_hint(local_name, 0.76, 'PMX local material name')
        if english_name:
            add_hint(english_name, 0.72, 'PMX english material name')
        if memo:
            add_hint(memo, 0.55, 'PMX material memo')
    for role, image in contextual.items():
        try:
            stem = Path(str(getattr(image, 'name', '') or '')).stem
        except Exception:
            stem = ''
        if stem:
            add_hint(stem, 0.42, f'contextual {role} texture stem')

    primary_role_hints = []
    for row in hints:
        role = _aef11_role_from_text(row['text'])
        if role in XDZR8_V112_VALID_ROLES and role not in primary_role_hints:
            primary_role_hints.append(role)

    return {
        'primary_root': primary_root,
        'ranked_roots': ranked,
        'root_reasons': {root: list(rows) for root, rows in reasons.items()},
        'family': family,
        'family_roots': family_roots,
        'family_roles': sorted(family_roles),
        'family_images': family_images,
        'contextual_images': contextual,
        'semantic_hints': hints,
        'primary_role_hints': primary_role_hints,
    }


def _xdzr8_v1182_mesh_provenance(objects):
    """Audit non-identity mesh channels and possible exporter helper swarms.

    This is telemetry/evidence only.  It never classifies a material and never
    excludes geometry.  The point is to preserve useful Extra-UV/vertex-colour/
    custom-normal data and warn when a mesh contains many tiny disconnected
    components that may be billboard/helper proxies.
    """
    result = {
        'meshes': 0, 'extra_uv_meshes': 0, 'extra_uv_layers': 0,
        'vertex_color_meshes': 0, 'vertex_color_layers': 0,
        'custom_normal_meshes': 0, 'component_swarm_candidates': 0,
        'rows': [], 'swarm_rows': [],
    }
    for obj in objects or []:
        if not obj or getattr(obj, 'type', '') != 'MESH' or not getattr(obj, 'data', None):
            continue
        me = obj.data
        result['meshes'] += 1
        try:
            uv_names = [str(layer.name) for layer in me.uv_layers]
        except Exception:
            uv_names = []
        extra_uv = max(0, len(uv_names) - 1)
        if extra_uv:
            result['extra_uv_meshes'] += 1
            result['extra_uv_layers'] += extra_uv
        try:
            color_attrs = [str(a.name) for a in me.color_attributes if getattr(a, 'domain', '') in {'POINT','CORNER'}]
        except Exception:
            try:
                color_attrs = [str(a.name) for a in me.vertex_colors]
            except Exception:
                color_attrs = []
        if color_attrs:
            result['vertex_color_meshes'] += 1
            result['vertex_color_layers'] += len(color_attrs)
        try:
            has_custom = bool(getattr(me, 'has_custom_normals', False))
        except Exception:
            has_custom = False
        if has_custom:
            result['custom_normal_meshes'] += 1
        result['rows'].append(
            f'{getattr(obj,"name","Mesh")}: uv={len(uv_names)} extraUV={extra_uv} '
            f'vertexColor={len(color_attrs)} customNormals={has_custom}'
        )

        # Conservative disconnected-component audit.  No source geometry is changed.
        try:
            polys = me.polygons
            if len(polys) < 24 or len(polys) > 200000:
                continue
            parent = list(range(len(polys)))
            size = [1] * len(polys)
            def find(x):
                while parent[x] != x:
                    parent[x] = parent[parent[x]]; x = parent[x]
                return x
            def union(a,b):
                ra,rb=find(a),find(b)
                if ra == rb: return
                if size[ra] < size[rb]: ra,rb=rb,ra
                parent[rb]=ra; size[ra]+=size[rb]
            owner = {}
            for pi, poly in enumerate(polys):
                for vid in poly.vertices:
                    vid = int(vid)
                    prior = owner.get(vid)
                    if prior is None: owner[vid] = pi
                    else: union(pi, prior)
            comp_sizes = {}
            for pi in range(len(polys)):
                r=find(pi); comp_sizes[r]=comp_sizes.get(r,0)+1
            small = [n for n in comp_sizes.values() if n <= 80]
            small_polys = sum(small)
            ratio = small_polys / max(len(polys),1)
            if len(small) >= 12 and ratio >= 0.20:
                result['component_swarm_candidates'] += 1
                row = f'{getattr(obj,"name","Mesh")}: components={len(comp_sizes)} small<=80={len(small)} smallPolyRatio={ratio:.2f}'
                result['swarm_rows'].append(row)
        except Exception:
            pass
    return result


def _xdzr8_v1182_eye_highlight_paths(base_image, intelligence=None):
    """Return numbered highlight companions that demonstrably share the eye-base prefix."""
    if base_image is None:
        return []
    stem = Path(str(getattr(base_image, 'name', '') or '')).stem.casefold()
    m = re.match(r'^(.*?)(?:eye\d+)$', stem)
    if not m:
        return []
    prefix = m.group(1)
    rows = []
    for path in (intelligence or {}).get('image_paths', []) or []:
        pstem = path.stem.casefold()
        hm = re.match(r'^(.*?)(?:eyehi(\d+))$', pstem)
        if not hm or hm.group(1) != prefix:
            continue
        try: order = int(hm.group(2))
        except Exception: order = 999
        rows.append((order, path))
    rows.sort(key=lambda row: (row[0], str(row[1]).casefold()))
    return [p for _order,p in rows[:6]]


def _xdzr8_v1182_expose_control_channels(nodes, links, texture_nodes):
    """Expose authored control/region RGB(A) channels without assigning meanings."""
    audit = {'maps': 0, 'channels': 0, 'rows': []}
    y = -2460
    for role in ('region_map', 'control_map'):
        tex = (texture_nodes or {}).get(role)
        image = getattr(tex, 'image', None) if tex else None
        if image is None:
            continue
        sep = _xdzr8_v114_new_separate_color(nodes)
        if sep is None:
            continue
        sep.name = f'XDZR8 V11.8.2 • {role} • Channel Split'
        sep.label = f'{AEF11_ROLE_LABELS.get(role, role)} • Channels UNRESOLVED'
        sep.location = (-500, y)
        try: links.new(tex.outputs['Color'], sep.inputs[0])
        except Exception: pass
        audit['maps'] += 1
        labels=[]
        for offset,ch in enumerate(('R','G','B','A')):
            reroute=nodes.new('NodeReroute')
            reroute.name=f'XDZR8 V11.8.2 • {role} • {ch} • UNRESOLVED'
            reroute.label=f'{ch} • Authored Control • UNRESOLVED'
            reroute.location=(-250,y-offset*52)
            src = tex.outputs.get('Alpha') if ch == 'A' else _xdzr8_v114_output_socket(sep,ch)
            if src is not None:
                try: links.new(src, reroute.inputs[0])
                except Exception: pass
            audit['channels'] += 1; labels.append(ch)
        audit['rows'].append(f'{image.name}: {role} channels={"/".join(labels)} unresolved')
        y -= 270
    return audit


def _xdzr8_v1182_material_authored_audit(materials, intelligence=None):
    """Aggregate authored-companion usage without changing generated materials."""
    totals = {
        'shadow': 0, 'eye_highlights': 0, 'control_maps': 0, 'control_channels': 0,
        'outline_mask_ready': 0, 'face_directional_ready': 0,
        'target_core': 0, 'target_source_light': 0, 'target_region_threshold': 0,
        'target_authored_shadow': 0, 'target_eye_highlights': 0,
        'target_uma_eye_materials': 0, 'target_eye_reflection_layers': 0,
        'target_uma_face_materials': 0, 'target_face_feature_protected': 0,
        'target_uma_face_shading': 0, 'target_uma_face_sdf': 0,
        'target_uma_face_fallback_light': 0, 'target_uma_face_dynamic_light': 0, 'target_uma_face_physical_light': 0, 'target_uma_face_shadow_palette': 0, 'target_uma_face_outline_fidelity': 0, 'target_uma_face_auxiliary': 0, 'target_uma_view_dependent_correction': 0, 'target_fgo_native_slot_core': 0,
        'saber_groups': 0, 'duplicate_polygons_ignored': 0,
    }
    for mat in materials or []:
        if mat is None:
            continue
        try:
            totals['shadow'] += int(bool(mat.get('XDZR8_V11_8_2_AuthoredShadowConsumed', False)))
            totals['eye_highlights'] += int(mat.get('XDZR8_V11_8_2_EyeHighlightStack', 0))
            totals['control_maps'] += int(mat.get('XDZR8_V11_8_2_ControlMapsExposed', 0))
            totals['control_channels'] += int(mat.get('XDZR8_V11_8_2_ControlChannelsExposed', 0))
            totals['outline_mask_ready'] += int(bool(mat.get('XDZR8_V11_8_2_OutlineMaskReady', False)))
            totals['face_directional_ready'] += int(bool(mat.get('XDZR8_V11_8_2_FaceDirectionalReady', False)))
            totals['target_core'] += int(bool(mat.get('XDZR8_V119_TargetNPRCore', False)))
            totals['target_source_light'] += int(bool(mat.get('XDZR8_V119_SourceLightDirectionUsed', False)))
            totals['target_region_threshold'] += int(bool(mat.get('XDZR8_V119_RegionThresholdUsed', False)))
            totals['target_authored_shadow'] += int(bool(mat.get('XDZR8_V119_AuthoredShadowUsed', False)))
            totals['target_eye_highlights'] += int(mat.get('XDZR8_V119_EyeHighlightLayers', 0))
            totals['target_uma_eye_materials'] += int(bool(mat.get('XDZR8_V1192_UmaEyeProfile', False)))
            totals['target_eye_reflection_layers'] += int(mat.get('XDZR8_V1192_EyeReflectionLayers', 0))
            totals['target_uma_face_materials'] += int(bool(mat.get('XDZR8_V11921_UmaFaceProfile', False)))
            totals['target_face_feature_protected'] += int(bool(mat.get('XDZR8_V11921_FaceFeatureProtection', False)))
            totals['target_uma_face_shading'] += int(bool(mat.get('XDZR8_V11922_UmaFaceShading', False)))
            totals['target_uma_face_sdf'] += int(bool(mat.get('XDZR8_V11922_UmaFaceSDF', False)))
            totals['target_uma_face_fallback_light'] += int(bool(mat.get('XDZR8_V11923_UmaFaceFallbackLight', False)))
            totals['target_uma_face_dynamic_light'] += int(bool(mat.get('XDZR8_V11928_UmaFaceDynamicLight', False)))
            totals['target_uma_face_physical_light'] += int(bool(mat.get('XDZR8_V119211_UmaFacePhysicalLightAcquisition', False)))
            totals['target_uma_face_shadow_palette'] += int(bool(mat.get('XDZR8_V119211_UmaShadowPalette', False)))
            totals['target_uma_face_outline_fidelity'] += int(bool(mat.get('XDZR8_V119211_UmaFaceOutlineFidelity', False)))
            totals['target_uma_face_auxiliary'] += int(bool(mat.get('XDZR8_V11923_UmaFaceAuxiliary', False)))
            totals['target_uma_view_dependent_correction'] += int(bool(mat.get('XDZR8_V1192188_UmaViewDependentFacialCorrection', False)))
            totals['target_fgo_native_slot_core'] += int(bool(mat.get('SaberShader_V103_FGONativeSlotCore', False)))
            totals['saber_groups'] += int(bool(mat.get('XDZR8_V1191_SaberShaderNodeGroup', False)))
        except Exception:
            pass
    seen = set()
    for name,row in ((intelligence or {}).get('_v117_material_local_audit', {}) or {}).items():
        marker = str(name)
        if marker in seen:
            continue
        seen.add(marker)
        try: totals['duplicate_polygons_ignored'] += int(row.get('duplicate_polygons_ignored', 0))
        except Exception: pass
    return totals


def _xdzr8_v1181_binding_role_evidence(mat, source_ref, intelligence=None):
    records = _xdzr8_v1181_match_binding_records(mat, source_ref, intelligence)
    roles = set()
    details = []
    for rec in records:
        for role, names in (rec.get('roles') or {}).items():
            roles.add(role)
            details.append(f'{role}={"/".join(Path(n).name for n in names[:3])}')
    return roles, records, details



def _aef11_key(text):
    text = str(text or '').lower()
    text = re.sub(r'\.\d{3}$', '', text)
    text = re.sub(r'[^0-9a-z\u0080-\uffff]+', '', text)
    return text


def _aef1164_idprop_text(idblock, key):
    try:
        if idblock and hasattr(idblock, 'get'):
            value = idblock.get(key)
            if value is not None:
                return str(value)
    except Exception:
        pass
    try:
        value = getattr(idblock, key, None)
        if value is not None:
            return str(value)
    except Exception:
        pass
    return ''


def _aef1164_collection_name_hints(obj):
    names = []
    try:
        for col in getattr(obj, 'users_collection', []) or []:
            name = str(getattr(col, 'name', '') or '')
            if name:
                names.append(name)
    except Exception:
        pass
    cur = getattr(obj, 'parent', None)
    steps = 0
    while cur and steps < 8:
        name = str(getattr(cur, 'name', '') or '')
        if name:
            names.append(name)
        cur = getattr(cur, 'parent', None)
        steps += 1
    return names


def _aef1164_is_mmd_physics_helper(obj):
    if not obj:
        return False
    try:
        obj_type = getattr(obj, 'type', '')
        if obj_type not in {'MESH', 'EMPTY', 'ARMATURE'}:
            return False
    except Exception:
        return False
    name = str(getattr(obj, 'name', '') or '')
    key = _aef11_key(name)
    mmd_type = _aef11_key(_aef1164_idprop_text(obj, 'mmd_type'))
    if mmd_type in {'mmd_rigid', 'mmd_joint'}:
        return True
    if 'mmd_tools_rigid' in key or 'mmd_tools_joint' in key:
        return True
    try:
        if getattr(obj, 'rigid_body', None) is not None and ('mmd' in key or 'rigid' in key):
            return True
    except Exception:
        pass
    for hint in _aef1164_collection_name_hints(obj):
        low = _aef11_key(hint)
        if any(token in low for token in ('rigidbodies', 'rigid_bodies', 'rigid bodies', 'joints', 'joint')):
            if 'adj' not in low:
                return True
    try:
        for slot in getattr(obj, 'material_slots', []) or []:
            mat = getattr(slot, 'material', None)
            mat_name = _aef11_key(getattr(mat, 'name', ''))
            mat_type = _aef11_key(_aef1164_idprop_text(mat, 'mmd_type'))
            if mat_name.startswith('mmd_tools_rigid') or mat_name.startswith('mmd_tools_joint'):
                return True
            if mat_type in {'mmd_rigid', 'mmd_joint'}:
                return True
    except Exception:
        pass
    return False


def _aef1164_excluded_physics_helpers(scene):
    if not scene:
        return []
    out = []
    for obj in getattr(scene, 'objects', []):
        try:
            if _aef1164_is_mmd_physics_helper(obj):
                out.append(obj)
        except Exception:
            pass
    return out


# ---------------------------------------------------------------------
# V11.6.5 — AUTO GEOMETRY PROFILE / LOW-POLY DETECTION
# ---------------------------------------------------------------------

def _xdzr8_v1165_mesh_stats(obj):
    data = getattr(obj, 'data', None)
    if obj is None or getattr(obj, 'type', None) != 'MESH' or data is None:
        return {'polygons': 0, 'vertices': 0, 'edges': 0, 'material_slots': 0, 'used_materials': 0}
    try:
        used = {int(p.material_index) for p in data.polygons}
    except Exception:
        used = set()
    return {
        'polygons': len(getattr(data, 'polygons', []) or []),
        'vertices': len(getattr(data, 'vertices', []) or []),
        'edges': len(getattr(data, 'edges', []) or []),
        'material_slots': len(getattr(obj, 'material_slots', []) or []),
        'used_materials': len(used),
    }


def _xdzr8_v1165_geometry_profile(objects, source_family='General'):
    meshes = [o for o in (objects or []) if o and getattr(o, 'type', None) == 'MESH' and not _aef11_is_helper_object(o)]
    rows = []
    total_polys = 0
    total_verts = 0
    unique_mats = set()
    for obj in meshes:
        stats = _xdzr8_v1165_mesh_stats(obj)
        total_polys += int(stats['polygons'])
        total_verts += int(stats['vertices'])
        try:
            for slot in getattr(obj, 'material_slots', []) or []:
                mat = getattr(slot, 'material', None)
                if mat:
                    unique_mats.add(mat.as_pointer())
        except Exception:
            pass
        rows.append((obj, stats))
    rows.sort(key=lambda item: int(item[1]['polygons']), reverse=True)
    dominant_obj = rows[0][0] if rows else None
    dominant_stats = rows[0][1] if rows else {'polygons': 0, 'material_slots': 0, 'used_materials': 0}
    dominant_ratio = (float(dominant_stats['polygons']) / float(total_polys)) if total_polys > 0 else 0.0
    real_meshes = len(meshes)
    materials = len(unique_mats)
    dominant_slots = int(dominant_stats.get('material_slots', 0))
    dominant_used = int(dominant_stats.get('used_materials', 0))
    polys_per_material = float(total_polys) / max(1, materials)
    family = str(source_family or 'General')

    score = 0.0
    evidence = []
    if real_meshes == 1:
        score += 4.0
        evidence.append('single real mesh +4.0')
    elif real_meshes <= 2:
        score += 2.4
        evidence.append(f'{real_meshes} real meshes +2.4')
    elif real_meshes <= 4:
        score += 0.8
        evidence.append(f'{real_meshes} real meshes +0.8')
    if dominant_ratio >= 0.94:
        score += 3.0
        evidence.append(f'dominant mesh ratio={dominant_ratio:.3f} +3.0')
    elif dominant_ratio >= 0.80:
        score += 1.8
        evidence.append(f'dominant mesh ratio={dominant_ratio:.3f} +1.8')
    if dominant_used >= 8 or dominant_slots >= 8:
        score += 2.4
        evidence.append(f'dominant material slots={dominant_slots}/used={dominant_used} +2.4')
    elif dominant_used >= 4 or dominant_slots >= 4:
        score += 1.2
        evidence.append(f'dominant material slots={dominant_slots}/used={dominant_used} +1.2')
    if total_polys <= 60000:
        score += 1.4
        evidence.append(f'polygons={total_polys} <= 60000 +1.4')
    elif total_polys <= 120000:
        score += 0.6
        evidence.append(f'polygons={total_polys} <= 120000 +0.6')
    if materials >= 6 and polys_per_material <= 12000:
        score += 1.0
        evidence.append(f'polys/material={polys_per_material:.0f} +1.0')
    if family == 'MMD-type':
        score += 0.7
        evidence.append('MMD-type prior +0.7')

    # Counter-evidence: many independent meshes usually benefit from role-aware shells.
    if real_meshes >= 8:
        score -= 3.0
        evidence.append(f'many meshes={real_meshes} -3.0')
    if dominant_ratio < 0.55 and real_meshes >= 4:
        score -= 1.8
        evidence.append(f'low dominant ratio={dominant_ratio:.3f} -1.8')
    if total_polys > 220000:
        score -= 1.4
        evidence.append(f'high polygon count={total_polys} -1.4')

    # Strong topology pattern: one/two meshes carrying many materials should
    # switch to whole-mesh outline even when polygon count is moderately high.
    structural_low_poly = bool(
        real_meshes <= 2 and dominant_ratio >= 0.80 and max(dominant_used, dominant_slots) >= 6
    )
    low_poly = bool(score >= 6.0 or structural_low_poly)
    if low_poly:
        profile = 'LOW_POLY'
        confidence = 'HIGH' if (score >= 8.0 or structural_low_poly and real_meshes == 1) else 'MEDIUM'
        outline_strategy = 'WHOLE_MESH_SILHOUETTE'
    else:
        profile = 'STANDARD'
        confidence = 'HIGH' if score <= 2.5 else 'MEDIUM'
        outline_strategy = 'ROLE_AWARE_MULTI_SHELL'

    return {
        'profile': profile,
        'confidence': confidence,
        'score': float(score),
        'outline_strategy': outline_strategy,
        'real_meshes': int(real_meshes),
        'materials': int(materials),
        'total_polygons': int(total_polys),
        'total_vertices': int(total_verts),
        'dominant_object': getattr(dominant_obj, 'name', '') if dominant_obj else '',
        'dominant_ratio': float(dominant_ratio),
        'dominant_material_slots': int(dominant_slots),
        'dominant_used_materials': int(dominant_used),
        'polygons_per_material': float(polys_per_material),
        'evidence': evidence,
    }


def _xdzr8_v1165_whole_mesh_group(obj):
    data = getattr(obj, 'data', None)
    if data is None or not getattr(data, 'polygons', None):
        return None
    used = sorted({int(poly.material_index) for poly in data.polygons})
    if not used:
        return None
    return {
        'role': 'silhouette',
        'indices': used,
        'polygons': len(data.polygons),
        'materials': [
            getattr(slot.material, 'name', '')
            for slot in getattr(obj, 'material_slots', [])
            if getattr(slot, 'material', None)
        ],
    }

def _xdzr8_v11684_face_support_slot_role(obj, mat, character_context=None, settings=None):
    """Resolve the role of one material slot for LOW_POLY facial support.

    V11.6.8.2 exposed an important single-mesh failure mode: the normal refined
    outline role can fall back to *object-wide* head geometry. On a character
    whose entire body is one mesh, that same head hint is then reused for every
    slot and can incorrectly promote unrelated accessory slots to Face. The
    generated V11 material already stores its canonical material-local role, so
    for face-support targeting that stored role must win. Only genuinely legacy
    or unclassified materials are allowed to use the old object-hint fallback.
    """
    if mat is None:
        return 'cloth', 'missing material'
    try:
        usage = str(mat.get('XDZR8_UsageRole', '') or '').strip().lower()
        category = str(mat.get('AEF_V11_Category', '') or '').strip().lower()
        universal = bool(mat.get('AEF_V11_Universal', False))
    except Exception:
        usage, category, universal = '', '', False

    stored = usage or category
    if stored in XDZR8_V116_ROLE_MULTIPLIER:
        source = 'stored usage role' if usage else ('canonical generated role' if universal else 'stored category')
        return stored, source

    # Legacy/source material fallback only. This preserves compatibility for
    # models that have not yet been replaced by V11 generated materials.
    return _xdzr8_v116_refined_outline_role(obj, mat, character_context, settings), 'legacy object-hint fallback'


def _xdzr8_v11684_head_family_slot_evidence(mat, role=''):
    """Return conservative evidence that a generated slot belongs to a head shader family.

    This is deliberately broader than an anatomical Face verdict. MMD/game models
    commonly put face skin, eyes, lashes and small head accessories in one ``chr``
    or ``Face`` shader family. V11.6.8.5 uses this only to define the search pool;
    connected-component geometry decides which patch is the actual face surface.
    """
    if mat is None:
        return 0.0, 'missing material'
    bits = []
    try:
        bits.extend([
            str(getattr(mat, 'name', '') or ''),
            str(mat.get('AEF_V11_SourceMaterial', '') or ''),
            str(mat.get('AEF_V11_BaseImage', '') or ''),
            str(mat.get('XDZR8_RoleReason', '') or ''),
            str(mat.get('XDZR8_SourceConvention', '') or ''),
        ])
    except Exception:
        bits.append(str(getattr(mat, 'name', '') or ''))
    text = ' '.join(bits).lower()
    score = 0.0
    reasons = []
    role = str(role or '').lower()
    if role in {'face', 'mouth', 'eyes', 'eyes5'}:
        score += 3.0
        reasons.append(f'role={role}')
    if any(tok in text for tok in ('face', 'head-family', 'head family')):
        score += 2.4
        reasons.append('face/head metadata')
    # ``chr`` is a common head/character texture family in MMD game exports.
    if re.search(r'(^|[^a-z])chr([^a-z]|$)', text) or 'tex_chr' in text or 'mtl_chr' in text:
        score += 2.6
        reasons.append('chr texture/material family')
    if any(tok in text for tok in (' eye', 'eye_', 'iris', 'pupil', 'highlight')):
        score += 1.2
        reasons.append('eye-family metadata')
    return float(score), '; '.join(reasons) if reasons else 'no head-family evidence'


def _xdzr8_v11684_component_world_stats(component, src_obj, character_context):
    verts = set()
    for face in component:
        verts.update(face.verts)
    if not verts:
        return None
    points = []
    for vert in verts:
        try:
            points.append(src_obj.matrix_world @ vert.co)
        except Exception:
            points.append(vert.co.copy())
    if not points:
        return None
    lo = Vector((min(p.x for p in points), min(p.y for p in points), min(p.z for p in points)))
    hi = Vector((max(p.x for p in points), max(p.y for p in points), max(p.z for p in points)))
    center = (lo + hi) * 0.5
    span = hi - lo

    ctx = character_context or {}
    axis = int(ctx.get('axis', 2))
    cmin = ctx.get('min')
    cmax = ctx.get('max')
    ccenter = ctx.get('center')
    if cmin is None or cmax is None or ccenter is None:
        # Conservative local fallback. Normally the adaptive outline has already
        # built character_context, but this keeps the helper safe in isolation.
        cmin = lo.copy()
        cmax = hi.copy()
        ccenter = center.copy()
    height = max(float(ctx.get('height', float(cmax[axis] - cmin[axis]))), 1e-6)
    lateral_axes = [i for i in range(3) if i != axis]
    if not lateral_axes:
        lateral_axes = [0, 1]
    extents = {i: max(abs(float(cmax[i] - cmin[i])), 1e-6) for i in lateral_axes}
    width_axis = max(lateral_axes, key=lambda i: extents[i])
    depth_axis = min(lateral_axes, key=lambda i: extents[i])
    width_extent = extents[width_axis]
    depth_extent = extents[depth_axis]

    center_n = (float(center[axis]) - float(cmin[axis])) / height
    span_n = abs(float(span[axis])) / height
    width_center_n = abs(float(center[width_axis] - ccenter[width_axis])) / width_extent
    width_span_n = abs(float(span[width_axis])) / width_extent
    depth_center_n = abs(float(center[depth_axis] - ccenter[depth_axis])) / depth_extent
    depth_span_n = abs(float(span[depth_axis])) / depth_extent
    return {
        'verts': verts,
        'lo': lo, 'hi': hi, 'center': center, 'span': span,
        'axis': axis, 'width_axis': width_axis, 'depth_axis': depth_axis,
        'center_n': float(center_n), 'span_n': float(span_n),
        'width_center_n': float(width_center_n), 'width_span_n': float(width_span_n),
        'depth_center_n': float(depth_center_n), 'depth_span_n': float(depth_span_n),
    }


def _xdzr8_v11684_recover_face_surface_component(mesh, src_obj, group, character_context=None):
    """Keep only the most plausible connected facial surface on a LOW_POLY copy.

    V11.6.8.3 proved that material-level role labels alone are insufficient on
    single-mesh MMD characters: Miku's acc/acc+ were labelled Face, while the
    actual skin patch can be one connected island inside a mixed head atlas. This helper is a
    deliberately narrow material-local geometry pass used only by face support.
    It never edits the source mesh.
    """
    info = {
        'built': False,
        'candidate_slots': list(group.get('recovery_candidate_indices', []) or []),
        'candidate_components': 0,
        'eligible_components': 0,
        'material_index': -1,
        'material_name': '',
        'polygons': 0,
        'vertices': 0,
        'score': 0.0,
        'center_n': 0.0,
        'span_n': 0.0,
        'width_center_n': 0.0,
        'width_span_n': 0.0,
        'depth_center_n': 0.0,
        'depth_span_n': 0.0,
        'error': '',
    }
    if mesh is None or src_obj is None:
        info['error'] = 'missing mesh/object'
        return info
    candidate_slots = set(int(i) for i in info['candidate_slots'])
    if not candidate_slots:
        info['error'] = 'no head-family candidate slots'
        return info

    bm = bmesh.new()
    try:
        bm.from_mesh(mesh)
        bm.faces.ensure_lookup_table()
        bm.verts.ensure_lookup_table()
        pending = {face for face in bm.faces if int(face.material_index) in candidate_slots}
        components = []
        while pending:
            seed = pending.pop()
            mat_index = int(seed.material_index)
            stack = [seed]
            comp = [seed]
            while stack:
                face = stack.pop()
                for edge in face.edges:
                    for other in edge.link_faces:
                        if other in pending and int(other.material_index) == mat_index:
                            pending.remove(other)
                            stack.append(other)
                            comp.append(other)
            components.append((mat_index, comp))
        info['candidate_components'] = len(components)
        if not components:
            info['error'] = 'no connected head-family components'
            return info

        rows = []
        for mat_index, comp in components:
            stats = _xdzr8_v11684_component_world_stats(comp, src_obj, character_context)
            if not stats:
                continue
            poly_count = len(comp)
            # Conservative face-surface gate. The true anime face should be a
            # substantial, compact, central patch in the upper portion of the
            # character. Long hair/tails and tiny eye/accessory cards fail here.
            eligible = (
                poly_count >= 20 and
                0.72 <= stats['center_n'] <= 0.98 and
                0.025 <= stats['span_n'] <= 0.30 and
                stats['width_center_n'] <= 0.10 and
                0.04 <= stats['width_span_n'] <= 0.45 and
                stats['depth_span_n'] <= 0.60
            )
            if not eligible:
                continue
            info['eligible_components'] += 1
            # Polygon mass is intentionally strong: in the supplied Miku scene
            # the real face is 796 polygons, while eye/accessory islands are tens
            # of polygons and side head patches are ~170. Centrality/shape then
            # break ties without hard-coding any material name.
            score = 0.0
            score += min(6.0, float(poly_count) / 160.0)
            score += max(0.0, 2.5 - abs(stats['center_n'] - 0.89) * 12.0)
            score += max(0.0, 2.2 - stats['width_center_n'] * 20.0)
            score += max(0.0, 1.6 - abs(stats['span_n'] - 0.12) * 8.0)
            score += min(1.6, stats['width_span_n'] * 8.0)
            rows.append((score, poly_count, mat_index, comp, stats))

        if not rows:
            info['error'] = 'no eligible compact upper-head component'
            return info
        rows.sort(key=lambda row: (row[0], row[1]), reverse=True)
        score, poly_count, mat_index, best_comp, stats = rows[0]
        keep = set(best_comp)
        remove = [face for face in bm.faces if face not in keep]
        if remove:
            bmesh.ops.delete(bm, geom=remove, context='FACES')
        loose_edges = [edge for edge in bm.edges if not edge.link_faces]
        if loose_edges:
            try:
                bmesh.ops.delete(bm, geom=loose_edges, context='EDGES')
            except Exception:
                pass
        loose_verts = [vert for vert in bm.verts if not vert.link_faces]
        if loose_verts:
            try:
                bmesh.ops.delete(bm, geom=loose_verts, context='VERTS')
            except Exception:
                pass
        bm.normal_update()
        bm.to_mesh(mesh)
        try:
            mesh.update(calc_edges=True, calc_edges_loose=True)
        except TypeError:
            mesh.update()

        mat_name = ''
        try:
            if 0 <= mat_index < len(src_obj.material_slots):
                mat = src_obj.material_slots[mat_index].material
                mat_name = getattr(mat, 'name', '') if mat else ''
        except Exception:
            pass
        info.update({
            'built': True,
            'material_index': int(mat_index),
            'material_name': str(mat_name),
            'polygons': int(poly_count),
            'vertices': int(len(stats.get('verts', []))),
            'score': float(score),
            'center_n': float(stats['center_n']),
            'span_n': float(stats['span_n']),
            'width_center_n': float(stats['width_center_n']),
            'width_span_n': float(stats['width_span_n']),
            'depth_center_n': float(stats['depth_center_n']),
            'depth_span_n': float(stats['depth_span_n']),
        })
    except Exception as exc:
        info['error'] = str(exc)
    finally:
        bm.free()
    return info


def _xdzr8_v1168_low_poly_face_support_groups(obj, character_context=None, settings=None, geometry_profile=None):
    whole = _xdzr8_v1165_whole_mesh_group(obj)
    if whole is None:
        return []
    groups = [whole]
    profile = str((geometry_profile or {}).get('profile', 'STANDARD'))
    strategy = str((geometry_profile or {}).get('outline_strategy', 'ROLE_AWARE_MULTI_SHELL'))
    if profile != 'LOW_POLY' or strategy != 'WHOLE_MESH_SILHOUETTE':
        return groups

    face_indices = []
    face_polygons = 0
    face_materials = []
    face_role_sources = []
    # V11.9.2.16.1: Uma must not inherit Miku's component-recovery/jaw ribbon.
    # Keep a separate, semantically proven Face-only pool for the camera-silhouette path.
    face_only_indices = []
    face_only_polygons = 0
    face_only_materials = []
    face_only_role_sources = []
    slot_role_audit = []
    recovery_candidate_indices = []
    recovery_candidate_materials = []
    recovery_candidate_audit = []
    data = getattr(obj, 'data', None)
    if data is None or not getattr(data, 'polygons', None):
        return groups
    used = {}
    for poly in data.polygons:
        idx = int(poly.material_index)
        used[idx] = used.get(idx, 0) + 1

    for index, slot in enumerate(getattr(obj, 'material_slots', [])):
        mat = getattr(slot, 'material', None)
        if mat is None or index not in used:
            continue
        role, role_source = _xdzr8_v11684_face_support_slot_role(obj, mat, character_context, settings)
        mat_name = getattr(mat, 'name', '')
        slot_role_audit.append(f'{index}:{mat_name}->{role}[{role_source}]')
        if role in {'face', 'mouth'}:
            face_indices.append(index)
            face_polygons += int(used.get(index, 0))
            face_materials.append(mat_name)
            face_role_sources.append(role_source)
        if role == 'face':
            face_only_indices.append(index)
            face_only_polygons += int(used.get(index, 0))
            face_only_materials.append(mat_name)
            face_only_role_sources.append(role_source)

        head_score, head_reason = _xdzr8_v11684_head_family_slot_evidence(mat, role)
        recovery_candidate_audit.append(
            f'{index}:{mat_name} headScore={head_score:.1f} ({head_reason}) polys={int(used.get(index,0))}'
        )
        if head_score >= 2.5:
            recovery_candidate_indices.append(index)
            recovery_candidate_materials.append(mat_name)

    # V11.9.2.18: Raw Uma face support is a distinct architecture. The Face
    # material must already be semantically proven by the universal classifier.
    # The builder keeps the FULL source topology so loop/split normals and _UV3
    # corner data survive; only material routing decides which Solidify faces can ink.
    if bool((geometry_profile or {}).get('uma_reference_outline_architecture', False)):
        facial_shell_excluded_indices = []
        facial_shell_excluded_materials = []
        for index, slot in enumerate(getattr(obj, 'material_slots', [])):
            mat = getattr(slot, 'material', None)
            if mat is None or index not in used:
                continue
            role, _role_source = _xdzr8_v11684_face_support_slot_role(obj, mat, character_context, settings)
            mat_name = getattr(mat, 'name', '')
            low = str(mat_name).casefold()
            if role in {'face', 'mouth', 'eyes', 'eyes5'} or any(tag in low for tag in ('mayu','brow','lash')):
                facial_shell_excluded_indices.append(index)
                facial_shell_excluded_materials.append(mat_name)
        if facial_shell_excluded_indices and groups:
            keep_indices = [i for i in list(groups[0].get('indices', []) or []) if i not in set(facial_shell_excluded_indices)]
            keep_materials = []
            for idx, slot in enumerate(getattr(obj, 'material_slots', [])):
                mat = getattr(slot, 'material', None)
                if mat is not None and idx in keep_indices:
                    keep_materials.append(getattr(mat, 'name', ''))
            groups[0]['indices'] = keep_indices
            groups[0]['polygons'] = int(sum(int(used.get(i, 0)) for i in keep_indices))
            groups[0]['materials'] = keep_materials
            groups[0]['uma_facial_shell_separation'] = True
            groups[0]['excluded_face_indices'] = sorted(set(int(i) for i in facial_shell_excluded_indices))
            groups[0]['excluded_face_materials'] = list(dict.fromkeys(facial_shell_excluded_materials))
            groups[0]['separation_reason'] = 'Uma dedicated face-support owns facial outline; whole-mesh hull excludes face/eyes/mayu'
        if face_only_indices and face_only_polygons > 0:
            groups.append({
                'role': 'face',
                'indices': sorted(set(face_only_indices)),
                'polygons': int(face_only_polygons),
                'materials': list(dict.fromkeys(face_only_materials)),
                'face_role_sources': sorted(set(face_only_role_sources)) or ['semantic face slot'],
                'slot_role_audit': slot_role_audit,
                'recovery_candidate_indices': [],
                'recovery_candidate_materials': [],
                'recovery_candidate_audit': recovery_candidate_audit,
                'face_component_recovery': False,
                'use_direct_backface_hull': False,
                'face_support': True,
                'uma_reference_outline': True,
                'uma_authored_mask_outline': True,
                'uma_face_source': 'source_topology_semantic_face_slots_plus_authored_mask',
            })
        # Fail closed when no Face-only source can be demonstrated. Whole-mesh
        # silhouette remains available, but no synthetic facial ink is created.
        return groups

    # V11.6.8.5: the material-local connected-component pass remains Miku/generic
    # LOW_POLY behaviour whenever a conservative head-family pool exists.
    if recovery_candidate_indices or (face_indices and face_polygons > 0):
        fallback_indices = sorted(face_indices or recovery_candidate_indices)
        fallback_materials = list(face_materials or recovery_candidate_materials)
        groups.append({
            'role': 'face',
            'indices': fallback_indices,
            'polygons': int(face_polygons or sum(int(used.get(i, 0)) for i in fallback_indices)),
            'materials': fallback_materials,
            'face_role_sources': sorted(set(face_role_sources)) if face_role_sources else ['component-local recovery'],
            'slot_role_audit': slot_role_audit,
            'recovery_candidate_indices': sorted(set(recovery_candidate_indices)),
            'recovery_candidate_materials': list(dict.fromkeys(recovery_candidate_materials)),
            'recovery_candidate_audit': recovery_candidate_audit,
            'face_component_recovery': bool(recovery_candidate_indices),
            'use_direct_backface_hull': True,
            'face_support': True,
            'uma_reference_outline': bool((geometry_profile or {}).get('uma_reference_outline_architecture', False)),
        })
    return groups

def _aef11_is_helper_object(obj):
    if not obj:
        return True
    if _aef1164_is_mmd_physics_helper(obj):
        return True
    name = str(getattr(obj, 'name', ''))
    return name.startswith((
        'AEF_V10_7A_Shell__', 'AEF V9', 'AEF_V11_', 'AEF V10.',
        'AEF_V10_7B_', 'AEF_V10_7C_', 'AEF_V10_9',
    ))


def _aef11_collection_meshes(collection):
    out, seen = [], set()
    def walk(col):
        if not col or col.as_pointer() in seen:
            return
        seen.add(col.as_pointer())
        for obj in col.objects:
            if obj.type == 'MESH' and obj not in out and not _aef11_is_helper_object(obj):
                out.append(obj)
        for child in col.children:
            walk(child)
    walk(collection)
    return out


def _aef111_parent_chain(obj):
    chain, seen = [], set()
    cur = obj
    while cur and cur.as_pointer() not in seen:
        seen.add(cur.as_pointer())
        chain.append(cur)
        cur = getattr(cur, 'parent', None)
    return chain


def _aef111_root_parent(obj):
    chain = _aef111_parent_chain(obj)
    return chain[-1] if chain else obj


def _aef111_armature_for_object(obj):
    if not obj:
        return None
    if obj.type == 'ARMATURE':
        return obj
    for cur in _aef111_parent_chain(obj):
        if cur.type == 'ARMATURE':
            return cur
    for mod in getattr(obj, 'modifiers', []):
        if getattr(mod, 'type', '') == 'ARMATURE':
            arm = getattr(mod, 'object', None)
            if arm and arm.type == 'ARMATURE':
                return arm
    return None


def _aef11_bound_to_armature(obj, arm):
    if not obj or not arm:
        return False
    if _aef111_armature_for_object(obj) == arm:
        return True
    for mod in getattr(obj, 'modifiers', []):
        if getattr(mod, 'type', '') == 'ARMATURE' and getattr(mod, 'object', None) == arm:
            return True
    return False


def _aef111_meshes_bound_to_armature(scene, arm):
    if not scene or not arm:
        return []
    return [
        o for o in scene.objects
        if o.type == 'MESH' and not _aef11_is_helper_object(o) and _aef11_bound_to_armature(o, arm)
    ]


def _aef111_descendant_meshes(root):
    if not root:
        return []
    out, stack, seen = [], [root], set()
    while stack:
        obj = stack.pop()
        if not obj or obj.as_pointer() in seen:
            continue
        seen.add(obj.as_pointer())
        if obj.type == 'MESH' and not _aef11_is_helper_object(obj):
            out.append(obj)
        stack.extend(list(getattr(obj, 'children', [])))
    return out


def _aef111_world_bounds(obj):
    try:
        pts = [obj.matrix_world @ Vector(corner) for corner in obj.bound_box]
        if not pts:
            raise ValueError('empty bound box')
        lo = Vector((min(p.x for p in pts), min(p.y for p in pts), min(p.z for p in pts)))
        hi = Vector((max(p.x for p in pts), max(p.y for p in pts), max(p.z for p in pts)))
        center = (lo + hi) * 0.5
        diag = max((hi - lo).length, 1e-6)
        return center, diag
    except Exception:
        try:
            return obj.matrix_world.translation.copy(), max(float(obj.dimensions.length), 1e-6)
        except Exception:
            return Vector((0.0, 0.0, 0.0)), 1.0


def _aef111_scene_armature_guess(context):
    """Return (armature, confidence, note) without guessing through collections."""
    scene = context.scene
    active = context.view_layer.objects.active if context and context.view_layer else None
    # Active object ownership has the highest priority.
    arm = _aef111_armature_for_object(active)
    if arm:
        return arm, 'HIGH', f'active object belongs to armature {arm.name}'

    selected = list(context.selected_objects) if context else []
    selected_arms = [o for o in selected if o.type == 'ARMATURE']
    if len(selected_arms) == 1:
        return selected_arms[0], 'HIGH', f'selected armature {selected_arms[0].name}'

    owned = [_aef111_armature_for_object(o) for o in selected if o.type == 'MESH']
    owned = [a for a in owned if a]
    unique = {a.as_pointer(): a for a in owned}
    if len(unique) == 1:
        arm = next(iter(unique.values()))
        return arm, 'HIGH', f'selected meshes share armature {arm.name}'

    # If the scene has a single rig that actually owns meshes, it is a safe
    # collection-free fallback. Multiple rigs are ranked by owned mesh count,
    # but accepted only when one clearly dominates the others.
    ranked = []
    for candidate in [o for o in scene.objects if o.type == 'ARMATURE']:
        meshes = _aef111_meshes_bound_to_armature(scene, candidate)
        if meshes:
            ranked.append((len(meshes), candidate))
    ranked.sort(key=lambda x: x[0], reverse=True)
    if len(ranked) == 1:
        return ranked[0][1], 'MEDIUM', f'only rig owning meshes in scene ({ranked[0][0]} meshes)'
    if len(ranked) >= 2 and ranked[0][0] >= max(3, ranked[1][0] * 2):
        return ranked[0][1], 'MEDIUM', f'dominant rig by mesh ownership ({ranked[0][0]} vs {ranked[1][0]})'
    return None, 'LOW', 'no unique armature owner could be inferred'



# ---------------------------------------------------------------------
# V11.2.1 — MMD MULTI-MESH CHARACTER CLUSTER DETECTION
# ---------------------------------------------------------------------

_AEF121_STAGE_TOKENS = (
    'stage', 'floor', 'ground', 'wall', 'background', 'backdrop', 'sky',
    'room', 'terrain', 'building', 'scenery', 'environment', 'env',
)
_AEF121_GENERIC_NAME_TOKENS = {
    'arm', 'armature', 'rig', 'root', 'model', 'mdl', 'mesh', 'obj',
    'body', 'bdy', 'base', 'main', 'character', 'char', 'mmd', 'pmx', 'fbx',
}


def _aef121_is_stage_like(obj):
    name = _aef11_key(getattr(obj, 'name', ''))
    return any(token in name for token in _AEF121_STAGE_TOKENS)


def _aef121_significant_name_tokens(name):
    # Do NOT use _aef11_key here: it intentionally removes separators, while
    # legacy tokenization supported generic imported rig/object names; V11.8 runtime no longer uses name affinity for cluster expansion.
    raw = str(name or '').lower()
    raw = re.sub(r'\.\d{3}$', '', raw)
    tokens = [t for t in re.findall(r'[a-z0-9]+', raw) if len(t) >= 3]
    out = []
    for token in tokens:
        if token in _AEF121_GENERIC_NAME_TOKENS or token.isdigit():
            continue
        if token not in out:
            out.append(token)
    return out[:6]


def _aef121_union_world_bounds(objects):
    points = []
    for obj in objects or []:
        try:
            points.extend([obj.matrix_world @ Vector(corner) for corner in obj.bound_box])
        except Exception:
            try:
                c = obj.matrix_world.translation.copy()
                d = Vector((max(float(obj.dimensions.x), 1e-5), max(float(obj.dimensions.y), 1e-5), max(float(obj.dimensions.z), 1e-5))) * 0.5
                points.extend([c - d, c + d])
            except Exception:
                pass
    if not points:
        return Vector((0.0, 0.0, 0.0)), 1.0
    lo = Vector((min(p.x for p in points), min(p.y for p in points), min(p.z for p in points)))
    hi = Vector((max(p.x for p in points), max(p.y for p in points), max(p.z for p in points)))
    return (lo + hi) * 0.5, max((hi - lo).length, 1e-6)


def _xdzr8_v11822_material_image_signatures(mat):
    signatures = set()
    for candidate in (_aef111_resolve_original_source_material(mat) or mat, mat):
        if not candidate:
            continue
        try:
            for img in (_aef11_existing_role_images(candidate) or {}).values():
                if img and getattr(img, 'filepath', ''):
                    signatures.add(Path(bpy.path.abspath(img.filepath)).name.lower())
                elif img and getattr(img, 'name', ''):
                    signatures.add(Path(img.name).name.lower())
        except Exception:
            pass
        try:
            if getattr(candidate, 'use_nodes', False) and getattr(candidate, 'node_tree', None):
                for node in candidate.node_tree.nodes:
                    if node.bl_idname == 'ShaderNodeTexImage' and getattr(node, 'image', None):
                        img = node.image
                        if getattr(img, 'filepath', ''):
                            signatures.add(Path(bpy.path.abspath(img.filepath)).name.lower())
                        elif getattr(img, 'name', ''):
                            signatures.add(Path(img.name).name.lower())
        except Exception:
            pass
    return {s for s in signatures if s}


def _xdzr8_v11822_object_material_affinity_signatures(obj):
    mats = []
    signatures = set()
    source_names = set()
    if not obj or getattr(obj, 'type', '') != 'MESH':
        return {'materials': mats, 'images': signatures, 'sources': source_names}
    for slot in getattr(obj, 'material_slots', []):
        mat = getattr(slot, 'material', None)
        if not mat:
            continue
        mats.append(mat)
        try:
            source_names.add(_xdzr8_v11232_source_name(mat).lower())
        except Exception:
            pass
        signatures.update(_xdzr8_v11822_material_image_signatures(mat))
    return {'materials': mats, 'images': signatures, 'sources': {s for s in source_names if s}}


def _xdzr8_v11822_safe_spatial_affinity(obj, direct, selected=None, root=None):
    """Conservative structural sanity check for spatial-only cluster expansion.

    A nearby mesh may join the character only when it shows at least one non-
    spatial affinity signal: shared imported root/parent lineage, shared source
    material names, or shared bound texture basenames. This blocks scene helper
    props (for example debugging cubes) from being absorbed merely because they
    sit near the body, while still allowing fragmented unbound character parts.
    """
    if not obj or getattr(obj, 'type', '') != 'MESH':
        return False, 'not a mesh'
    if _aef11_is_helper_object(obj) or _aef121_is_stage_like(obj):
        return False, 'helper/stage mesh'

    direct = list(direct or [])
    selected = list(selected or [])
    reference = direct or selected
    if not reference:
        return False, 'no reference character meshes'

    obj_root = _aef111_root_parent(obj)
    ref_roots = {_aef111_root_parent(o).as_pointer(): _aef111_root_parent(o) for o in reference if o}
    if root and obj_root and obj_root == root:
        return True, f'shared model root {root.name}'
    if obj_root and obj_root.as_pointer() in ref_roots:
        return True, f'shared imported root {obj_root.name}'

    obj_parent = getattr(obj, 'parent', None)
    ref_parents = {getattr(o, 'parent', None).as_pointer(): getattr(o, 'parent', None) for o in reference if getattr(o, 'parent', None)}
    if obj_parent and obj_parent.as_pointer() in ref_parents:
        return True, f'shared parent {obj_parent.name}'

    obj_sig = _xdzr8_v11822_object_material_affinity_signatures(obj)
    ref_sources, ref_images = set(), set()
    for ref in reference:
        sig = _xdzr8_v11822_object_material_affinity_signatures(ref)
        ref_sources.update(sig['sources'])
        ref_images.update(sig['images'])

    shared_sources = sorted(obj_sig['sources'] & ref_sources)
    if shared_sources:
        return True, 'shared source material ' + ', '.join(shared_sources[:3])

    shared_images = sorted(obj_sig['images'] & ref_images)
    if shared_images:
        return True, 'shared texture basename ' + ', '.join(shared_images[:3])

    return False, 'no safe ownership/material affinity beyond proximity'


def _xdzr8_v11822_is_source_helper_material(mat):
    """Detect authored source outline/helper materials conservatively.

    The goal is not to recognize every stylized shader, only to quarantine
    obvious non-anatomical authored helper/outline materials so they do not get
    classified as face/hair/eyes. Detection relies primarily on source-graph
    behavior (Backfacing + Mix + Transparent/flat-color helpers) and only
    secondarily on naming tokens.
    """
    source_ref = _aef111_resolve_original_source_material(mat) or mat
    names = []
    for candidate in (mat, source_ref):
        if not candidate:
            continue
        try:
            names.append(str(candidate.get('AEF_V11_SourceMaterial', candidate.name) or candidate.name))
        except Exception:
            try:
                names.append(str(candidate.name))
            except Exception:
                pass
    name_text = ' '.join(n.lower() for n in names if n)
    name_tokens = ('outline', 'edge', 'backface', 'line', 'empty shader')

    has_backfacing = False
    has_transparent = False
    has_mix_shader = False
    has_emission = False
    has_principled = False
    image_count = 0
    opaque_alpha = 1.0
    simple_bsdf_count = 0
    try:
        principled = _aef11_principled(source_ref)
        if principled:
            has_principled = True
            try:
                opaque_alpha = min(opaque_alpha, float(_aef11_socket_default(principled, 'Alpha', 1.0)))
            except Exception:
                pass
    except Exception:
        pass
    try:
        if source_ref and getattr(source_ref, 'use_nodes', False) and getattr(source_ref, 'node_tree', None):
            for node in source_ref.node_tree.nodes:
                blid = getattr(node, 'bl_idname', '')
                if blid == 'ShaderNodeNewGeometry':
                    has_backfacing = True
                elif blid == 'ShaderNodeBsdfTransparent':
                    has_transparent = True
                    simple_bsdf_count += 1
                elif blid == 'ShaderNodeMixShader':
                    has_mix_shader = True
                elif blid == 'ShaderNodeEmission':
                    has_emission = True
                    simple_bsdf_count += 1
                elif blid == 'ShaderNodeTexImage' and getattr(node, 'image', None):
                    image_count += 1
                elif blid == 'ShaderNodeBsdfDiffuse':
                    simple_bsdf_count += 1
    except Exception:
        pass

    # Strong graph evidence: classic authored outline/helper setup.
    if has_backfacing and has_mix_shader and has_transparent and image_count <= 1:
        return True, 'backfacing + mix shader + transparent helper graph'
    # Flat helper shaders often contain almost no texture signal and no real PBR.
    if has_backfacing and has_mix_shader and not has_principled and image_count == 0 and (has_emission or simple_bsdf_count >= 2):
        return True, 'backfacing helper graph without anatomical texture inputs'
    # Naming alone is only accepted when the shader graph also looks helper-like.
    if any(tok in name_text for tok in name_tokens) and ((has_backfacing and has_mix_shader) or has_transparent or opaque_alpha < 0.05 or image_count == 0):
        return True, 'outline/helper naming corroborated by shader behavior'
    # Pure empty/transparent placeholders are not semantic anatomy materials.
    if opaque_alpha < 0.05 and image_count == 0 and not has_principled:
        return True, 'effectively invisible placeholder/helper material'
    return False, 'no authored helper/outline evidence'


def _xdzr8_v11822_sanitize_source_materials(materials):
    processable = []
    quarantined = []
    seen_sources = set()
    for mat in (materials or []):
        source_name = _xdzr8_v11232_source_name(mat) or _aef111_safe_material_name(mat, 'Material')
        # Evaluate one representative per source group.
        key = source_name.lower()
        if key in seen_sources:
            processable.append(mat)
            continue
        seen_sources.add(key)
        is_helper, reason = _xdzr8_v11822_is_source_helper_material(mat)
        if is_helper:
            quarantined.append((mat, source_name, reason))
        else:
            processable.append(mat)
    quarantined_sources = {name.lower() for _mat, name, _reason in quarantined}
    processable = [m for m in (materials or []) if (_xdzr8_v11232_source_name(m) or _aef111_safe_material_name(m, 'Material')).lower() not in quarantined_sources]
    return processable, quarantined


def _aef121_descendant_armatures(root):
    if not root:
        return []
    out, stack, seen = [], [root], set()
    while stack:
        obj = stack.pop()
        if not obj or obj.as_pointer() in seen:
            continue
        seen.add(obj.as_pointer())
        if obj.type == 'ARMATURE':
            out.append(obj)
        stack.extend(list(getattr(obj, 'children', [])))
    return out


def _aef121_safe_model_root(arm, direct_count):
    """Find the highest plausible object-root around an MMD/FBX rig.

    MMD exports often parent dozens of sibling meshes and several helper rigs to
    one Empty while only the body mesh carries the main Armature modifier. We
    accept such a hierarchy only while its mesh count stays character-sized.
    """
    if not arm:
        return None, []
    candidates = [arm]
    candidates.extend(_aef111_parent_chain(arm)[1:])
    best_root, best_meshes = None, []
    for root in candidates:
        if not root or _aef121_is_stage_like(root):
            continue
        meshes = [m for m in _aef111_descendant_meshes(root) if not _aef121_is_stage_like(m)]
        count = len(meshes)
        if count <= max(1, direct_count) or count > 160:
            continue
        arms = _aef121_descendant_armatures(root)
        # More than a handful of rigs usually means this root is a whole scene,
        # not one imported character. MMD models may legitimately have several.
        if len(arms) > 12:
            continue
        best_root, best_meshes = root, meshes
    return best_root, best_meshes


def _aef121_expand_armature_cluster(scene, arm):
    """Expand one rig-owned mesh set into a conservative character cluster.

    Signals are additive rather than exclusive: direct rig ownership, a safe
    shared root/Empty, auxiliary rigs under that root, model-name affinity and
    spatial containment around the directly rigged body. This specifically
    fixes common MMD/FBX layouts where only one body mesh owns the primary rig.
    """
    if not scene or not arm:
        return [], 'LOW', 'no armature available for cluster expansion'

    direct = _aef111_meshes_bound_to_armature(scene, arm)
    selected = {o.as_pointer(): o for o in direct}
    reasons = {o.as_pointer(): 'direct rig ownership' for o in direct}

    root, root_meshes = _aef121_safe_model_root(arm, len(direct))
    if root and root_meshes:
        for obj in root_meshes:
            selected[obj.as_pointer()] = obj
            reasons.setdefault(obj.as_pointer(), f'shared model root {root.name}')

        # Auxiliary armatures inside the same imported root are common for
        # accessories, hair physics and MMD helper systems.
        for aux in _aef121_descendant_armatures(root):
            for obj in _aef111_meshes_bound_to_armature(scene, aux):
                if not _aef121_is_stage_like(obj):
                    selected[obj.as_pointer()] = obj
                    reasons.setdefault(obj.as_pointer(), f'auxiliary rig {aux.name}')

    # V11.8.1: clustering is identity-agnostic. Shared hierarchy/rig ownership
    # and spatial containment are allowed; armature/mesh name affinity is not.
    base_center, base_diag = _aef121_union_world_bounds(direct or list(selected.values()))
    name_added = 0
    spatial_added = 0

    for obj in scene.objects:
        if obj.type != 'MESH' or _aef11_is_helper_object(obj) or _aef121_is_stage_like(obj):
            continue
        ptr = obj.as_pointer()
        if ptr in selected:
            continue

        center, diag = _aef111_world_bounds(obj)
        distance = (center - base_center).length
        spatially_close = (
            bool(direct)
            and distance <= max(base_diag * 0.95, 0.25)
            and diag <= max(base_diag * 1.60, 0.35)
        )

        # No model-name affinity path in V11.8.1. Spatial fallback is
        # intentionally enabled mainly for fragmented imports where the primary
        # rig owns very few meshes.

        # Spatial fallback is intentionally enabled mainly for the pathological
        # MMD case where the detected rig owns very few meshes.
        if len(direct) <= 3 and spatially_close:
            safe_affinity, safe_reason = _xdzr8_v11822_safe_spatial_affinity(obj, direct, list(selected.values()), root=root)
            if safe_affinity:
                selected[ptr] = obj
                reasons[ptr] = f'spatial character envelope + {safe_reason}'
                spatial_added += 1

    result = list(selected.values())
    # Hard safety cap. Refuse a scene-sized accidental expansion rather than
    # silently shading an environment.
    if len(result) > 160:
        result = direct
        root = None
        name_added = spatial_added = 0

    expanded = max(0, len(result) - len(direct))
    if expanded:
        confidence = 'HIGH' if root and len(result) <= 120 else 'MEDIUM'
        method_bits = [f'direct={len(direct)}', f'expanded={expanded}', f'total={len(result)}']
        if root:
            method_bits.append(f'root={root.name}')
        if name_added:
            method_bits.append(f'name={name_added}')
        if spatial_added:
            method_bits.append(f'spatial={spatial_added}')
        return result, confidence, 'MMD/FBX character cluster (' + ', '.join(method_bits) + ')'

    return result, ('HIGH' if len(direct) > 1 else 'MEDIUM'), f'direct rig cluster only ({len(direct)} meshes)'

def _aef111_selected_mesh_cluster(context):
    selected_meshes = [o for o in context.selected_objects if o.type == 'MESH' and not _aef11_is_helper_object(o)] if context else []
    if not selected_meshes:
        return [], 'LOW', 'no selected meshes'
    arms = {_aef111_armature_for_object(o).as_pointer(): _aef111_armature_for_object(o)
            for o in selected_meshes if _aef111_armature_for_object(o)}
    if len(arms) == 1:
        arm = next(iter(arms.values()))
        full, cluster_conf, cluster_note = _aef121_expand_armature_cluster(context.scene, arm)
        if full:
            return full, cluster_conf, f'selection expanded through shared armature {arm.name}; {cluster_note}'
    # Explicit selection is trusted. This is the manual escape hatch for
    # unrigged FBX/OBJ characters with no collection.
    return selected_meshes, 'HIGH', 'explicit selected mesh set'


def _sabershader_v101_fgo_scene_signature(context=None):
    """Detect the FGO Arcade/Noesis-style scene structure before target isolation.

    This is intentionally character-agnostic. It looks for the recurring MODEL| mesh
    blocks, mt_* material families, facial base morph objects and loaded SVT/ramp
    images. The purpose is target recovery, not shading classification.
    """
    scene = getattr(context, 'scene', None) if context else None
    objects = list(getattr(scene, 'objects', []) or []) if scene is not None else []
    mats = list(getattr(bpy.data, 'materials', []) or [])
    imgs = list(getattr(bpy.data, 'images', []) or [])
    score = 0.0
    evidence = []

    model_meshes = [o for o in objects if getattr(o, 'type', '') == 'MESH' and str(getattr(o, 'name', '')).startswith('MODEL|-')]
    if len(model_meshes) >= 4:
        score += 4.0
        evidence.append(f'MODEL| mesh blocks={len(model_meshes)}')

    fgo_mats = []
    for mat in mats:
        name = str(getattr(mat, 'name', '') or '').casefold()
        if name.startswith('mt_') and any(tok in name for tok in ('face', 'hair', 'skin', 'cloth', 'armor', 'chestarm', 'eye', 'oral', 'cheek', 'gold')):
            fgo_mats.append(mat)
    if len(fgo_mats) >= 4:
        score += 4.0
        evidence.append(f'mt_* semantic material family={len(fgo_mats)}')

    base_expr = []
    base_pat = re.compile(r'^(?:face|cheek|eyebrow|eyehole|eyelashes|eyelid|oral|tooth)_base(?:_0)?$', re.I)
    for obj in objects:
        if getattr(obj, 'type', '') == 'MESH' and base_pat.match(str(getattr(obj, 'name', '') or '')):
            base_expr.append(obj)
    if len(base_expr) >= 3:
        score += 2.0
        evidence.append(f'facial base meshes={len(base_expr)}')

    image_names = []
    for img in imgs:
        try:
            image_names.append(Path(str(getattr(img, 'name', '') or '')).name.casefold())
            fp = str(getattr(img, 'filepath', '') or '')
            if fp:
                image_names.append(Path(fp.replace('\\', '/')).name.casefold())
        except Exception:
            pass
    svt = sum(1 for n in image_names if n.startswith('svt_'))
    ramps = sum(1 for n in image_names if n.startswith('_ramp01'))
    if svt >= 3:
        score += 3.0
        evidence.append(f'loaded SVT images={svt}')
    if ramps >= 3:
        score += 3.0
        evidence.append(f'loaded ramp LUTs={ramps}')

    return {
        'enabled': bool(score >= 7.0),
        'score': float(score),
        'evidence': evidence,
        'model_meshes': model_meshes,
        'base_expression_meshes': base_expr,
        'fgo_materials': fgo_mats,
    }



def _sabershader_v1036_fgo_facial_layers(context=None):
    """Non-destructively isolate source-authored base facial layers for FGO Arcade.

    The reviewed FGO Arcade export keeps facial expressions as independent meshes
    stacked in nearly the same space. During shader reconstruction these stacks
    can visually combine many face/cheek/oral/tooth/brow/eyehole/eyelash/eyelid states at once. V1.0.3.6
    therefore keeps only each family's explicit *_base / *_base_0 mesh visible and
    hides expression variants without deleting, merging or editing their geometry.

    The source objects and their original visibility state are retained in custom
    properties so a later expression/driver/shape-key layer can restore or control
    them deliberately.
    """
    scene = getattr(context or bpy.context, 'scene', None)
    settings = getattr(scene, 'xdzr8_settings', None) if scene is not None else None
    isolation_enabled = bool(getattr(settings, 'fgo_isolate_base_facial_layers', True))
    families = ('face', 'cheek', 'oral', 'tooth', 'eyebrow', 'eyehole', 'eyelashes', 'eyelid')

    def _blank_family(name):
        return {
            'family': name,
            'count': 0,
            'base_count': 0,
            'expression_count': 0,
            'visible_before_count': 0,
            'visible_count': 0,
            'base_visible_count': 0,
            'expression_visible_count': 0,
            'expression_hidden_count': 0,
            'has_base': False,
            'names': [],
            'base_names': [],
            'expression_names': [],
            'hidden_expression_names': [],
            'rows': [],
        }

    result = {
        'isolation_enabled': bool(isolation_enabled),
        'families': {name: _blank_family(name) for name in families},
        'count': 0,
        'base_count': 0,
        'expression_count': 0,
        'visible_before_count': 0,
        'visible_count': 0,
        'base_visible_count': 0,
        'expression_visible_count': 0,
        'expression_hidden_count': 0,
        'families_with_base': 0,
        'rows': [],
    }
    if scene is None:
        return result

    family_re = re.compile(r'^(face|cheek|oral|tooth|eyebrow|eyehole|eyelashes|eyelid)_(.+)$', re.I)

    def _is_base_name(name, family):
        return bool(re.match(rf'^{re.escape(family)}_base(?:_0)?$', name, re.I))

    def _hide_get(_obj):
        try:
            return bool(_obj.hide_get())
        except Exception:
            return False

    def _visible(_obj):
        try:
            return not bool(_hide_get(_obj) or getattr(_obj, 'hide_viewport', False))
        except Exception:
            return not bool(getattr(_obj, 'hide_viewport', False))

    def _remember_original_state(_obj):
        try:
            if 'SaberShader_V1035_FGOOriginalHideGet' not in _obj:
                _obj['SaberShader_V1035_FGOOriginalHideGet'] = bool(_hide_get(_obj))
            if 'SaberShader_V1035_FGOOriginalHideViewport' not in _obj:
                _obj['SaberShader_V1035_FGOOriginalHideViewport'] = bool(getattr(_obj, 'hide_viewport', False))
            if 'SaberShader_V1035_FGOOriginalHideRender' not in _obj:
                _obj['SaberShader_V1035_FGOOriginalHideRender'] = bool(getattr(_obj, 'hide_render', False))
        except Exception:
            pass

    def _apply_visibility(_obj, visible):
        hidden = not bool(visible)
        try:
            _obj.hide_set(hidden)
        except Exception:
            pass
        try:
            _obj.hide_viewport = hidden
        except Exception:
            pass
        try:
            _obj.hide_render = hidden
        except Exception:
            pass

    # Two-pass design: a family is modified only if an explicit source base layer
    # exists. This prevents similarly named helper meshes from being hidden by a
    # naming guess when the expected *_base(_0) source structure is absent.
    candidates = {name: [] for name in families}
    for obj in getattr(scene, 'objects', []) or []:
        if getattr(obj, 'type', '') != 'MESH':
            continue
        name = str(getattr(obj, 'name', '') or '')
        match = family_re.match(name)
        if not match:
            continue
        family = str(match.group(1)).casefold()
        if family not in candidates:
            continue
        candidates[family].append(obj)

    for family in families:
        family_result = result['families'][family]
        family_objects = candidates.get(family, [])
        base_objects = [obj for obj in family_objects if _is_base_name(str(getattr(obj, 'name', '') or ''), family)]
        family_result['has_base'] = bool(base_objects)
        result['families_with_base'] += int(bool(base_objects))

        for obj in family_objects:
            name = str(getattr(obj, 'name', '') or '')
            is_base = _is_base_name(name, family)
            visible_before = _visible(obj)
            _remember_original_state(obj)

            # Fail conservative: only enforce visibility when this family has a
            # recognized authored base layer. Otherwise preserve source state.
            if isolation_enabled and base_objects:
                _apply_visibility(obj, bool(is_base))
            visible_after = _visible(obj)

            family_result['count'] += 1
            family_result['visible_before_count'] += int(visible_before)
            family_result['visible_count'] += int(visible_after)
            family_result['names'].append(name)
            if is_base:
                family_result['base_count'] += 1
                family_result['base_names'].append(name)
                family_result['base_visible_count'] += int(visible_after)
            else:
                family_result['expression_count'] += 1
                family_result['expression_names'].append(name)
                family_result['expression_visible_count'] += int(visible_after)
                if isolation_enabled and base_objects and not visible_after:
                    family_result['expression_hidden_count'] += 1
                    family_result['hidden_expression_names'].append(name)

            if isolation_enabled and base_objects:
                policy = 'BASE_VISIBLE' if is_base else ('EXPRESSION_HIDDEN' if not visible_after else 'EXPRESSION_VISIBLE_UNEXPECTED')
            else:
                policy = 'PRESERVE_SOURCE_VISIBILITY'

            row = {
                'family': family,
                'name': name,
                'base': bool(is_base),
                'has_base': bool(base_objects),
                'visible_before': bool(visible_before),
                'visible_after': bool(visible_after),
                'policy': policy,
            }
            family_result['rows'].append(row)
            result['rows'].append(row)

            try:
                obj['SaberShader_V1035_FGOFacialLayer'] = True
                obj['SaberShader_V1035_FGOFacialFamily'] = family
                obj['SaberShader_V1035_FGOFacialBaseLayer'] = bool(is_base)
                obj['SaberShader_V1035_FGOFacialLayerPreserve'] = True
                obj['SaberShader_V1035_FGOFacialVisible'] = bool(visible_after)
                obj['SaberShader_V1035_FGOExpressionHidden'] = bool((not is_base) and isolation_enabled and bool(base_objects) and (not visible_after))
                # Preserve legacy cheek metadata used by earlier project builds.
                if family == 'cheek':
                    obj['SaberShader_V1024_FGO_CheekLayer'] = True
                    obj['SaberShader_V1024_FGO_CheekBaseLayer'] = bool(is_base)
                    obj['SaberShader_V1024_FGO_CheekLayerPreserve'] = True
                    if 'SaberShader_V1032_FGO_CheekOriginalVisible' not in obj:
                        obj['SaberShader_V1032_FGO_CheekOriginalVisible'] = bool(visible_before)
                    obj['SaberShader_V1032_FGO_CheekVisible'] = bool(visible_after)
                    obj['SaberShader_V1032_FGO_CheekExpressionHidden'] = bool((not is_base) and isolation_enabled and bool(base_objects) and (not visible_after))
            except Exception:
                pass

        for key in ('count', 'base_count', 'expression_count', 'visible_before_count', 'visible_count', 'base_visible_count', 'expression_visible_count', 'expression_hidden_count'):
            result[key] += int(family_result.get(key, 0))

    try:
        scene['SaberShader_V1035_FGOBaseFacialLayersOnly'] = bool(isolation_enabled)
        scene['SaberShader_V1035_FGOFacialLayers'] = int(result.get('count', 0))
        scene['SaberShader_V1035_FGOFacialBaseLayers'] = int(result.get('base_count', 0))
        scene['SaberShader_V1035_FGOFacialExpressionLayers'] = int(result.get('expression_count', 0))
        scene['SaberShader_V1035_FGOFacialExpressionsHidden'] = int(result.get('expression_hidden_count', 0))
        scene['SaberShader_V1035_FGOFacialFamiliesWithBase'] = int(result.get('families_with_base', 0))
        for family, family_result in result['families'].items():
            token = family.capitalize()
            scene[f'SaberShader_V1035_FGO{token}Layers'] = int(family_result.get('count', 0))
            scene[f'SaberShader_V1035_FGO{token}Base'] = int(family_result.get('base_count', 0))
            scene[f'SaberShader_V1035_FGO{token}Expressions'] = int(family_result.get('expression_count', 0))
            scene[f'SaberShader_V1035_FGO{token}ExpressionsHidden'] = int(family_result.get('expression_hidden_count', 0))

        cheek = result['families'].get('cheek', {})
        scene['SaberShader_V1032_FGOBaseCheekOnly'] = bool(isolation_enabled and cheek.get('has_base', False))
        scene['SaberShader_V1032_FGOBaseCheekVisible'] = int(cheek.get('base_visible_count', 0))
        scene['SaberShader_V1032_FGOExpressionCheeksHidden'] = int(cheek.get('expression_hidden_count', 0))
    except Exception:
        pass
    return result


def _sabershader_v1024_fgo_cheek_layers(context=None):
    """Compatibility wrapper returning the cheek-family audit from V1.0.3.6."""
    audit = _sabershader_v1036_fgo_facial_layers(context)
    cheek = dict((audit.get('families') or {}).get('cheek', {}) or {})
    cheek['isolation_enabled'] = bool(audit.get('isolation_enabled', False))
    cheek.setdefault('isolated_base_visible', int(cheek.get('base_visible_count', 0)))
    cheek.setdefault('isolated_expression_hidden', int(cheek.get('expression_hidden_count', 0)))
    return cheek

