XDZR8_V112_ROLE_ORDER = ('eyes5','eyes','mouth','hair','face','mask','stockings','glove','boots','transparent_cloth','cloth','body','accessory')
XDZR8_V112_VALID_ROLES = set(XDZR8_V112_ROLE_ORDER)


def _xdzr8_v112_text_has_token(text, token):
    raw = str(text or '').lower()
    tok = str(token or '').lower()
    if not raw or not tok:
        return False
    # CJK/Japanese tokens are safest as direct substrings.
    if any(ord(c) > 127 for c in tok):
        return tok in raw
    # Short ASCII hints (eye, arm, etc.) must be complete words to avoid
    # accidental hits such as "arm" inside "armature" or "eye" in "eyelash".
    if len(tok) <= 3:
        return re.search(r'(?<![a-z0-9])' + re.escape(tok) + r'(?![a-z0-9])', raw) is not None
    compact_raw = _aef11_key(raw)
    compact_tok = _aef11_key(tok)
    return bool(compact_tok and compact_tok in compact_raw)


def _xdzr8_v112_score_text(scores, evidence, text, weight, source_label):
    if not text:
        return
    for role, tokens in XDZR8_V112_ROLE_TOKENS.items():
        hits = [tok for tok in tokens if _xdzr8_v112_text_has_token(text, tok)]
        if not hits:
            continue
        # Cap repeated hints from one source so a filename like
        # hair_bangs_ponytail does not drown every other signal.
        bonus = min(0.8, max(0, len(hits) - 1) * 0.25)
        value = float(weight) + bonus
        scores[role] = scores.get(role, 0.0) + value
        evidence.setdefault(role, []).append(f'{source_label}:{"/".join(hits[:3])} +{value:.1f}')


def _xdzr8_v112_material_vertex_group_text(mat, objects, sample_limit=3200):
    """Return dominant vertex-group names used by polygons carrying mat.

    This is deliberately sampled and read-only. It gives useful anatomical
    hints on single-mesh MMD/FBX characters where object names are generic.
    """
    accum = {}
    for obj in (objects or []):
        if not obj or getattr(obj, 'type', '') != 'MESH' or not getattr(obj, 'data', None):
            continue
        slot_ids = {i for i, slot in enumerate(getattr(obj, 'material_slots', [])) if slot.material == mat}
        if not slot_ids:
            continue
        vertices = getattr(obj.data, 'vertices', None)
        polygons = getattr(obj.data, 'polygons', None)
        if not vertices or not polygons:
            continue
        vids = []
        seen = set()
        try:
            for poly in polygons:
                if poly.material_index not in slot_ids:
                    continue
                for vid in poly.vertices:
                    if vid not in seen:
                        seen.add(vid)
                        vids.append(vid)
                        if len(vids) >= sample_limit:
                            break
                if len(vids) >= sample_limit:
                    break
            for vid in vids:
                v = vertices[vid]
                for membership in v.groups:
                    try:
                        name = obj.vertex_groups[membership.group].name
                    except Exception:
                        continue
                    accum[name] = accum.get(name, 0.0) + float(getattr(membership, 'weight', 0.0))
        except Exception:
            continue
    if not accum:
        return ''
    ordered = sorted(accum.items(), key=lambda kv: kv[1], reverse=True)[:10]
    return ' '.join(name for name, _weight in ordered)



# ---------------------------------------------------------------------
# V11.7 — MATERIAL-LOCAL GEOMETRY INTELLIGENCE
# ---------------------------------------------------------------------

def _xdzr8_v117_same_source_material(slot_mat, mat, source_ref=None):
    """True when a material slot belongs to the same canonical V11 source.

    Repeat builds may leave generated AEF_V11_* materials in the slot while the
    classifier is reading the original source reference. Matching the canonical
    source name keeps the geometry audit idempotent without mutating the mesh.
    """
    if slot_mat is None:
        return False
    if slot_mat == mat or (source_ref is not None and slot_mat == source_ref):
        return True
    try:
        a = _xdzr8_v11232_source_name(slot_mat)
        b = _xdzr8_v11232_source_name(mat)
        c = _xdzr8_v11232_source_name(source_ref) if source_ref is not None else ''
        target = b or c
        return bool(a and target and a == target)
    except Exception:
        return False


def _xdzr8_v117_material_local_geometry(mat, objects=None, source_intelligence=None):
    """Measure only polygons that actually use *mat*.

    V11.6 head geometry operated at object level. That is correct for separated
    head/hair meshes, but on one-mesh MMD/game exports every material inherited
    the same full-character bounds. V11.7 collects the vertices referenced by
    this material's polygons, converts them to world space, then normalizes the
    local bounds against the already detected character bounds.
    """
    info = source_intelligence if isinstance(source_intelligence, dict) else {}
    source_ref = _aef111_resolve_original_source_material(mat) or mat
    try:
        source_name = _xdzr8_v11232_source_name(mat) or _xdzr8_v11232_source_name(source_ref) or source_ref.name
    except Exception:
        source_name = getattr(source_ref, 'name', 'Material')

    cache = info.setdefault('_v117_material_geometry_cache', {}) if isinstance(info, dict) else {}
    try:
        obj_sig = tuple(sorted(int(o.as_pointer()) for o in (objects or []) if o))
        cache_key = (str(source_name), obj_sig)
    except Exception:
        cache_key = (str(source_name), tuple(getattr(o, 'name', '') for o in (objects or []) if o))
    if cache_key in cache:
        return cache[cache_key]

    result = {
        'used': False, 'source_name': str(source_name), 'objects': 0,
        'polygons': 0, 'vertices': 0, 'slot_indices': [], 'duplicate_polygons_ignored': 0,
        'center_n': 0.0, 'min_n': 0.0, 'max_n': 0.0, 'span_n': 0.0,
        'width_offset_n': 0.0, 'width_span_n': 0.0, 'depth_span_n': 0.0,
        'polygon_fraction': 0.0, 'vertex_fraction': 0.0,
        'vertical_axis': -1, 'width_axis': -1, 'depth_axis': -1,
        'primary_mode': False, 'head_family': False, 'body_family': False,
        'mixed_roles': [], 'summary': 'no material-local geometry',
    }

    points = []
    point_keys = set()
    local_polys = 0
    duplicate_polys_ignored = 0
    total_polys = 0
    total_vertices = 0
    slot_indices = set()
    used_objects = set()

    for obj in (objects or []):
        if not obj or getattr(obj, 'type', '') != 'MESH' or not getattr(obj, 'data', None):
            continue
        data = obj.data
        polys = getattr(data, 'polygons', None)
        verts = getattr(data, 'vertices', None)
        if polys is None or verts is None:
            continue
        try:
            total_polys += len(polys)
            total_vertices += len(verts)
        except Exception:
            pass
        ids = set()
        for idx, slot in enumerate(getattr(obj, 'material_slots', [])):
            if _xdzr8_v117_same_source_material(getattr(slot, 'material', None), mat, source_ref):
                ids.add(int(idx)); slot_indices.add(int(idx))
        if not ids:
            continue
        used_objects.add(getattr(obj, 'name', 'Object'))
        try:
            mw = obj.matrix_world
            seen_poly_signatures = set()
            for poly in polys:
                if int(poly.material_index) not in ids:
                    continue
                signature = tuple(int(v) for v in poly.vertices)
                if signature in seen_poly_signatures:
                    duplicate_polys_ignored += 1
                    continue
                seen_poly_signatures.add(signature)
                local_polys += 1
                for vid in poly.vertices:
                    key = (int(obj.as_pointer()), int(vid))
                    if key in point_keys:
                        continue
                    point_keys.add(key)
                    try:
                        points.append(mw @ verts[int(vid)].co)
                    except Exception:
                        pass
        except Exception:
            continue

    result['objects'] = len(used_objects)
    result['polygons'] = int(local_polys)
    result['duplicate_polygons_ignored'] = int(duplicate_polys_ignored)
    result['vertices'] = len(points)
    result['slot_indices'] = sorted(slot_indices)
    result['polygon_fraction'] = float(local_polys) / max(float(total_polys), 1.0)
    result['vertex_fraction'] = float(len(points)) / max(float(total_vertices), 1.0)
    if not points:
        cache[cache_key] = result
        return result

    lo = Vector((min(p.x for p in points), min(p.y for p in points), min(p.z for p in points)))
    hi = Vector((max(p.x for p in points), max(p.y for p in points), max(p.z for p in points)))
    center = (lo + hi) * 0.5
    span = hi - lo
    result['world_min'] = lo
    result['world_max'] = hi
    result['world_center'] = center
    result['world_span'] = span

    character_context = info.get('character_geometry') if isinstance(info, dict) else None
    if not character_context:
        try:
            character_context = _xdzr8_v116_character_geometry(objects)
        except Exception:
            character_context = None
    if character_context:
        try:
            axis = int(character_context['axis'])
            char_lo = character_context['min']
            char_hi = character_context['max']
            char_center = character_context['center']
            height = max(float(character_context['height']), 1e-6)
            lateral_axes = [i for i in range(3) if i != axis]
            if len(lateral_axes) >= 2:
                char_ext = {i: max(float(char_hi[i] - char_lo[i]), 1e-6) for i in lateral_axes}
                width_axis = max(lateral_axes, key=lambda i: char_ext[i])
                depth_axis = min(lateral_axes, key=lambda i: char_ext[i])
            elif lateral_axes:
                width_axis = lateral_axes[0]; depth_axis = lateral_axes[0]
                char_ext = {width_axis: max(float(char_hi[width_axis] - char_lo[width_axis]), 1e-6)}
            else:
                width_axis = axis; depth_axis = axis; char_ext = {axis: height}

            min_n = (float(lo[axis]) - float(char_lo[axis])) / height
            max_n = (float(hi[axis]) - float(char_lo[axis])) / height
            center_n = (float(center[axis]) - float(char_lo[axis])) / height
            span_n = float(span[axis]) / height
            width_extent = max(float(char_hi[width_axis] - char_lo[width_axis]), 1e-6)
            depth_extent = max(float(char_hi[depth_axis] - char_lo[depth_axis]), 1e-6)
            width_offset_n = abs(float(center[width_axis]) - float(char_center[width_axis])) / max(width_extent * 0.5, 1e-6)
            width_span_n = abs(float(span[width_axis])) / width_extent
            depth_span_n = abs(float(span[depth_axis])) / depth_extent
            result.update({
                'center_n': max(-0.25, min(1.25, center_n)),
                'min_n': max(-0.25, min(1.25, min_n)),
                'max_n': max(-0.25, min(1.25, max_n)),
                'span_n': max(0.0, min(1.5, span_n)),
                'width_offset_n': max(0.0, min(2.5, width_offset_n)),
                'width_span_n': max(0.0, min(2.5, width_span_n)),
                'depth_span_n': max(0.0, min(2.5, depth_span_n)),
                'vertical_axis': axis, 'width_axis': width_axis, 'depth_axis': depth_axis,
            })
        except Exception:
            pass

    profile = info.get('geometry_profile') or {}
    try:
        primary_mode = (
            int(profile.get('real_meshes', 99)) <= 2
            and float(profile.get('dominant_ratio', 0.0)) >= 0.85
            and int(profile.get('materials', 0)) >= 4
        )
    except Exception:
        primary_mode = False
    result['primary_mode'] = bool(primary_mode)

    # PMX Body/Face memos are family context, not verdicts. They are useful here
    # only to decide which conservative spatial priors are relevant.
    try:
        records = _xdzr8_v1123_match_pmx_records(mat, source_ref, info)
    except Exception:
        records = []
    memos = ' '.join(str(r.get('memo', '')) for r in records).lower()
    result['head_family'] = 'face' in _aef11_key(memos)
    result['body_family'] = 'body' in _aef11_key(memos)
    result['used'] = True
    result['summary'] = (
        f"polys={result['polygons']} verts={result['vertices']} "
        f"z={result['center_n']:.2f} span={result['span_n']:.2f} "
        f"wOff={result['width_offset_n']:.2f} wSpan={result['width_span_n']:.2f} "
        f"polyFrac={result['polygon_fraction']:.2f} dupIgnored={result['duplicate_polygons_ignored']} primary={result['primary_mode']}"
    )
    cache[cache_key] = result
    return result


def _xdzr8_v117_apply_material_local_intelligence(scores, evidence, mat, objects=None, source_intelligence=None, geometry=None):
    """Add conservative role evidence from one material's own geometry."""
    info = source_intelligence if isinstance(source_intelligence, dict) else {}
    geo = geometry or _xdzr8_v117_material_local_geometry(mat, objects, info)
    if not geo.get('used', False):
        return geo

    scale = 1.0 if geo.get('primary_mode', False) else 0.55
    c = float(geo.get('center_n', 0.0)); mn = float(geo.get('min_n', 0.0)); mx = float(geo.get('max_n', 0.0))
    sp = float(geo.get('span_n', 0.0)); wo = float(geo.get('width_offset_n', 0.0)); ws = float(geo.get('width_span_n', 0.0))
    pf = float(geo.get('polygon_fraction', 0.0))
    head_family = bool(geo.get('head_family', False)); body_family = bool(geo.get('body_family', False))
    mixed = []

    def add(role, value, why):
        v = float(value) * scale
        if role in scores and v > 0.0:
            scores[role] += v
            evidence.setdefault(role, []).append(f'V11.7 material-local {why} +{v:.1f}')

    # Head-family long surfaces reaching the crown but extending far down the
    # body are normally hair/tails, not facial skin. This is deliberately a
    # prior, not a hard override, because atlases can genuinely mix face+hair.
    if mx >= 0.90 and sp >= 0.42 and ws >= 0.28:
        add('hair', 3.0 if head_family else 2.0, 'crown-reaching long surface')
        if head_family:
            add('face', 0.9, 'mixed head-atlas safety prior')
            mixed = ['hair', 'face']
    elif mx >= 0.86 and c >= 0.68 and sp <= 0.42:
        add('hair', 1.6 if head_family else 1.0, 'compact upper-head surface')

    # Central compact head surfaces are face candidates; very small eye-band
    # islands receive only modest eye evidence so exact names still dominate.
    if 0.62 <= c <= 0.92 and sp <= 0.34 and wo <= 0.38 and 0.10 <= ws <= 0.72:
        add('face', 2.0 if head_family else 1.15, 'central compact head surface')
    if 0.76 <= c <= 0.94 and sp <= 0.12 and wo <= 0.48 and ws <= 0.42 and pf <= 0.12:
        add('eyes', 1.25, 'small eye-band island')
        add('eyes5', 0.55, 'small eye-band detail')
    if 0.58 <= c <= 0.84 and sp <= 0.09 and wo <= 0.24 and ws <= 0.24 and pf <= 0.08:
        add('mouth', 1.1, 'small central lower-head detail')

    # Body-family materials occupying the middle/lower character are much more
    # likely clothing than anatomical skin unless semantic/name/color evidence
    # already says Skin/Body. The geometry bonus is intentionally modest.
    if body_family:
        if mx <= 0.88 and (sp >= 0.18 or 0.24 <= c <= 0.74):
            add('cloth', 2.6, 'body-family torso/lower coverage')
        if mn <= 0.18 and mx <= 0.42:
            add('boots', 1.3, 'low character coverage')
        if c <= 0.48 and sp >= 0.16:
            add('stockings', 0.65, 'lower-body elongated coverage')

    # Generic position-only fallback for packs without PMX family metadata.
    if not head_family and not body_family:
        if mx <= 0.23 and sp <= 0.28:
            add('boots', 1.6, 'very low compact geometry')
        elif 0.24 <= c <= 0.68 and sp >= 0.18 and ws >= 0.18:
            add('cloth', 1.25, 'mid-body coverage')

    geo['mixed_roles'] = mixed
    # Store a compact, serializable audit. Private cache fields are not written
    # into the Blender scene; the generated material/report receives the summary.
    try:
        audit = info.setdefault('_v117_material_local_audit', {})
        audit[str(geo.get('source_name', getattr(mat, 'name', 'Material')))] = {
            k: geo.get(k) for k in (
                'source_name','used','primary_mode','polygons','vertices','slot_indices',
                'center_n','min_n','max_n','span_n','width_offset_n','width_span_n','depth_span_n',
                'polygon_fraction','vertex_fraction','head_family','body_family','mixed_roles','summary'
            )
        }
    except Exception:
        pass
    return geo

def _xdzr8_v112_manual_override(mat, source_ref=None):
    for candidate in (mat, source_ref):
        if not candidate:
            continue
        try:
            role = str(getattr(candidate, 'xdzr8_role_override', 'AUTO') or 'AUTO')
        except (ReferenceError, AttributeError):
            role = 'AUTO'
        if role in XDZR8_V112_VALID_ROLES:
            return role
        try:
            role = str(candidate.get('XDZR8_RoleOverride', '') or '')
        except (ReferenceError, AttributeError):
            role = ''
        if role in XDZR8_V112_VALID_ROLES:
            return role
    return None


def _aef11_classify_material(mat, objects=None, source_intelligence=None):
    """V11.8.3 metadata + material-bound companion semantics classifier.

    Returns (role, reason, confidence, sorted_scores). No scene data is
    modified. A manual material override always wins.
    """
    source_ref = _aef111_resolve_original_source_material(mat) or mat
    override = _xdzr8_v112_manual_override(mat, source_ref)
    if override:
        return override, 'manual Active Material Role Override', 'HIGH', [(override, 99.0)]

    scores = {role: 0.0 for role in XDZR8_V112_ROLE_ORDER}
    evidence = {role: [] for role in XDZR8_V112_ROLE_ORDER}
    info = source_intelligence if isinstance(source_intelligence, dict) else {}

    # 1) Material names are the strongest portable semantic signal.
    names = []
    for candidate in (mat, source_ref):
        if not candidate:
            continue
        try:
            name = str(candidate.get('AEF_V11_SourceMaterial', candidate.name) or candidate.name)
        except Exception:
            try:
                name = str(candidate.name)
            except Exception:
                name = ''
        if name and name not in names:
            names.append(name)
    for name in names:
        _xdzr8_v112_score_text(scores, evidence, name, 7.0, 'material')

    # V11.9.3: recurring Uma source material dictionary. Numeric IDs identify
    # asset instances only; they never become character-specific rules. Blender
    # duplicate suffixes are removed before matching.
    uma_naming = info.get('uma_naming_profile') or {}
    if uma_naming.get('enabled', False):
        def uma_add(role, value, reason):
            if role in scores:
                _xdzr8_v1123_add_score(scores, evidence, role, value, reason)
        for raw_name in names:
            uname = _xdzr8_v1193_normalize_source_material_name(raw_name)
            m = re.match(r'^mtl_chr\d+_\d+_(face|hair|eye|mayu)$', uname)
            if m:
                token=m.group(1)
                if token == 'face': uma_add('face', 11.0, 'UMA source alias: chr/*/face')
                elif token == 'hair': uma_add('hair', 11.0, 'UMA source alias: chr/*/hair')
                elif token == 'eye': uma_add('eyes', 11.0, 'UMA source alias: chr/*/eye')
                elif token == 'mayu': uma_add('eyes5', 10.5, 'UMA source alias: mayu/eyebrow')
                continue
            if re.match(r'^mtl_bdy\d+_\d+$', uname):
                uma_add('cloth', 5.4, 'UMA source alias: bdy outfit/body family')
                uma_add('body', 5.0, 'UMA source alias: bdy outfit/body family')
                continue
            if re.match(r'^mtl_tail\d+_\d+(?:_\d+)?$', uname):
                uma_add('hair', 9.5, 'UMA source alias: tail hair-like appendage')

    # SaberShader V1.0.1: FGO Arcade materials have strong semantic mt_* names.
    # Use them only after the render profile has been independently detected.
    if bool((info.get('fgo_arcade_profile') or {}).get('enabled', False)):
        fgo_key = ' '.join(str(n).casefold() for n in names)
        def fgo_add(role, value, reason):
            if role in scores:
                _xdzr8_v1123_add_score(scores, evidence, role, value, reason)
        if any(t in fgo_key for t in ('mt_face_bs','mt_faceback','mt_faceparts','mt_cheek')):
            fgo_add('face', 10.0, 'FGO Arcade face material family')
        if 'mt_hair' in fgo_key:
            fgo_add('hair', 11.0, 'FGO Arcade hair material family')
        if re.search(r'(^|\W)mt_skin(?:\W|$)', fgo_key):
            fgo_add('body', 11.0, 'FGO Arcade skin material')
        if any(t in fgo_key for t in ('mt_eye_l','mt_eye_r','mt_eye_')) and 'eyehole' not in fgo_key:
            fgo_add('eyes', 11.0, 'FGO Arcade eye material')
        if any(t in fgo_key for t in ('mt_eyehole','mt_eyelash','mt_eyebrow','mt_eyelid')):
            fgo_add('eyes5', 10.0, 'FGO Arcade eye-line material')
        if any(t in fgo_key for t in ('mt_oral','mt_tooth')):
            fgo_add('mouth', 10.5, 'FGO Arcade oral material')
        if 'mt_cloth' in fgo_key:
            fgo_add('cloth', 10.0, 'FGO Arcade cloth material family')
        if any(t in fgo_key for t in ('mt_armora','mt_chestarm','mt_guntlet','mt_gauntlet','mt_moon_gold','mt_alfa_gold')):
            fgo_add('accessory', 10.0, 'FGO Arcade armor/metal material family')

    # 2) Contextual bound images are strong semantic evidence. V11.8.3 also
    # derives an authored companion-family context tied to THIS material.
    images = _aef11_existing_role_images(source_ref) if source_ref else {}
    images = _xdzr8_v1122_contextual_existing_images(source_ref, images, info)
    image_seen = set()
    if source_ref and getattr(source_ref, 'use_nodes', False) and getattr(source_ref, 'node_tree', None):
        try:
            for node in source_ref.node_tree.nodes:
                if node.bl_idname == 'ShaderNodeTexImage' and getattr(node, 'image', None):
                    image_seen.add(node.image.name)
        except Exception:
            pass
    image_seen.update(img.name for img in images.values() if img)
    texture_knowledge_hits = []
    for image_name in image_seen:
        _xdzr8_v112_score_text(scores, evidence, image_name, 3.6, 'texture')
        known_role, _known_reason = _xdzr8_v118_texture_anatomy_hint(image_name)
        if known_role in scores:
            _xdzr8_v1123_add_score(scores, evidence, known_role, 4.4, f'texture knowledge: {Path(image_name).name}')
            texture_knowledge_hits.append(f'{Path(image_name).name}->{known_role}')
    try:
        info.setdefault('_v118_texture_knowledge_hits', []).extend(texture_knowledge_hits)
    except Exception:
        pass

    bound_ctx = _xdzr8_v1183_material_bound_companion_context(mat, source_ref, images, info)
    for row in bound_ctx.get('semantic_hints', [])[:10]:
        weight = max(1.6, 5.1 * float(row.get('weight', 0.0)))
        _xdzr8_v112_score_text(scores, evidence, row.get('text', ''), weight, 'material-bound companion')
    for role in bound_ctx.get('primary_role_hints', [])[:3]:
        if role in scores:
            _xdzr8_v1123_add_score(scores, evidence, role, 1.3, 'material-bound primary-role hint')

    # 3) V11.8 resolves geometry without using mesh/object names.
    local_geo = _xdzr8_v117_material_local_geometry(mat, objects, info)
    local_primary = bool(local_geo.get('used', False) and local_geo.get('primary_mode', False))

    # 4) Dominant bone / vertex-group names are already material-local because
    # this helper samples only polygons carrying the current material.
    vg_text = _xdzr8_v112_material_vertex_group_text(mat, objects)
    if vg_text:
        _xdzr8_v112_score_text(scores, evidence, vg_text, 2.7, 'vertex-groups')

    local_geo = _xdzr8_v117_apply_material_local_intelligence(
        scores, evidence, mat, objects, info, geometry=local_geo
    )
    if not local_primary:
        _xdzr8_v116_apply_head_intelligence(scores, evidence, objects, info)

    metadata_assist, metadata_records = _xdzr8_v1123_metadata_assist(
        scores, evidence, mat, source_ref, objects, info
    )

    primary_root = bound_ctx.get('primary_root', '')
    if primary_root:
        for rec in metadata_records or []:
            memo = _aef11_key(rec.get('memo', ''))
            local_name = str(rec.get('local_name', '') or '')
            english_name = str(rec.get('english_name', '') or '')
            combined_name = ' '.join(x for x in (local_name, english_name) if x)
            tex_name = Path(str(rec.get('texture') or '').replace('\\', '/')).name
            tex_role = _xdzr8_v1122_semantic_role(tex_name, info) if tex_name else ''
            tex_root = _xdzr8_v1122_texture_family_root(tex_name, tex_role, info) if tex_name else ''
            if tex_root and tex_root == primary_root:
                _xdzr8_v112_score_text(scores, evidence, combined_name, 6.1, 'PMX material bound to companion family')
                if 'body' in memo:
                    _xdzr8_v1123_add_score(scores, evidence, 'body', 2.9, 'material-bound PMX Body-family agreement')
                    _xdzr8_v1123_add_score(scores, evidence, 'cloth', 1.2, 'material-bound PMX Body-family context')
                elif 'face' in memo:
                    usage = _xdzr8_v11231_head_usage_bias(objects, mat)
                    best = max(('hair', 'eyes', 'face'), key=lambda r: usage.get(r, 0))
                    if usage.get(best, 0) > 0:
                        _xdzr8_v1123_add_score(scores, evidence, best, 2.6, f'material-bound PMX head-family usage ({best})')
                    else:
                        _xdzr8_v1123_add_score(scores, evidence, 'face', 1.6, 'material-bound PMX head-family neutral context')
                        _xdzr8_v1123_add_score(scores, evidence, 'hair', 0.9, 'material-bound PMX head-family neutral context')
                        _xdzr8_v1123_add_score(scores, evidence, 'eyes', 0.6, 'material-bound PMX head-family neutral context')

    binding_roles, binding_records, _binding_details = _xdzr8_v1181_binding_role_evidence(
        mat, source_ref, info
    )
    if {'sdf_lightmap', 'sdf_mask'} & binding_roles:
        _xdzr8_v1123_add_score(scores, evidence, 'face', 6.2, 'explicit face SDF shader slots')
        metadata_assist.append('source-binding SDF→face')
    if 'emotion' in binding_roles:
        _xdzr8_v1123_add_score(scores, evidence, 'face', 2.8, 'explicit emotion-atlas slot')
        metadata_assist.append('source-binding emotion→face')
    hair_bundle = len(binding_roles & {'line_map', 'stroke_map', 'split_normal', 'specular_ramp'})
    if hair_bundle >= 2:
        _xdzr8_v1123_add_score(scores, evidence, 'hair', 5.6, 'explicit hair-control slot bundle')
        metadata_assist.append('source-binding controls→hair')
    if 'fur_map' in binding_roles:
        _xdzr8_v1123_add_score(scores, evidence, 'cloth', 2.6, 'explicit fur-control slot')
        metadata_assist.append('source-binding fur→cloth')
    try:
        if binding_records:
            info.setdefault('_v1181_binding_material_hits', set()).add(_aef111_safe_material_name(source_ref or mat, 'Material'))
    except Exception:
        pass

    principled = _aef11_principled(source_ref)
    alpha = 1.0
    metallic = 0.0
    color = None
    if principled:
        try: alpha = float(_aef11_socket_default(principled, 'Alpha', 1.0))
        except Exception: pass
        try: metallic = float(_aef11_socket_default(principled, 'Metallic', 0.0))
        except Exception: pass
        try: color = tuple(_aef11_socket_default(principled, 'Base Color', (0.5,0.5,0.5,1.0)))
        except Exception: pass
    try:
        alpha = min(alpha, float(source_ref.diffuse_color[3]))
    except Exception:
        pass
    if images.get('opacity'):
        scores['transparent_cloth'] += 2.2
        evidence['transparent_cloth'].append('opacity texture +2.2')
    if alpha < 0.985:
        v = 5.2 + (1.2 if alpha < 0.80 else 0.0)
        scores['transparent_cloth'] += v
        evidence['transparent_cloth'].append(f'alpha={alpha:.3f} +{v:.1f}')
    if metallic > 0.40:
        scores['accessory'] += 5.0
        evidence['accessory'].append(f'metallic={metallic:.3f} +5.0')
    elif metallic > 0.15:
        scores['accessory'] += 2.0
        evidence['accessory'].append(f'metallic={metallic:.3f} +2.0')
    if color and len(color) >= 3:
        r,g,b = color[:3]
        if r > 0.48 and r > b*1.05 and g > b*0.95 and abs(r-g) < 0.32:
            scores['body'] += 3.0
            evidence['body'].append('skin-like base color +3.0')

    ranked = sorted(scores.items(), key=lambda kv: kv[1], reverse=True)
    top_role, top_score = ranked[0]
    second_role, second_score = ranked[1]
    margin = top_score - second_score

    if top_score < 2.5:
        reason = f'generic fallback; no role signal above threshold (best {top_role}={top_score:.1f})'
        return 'cloth', reason, 'LOW', ranked[:4]

    if metadata_records and top_score >= 5.0 and margin >= 1.5:
        confidence = 'HIGH'
    elif top_score >= 6.5 and margin >= 2.4:
        confidence = 'HIGH'
    elif metadata_records and top_score >= 3.5 and margin >= 0.8:
        confidence = 'MEDIUM'
    elif top_score >= 3.8 and margin >= 1.0:
        confidence = 'MEDIUM'
    else:
        confidence = 'LOW'

    mixed_local = list(local_geo.get('mixed_roles', []) or []) if isinstance(local_geo, dict) else []
    if mixed_local and top_role in mixed_local and confidence == 'HIGH':
        confidence = 'MEDIUM'

    why_bits = evidence.get(top_role, [])[:3]
    reason = '; '.join(why_bits) if why_bits else 'weighted material signals'
    if local_geo.get('used', False):
        reason += f'; material-local geometry ({local_geo.get("summary", "measured")})'
        if mixed_local:
            reason += f'; mixed-local={"/".join(mixed_local)}'
    if primary_root:
        family_roles = '/'.join(bound_ctx.get('family_roles', [])[:6]) or 'none'
        reason += f'; bound-family={primary_root} roles={family_roles}'
    if metadata_assist:
        reason += f'; metadata-assisted ({len(metadata_assist)} hint{"s" if len(metadata_assist) != 1 else ""})'
    reason += f'; score={top_score:.1f}, next={second_role}:{second_score:.1f}, margin={margin:.1f}'
    return top_role, reason, confidence, ranked[:4]


def _aef11_category_style(category, settings):
    depth = float(getattr(settings, 'universal_shadow_depth', 0.55))
    strength = float(getattr(settings, 'universal_toon_strength', 0.88))
    base = {
        'face': (0.66, 0.56, 0.90),
        'body': (0.64, 0.55, 0.88),
        'hair': (0.48, 0.46, 0.82),
        'eyes': (0.88, 0.70, 0.30),
        'eyes5': (0.76, 0.62, 0.68),
        'mouth': (0.72, 0.60, 0.76),
        'transparent_cloth': (0.62, 0.54, 0.82),
        'stockings': (0.50, 0.50, 0.84),
        'accessory': (0.55, 0.50, 0.78),
        'mask': (0.48, 0.48, 0.82),
        'glove': (0.48, 0.48, 0.84),
        'boots': (0.46, 0.48, 0.84),
        'cloth': (0.50, 0.48, 0.84),
    }.get(category, (0.52,0.50,0.84))
    shadow, threshold, toon_mix = base
    # User strength/depth are centered around the locked-look defaults.
    shadow = max(0.18, min(0.90, shadow * (1.10 - depth * 0.35)))
    toon_mix = max(0.0, min(1.0, toon_mix * strength))
    return shadow, threshold, toon_mix


def _aef11_source_color(mat):
    p = _aef11_principled(mat)
    if p and p.inputs.get('Base Color'):
        try: return tuple(p.inputs['Base Color'].default_value)
        except Exception: pass
    try: return tuple(mat.diffuse_color)
    except Exception: return (0.8,0.8,0.8,1.0)


def _aef11_add_image_node(nodes, image, label, location, non_color=False, uv_socket=None, status=None):
    node = nodes.new('ShaderNodeTexImage')
    node.name = 'AEF V11 • ' + label
    resolved_status = str(status or ('FOUND' if image else 'MISSING')).upper()
    node.label = _xdzr8_v113_status_label(label, image, resolved_status)
    node.location = location
    node.image = image
    try:
        node['XDZR8_TextureStatus'] = resolved_status
        node['XDZR8_TextureSemantic'] = str(label)
    except Exception:
        pass
    if image and non_color:
        try: image.colorspace_settings.name = 'Non-Color'
        except Exception: pass
    if uv_socket is not None and node.inputs.get('Vector'):
        try: node.id_data.links.new(uv_socket, node.inputs['Vector'])
        except Exception: pass
    return node


def _aef111_safe_material_name(mat, fallback='Material'):
    """Return a material name without trusting a potentially removed RNA wrapper."""
    try:
        return str(mat.name) if mat else str(fallback)
    except ReferenceError:
        return str(fallback)


def _aef111_resolve_original_source_material(source_mat):
    """Resolve the pre-V11 source when a generated AEF_V11 material is rebuilt.

    V11 materials keep AEF_V11_SourceMaterial. On a second Add Shaders pass the
    object slots commonly point to the generated material, not the original.
    Prefer the still-existing original material when possible, but never require
    it: imported scenes may have purged unused originals.
    """
    if source_mat is None:
        return None
    try:
        is_generated = bool(source_mat.get('AEF_V11_Universal', False))
        source_name = str(source_mat.get('AEF_V11_SourceMaterial', '') or '')
    except ReferenceError:
        return None
    if is_generated and source_name:
        original = bpy.data.materials.get(source_name)
        if original is not None and original != source_mat:
            return original
    return source_mat



_AEF1162_HEAD_ALPHA_ROLES = {'hair', 'face', 'eyes', 'eyes5', 'mouth'}
_AEF1162_ALPHA_NAME_TOKENS = ('alpha', 'opacity', 'transparent', 'transparency', 'cutout', 'clip', 'eyelash', 'eyelashes', 'lash', 'lashes', 'brow', 'eyebrow', 'fringe', 'bang')
_AEF1162_NONOPAQUE_METHODS = {'BLEND', 'HASHED', 'CLIP', 'DITHERED', 'BLENDED'}


def _aef1162_image_has_alpha(image):
    if not image:
        return False
    for attr in ('channels', 'num_channels'):
        try:
            value = int(getattr(image, attr))
            if value >= 4:
                return True
        except Exception:
            pass
    try:
        alpha_mode = str(getattr(image, 'alpha_mode', '') or '').upper()
        if alpha_mode and alpha_mode != 'NONE':
            return True
    except Exception:
        pass
    try:
        depth = int(getattr(image, 'depth', 0) or 0)
        if depth >= 32 and depth % 4 == 0:
            return True
    except Exception:
        pass
    return False


def _sabershader_v1027_fgo_alpha_policy(source_mat, category, existing, source_intelligence=None):
    """FGO Arcade alpha policy with V1.0.3.1 native ObjBin authority.

    When a valid native material table exists, slot 16 is the only authority for
    opacity. A material with native slot 16 preserves that RGB/luminance mask;
    a material without slot 16 is opaque. Legacy name/category/base-alpha
    heuristics are bypassed completely in that mode. The pre-ObjBin fallback is
    retained only for FGO sources that do not ship a parseable native table.
    """
    info = source_intelligence or {}
    if not bool((info.get('fgo_arcade_profile') or {}).get('enabled', False)):
        return None
    category = str(category or 'cloth')
    try:
        source_name = str(source_mat.get('AEF_V11_SourceMaterial', source_mat.name) or source_mat.name)
    except Exception:
        source_name = str(getattr(source_mat, 'name', '') or '')
    name = source_name.casefold()
    opacity_img = existing.get('opacity') if isinstance(existing, dict) else None

    obj_audit = info.get('fgo_objbin_audit') or {}
    native_table_valid = bool(obj_audit.get('valid', False))
    if native_table_valid:
        row = _sabershader_v1029_material_row(info, source_name)
        native_slots = set()
        if row:
            for bind in row.get('slots', []) or []:
                try:
                    native_slots.add(int(bind.get('slot', -1)))
                except Exception:
                    pass
        if 16 in native_slots:
            return {
                'preserve': True,
                'reason': 'FGO ObjBin authoritative native slot 16 RGB/luminance mask',
                'source': 'native_slot16',
                'render_role': True,
                'policy': 'SLOT16_NATIVE_MASK',
                'force_opaque': False,
                'native_slot16': True,
                'native_authority': True,
                'legacy_alpha_discipline': False,
            }
        return {
            'preserve': False,
            'reason': 'FGO ObjBin authoritative material has no native slot 16; opaque',
            'source': '',
            'render_role': False,
            'policy': 'NATIVE_NO_SLOT16_OPAQUE',
            'force_opaque': True,
            'native_slot16': False,
            'native_authority': True,
            'legacy_alpha_discipline': False,
        }

    # Legacy fallback for FGO sources without a parseable ObjBin table.
    if 'cheek' in name and opacity_img is not None:
        return {
            'preserve': True,
            'reason': 'FGO fallback selective cheek overlay mask (RGB/luminance)',
            'source': 'opacity',
            'render_role': True,
            'policy': 'SELECTIVE_RGB_MASK',
            'force_opaque': False,
            'native_slot16': False,
            'native_authority': False,
            'legacy_alpha_discipline': True,
        }

    explicit_cutout_tokens = (
        'eyelash', 'lashes', 'lash', 'eyebrow', 'brow', 'haircard',
        'cutout', 'cut_out', 'alpha_mask', 'alphamask', 'lace', 'veil',
        'transparent', 'translucent',
    )
    if opacity_img is not None and any(tok in name for tok in explicit_cutout_tokens):
        return {
            'preserve': True,
            'reason': 'FGO fallback explicit cutout material with authored opacity map',
            'source': 'opacity',
            'render_role': True,
            'policy': 'SELECTIVE_CUTOUT_MASK',
            'force_opaque': False,
            'native_slot16': False,
            'native_authority': False,
            'legacy_alpha_discipline': True,
        }

    return {
        'preserve': False,
        'reason': 'FGO fallback opaque-by-default surface',
        'source': '',
        'render_role': False,
        'policy': 'FORCE_OPAQUE',
        'force_opaque': True,
        'native_slot16': False,
        'native_authority': False,
        'legacy_alpha_discipline': True,
    }


def _aef1162_source_alpha_decision(source_mat, category, existing, source_intelligence=None):
    fgo_policy = _sabershader_v1027_fgo_alpha_policy(source_mat, category, existing, source_intelligence)
    if fgo_policy is not None:
        return fgo_policy
    category = str(category or 'cloth')
    result = {
        'preserve': False,
        'reason': 'no alpha preservation requested',
        'source': '',
        'render_role': category in {'transparent_cloth', 'mask'},
    }
    opacity_img = existing.get('opacity') if isinstance(existing, dict) else None
    base_img = existing.get('base') if isinstance(existing, dict) else None
    base_has_alpha = _aef1162_image_has_alpha(base_img)
    name_blob = ' '.join(filter(None, [
        getattr(source_mat, 'name', ''),
        getattr(base_img, 'name', ''),
        getattr(opacity_img, 'name', ''),
    ])).lower()
    token_hit = next((tok for tok in _AEF1162_ALPHA_NAME_TOKENS if tok in name_blob), '')
    principled = _aef11_principled(source_mat)
    alpha_linked = False
    alpha_value = 1.0
    try:
        if principled and principled.inputs.get('Alpha'):
            alpha_input = principled.inputs.get('Alpha')
            alpha_linked = bool(getattr(alpha_input, 'is_linked', False))
            alpha_value = float(_aef11_socket_default(principled, 'Alpha', 1.0))
    except Exception:
        alpha_linked = False
        alpha_value = 1.0
    diffuse_alpha = 1.0
    try:
        diffuse_alpha = float(getattr(source_mat, 'diffuse_color', (1.0, 1.0, 1.0, 1.0))[3])
    except Exception:
        diffuse_alpha = 1.0
    render_modes = []
    for attr in ('surface_render_method', 'blend_method'):
        try:
            value = str(getattr(source_mat, attr, '') or '').upper()
        except Exception:
            value = ''
        if value and value not in {'', 'OPAQUE'}:
            render_modes.append(f'{attr}={value}')
    nonopaque = any(mode.split('=', 1)[-1] in _AEF1162_NONOPAQUE_METHODS for mode in render_modes)
    family = str((source_intelligence or {}).get('family', 'General') or 'General')

    evidence = []
    if opacity_img is not None:
        evidence.append('explicit opacity texture')
        result['source'] = 'opacity'
    if alpha_linked:
        evidence.append('source Principled alpha linked')
    if alpha_value < 0.995:
        evidence.append(f'source Principled alpha={alpha_value:.3f}')
    if diffuse_alpha < 0.995:
        evidence.append(f'material diffuse alpha={diffuse_alpha:.3f}')
    if nonopaque:
        evidence.append(', '.join(render_modes))
    if token_hit and base_has_alpha and category in _AEF1162_HEAD_ALPHA_ROLES.union({'mask'}):
        evidence.append(f'name/token hint={token_hit}')
    if base_has_alpha and category == 'hair' and family == 'MMD-type':
        evidence.append('MMD-type hair base texture exposes alpha-capable channels')
    if base_has_alpha and category in {'eyes', 'eyes5'} and token_hit in {'eyelash', 'eyelashes', 'lash', 'lashes', 'brow', 'eyebrow'}:
        evidence.append('eye-adjacent card alpha hint')

    if category in {'transparent_cloth', 'mask'} and (opacity_img is not None or base_has_alpha):
        result['preserve'] = True
        result['render_role'] = True
        result['source'] = result['source'] or ('opacity' if opacity_img is not None else 'base_alpha')
        result['reason'] = '; '.join(evidence or ['transparent role'])
        return result

    if category in _AEF1162_HEAD_ALPHA_ROLES and base_has_alpha and evidence:
        result['preserve'] = True
        result['render_role'] = True
        result['source'] = result['source'] or 'base_alpha'
        result['reason'] = '; '.join(evidence)
        return result

    return result


