    optional_layout = [('roughness',-600),('metallic',-720),('specular',-840),('emission',-960),('ao',-1080),('mask',-1200)]
    family = (source_intelligence or {}).get('family', 'General')
    if family == 'MMD-type':
        optional_layout += [('toon_control',-1320),('shadow_color',-1440),('light_aux',-1560),('auxiliary',-1680)]
    else:
        optional_layout += [('toon_control',-1320),('face_map',-1440),('packed_material',-1560),('packed_aux',-1680)]
    # V11.8.2: proven companion roles survive PMX export loss as a dialect, so
    # expose them for both public source families. Unknown channels stay unconnected.
    dialect_roles = [r for r in _XDZR8_V1181_DIALECT_AUX_ROLES if existing.get(r) or role_status.get(r) in {'FOUND','EXISTING','MISSING'}]
    y = -1800
    for role in sorted(dialect_roles):
        if role not in {r for r,_ in optional_layout}:
            optional_layout.append((role, y)); y -= 120
    texture_slot_nodes = dict(authored_nodes)
    for role,y in optional_layout:
        if role in texture_slot_nodes:
            continue
        texture_slot_nodes[role] = _aef11_add_image_node(nodes, existing.get(role), AEF11_ROLE_LABELS.get(role, role.replace('_',' ').title()), (-820,y), role not in {'emission','shadow_color','auxiliary','light_aux','derived_eye_atlas'}, uv_socket, role_status.get(role))

    authored_control_audit = _xdzr8_v1182_expose_control_channels(nodes, links, texture_slot_nodes)
    packed_audit = _xdzr8_v114_build_packed_channel_nodes(
        nodes, links, texture_slot_nodes, category, source_intelligence,
        bool(getattr(settings, 'universal_decode_packed_maps', True))
    )

    # Keep additional safe auxiliary maps visible but unconnected. This is
