    mat['XDZR8_V119211_UmaShadowPalette'] = bool(target_core_audit.get('uma_shadow_palette', False))
    mat['XDZR8_V119211_UmaShadowPaletteProfile'] = str(target_core_audit.get('uma_shadow_palette_profile', ''))
    mat['XDZR8_V119211_UmaShadowPaletteStrength'] = float(target_core_audit.get('uma_shadow_palette_strength', 0.0))
    mat['XDZR8_V119211_UmaFaceOutlineFidelity'] = bool(target_core_audit.get('uma_face_outline_fidelity', False))
