def _aef108b1_refine_cloth_style(style, profile, family, source_name, settings):
    out = dict(style)
    if not settings or not getattr(settings, 'build_graphic_separation_refinement_v108b1', True):
        return out
    if profile != 'AVE':
        return out

    black_t = max(0.0, min(1.0, float(getattr(settings, 'cloth_black_rebalance_v108b1', 0.18))))
    trans_t = max(0.0, min(1.0, float(getattr(settings, 'transparent_cleanup_v108b1', 0.22))))

    if family in {'main', 'corset', 'hard'}:
        out['shadow_mul'] = _aef108a_mix_scalar(out.get('shadow_mul', 1.0), float(out.get('shadow_mul', 1.0)) * 0.88, black_t)
        out['mid_mul'] = _aef108a_mix_scalar(out.get('mid_mul', 1.0), float(out.get('mid_mul', 1.0)) * 0.93, black_t)
        out['light_mul'] = _aef108a_mix_scalar(out.get('light_mul', 1.0), float(out.get('light_mul', 1.0)) * 0.97, black_t)
        out['value'] = _aef108a_mix_scalar(out.get('value', 1.0), float(out.get('value', 1.0)) * 0.975, black_t)
        out['bright_protect'] = _aef108a_mix_scalar(out.get('bright_protect', 0.3), float(out.get('bright_protect', 0.3)) * 0.94, black_t)
        out['emission_strength'] = _aef108a_mix_scalar(out.get('emission_strength', 1.0), float(out.get('emission_strength', 1.0)) * 0.985, black_t)
        out['saturation'] = _aef108a_mix_scalar(out.get('saturation', 1.0), float(out.get('saturation', 1.0)) * 1.015, black_t)
    elif family in {'accent', 'ornament'}:
        t = black_t * 0.65
        out['shadow_mul'] = _aef108a_mix_scalar(out.get('shadow_mul', 1.0), float(out.get('shadow_mul', 1.0)) * 0.92, t)
        out['mid_mul'] = _aef108a_mix_scalar(out.get('mid_mul', 1.0), float(out.get('mid_mul', 1.0)) * 0.96, t)
        out['light_mul'] = _aef108a_mix_scalar(out.get('light_mul', 1.0), float(out.get('light_mul', 1.0)) * 0.985, t)
        out['value'] = _aef108a_mix_scalar(out.get('value', 1.0), float(out.get('value', 1.0)) * 0.985, t)
    elif family == 'stockings':
        t = black_t * 0.45
        out['shadow_mul'] = _aef108a_mix_scalar(out.get('shadow_mul', 1.0), float(out.get('shadow_mul', 1.0)) * 0.95, t)
        out['mid_mul'] = _aef108a_mix_scalar(out.get('mid_mul', 1.0), float(out.get('mid_mul', 1.0)) * 0.97, t)
        out['light_mul'] = _aef108a_mix_scalar(out.get('light_mul', 1.0), float(out.get('light_mul', 1.0)) * 0.98, t)
        out['value'] = _aef108a_mix_scalar(out.get('value', 1.0), float(out.get('value', 1.0)) * 0.985, t)
    elif family == 'transparent':
        out['shadow_mul'] = _aef108a_mix_scalar(out.get('shadow_mul', 1.0), float(out.get('shadow_mul', 1.0)) * 0.90, trans_t)
        out['mid_mul'] = _aef108a_mix_scalar(out.get('mid_mul', 1.0), float(out.get('mid_mul', 1.0)) * 0.95, trans_t)
        out['light_mul'] = _aef108a_mix_scalar(out.get('light_mul', 1.0), float(out.get('light_mul', 1.0)) * 0.97, trans_t)
        out['value'] = _aef108a_mix_scalar(out.get('value', 1.0), float(out.get('value', 1.0)) * 0.965, trans_t)
        out['bright_protect'] = _aef108a_mix_scalar(out.get('bright_protect', 0.1), float(out.get('bright_protect', 0.1)) * 0.88, trans_t)
        out['opacity_scale'] = _aef108a_mix_scalar(out.get('opacity_scale', 1.0), float(out.get('opacity_scale', 1.0)) * 0.95, trans_t)
