def _aef108c1_final_micro_polish_cloth_style(style, profile, family, source_name, settings):
    out = dict(style)
    if not settings or not getattr(settings, 'build_final_micro_polish_v108c1', True):
        return out
    if profile != 'AVE':
        return out

    sep_t = max(0.0, min(1.0, float(getattr(settings, 'doloris_cloth_separation_v108c1', 0.18))))
    trans_t = max(0.0, min(1.0, float(getattr(settings, 'transparency_red_hold_v108c1', 0.22))))
    skirt_t = max(0.0, min(1.0, float(getattr(settings, 'oblivionis_skirt_contain_v108c1', 0.24))))
    corset_t = max(0.0, min(1.0, float(getattr(settings, 'oblivionis_corset_compact_v108c1', 0.16))))
    src_name = (source_name or '').strip().lower()

    # Doloris: separate the main top a touch from the darker short block.
    if src_name == 'clothes':
        t = sep_t * 0.55
        out['mid_mul'] = _aef108a_mix_scalar(out.get('mid_mul', 1.0), float(out.get('mid_mul', 1.0)) * 1.010, t)
        out['light_mul'] = _aef108a_mix_scalar(out.get('light_mul', 1.0), float(out.get('light_mul', 1.0)) * 1.012, t)
        out['value'] = _aef108a_mix_scalar(out.get('value', 1.0), float(out.get('value', 1.0)) * 1.006, t)
        out['recover_strength'] = _aef108a_mix_scalar(out.get('recover_strength', 0.0), float(out.get('recover_strength', 0.0)) * 1.10, t)
    elif src_name == 'clothes3':
        out['shadow_mul'] = _aef108a_mix_scalar(out.get('shadow_mul', 1.0), float(out.get('shadow_mul', 1.0)) * 0.975, sep_t)
        out['mid_mul'] = _aef108a_mix_scalar(out.get('mid_mul', 1.0), float(out.get('mid_mul', 1.0)) * 0.978, sep_t)
        out['light_mul'] = _aef108a_mix_scalar(out.get('light_mul', 1.0), float(out.get('light_mul', 1.0)) * 0.988, sep_t)
        out['value'] = _aef108a_mix_scalar(out.get('value', 1.0), float(out.get('value', 1.0)) * 0.984, sep_t)
        out['emission_strength'] = _aef108a_mix_scalar(out.get('emission_strength', 1.0), float(out.get('emission_strength', 1.0)) * 0.992, sep_t)

    # Doloris / global transparencies: less milky veil, better hold of interior colour.
    if family == 'transparent' or src_name in {'clothes4', '裙透'}:
        t = trans_t if src_name == 'clothes4' else trans_t * 0.70
        out['opacity_scale'] = _aef108a_mix_scalar(out.get('opacity_scale', 1.0), float(out.get('opacity_scale', 1.0)) * 0.965, t)
        out['alpha_luma_bright'] = _aef108a_mix_scalar(out.get('alpha_luma_bright', 0.46), max(0.20, float(out.get('alpha_luma_bright', 0.46)) - 0.030), t)
        out['recover_strength'] = _aef108a_mix_scalar(out.get('recover_strength', 0.0), float(out.get('recover_strength', 0.0)) * 1.18, t)
        out['saturation'] = _aef108a_mix_scalar(out.get('saturation', 1.0), float(out.get('saturation', 1.0)) * 1.03, t)
        out['white_compress_strength'] = _aef108a_mix_scalar(out.get('white_compress_strength', 0.48), float(out.get('white_compress_strength', 0.48)) * 0.96, t * 0.65)
        out['emission_strength'] = _aef108a_mix_scalar(out.get('emission_strength', 1.0), float(out.get('emission_strength', 1.0)) * 0.985, t * 0.60)

    # Oblivionis skirt/black dress: contain the light inner skirt and add a little depth.
    if src_name == '裙':
        out['shadow_mul'] = _aef108a_mix_scalar(out.get('shadow_mul', 1.0), float(out.get('shadow_mul', 1.0)) * 0.975, skirt_t * 0.70)
        out['mid_mul'] = _aef108a_mix_scalar(out.get('mid_mul', 1.0), float(out.get('mid_mul', 1.0)) * 0.988, skirt_t * 0.65)
        out['light_mul'] = _aef108a_mix_scalar(out.get('light_mul', 1.0), float(out.get('light_mul', 1.0)) * 0.958, skirt_t)
        out['value'] = _aef108a_mix_scalar(out.get('value', 1.0), float(out.get('value', 1.0)) * 0.960, skirt_t)
        out['bright_protect'] = _aef108a_mix_scalar(out.get('bright_protect', 0.3), float(out.get('bright_protect', 0.3)) * 0.92, skirt_t * 0.85)
        out['emission_strength'] = _aef108a_mix_scalar(out.get('emission_strength', 1.0), float(out.get('emission_strength', 1.0)) * 0.985, skirt_t * 0.75)
    elif src_name == '服':
        t = skirt_t * 0.45
        out['shadow_mul'] = _aef108a_mix_scalar(out.get('shadow_mul', 1.0), float(out.get('shadow_mul', 1.0)) * 0.985, t)
        out['mid_mul'] = _aef108a_mix_scalar(out.get('mid_mul', 1.0), float(out.get('mid_mul', 1.0)) * 0.992, t)
        out['value'] = _aef108a_mix_scalar(out.get('value', 1.0), float(out.get('value', 1.0)) * 0.992, t)

    # Oblivionis/Doloris corset blocks: slightly more integrated, less contrasty.
    if family == 'corset' or src_name == 'clothes2':
        t = corset_t if src_name == 'clothes2' else corset_t * 0.70
        out['mid_mul'] = _aef108a_mix_scalar(out.get('mid_mul', 1.0), float(out.get('mid_mul', 1.0)) * 0.985, t)
        out['light_mul'] = _aef108a_mix_scalar(out.get('light_mul', 1.0), float(out.get('light_mul', 1.0)) * 0.972, t)
        out['value'] = _aef108a_mix_scalar(out.get('value', 1.0), float(out.get('value', 1.0)) * 0.978, t)
        out['saturation'] = _aef108a_mix_scalar(out.get('saturation', 1.0), float(out.get('saturation', 1.0)) * 0.988, t)
        out['bright_protect'] = _aef108a_mix_scalar(out.get('bright_protect', 0.3), float(out.get('bright_protect', 0.3)) * 0.985, t * 0.60)

    return out



def _aef108c2_final_lock_cloth_style(style, profile, family, source_name, settings):
    out = dict(style)
    if not settings or not getattr(settings, 'build_final_lock_v108c2', True):
        return out
    if profile != 'AVE':
        return out

    view_t = max(0.0, min(1.0, float(getattr(settings, 'view_consistency_v108c2', 0.12))))
    black_t = max(0.0, min(1.0, float(getattr(settings, 'black_midtone_lock_v108c2', 0.12))))
    trans_t = max(0.0, min(1.0, float(getattr(settings, 'transparency_edge_hold_v108c2', 0.14))))
    trim_t = max(0.0, min(1.0, float(getattr(settings, 'gold_trim_balance_v108c2', 0.10))))

    # A tiny widening of the artistic normal remap makes frontal and 3/4
    # react more similarly without removing designed volume.
    if view_t > 0.0:
        rmin = float(out.get('remap_min', -0.20))
        rmax = float(out.get('remap_max', 0.82))
        out['remap_min'] = _aef108a_mix_scalar(rmin, rmin - 0.035, view_t)
        out['remap_max'] = _aef108a_mix_scalar(rmax, rmax + 0.025, view_t)
        out['mid_pos'] = _aef108a_mix_scalar(out.get('mid_pos', 0.43), float(out.get('mid_pos', 0.43)) + 0.004, view_t)
        out['light_pos'] = _aef108a_mix_scalar(out.get('light_pos', 0.70), float(out.get('light_pos', 0.70)) + 0.006, view_t)
        out['inner_strength'] = _aef108a_mix_scalar(out.get('inner_strength', 0.10), float(out.get('inner_strength', 0.10)) * 0.985, view_t)

    if family in {'main', 'corset', 'hard'}:
        out['shadow_mul'] = _aef108a_mix_scalar(out.get('shadow_mul', 1.0), float(out.get('shadow_mul', 1.0)) * 0.985, black_t)
        out['mid_mul'] = _aef108a_mix_scalar(out.get('mid_mul', 1.0), float(out.get('mid_mul', 1.0)) * 0.982, black_t)
        out['light_mul'] = _aef108a_mix_scalar(out.get('light_mul', 1.0), float(out.get('light_mul', 1.0)) * 0.992, black_t)
        out['value'] = _aef108a_mix_scalar(out.get('value', 1.0), float(out.get('value', 1.0)) * 0.992, black_t)
        out['bright_protect'] = _aef108a_mix_scalar(out.get('bright_protect', 0.3), float(out.get('bright_protect', 0.3)) * 0.985, black_t)
        out['recover_strength'] = _aef108a_mix_scalar(out.get('recover_strength', 0.05), float(out.get('recover_strength', 0.05)) * 1.015, black_t * 0.50)

    elif family == 'transparent':
        out['opacity_scale'] = _aef108a_mix_scalar(out.get('opacity_scale', 1.0), float(out.get('opacity_scale', 1.0)) * 0.982, trans_t)
        out['alpha_luma_bright'] = _aef108a_mix_scalar(out.get('alpha_luma_bright', 0.46), max(0.18, float(out.get('alpha_luma_bright', 0.46)) - 0.022), trans_t)
        out['white_compress_strength'] = _aef108a_mix_scalar(out.get('white_compress_strength', 0.48), float(out.get('white_compress_strength', 0.48)) * 0.975, trans_t)
        out['white_compress_color'] = _aef108a_mix_rgba(out.get('white_compress_color', (0.68, 0.71, 0.79, 1.0)), (0.55, 0.57, 0.64, 1.0), trans_t * 0.55)
        out['recover_strength'] = _aef108a_mix_scalar(out.get('recover_strength', 0.03), float(out.get('recover_strength', 0.03)) * 1.08, trans_t)
        out['saturation'] = _aef108a_mix_scalar(out.get('saturation', 1.0), float(out.get('saturation', 1.0)) * 1.012, trans_t)
        out['emission_strength'] = _aef108a_mix_scalar(out.get('emission_strength', 1.0), float(out.get('emission_strength', 1.0)) * 0.992, trans_t)

    elif family in {'accent', 'ornament'}:
        # Keep the antique gold readable, but stop it from becoming the
        # brightest object when the view rotates.
        out['gold_strength'] = _aef108a_mix_scalar(out.get('gold_strength', 0.20), float(out.get('gold_strength', 0.20)) * 0.965, trim_t)
        out['light_mul'] = _aef108a_mix_scalar(out.get('light_mul', 1.0), float(out.get('light_mul', 1.0)) * 0.993, trim_t)
        out['bright_protect'] = _aef108a_mix_scalar(out.get('bright_protect', 0.5), float(out.get('bright_protect', 0.5)) * 0.985, trim_t)
        out['saturation'] = _aef108a_mix_scalar(out.get('saturation', 1.0), float(out.get('saturation', 1.0)) * 0.995, trim_t)

    return out


AEF96_FACE_SHADOW_PREFIX = "AEF V9.6 • Face Shadow • "

AEF96_FACE_SHADOW_STYLE = {
    "MYGO": {
        # Sin cambios en V10.1: MYGO es "suave y contenido" a propósito
        # (ver shot_profile.items), así que se deja tal cual estaba.
        # chin_scale explícito solo para que _aef96_apply_face_shadow no
        # dependa del default de .get(): mismo 0.28 de siempre.
        "shadow": (0.88, 0.90, 0.96, 1.0),
        "chin":   (0.94, 0.90, 0.92, 1.0),
        "key_dir": (-0.18, -0.82, 0.55),
        "normal_from": -0.05,
        "normal_to": 0.50,
        "chin_from": 0.18,
        "chin_to": 0.52,
        "chin_scale": 0.28,
    },
    "AVE": {
        # V10.3 — PERFIL AVE: base luminosa tipo Tertiary Sanzigen.
        #   - sombra/chin aún más levantados para conservar piel visible;
        #   - máscara lateral suave y transición amplia;
        #   - barbilla progresiva, sin aplastar la zona media.
        "shadow": (0.74, 0.76, 0.84, 1.0),
        "chin":   (0.82, 0.78, 0.82, 1.0),
        "key_dir": (-0.30, -0.76, 0.58),
        "normal_from": 0.08,
        "normal_to": 0.42,
        "chin_from": 0.06,
        "chin_to": 0.62,
        "chin_scale": 0.24,
    },
}


def _aef96_remove_nodes_and_restore(group):
    """Remove only V9.6 nodes and restore the previous Base Color source."""
    if not group:
        return False
    nodes, links = group.nodes, group.links
    final = nodes.get("AEF Face Principled") or nodes.get("AEF Face Principled Toon")
    if not final:
        return False
    base = final.inputs.get("Base Color")
    shadow2 = nodes.get(AEF96_FACE_SHADOW_PREFIX + "Chin Mix")
    shadow1 = nodes.get(AEF96_FACE_SHADOW_PREFIX + "Main Mix")
    source_socket = None
    source_value = None
    if shadow2:
        c1 = shadow2.inputs.get("Color1")
        if c1 and c1.is_linked:
            source_socket = c1.links[0].from_socket
        elif c1:
            try: source_value = tuple(c1.default_value)
            except Exception: source_value = None
    elif shadow1:
        c1 = shadow1.inputs.get("Color1")
        if c1 and c1.is_linked:
            source_socket = c1.links[0].from_socket
        elif c1:
            try: source_value = tuple(c1.default_value)
            except Exception: source_value = None
    elif base and base.is_linked:
        lk = base.links[0]
        if lk.from_node.name.startswith(AEF96_FACE_SHADOW_PREFIX):
            return False
    if base:
        for lk in list(base.links):
            if lk.from_node.name.startswith(AEF96_FACE_SHADOW_PREFIX):
                links.remove(lk)
    removed=False
    for n in list(nodes):
        if n.name.startswith(AEF96_FACE_SHADOW_PREFIX):
            nodes.remove(n); removed=True
    if removed and base:
        if source_socket is not None:
            links.new(source_socket, base)
        elif source_value is not None:
            base.default_value = source_value
    return removed


def _aef96_apply_face_shadow(group, profile="AVE", strength=0.55, style_override=None):
    """V10.4 designed face shadow using 2D Generated coords, not mesh normals."""
    if not group:
        return False, "grupo inexistente"
    before = _aef15_image_link_signature(group)
    final = group.nodes.get("AEF Face Principled") or group.nodes.get("AEF Face Principled Toon")
    if not final or final.bl_idname != 'ShaderNodeBsdfPrincipled':
        return False, "sin Principled facial V8.17/V9"
    base = final.inputs.get('Base Color')
    if not base:
        return False, "sin Base Color"
    _aef96_remove_nodes_and_restore(group)
    final = group.nodes.get("AEF Face Principled") or group.nodes.get("AEF Face Principled Toon")
    if not final:
        return False, "Principled facial desapareció"
    base = final.inputs.get('Base Color')
    source_socket = base.links[0].from_socket if base.is_linked else None
    source_value = None if source_socket is not None else tuple(base.default_value)
    nodes, links = group.nodes, group.links
    s = dict(AEF96_FACE_SHADOW_STYLE.get(profile, AEF96_FACE_SHADOW_STYLE['AVE']))
    if style_override:
        s = dict(style_override)
    strength = max(0.0, min(1.0, float(strength)))

    # One stable 2D coordinate field for the face. X controls broad side
    # shadow; Z controls chin bias. The nose's local normals are irrelevant.
    tc=nodes.new('ShaderNodeTexCoord'); tc.name=AEF96_FACE_SHADOW_PREFIX+'Generated'; tc.label='V10.4 • Face SDF coords'; tc.location=(final.location.x-980, final.location.y-160)
    sep=nodes.new('ShaderNodeSeparateXYZ'); sep.name=AEF96_FACE_SHADOW_PREFIX+'XYZ'; sep.location=(final.location.x-780, final.location.y-160)
    links.new(tc.outputs['Generated'], sep.inputs['Vector'])

    nr = nodes.new('ShaderNodeMapRange'); nr.name=AEF96_FACE_SHADOW_PREFIX+'Side Mask'; nr.label='V10.4 • Broad side shadow'; nr.location=(final.location.x-580, final.location.y-40); nr.clamp=True
    nr.inputs['From Min'].default_value=float(s.get('side_from', 0.38)); nr.inputs['From Max'].default_value=float(s.get('side_to', 0.62))
    if float(s.get('key_dir', (-0.3, -0.7, 0.5))[0]) < 0.0:
        nr.inputs['To Min'].default_value=0.0; nr.inputs['To Max'].default_value=1.0
    else:
        nr.inputs['To Min'].default_value=1.0; nr.inputs['To Max'].default_value=0.0
    links.new(sep.outputs['X'], nr.inputs['Value'])

    cr=nodes.new('ShaderNodeMapRange'); cr.name=AEF96_FACE_SHADOW_PREFIX+'Chin Mask'; cr.label='V9.6 • Chin bias'; cr.location=(final.location.x-580, final.location.y-260); cr.clamp=True
    cr.inputs['From Min'].default_value=s['chin_from']; cr.inputs['From Max'].default_value=s['chin_to']; cr.inputs['To Min'].default_value=1.0; cr.inputs['To Max'].default_value=0.0
    links.new(sep.outputs['Z'], cr.inputs['Value'])

    sm=nodes.new('ShaderNodeMath'); sm.name=AEF96_FACE_SHADOW_PREFIX+'Shadow Strength'; sm.label='V10.4 • Shadow strength'; sm.operation='MULTIPLY'; sm.location=(final.location.x-430, final.location.y-20)
    sm.inputs[1].default_value=strength
    links.new(nr.outputs['Result'], sm.inputs[0])

    mm=nodes.new('ShaderNodeMixRGB'); mm.name=AEF96_FACE_SHADOW_PREFIX+'Main Mix'; mm.label='V10.4 • Designed Face SDF Shadow'; mm.blend_type='MULTIPLY'; mm.location=(final.location.x-300, final.location.y+60)
    mm.inputs['Color2'].default_value=s['shadow']
    links.new(sm.outputs['Value'], mm.inputs['Fac'])
    if source_socket is not None: links.new(source_socket, mm.inputs['Color1'])
    else: mm.inputs['Color1'].default_value=source_value

    csm=nodes.new('ShaderNodeMath'); csm.name=AEF96_FACE_SHADOW_PREFIX+'Chin Strength'; csm.label='V9.6 • Chin strength'; csm.operation='MULTIPLY'; csm.location=(final.location.x-250, final.location.y-180)
    csm.inputs[1].default_value=max(0.0, min(1.0, strength*s.get('chin_scale', 0.28)))
    links.new(cr.outputs['Result'], csm.inputs[0])

    cm=nodes.new('ShaderNodeMixRGB'); cm.name=AEF96_FACE_SHADOW_PREFIX+'Chin Mix'; cm.label='V9.6 • Chin soft tint'; cm.blend_type='MULTIPLY'; cm.location=(final.location.x-60, final.location.y+60); cm.inputs['Color2'].default_value=s['chin']
    links.new(csm.outputs['Value'], cm.inputs['Fac']); links.new(mm.outputs['Color'], cm.inputs['Color1'])

    for lk in list(base.links): links.remove(lk)
    links.new(cm.outputs['Color'], base)

    after=_aef15_image_link_signature(group)
    if before!=after:
        _aef96_remove_nodes_and_restore(group)
        raise RuntimeError(f"V10.4 Face SDF safety check FAILED: Image Texture links changed on {group.name}")
    group['AEF_V9_6_FaceShadow']=True
    group['AEF_V9_6_Profile']=profile
    group['AEF_V9_6_Strength']=strength
    group['AEF_V10_4_FaceSDF']=True
    return True, f"2D face SDF side shadow + chin bias (strength={strength:.2f})"

def build_v96_face_shadow_system(settings):
    if not getattr(settings, 'build_face_shadow_design', True):
        return 0
    profile=getattr(settings,'shot_profile','AVE')
    # V10.3 AVE: Sanzigen-like base shader should keep the face luminous.
    # Use a localized AVE override rather than changing the MYGO/default slider.
    # AVE default effective strength = 0.38 (within the requested 0.35-0.40 range).
    strength = (0.38 if profile == 'AVE' else getattr(settings,'face_shadow_strength',0.55))
    base_style = AEF96_FACE_SHADOW_STYLE.get(profile, AEF96_FACE_SHADOW_STYLE['AVE'])
    style_override = None
    if getattr(settings, 'build_series_match_v108a', True):
        face_t = getattr(settings, 'face_series_match_strength', 0.62)
        target = AEF108A_FACE_TARGET.get(profile)
        if target:
            strength = _aef108a_mix_scalar(strength, target.get('effective_strength', strength), face_t)
            style_override = _aef108a_blend_style(base_style, target, face_t)
    count=0; prefix='AEF_V8_'
    for obj in bpy.context.scene.objects:
        if obj.type!='MESH': continue
        for slot in obj.material_slots:
            mat=slot.material
            if not mat or not mat.name.startswith(prefix): continue
            if mat.get('AEF_V8_Category')!='face': break
            gn=mat.node_tree.nodes.get('XDZR8_V8') if getattr(mat,'use_nodes',False) else None
            group=gn.node_tree if gn else None
            if group:
                try:
                    local_strength = strength
                    local_style = dict(style_override) if style_override else dict(base_style)
                    character = _aef108a_character_from_material(mat.name)
                    char_target, char_t = _aef108a1_face_character_target(profile, character, settings)
                    if char_target and char_t > 0.0:
                        local_strength = _aef108a_mix_scalar(local_strength, char_target.get('effective_strength', local_strength), char_t)
                        local_style = _aef108a_blend_style(local_style, char_target, char_t)
                    g_target, g_t = _aef108b_face_target(profile, settings)
                    if g_target and g_t > 0.0:
                        local_strength = _aef108a_mix_scalar(local_strength, g_target.get('effective_strength', local_strength), g_t)
                        local_style = _aef108a_blend_style(local_style, g_target, g_t)
                    b1_target, b1_t = _aef108b1_face_character_target(profile, character, settings)
                    if b1_target and b1_t > 0.0:
                        local_strength = _aef108a_mix_scalar(local_strength, b1_target.get('effective_strength', local_strength), b1_t)
                        local_style = _aef108a_blend_style(local_style, b1_target, b1_t)
                    c1_target, c1_t = _aef109c1_face_character_target(profile, character, settings)
                    if c1_target and c1_t > 0.0:
                        local_strength = _aef108a_mix_scalar(local_strength, c1_target.get('effective_strength', local_strength), c1_t)
                        local_style = _aef108a_blend_style(local_style, c1_target, c1_t)
                    ok,_=_aef96_apply_face_shadow(group, profile, local_strength, local_style)
                    if ok: count+=1
                except Exception as exc:
                    log(f'V9.6 Face Shadow {obj.name}: {exc}')
            break
    scene=bpy.context.scene
    scene['AEF_V9_6_FaceShadowCount']=count
    scene['AEF_V9_6_FaceShadowStrength']=float(strength)
    scene['AEF_V9_6_ShotProfile']=profile
    scene['AEF_V10_8A_FaceMatchStrength']=float(getattr(settings, 'face_series_match_strength', 0.62) if getattr(settings, 'build_series_match_v108a', True) else 0.0)
    scene['AEF_V10_8A1_DolorisFaceSoften']=float(getattr(settings, 'doloris_face_soften_v108a1', 0.58) if getattr(settings, 'build_character_micro_tune_v108a1', True) else 0.0)
    scene['AEF_V10_8B_FaceGraphicSeparation']=float(getattr(settings, 'face_graphic_separation_strength_v108b', 0.52) if getattr(settings, 'build_graphic_separation_v108b', True) else 0.0)
    scene['AEF_V10_8B1_DolorisFaceBalance']=float(getattr(settings, 'doloris_face_balance_v108b1', 0.50) if getattr(settings, 'build_graphic_separation_refinement_v108b1', True) else 0.0)
    scene['AEF_V10_9C1_DolorisFaceFinal']=float(getattr(settings, 'doloris_face_match_final_v109c1', 0.42) if getattr(settings, 'build_face_hair_series_match_final_v109c1', True) else 0.0)
    scene['AEF_V10_9C1_OblivionisFaceFinal']=float(getattr(settings, 'oblivionis_face_match_final_v109c1', 0.28) if getattr(settings, 'build_face_hair_series_match_final_v109c1', True) else 0.0)
    return count


# =====================================================================
# V9.7 — HAIR TOON / HIGHLIGHT
# ---------------------------------------------------------------------
# Objetivo: sacar el pelo del aspecto PBR uniforme y acercarlo a una
# masa de toon estilizada: sombra amplia + semitono + highlight gráfico.
#
# Restricciones:
#   - No se crean ni reasignan Image Texture.
#   - No se modifican UVs.
#   - Se trabaja únicamente alrededor del Base Color y propiedades del
#     Principled ya existentes del grupo Hair.
#   - Se elimina SOLO la cadena V9.3 Hair Ribbon y se restaura su entrada
#     previa antes de construir la V9.7.
# =====================================================================
AEF97_HAIR_PREFIX = "AEF V9.7 • Hair Toon • "

AEF97_HAIR_STYLE = {
    "MYGO": {
        "shadow": (0.76, 0.79, 0.88, 1.0),
        "mid":    (0.94, 0.95, 1.00, 1.0),
        "highlight": (1.00, 0.93, 0.92, 1.0),
        "facing0": 0.70,
        "facing1": 0.94,
        "shadow_fac": 0.24,
        "highlight_fac": 0.10,
    },
    "AVE": {
        "shadow": (0.66, 0.70, 0.84, 1.0),
        "mid":    (0.90, 0.91, 0.98, 1.0),
        "highlight": (1.00, 0.78, 0.84, 1.0),
        "facing0": 0.64,
        "facing1": 0.92,
        "shadow_fac": 0.28,
        "highlight_fac": 0.13,
    },
}


def _aef97_image_sig(group):
    try:
        return _aef15_image_link_signature(group)
    except Exception:
        return None


def _aef97_remove_old_chain(group):
    """Remove V9.7 and the old V9.3 ribbon, restoring the pre-ribbon Base Color source."""
    if not group:
        return False
    nodes, links = group.nodes, group.links
    final = nodes.get("Principled BSDF") or nodes.get("AEF Anime Toon Principled") or nodes.get("AEF Hair Principled")
    if not final:
        return False
    base = final.inputs.get("Base Color")
    if not base:
        return False

    source_socket = None
    source_value = None

    # Prefer the Color1 input of the V9.3 ADD node, which stores the
    # pre-ribbon source exactly as it existed before V9.3.
    ribbon_add = nodes.get(AEF93_HAIR_PREFIX + 'Add')
    if ribbon_add:
        c1 = ribbon_add.inputs.get('Color1')
        if c1 and c1.is_linked:
            source_socket = c1.links[0].from_socket
        elif c1:
            try: source_value = tuple(c1.default_value)
            except Exception: source_value = None

    # If V9.3 isn't present, preserve the current Base Color source unless
    # it is one of our own V9.7 nodes.
    if source_socket is None and source_value is None and base.is_linked:
        src = base.links[0].from_socket
        if not src.node.name.startswith((AEF97_HAIR_PREFIX, AEF93_HAIR_PREFIX)):
            source_socket = src

    if source_socket is None and source_value is None and not base.is_linked:
        try: source_value = tuple(base.default_value)
        except Exception: source_value = None

    changed=False
    for n in list(nodes):
        if n.name.startswith(AEF97_HAIR_PREFIX) or n.name.startswith(AEF93_HAIR_PREFIX):
            nodes.remove(n); changed=True

    for lk in list(base.links):
        if lk.from_node.name.startswith((AEF97_HAIR_PREFIX, AEF93_HAIR_PREFIX)):
            links.remove(lk)
            changed=True

    if source_socket is not None:
        for lk in list(base.links):
            links.remove(lk)
        links.new(source_socket, base)
        changed=True
    elif source_value is not None:
        for lk in list(base.links):
            links.remove(lk)
        base.default_value=source_value
        changed=True

    return changed


def _aef97_apply_hair_toon(group, profile="AVE", toon_strength=0.72, highlight_strength=0.16, style_override=None):
    if not group:
        return False, "grupo inexistente"
    before = _aef97_image_sig(group)
    final = group.nodes.get("Principled BSDF") or group.nodes.get("AEF Anime Toon Principled") or group.nodes.get("AEF Hair Principled")
    if not final or final.bl_idname != 'ShaderNodeBsdfPrincipled':
        return False, "sin Principled de Hair"
    base = final.inputs.get('Base Color')
    if not base:
        return False, "sin Base Color"

    # Remove V9.3/V9.7 chains and restore the underlying base color source.
    _aef97_remove_old_chain(group)
    final = group.nodes.get("Principled BSDF") or group.nodes.get("AEF Anime Toon Principled") or group.nodes.get("AEF Hair Principled")
    base = final.inputs.get('Base Color')
    source_socket = base.links[0].from_socket if base.is_linked else None
    source_value = None if source_socket is not None else tuple(base.default_value)

    nodes, links = group.nodes, group.links
    style = dict(AEF97_HAIR_STYLE.get(profile, AEF97_HAIR_STYLE['AVE']))
    if style_override:
        style = dict(style_override)
    toon_strength=max(0.0,min(1.0,float(toon_strength)))
    highlight_strength=max(0.0,min(0.5,float(highlight_strength)))

    # Camera-facing factor: broad enough to behave like a graphic ribbon,
    # not like a physically small Fresnel highlight.
    lw=nodes.new('ShaderNodeLayerWeight'); lw.name=AEF97_HAIR_PREFIX+'Facing'; lw.label='V9.7 • Hair facing'; lw.location=(final.location.x-980,final.location.y-240)
    ramp=nodes.new('ShaderNodeValToRGB'); ramp.name=AEF97_HAIR_PREFIX+'Toon Band'; ramp.label='V9.7 • Broad hair band'; ramp.location=(final.location.x-760,final.location.y-240)
    ramp.color_ramp.interpolation='CONSTANT'
    elems=ramp.color_ramp.elements
    elems[0].position=style['facing0']; elems[0].color=style['shadow']
    elems[1].position=style['facing1']; elems[1].color=style['mid']
    links.new(lw.outputs['Facing'],ramp.inputs['Fac'])

    # Multiply the original texture/color by the designed broad band.
    mult=nodes.new('ShaderNodeMixRGB'); mult.name=AEF97_HAIR_PREFIX+'Toon Mix'; mult.label='V9.7 • Hair toon mass'; mult.blend_type='MULTIPLY'; mult.location=(final.location.x-500,final.location.y-20)
    mult.inputs['Fac'].default_value=toon_strength
    if source_socket is not None: links.new(source_socket,mult.inputs['Color1'])
    else: mult.inputs['Color1'].default_value=source_value
    links.new(ramp.outputs['Color'],mult.inputs['Color2'])

    # Separate compact highlight. It is added on top of the toon mass.
    hr=nodes.new('ShaderNodeValToRGB'); hr.name=AEF97_HAIR_PREFIX+'Highlight Band'; hr.label='V9.7 • Graphic hair highlight'; hr.location=(final.location.x-760,final.location.y-430)
    hr.color_ramp.interpolation='CONSTANT'
    he=hr.color_ramp.elements
    he[0].position=style['facing1']-0.04; he[0].color=(0,0,0,1)
    he[1].position=min(0.995,style['facing1']+0.035); he[1].color=(1,1,1,1)
    links.new(lw.outputs['Facing'],hr.inputs['Fac'])
    hm=nodes.new('ShaderNodeMath'); hm.name=AEF97_HAIR_PREFIX+'Highlight Strength'; hm.label='V9.7 • Highlight strength'; hm.operation='MULTIPLY'; hm.location=(final.location.x-440, final.location.y-430)
    hm.inputs[1].default_value=highlight_strength * float(style.get('highlight_gain', (1.20 if profile=='AVE' else 1.0)))
    links.new(hr.outputs['Color'], hm.inputs[0])

    high=nodes.new('ShaderNodeMixRGB'); high.name=AEF97_HAIR_PREFIX+'Highlight Add'; high.label='V9.7 • Hair highlight'; high.blend_type='ADD'; high.location=(final.location.x-260,final.location.y-110)
    links.new(mult.outputs['Color'],high.inputs['Color1'])
    high.inputs['Color2'].default_value=style['highlight']
    links.new(hm.outputs['Value'],high.inputs['Fac'])

    # Preserve the image-derived color as the first-order signal while making
    # the hair materially quieter than a conventional PBR response.
    for lk in list(base.links): links.remove(lk)
    links.new(high.outputs['Color'],base)

    # Principled tuning: avoid plastic/specular hair while keeping a soft edge response.
    for sock_name,val in (
        ('Roughness',float(style.get('roughness', 0.72 if profile=='MYGO' else 0.66))),
        ('Specular IOR Level',float(style.get('specular', 0.18 if profile=='MYGO' else 0.22))),
        ('Metallic',0.0),
    ):
        sock=final.inputs.get(sock_name)
        if sock and not sock.is_linked:
            sock.default_value=val
    sheen=final.inputs.get('Sheen Weight')
    if sheen and not sheen.is_linked:
        sheen.default_value=float(style.get('sheen', 0.035 if profile=='MYGO' else 0.055))
    aniso=final.inputs.get('Anisotropic')
    if aniso and not aniso.is_linked:
        aniso.default_value=0.0

    after=_aef97_image_sig(group)
    if before!=after:
        # Restore the underlying source and remove only our nodes.
        _aef97_remove_old_chain(group)
        raise RuntimeError(f"V9.7 safety check FAILED: Image Texture links changed on {group.name}")
    group['AEF_V9_7_HairToon']=True
    group['AEF_V9_7_Profile']=profile
    group['AEF_V9_7_ToonStrength']=toon_strength
    group['AEF_V9_7_HighlightStrength']=highlight_strength
    return True, f"hair toon + broad band + graphic highlight (toon={toon_strength:.2f}, hi={highlight_strength:.2f})"


def build_v97_hair_toon_system(settings):
    if not getattr(settings,'build_hair_toon_design',True):
        return 0
    profile=getattr(settings,'shot_profile','AVE')
    toon_strength=getattr(settings,'hair_toon_strength',0.72)
    highlight_strength=getattr(settings,'hair_highlight_strength',0.16)
    base_style = AEF97_HAIR_STYLE.get(profile, AEF97_HAIR_STYLE['AVE'])
    style_override = None
    if getattr(settings, 'build_series_match_v108a', True):
        hair_t = getattr(settings, 'hair_series_match_strength', 0.70)
        target = AEF108A_HAIR_TARGET.get(profile)
        if target:
            toon_strength = _aef108a_mix_scalar(toon_strength, target.get('toon_strength', toon_strength), hair_t)
            highlight_strength = _aef108a_mix_scalar(highlight_strength, target.get('highlight_strength', highlight_strength), hair_t)
            style_override = _aef108a_blend_style(base_style, target, hair_t)
    count=0
    prefix='AEF_V8_'
    for obj in bpy.context.scene.objects:
        if obj.type!='MESH':
            continue
        for slot in obj.material_slots:
            mat=slot.material
            if not mat or not mat.name.startswith(prefix):
                continue
            if mat.get('AEF_V8_Category')!='hair':
                break
            gn=mat.node_tree.nodes.get('XDZR8_V8') if getattr(mat,'use_nodes',False) else None
            group=gn.node_tree if gn else None
            if group:
                try:
                    local_toon = toon_strength
                    local_hi = highlight_strength
                    local_style = dict(style_override) if style_override else dict(base_style)
                    character = _aef108a_character_from_material(mat.name)
                    char_target, char_t = _aef108a1_hair_character_target(profile, character, settings)
                    if char_target and char_t > 0.0:
                        local_toon = _aef108a_mix_scalar(local_toon, char_target.get('toon_strength', local_toon), char_t)
                        local_hi = _aef108a_mix_scalar(local_hi, char_target.get('highlight_strength', local_hi), char_t)
                        local_style = _aef108a_blend_style(local_style, char_target, char_t)
                    g_target, g_t = _aef108b_hair_target(profile, settings)
                    if g_target and g_t > 0.0:
                        local_toon = _aef108a_mix_scalar(local_toon, g_target.get('toon_strength', local_toon), g_t)
                        local_hi = _aef108a_mix_scalar(local_hi, g_target.get('highlight_strength', local_hi), g_t)
                        local_style = _aef108a_blend_style(local_style, g_target, g_t)
                    b1_target, b1_t = _aef108b1_hair_character_target(profile, character, settings)
                    if b1_target and b1_t > 0.0:
                        local_toon = _aef108a_mix_scalar(local_toon, b1_target.get('toon_strength', local_toon), b1_t)
                        local_hi = _aef108a_mix_scalar(local_hi, b1_target.get('highlight_strength', local_hi), b1_t)
                        local_style = _aef108a_blend_style(local_style, b1_target, b1_t)
                    c1_target, c1_t = _aef108c1_hair_character_target(profile, character, settings)
                    if c1_target and c1_t > 0.0:
                        local_toon = _aef108a_mix_scalar(local_toon, c1_target.get('toon_strength', local_toon), c1_t)
                        local_hi = _aef108a_mix_scalar(local_hi, c1_target.get('highlight_strength', local_hi), c1_t)
                        local_style = _aef108a_blend_style(local_style, c1_target, c1_t)
                    final_target, final_t = _aef109c1_hair_character_target(profile, character, settings)
                    if final_target and final_t > 0.0:
                        local_toon = _aef108a_mix_scalar(local_toon, final_target.get('toon_strength', local_toon), final_t)
                        local_hi = _aef108a_mix_scalar(local_hi, final_target.get('highlight_strength', local_hi), final_t)
                        local_style = _aef108a_blend_style(local_style, final_target, final_t)
                    ok,_=_aef97_apply_hair_toon(group,profile,local_toon,local_hi,local_style)
                    if ok: count+=1
                except Exception as exc:
                    log(f'V9.7 Hair Toon {obj.name}: {exc}')
            break
    scene=bpy.context.scene
    scene['AEF_V9_7_HairToonCount']=count
    scene['AEF_V9_7_HairToonStrength']=float(toon_strength)
    scene['AEF_V9_7_HairHighlightStrength']=float(highlight_strength)
    scene['AEF_V9_7_ShotProfile']=profile
    scene['AEF_V10_8A_HairMatchStrength']=float(getattr(settings, 'hair_series_match_strength', 0.70) if getattr(settings, 'build_series_match_v108a', True) else 0.0)
    scene['AEF_V10_8A1_OblivionisHairRibbon']=float(getattr(settings, 'oblivionis_hair_ribbon_v108a1', 0.66) if getattr(settings, 'build_character_micro_tune_v108a1', True) else 0.0)
    scene['AEF_V10_8B_HairGraphicSeparation']=float(getattr(settings, 'hair_graphic_separation_strength_v108b', 0.60) if getattr(settings, 'build_graphic_separation_v108b', True) else 0.0)
    scene['AEF_V10_8B1_OblivionisHairBalance']=float(getattr(settings, 'oblivionis_hair_balance_v108b1', 0.58) if getattr(settings, 'build_graphic_separation_refinement_v108b1', True) else 0.0)
    scene['AEF_V10_8B1_ClothBlackRebalance']=float(getattr(settings, 'cloth_black_rebalance_v108b1', 0.18) if getattr(settings, 'build_graphic_separation_refinement_v108b1', True) else 0.0)
    scene['AEF_V10_8B1_TransparentCleanup']=float(getattr(settings, 'transparent_cleanup_v108b1', 0.22) if getattr(settings, 'build_graphic_separation_refinement_v108b1', True) else 0.0)
    scene['AEF_V10_8B2_TransparencyDepth']=float(getattr(settings, 'transparency_depth_v108b2', 0.20) if getattr(settings, 'build_transparency_dark_balance_v108b2', True) else 0.0)
    scene['AEF_V10_8B2_TransparencyChroma']=float(getattr(settings, 'transparency_chroma_preserve_v108b2', 0.18) if getattr(settings, 'build_transparency_dark_balance_v108b2', True) else 0.0)
    scene['AEF_V10_8B2_DarkClothDepth']=float(getattr(settings, 'dark_cloth_depth_v108b2', 0.14) if getattr(settings, 'build_transparency_dark_balance_v108b2', True) else 0.0)
    scene['AEF_V10_8B2_AccentProtection']=float(getattr(settings, 'accent_protection_v108b2', 0.12) if getattr(settings, 'build_transparency_dark_balance_v108b2', True) else 0.0)
    scene['AEF_V10_9C1_DolorisHairFinal']=float(getattr(settings, 'doloris_hair_match_final_v109c1', 0.38) if getattr(settings, 'build_face_hair_series_match_final_v109c1', True) else 0.0)
    scene['AEF_V10_9C1_OblivionisHairFinal']=float(getattr(settings, 'oblivionis_hair_match_final_v109c1', 0.22) if getattr(settings, 'build_face_hair_series_match_final_v109c1', True) else 0.0)
    scene['AEF_V10_8C_DarkMassLock']=float(getattr(settings, 'dark_mass_lock_v108c', 0.16) if getattr(settings, 'build_series_lock_v108c', True) else 0.0)
    scene['AEF_V10_8C_TransparencySeriesLock']=float(getattr(settings, 'transparency_series_lock_v108c', 0.18) if getattr(settings, 'build_series_lock_v108c', True) else 0.0)
    scene['AEF_V10_8C_InnerSkirtBalance']=float(getattr(settings, 'inner_skirt_balance_v108c', 0.16) if getattr(settings, 'build_series_lock_v108c', True) else 0.0)
    scene['AEF_V10_8C_TrimHold']=float(getattr(settings, 'trim_hold_v108c', 0.14) if getattr(settings, 'build_series_lock_v108c', True) else 0.0)
    scene['AEF_V10_8C1_DolorisClothSeparation']=float(getattr(settings, 'doloris_cloth_separation_v108c1', 0.18) if getattr(settings, 'build_final_micro_polish_v108c1', True) else 0.0)
    scene['AEF_V10_8C1_TransparencyRedHold']=float(getattr(settings, 'transparency_red_hold_v108c1', 0.22) if getattr(settings, 'build_final_micro_polish_v108c1', True) else 0.0)
    scene['AEF_V10_8C1_OblivionisSkirtContain']=float(getattr(settings, 'oblivionis_skirt_contain_v108c1', 0.24) if getattr(settings, 'build_final_micro_polish_v108c1', True) else 0.0)
    scene['AEF_V10_8C1_OblivionisCorsetCompact']=float(getattr(settings, 'oblivionis_corset_compact_v108c1', 0.16) if getattr(settings, 'build_final_micro_polish_v108c1', True) else 0.0)
    scene['AEF_V10_8C1_OblivionisHairMicroTune']=float(getattr(settings, 'oblivionis_hair_microtune_v108c1', 0.12) if getattr(settings, 'build_final_micro_polish_v108c1', True) else 0.0)
    scene['AEF_V10_8C2_ViewConsistency']=float(getattr(settings, 'view_consistency_v108c2', 0.12) if getattr(settings, 'build_final_lock_v108c2', True) else 0.0)
    scene['AEF_V10_8C2_BlackMidtoneLock']=float(getattr(settings, 'black_midtone_lock_v108c2', 0.12) if getattr(settings, 'build_final_lock_v108c2', True) else 0.0)
    scene['AEF_V10_8C2_TransparencyEdgeHold']=float(getattr(settings, 'transparency_edge_hold_v108c2', 0.14) if getattr(settings, 'build_final_lock_v108c2', True) else 0.0)
    scene['AEF_V10_8C2_GoldTrimBalance']=float(getattr(settings, 'gold_trim_balance_v108c2', 0.10) if getattr(settings, 'build_final_lock_v108c2', True) else 0.0)
    return count


def _aef95_set_lineart_enabled(char_name, enabled):
    """Toggle the existing V9 Grease Pencil receiver without altering source
    meshes, Image Texture nodes, UVs or XDZR8 material routes."""
    gp = bpy.data.objects.get(f"AEF V9 • LineArt • {char_name}")
    if not gp or gp.type != 'GREASEPENCIL':
        return False
    gp.hide_viewport = not bool(enabled)
    gp.hide_render = not bool(enabled)
    gp['AEF_V9_5_CalibrationLineArtEnabled'] = bool(enabled)
    return True


def build_v95_calibration_system(settings):
    """V9.5 deterministic A/B visual calibration.

    The base XDZR8 material rebuild is unchanged. This mode only decides which
    optional artistic layers are evaluated, so their visual contribution can
    be compared without changing texture routes or UVs.
    """
    if not settings.calibration_mode:
        return None

    face = hair = shadow = lines = tertiary = 0

    if settings.calibration_face:
        # Foundational face correctors first, then angle-driven and performance layers.
        if settings.build_face_corrections:
            face += build_v91_face_corrections('Doloris')
            face += build_v91_face_corrections('Oblivionis')
        face += build_v92_face_angle('Doloris', settings)
        face += build_v92_face_angle('Oblivionis', settings)
        face += build_v94_face_performance('Doloris', settings)
        face += build_v94_face_performance('Oblivionis', settings)
        face += build_v94_expression_corrections('Doloris', settings)
        face += build_v94_expression_corrections('Oblivionis', settings)

    if settings.calibration_hair:
        hair += build_v93_hair_ribbon('Doloris', settings.shot_profile)
        hair += build_v93_hair_ribbon('Oblivionis', settings.shot_profile)

    if settings.calibration_shadow:
        shadow += build_v92_artistic_lighting('Doloris', settings.shot_profile)
        shadow += build_v92_artistic_lighting('Oblivionis', settings.shot_profile)

    if settings.calibration_lines and not _aef105a1_lineart_is_quarantined():
        lines += build_v92_line_hierarchy('Doloris')
        lines += build_v92_line_hierarchy('Oblivionis')
        lines += build_v94_smart_line_art('Doloris', settings)
        lines += build_v94_smart_line_art('Oblivionis', settings)
        _aef95_set_lineart_enabled('Doloris', True)
        _aef95_set_lineart_enabled('Oblivionis', True)
    else:
        # V10.5A.1: do not re-enable a receiver with LINEART while testing cloth.
        _aef95_set_lineart_enabled('Doloris', False)
        _aef95_set_lineart_enabled('Oblivionis', False)

    # Tertiary is off by default: it is authored shot content, not calibration.
    if settings.calibration_tertiary:
        tertiary += build_v93_tertiary_artist('Doloris', settings)
        tertiary += build_v93_tertiary_artist('Oblivionis', settings)

    scene = bpy.context.scene
    scene['AEF_V9_5_CalibrationMode'] = True
    scene['AEF_V9_5_CalibrationFace'] = bool(settings.calibration_face)
    scene['AEF_V9_5_CalibrationHair'] = bool(settings.calibration_hair)
    scene['AEF_V9_5_CalibrationShadows'] = bool(settings.calibration_shadow)
    scene['AEF_V9_5_CalibrationLines'] = bool(settings.calibration_lines)
    scene['AEF_V9_5_CalibrationTertiary'] = bool(settings.calibration_tertiary)
    return {'face': face, 'hair': hair, 'shadow': shadow, 'lines': lines, 'tertiary': tertiary}


# =====================================================================
# V10 — SHOT COMPOSER / FINAL LOOK
# ---------------------------------------------------------------------
# Capa final de composición. No sustituye Face/Hair/Line Art/Tertiary:
# recibe el render ya terminado y lo conduce por un único acabado por plano.
#
# Pipeline:
#   RENDER LAYERS
#       -> V9.1 grade + selective bloom
#       -> exposure / contrast / saturation
#       -> optional depth grade
#       -> soft vignette
#       -> V10 FINAL OUTPUT
#
# Seguridad:
#   - No toca Image Texture, UV, meshes ni materiales.
#   - Solo crea/reconecta nodos del Compositor.
#   - Conserva los nodos V9.1 y los usa como entrada.
# =====================================================================
AEF10_PREFIX = "AEF V10 • Shot Composer • "
AEF10_STYLE = {
    "MYGO": {
        "contrast": 0.025,
        "saturation": 0.985,
        "bloom": 0.060,
        "threshold": 1.30,
        "vignette": 0.055,
        "depth": 0.035,
    },
    "AVE": {
        "contrast": 0.065,
        "saturation": 0.970,
        "bloom": 0.095,
        "threshold": 1.18,
        "vignette": 0.085,
        "depth": 0.050,
    },
    "UNIVERSAL": {
        "contrast": 0.040,
        "saturation": 0.980,
        "bloom": 0.080,
        "threshold": 1.25,
        "vignette": 0.060,
        "depth": 0.040,
    },
}


def _aef10_tree(scene):
    tree = getattr(scene, 'compositing_node_group', None)
    if tree is None:
        tree = bpy.data.node_groups.new(
            name=f"AEF V10 • Compositor • {scene.name}",
            type='CompositorNodeTree'
        )
        scene.compositing_node_group = tree
    return tree


def _aef10_remove_generated_nodes(tree):
    for node in list(tree.nodes):
        if node.name.startswith(AEF10_PREFIX):
            tree.nodes.remove(node)


def _aef10_socket(node, name):
    return node.inputs.get(name) if node else None


def _aef10_set(node, name, value):
    sock = _aef10_socket(node, name)
    if sock is None:
        return False
    try:
        sock.default_value = value
        return True
    except (TypeError, ValueError):
        return False


def _aef10_find_v91_glare(tree):
    return tree.nodes.get("AEF V9.1 • Shoot • Selective Bloom")


def _aef10_find_v91_output(tree):
    # V11.1.3: generic scenes do not necessarily contain the old V9.1 node.
    # Reuse V10's canonical output when present so later grade stages do not
    # create a second, disconnected Group Output.
    return (tree.nodes.get("AEF V9.1 • Shoot • Group Output")
            or tree.nodes.get(AEF10_PREFIX + 'Group Output')
            or tree.nodes.get("Group Output"))


def _aef10_build_vignette(tree, image_socket, final_node, strength):
    # A large soft ellipse becomes a gentle multiply mask.  The center remains
    # untouched, while the frame edges are progressively darkened.
    ellipse = tree.nodes.new('CompositorNodeEllipseMask')
    ellipse.name = AEF10_PREFIX + 'Vignette Mask'
    ellipse.label = 'V10 • Soft vignette mask'
    ellipse.location = (final_node.location.x - 250, final_node.location.y - 430)
    _aef10_set(ellipse, 'Width', 0.92)
    _aef10_set(ellipse, 'Height', 0.86)

    blur = tree.nodes.new('CompositorNodeBlur')
    blur.name = AEF10_PREFIX + 'Vignette Blur'
    blur.label = 'V10 • Vignette feather'
    blur.location = (ellipse.location.x + 180, ellipse.location.y)
    _aef10_set(blur, 'Size X', 18)
    _aef10_set(blur, 'Size Y', 18)

    # Blender 5.1: CompositorNodeMixRGB is unavailable, but ShaderNodeMixRGB
    # can be instantiated in the compositor tree and keeps the classic
    # Fac/Color1/Color2 -> Color interface used by this pipeline.
    mix = tree.nodes.new('ShaderNodeMixRGB')
    mix.name = AEF10_PREFIX + 'Vignette Mix'
    mix.label = 'V10 • Final vignette'
    mix.blend_type = 'MULTIPLY'
    mix.location = (final_node.location.x + 220, final_node.location.y - 120)
    # Strength is represented by Color2: 1=no darkening, lower=more darkening.
    amount = max(0.0, min(0.5, float(strength)))
    mix.inputs['Color2'].default_value = (1.0 - amount, 1.0 - amount, 1.0 - amount, 1.0)

    links = tree.links
    links.new(ellipse.outputs.get('Mask'), blur.inputs.get('Image'))
    links.new(image_socket, mix.inputs.get('Color1'))
    links.new(blur.outputs.get('Image'), mix.inputs.get('Fac'))
    return mix


def build_v10_shot_composer(settings):
    if not getattr(settings, 'build_shot_composer', True):
        return 0

    scene = bpy.context.scene
    tree = _aef10_tree(scene)
    nodes, links = tree.nodes, tree.links
    profile = getattr(settings, 'shot_profile', 'AVE')
    style = AEF10_STYLE.get(profile, AEF10_STYLE['AVE'])
    _aef10_remove_generated_nodes(tree)

    # Reuse V9.1's compositor as the artistic input whenever present.
    source_node = _aef10_find_v91_glare(tree)
    if source_node is None:
        source_node = nodes.get('Render Layers')
    if source_node is None:
        source_node = nodes.new(type='CompositorNodeRLayers')
        source_node.name = 'Render Layers'
        source_node.scene = scene

    source_socket = source_node.outputs.get('Image')
    if source_socket is None:
        return 0

    exposure = nodes.new('CompositorNodeExposure')
    exposure.name = AEF10_PREFIX + 'Exposure'
    exposure.label = f'V10 • Exposure ({profile})'
    exposure.location = (0, 0)
    _aef10_set(exposure, 'Exposure', float(settings.final_exposure))

    contrast = nodes.new('CompositorNodeBrightContrast')
    contrast.name = AEF10_PREFIX + 'Contrast'
    contrast.label = 'V10 • Graphic contrast'
    contrast.location = (220, 0)
    _aef10_set(contrast, 'Bright', 0.0)
    _aef10_set(contrast, 'Contrast', float(settings.final_contrast if settings.final_contrast is not None else style['contrast']))

    hue = nodes.new('CompositorNodeHueSat')
    hue.name = AEF10_PREFIX + 'Saturation'
    hue.label = 'V10 • Saturation'
    hue.location = (440, 0)
    _aef10_set(hue, 'Hue', 0.5)
    _aef10_set(hue, 'Saturation', float(settings.final_saturation if settings.final_saturation is not None else style['saturation']))
    _aef10_set(hue, 'Value', 1.0)

    final_glare = nodes.new('CompositorNodeGlare')
    final_glare.name = AEF10_PREFIX + 'Final Glow'
    final_glare.label = 'V10 • Selective Glow'
    final_glare.location = (660, 0)
    _aef10_set(final_glare, 'Type', 'Fog Glow')
    _aef10_set(final_glare, 'Quality', 'High')
    _aef10_set(final_glare, 'Threshold', float(settings.final_bloom_threshold if settings.final_bloom_threshold is not None else style['threshold']))
    _aef10_set(final_glare, 'Size', 0.65)
    _aef10_set(final_glare, 'Strength', float(settings.final_bloom_strength if settings.final_bloom_strength is not None else style['bloom']))

    # Optional, restrained depth grade. It deliberately acts as a low-strength
    # atmospheric blend rather than depth-of-field, so it remains safe for an
    # anime/CG read and does not blur the line art.
    previous_socket = final_glare.outputs.get('Image')
    depth_mix = None
    if bool(getattr(settings, 'final_depth_grade', False)):
        rl = nodes.get('Render Layers')
        if rl is None:
            rl = nodes.new(type='CompositorNodeRLayers')
            rl.name = 'Render Layers'
            rl.scene = scene
        z = rl.outputs.get('Depth') or rl.outputs.get('Z')
        if z is not None:
            depth = nodes.new('CompositorNodeMapRange')
            depth.name = AEF10_PREFIX + 'Depth Mask'
            depth.label = 'V10 • Depth grade mask'
            depth.location = (650, -240)
            _aef10_set(depth, 'From Min', 2.0)
            _aef10_set(depth, 'From Max', 25.0)
            _aef10_set(depth, 'To Min', 0.0)
            _aef10_set(depth, 'To Max', 1.0)
            _aef10_set(depth, 'Clamp', True)
            links.new(z, depth.inputs.get('Value'))

            depth_strength = max(0.0, min(0.5, float(settings.final_depth_strength)))
            depth_weight = nodes.new('ShaderNodeMath')
            depth_weight.name = AEF10_PREFIX + 'Depth Strength'
            depth_weight.label = 'V10 • Depth strength'
            depth_weight.operation = 'MULTIPLY'
            depth_weight.location = (820, -300)
            _aef10_set(depth_weight, 'Value', depth_strength)
            links.new(depth.outputs.get('Value'), depth_weight.inputs.get('Value'))

            # Blender 5.1: use ShaderNodeMixRGB in the compositor tree.
            depth_mix = nodes.new('ShaderNodeMixRGB')
            depth_mix.name = AEF10_PREFIX + 'Depth Grade'
            depth_mix.label = 'V10 • Subtle depth tint'
            depth_mix.blend_type = 'MIX'
            depth_mix.location = (1040, -120)
            depth_mix.inputs['Color2'].default_value = (0.72, 0.77, 0.90, 1.0)
            links.new(previous_socket, depth_mix.inputs['Color1'])
            links.new(depth_weight.outputs.get('Value'), depth_mix.inputs['Fac'])
            previous_socket = depth_mix.outputs.get('Color')

    # Vignette follows the final glow/depth stage.
    vignette = _aef10_build_vignette(tree, previous_socket, final_glare, float(settings.final_vignette))
    previous_socket = vignette.outputs.get('Color')

    # Find/create the compositor Group Output socket used by Blender 5.x.
    group_out = _aef10_find_v91_output(tree)
    if group_out is None:
        group_out = nodes.new(type='NodeGroupOutput')
        group_out.name = AEF10_PREFIX + 'Group Output'
        group_out.location = (1280, 0)

    out_socket = group_out.inputs.get('Image')
    if out_socket is None:
        return 0

    # Disconnect only incoming links to the final output; V9.1 nodes remain.
    for lk in list(out_socket.links):
        links.remove(lk)

    # Disconnect any stale V10 links into the V10 processing nodes.
    for node in (exposure, contrast, hue, final_glare, group_out):
        for lk in list(links):
            if lk.to_node == node:
                links.remove(lk)

    links.new(source_socket, exposure.inputs.get('Image'))
    links.new(exposure.outputs.get('Image'), contrast.inputs.get('Image'))
    links.new(contrast.outputs.get('Image'), hue.inputs.get('Image'))
    links.new(hue.outputs.get('Image'), final_glare.inputs.get('Image'))
    if depth_mix is not None:
        # final_glare remains the glow input; depth_mix receives the glow output.
        pass
    links.new(previous_socket, out_socket)

    scene['AEF_V10_ShotComposer'] = True
    scene['AEF_V10_Profile'] = profile
    scene['AEF_V10_Exposure'] = float(settings.final_exposure)
    scene['AEF_V10_Contrast'] = float(settings.final_contrast)
    scene['AEF_V10_Saturation'] = float(settings.final_saturation)
    scene['AEF_V10_BloomStrength'] = float(settings.final_bloom_strength)
    scene['AEF_V10_BloomThreshold'] = float(settings.final_bloom_threshold)
    scene['AEF_V10_DepthGrade'] = bool(settings.final_depth_grade)
    scene['AEF_V10_DepthStrength'] = float(settings.final_depth_strength)
    scene['AEF_V10_Vignette'] = float(settings.final_vignette)
    scene['AEF_V10_Workflow'] = 'Character + Line Art + Tertiary + Depth + Color Grade + Selective Glow + Final'

    scene.render.use_compositing = True
    return 1



# =====================================================================
# V10.9C2 — FINAL ANIME COMPOSITE / SERIES GRADE
# ---------------------------------------------------------------------
# Capa final de acabado sobre V10 Shot Composer. No toca materiales, UV,
# Image Texture, geometría, cámara ni luces: solo recompone la salida ya
# aprobada con un lenguaje más cercano a un frame de Ave Mujica / MyGO!!.
#
# Objetivos:
#   - bajar la sensación de viewport CG demasiado uniforme;
#   - suavizar highlights con difusión mínima, sin lavar el linework;
#   - relajar la entrada en negros para evitar un contraste demasiado duro;
#   - compactar un poco la cohesión cromática del frame;
#   - mantener dos perfiles: MYGO (más suave) y AVE (más teatral).
# =====================================================================
AEF109C2_PREFIX = "AEF V10.9C2 • Final Anime Composite • "
AEF109C2_STYLE = {
    "MYGO": {
        "strength": 0.42,
        "soft": 0.30,
        "black": 0.16,
        "halation": 0.05,
        "threshold": 1.34,
        "chroma": 0.10,
        "vignette": 0.035,
        "contrast": 0.018,
        "gamma": 1.018,
        "saturation": 0.995,
    },
    "AVE": {
        "strength": 0.66,
        "soft": 0.46,
        "black": 0.24,
        "halation": 0.11,
        "threshold": 1.20,
        "chroma": 0.20,
        "vignette": 0.070,
        "contrast": 0.040,
        "gamma": 1.040,
        "saturation": 0.975,
    },
    "UNIVERSAL": {
        "strength": 0.52,
        "soft": 0.34,
        "black": 0.18,
        "halation": 0.070,
        "threshold": 1.26,
        "chroma": 0.14,
        "vignette": 0.045,
        "contrast": 0.028,
        "gamma": 1.024,
        "saturation": 0.985,
    },
}

AEF109C24_STYLE = {
    "MYGO": {
        "strength": 0.38,
        "soft": 0.22,
        "black": 0.12,
        "halation": 0.035,
        "threshold": 1.40,
        "chroma": 0.08,
        "vignette": 0.025,
        "contrast": 0.014,
        "gamma": 1.012,
        "saturation": 0.995,
    },
    "AVE": {
        "strength": 0.60,
        "soft": 0.32,
        "black": 0.18,
        "halation": 0.075,
        "threshold": 1.28,
        "chroma": 0.15,
        "vignette": 0.045,
        "contrast": 0.030,
        "gamma": 1.028,
        "saturation": 0.982,
    },
    "UNIVERSAL": {
        "strength": 0.50,
        "soft": 0.28,
        "black": 0.15,
        "halation": 0.055,
        "threshold": 1.32,
        "chroma": 0.12,
        "vignette": 0.035,
        "contrast": 0.022,
        "gamma": 1.020,
        "saturation": 0.988,
    },
}


def _aef109c24_lerp(a, b, t):
    t = max(0.0, min(1.0, float(t)))
    return float(a) * (1.0 - t) + float(b) * t


def _aef109c24_apply_profile_refinement(settings, p):
    if not bool(getattr(settings, 'build_series_grade_micro_tune_v109c24', True)):
        return dict(p)
    profile = str(p.get('profile', getattr(settings, 'shot_profile', 'AVE')))
    target = AEF109C24_STYLE.get(profile, AEF109C24_STYLE['AVE'])
    t = max(0.0, min(1.0, float(getattr(settings, 'series_grade_micro_tune_strength_v109c24', 1.0))))
    out = dict(p)
    for key in ('strength', 'soft', 'black', 'halation', 'threshold', 'chroma', 'vignette', 'contrast', 'gamma', 'saturation'):
        if key in out and key in target:
            out[key] = _aef109c24_lerp(out[key], target[key], t)
    out['micro_tune'] = t
    return out


def _aef109c2_remove_generated_nodes(tree):
    for node in list(tree.nodes):
        if node.name.startswith(AEF109C2_PREFIX):
            tree.nodes.remove(node)


def _aef109c2_source_socket(tree):
    candidates = [
        (AEF10_PREFIX + 'Vignette Mix', 'Color'),
        (AEF10_PREFIX + 'Depth Grade', 'Color'),
        (AEF10_PREFIX + 'Final Glare', 'Image'),
        (AEF10_PREFIX + 'Hue/Sat', 'Image'),
        ('AEF V9.1 • Shoot • Selective Bloom', 'Image'),
        ('Render Layers', 'Image'),
    ]
    for node_name, sock_name in candidates:
        node = tree.nodes.get(node_name)
        if node is None:
            continue
        sock = node.outputs.get(sock_name)
        if sock is not None:
            return sock
    return None


def _aef109c2_build_vignette(tree, image_socket, anchor_node, strength):
    ellipse = tree.nodes.new('CompositorNodeEllipseMask')
    ellipse.name = AEF109C2_PREFIX + 'Vignette Mask'
    ellipse.label = 'V10.9C2 • Vignette mask'
    ellipse.location = (anchor_node.location.x + 170, anchor_node.location.y - 320)
    _aef10_set(ellipse, 'Width', 0.94)
    _aef10_set(ellipse, 'Height', 0.88)
    # V10.9C2.3 / Blender 5.1: Ellipse Mask uses a vector Size socket.
    try:
        size_sock = ellipse.inputs.get('Size')
        if size_sock is not None:
            size_sock.default_value = (0.94, 0.88)
    except Exception:
        pass

    blur = tree.nodes.new('CompositorNodeBlur')
    blur.name = AEF109C2_PREFIX + 'Vignette Blur'
    blur.label = 'V10.9C2 • Vignette feather'
    blur.location = (ellipse.location.x + 180, ellipse.location.y)
    _aef10_set(blur, 'Size X', 16)
    _aef10_set(blur, 'Size Y', 16)
    # V10.9C2.3 / Blender 5.1: Blur also exposes Size as a vector.
    try:
        blur_size = blur.inputs.get('Size')
        if blur_size is not None:
            blur_size.default_value = (16.0, 16.0)
    except Exception:
        pass

    mix = tree.nodes.new('ShaderNodeMixRGB')
    mix.name = AEF109C2_PREFIX + 'Vignette Mix'
    mix.label = 'V10.9C2 • Final series vignette'
    mix.blend_type = 'MULTIPLY'
    mix.location = (anchor_node.location.x + 420, anchor_node.location.y - 30)
    amount = max(0.0, min(0.5, float(strength)))
    mix.inputs['Color2'].default_value = (1.0 - amount, 1.0 - amount, 1.0 - amount, 1.0)

    links = tree.links
    links.new(ellipse.outputs.get('Mask'), blur.inputs.get('Image'))
    links.new(image_socket, mix.inputs.get('Color1'))
    links.new(blur.outputs.get('Image'), mix.inputs.get('Fac'))
    return mix


def _aef109c2_profile_values(settings):
    profile = getattr(settings, 'shot_profile', 'AVE')
    style = AEF109C2_STYLE.get(profile, AEF109C2_STYLE['AVE'])
    if bool(getattr(settings, 'auto_tune_final_anime_composite_v109c2', True)):
        p = {
            'profile': profile,
            'strength': float(style['strength']),
            'soft': float(style['soft']),
            'black': float(style['black']),
            'halation': float(style['halation']),
            'threshold': float(style['threshold']),
            'chroma': float(style['chroma']),
            'vignette': float(style['vignette']),
            'contrast': float(style['contrast']),
            'gamma': float(style['gamma']),
            'saturation': float(style['saturation']),
        }
        return _aef109c24_apply_profile_refinement(settings, p)
    strength = max(0.0, min(1.0, float(getattr(settings, 'series_grade_strength_v109c2', style['strength']))))
    soft = max(0.0, min(1.0, float(getattr(settings, 'highlight_softness_v109c2', style['soft']))))
    black = max(0.0, min(1.0, float(getattr(settings, 'black_rolloff_v109c2', style['black']))))
    hal = max(0.0, min(1.0, float(getattr(settings, 'halation_strength_v109c2', style['halation']))))
    thr = max(0.0, min(5.0, float(getattr(settings, 'halation_threshold_v109c2', style['threshold']))))
    chr_ = max(0.0, min(1.0, float(getattr(settings, 'chroma_unify_v109c2', style['chroma']))))
    vig = max(0.0, min(0.5, float(getattr(settings, 'composite_vignette_v109c2', style['vignette']))))
    gamma = 1.0 + (0.09 * black * strength)
    contrast = float(style['contrast']) * (0.35 + 0.65 * strength)
    saturation = max(0.0, min(2.0, 1.0 - (0.14 * chr_ * strength)))
    p = {
        'profile': profile,
        'strength': strength,
        'soft': soft,
        'black': black,
        'halation': hal,
        'threshold': thr,
        'chroma': chr_,
        'vignette': vig,
        'contrast': contrast,
        'gamma': gamma,
        'saturation': saturation,
    }
    return _aef109c24_apply_profile_refinement(settings, p)


def build_v109c2_final_anime_composite(settings):
    scene = bpy.context.scene
    if not bool(getattr(settings, 'build_final_anime_composite_v109c2', True)):
        scene['AEF_V10_9C2_Enabled'] = False
        return 0

    tree = _aef10_tree(scene)
    nodes, links = tree.nodes, tree.links
    _aef109c2_remove_generated_nodes(tree)
    source_socket = _aef109c2_source_socket(tree)
    if source_socket is None:
        scene['AEF_V10_9C2_Enabled'] = False
        return 0

    p = _aef109c2_profile_values(settings)

    # Blender 5.1.1 compatibility: CompositorNodeGamma is not available
    # in this compositor tree. Use Bright/Contrast, already supported by this
    # pipeline, to create the same perceptual goal: a tiny shadow lift and
    # gentler black transition without flattening the anime linework.
    black_rolloff = nodes.new('CompositorNodeBrightContrast')
    black_rolloff.name = AEF109C2_PREFIX + 'Black Roll-Off'
    black_rolloff.label = 'V10.9C2.1 • Black roll-off / midtone easing'
    black_rolloff.location = (1450, 240)
    black_lift = max(0.0, min(0.12, 0.028 * p['black'] * p['strength']))
    black_contrast = -max(0.0, min(8.0, 4.5 * p['black'] * p['strength']))
    _aef10_set(black_rolloff, 'Bright', float(black_lift))
    _aef10_set(black_rolloff, 'Contrast', float(black_contrast))

    soften_blur = nodes.new('CompositorNodeBlur')
    soften_blur.name = AEF109C2_PREFIX + 'Highlight Diffusion Blur'
    soften_blur.label = 'V10.9C2.4 • Short highlight diffusion'
    soften_blur.location = (1650, 60)
    blur_px = max(1.0, min(5.0, 1.0 + (3.0 * p['soft'] * p['strength'])))
    _aef10_set(soften_blur, 'Size X', int(round(blur_px)))
    _aef10_set(soften_blur, 'Size Y', int(round(blur_px)))
    # Blender 5.1 compositor exports Blur.Size as a vector socket. C2.4 writes
    # it explicitly so Highlight Softness actually affects the image.
    try:
        size_sock = soften_blur.inputs.get('Size')
        if size_sock is not None:
            size_sock.default_value = (float(blur_px), float(blur_px))
    except Exception:
        pass

    soften_mix = nodes.new('ShaderNodeMixRGB')
    soften_mix.name = AEF109C2_PREFIX + 'Highlight Diffusion Mix'
    soften_mix.label = 'V10.9C2.4 • Line-preserving diffusion'
    soften_mix.blend_type = 'MIX'
    soften_mix.location = (1870, 220)
    soften_mix.inputs['Fac'].default_value = max(0.0, min(1.0, 0.065 * p['soft'] * p['strength']))

    contrast = nodes.new('CompositorNodeBrightContrast')
    contrast.name = AEF109C2_PREFIX + 'Series Contrast'
    contrast.label = 'V10.9C2.4 • Series contrast micro-tune'
    contrast.location = (2080, 220)
    _aef10_set(contrast, 'Bright', 0.008 * p['black'] * p['strength'])
    _aef10_set(contrast, 'Contrast', float(15.0 * p['contrast']))

    hue = nodes.new('CompositorNodeHueSat')
    hue.name = AEF109C2_PREFIX + 'Chroma Cohesion'
    hue.label = 'V10.9C2 • Chroma cohesion'
    hue.location = (2290, 220)
    _aef10_set(hue, 'Saturation', float(p['saturation']))
    _aef10_set(hue, 'Value', 1.0)

    glare = nodes.new('CompositorNodeGlare')
    glare.name = AEF109C2_PREFIX + 'Halation'
    glare.label = 'V10.9C2.4 • Fog Glow halation'
    glare.location = (2500, 70)
    # Blender 5.1 exposes these as sockets in the compositor. Properties alone
    # left the exported node on Streaks/Medium, so C2.4 sets both paths.
    try:
        glare.glare_type = 'FOG_GLOW'
        glare.quality = 'HIGH'
    except Exception:
        pass
    try:
        type_sock = glare.inputs.get('Type')
        if type_sock is not None:
            type_sock.default_value = 'Fog Glow'
        quality_sock = glare.inputs.get('Quality')
        if quality_sock is not None:
            quality_sock.default_value = 'High'
    except Exception:
        pass
    _aef10_set(glare, 'Threshold', float(p['threshold']))
    _aef10_set(glare, 'Highlights Threshold', float(p['threshold']))
    _aef10_set(glare, 'Size', 7.0)
    _aef10_set(glare, 'Strength', max(0.0, min(1.0, 0.42 * p['halation'] * (0.65 + 0.35 * p['strength']))))

    halation_mix = nodes.new('ShaderNodeMixRGB')
    halation_mix.name = AEF109C2_PREFIX + 'Halation Mix'
    halation_mix.label = 'V10.9C2.4 • Restrained halation blend'
    # Glare already outputs the source image plus glow. MIX interpolates only
    # the added glow delta; SCREEN would brighten the base image twice.
    halation_mix.blend_type = 'MIX'
    halation_mix.location = (2720, 220)
    halation_mix.inputs['Fac'].default_value = max(0.0, min(0.35, p['halation'] * (0.55 + 0.25 * p['strength'])))

    vignette = _aef109c2_build_vignette(tree, halation_mix.outputs.get('Color'), halation_mix, float(p['vignette']))

    group_out = _aef10_find_v91_output(tree)
    if group_out is None:
        group_out = nodes.new(type='NodeGroupOutput')
        group_out.name = AEF109C2_PREFIX + 'Group Output'
        group_out.location = (3180, 220)
    out_socket = group_out.inputs.get('Image')
    if out_socket is None:
        scene['AEF_V10_9C2_Enabled'] = False
        return 0

    for lk in list(out_socket.links):
        links.remove(lk)
    # V10.9C2.3: vignette is intentionally excluded. Its helper already
    # wires the real image and feather mask. C2/C2.1/C2.2 erased those links.
    for node in (black_rolloff, soften_blur, soften_mix, contrast, hue, glare, halation_mix, group_out):
        for lk in list(links):
            if lk.to_node == node:
                links.remove(lk)

    links.new(source_socket, black_rolloff.inputs.get('Image'))
    links.new(black_rolloff.outputs.get('Image'), soften_blur.inputs.get('Image'))
    links.new(black_rolloff.outputs.get('Image'), soften_mix.inputs.get('Color1'))
    links.new(soften_blur.outputs.get('Image'), soften_mix.inputs.get('Color2'))
    links.new(soften_mix.outputs.get('Color'), contrast.inputs.get('Image'))
    links.new(contrast.outputs.get('Image'), hue.inputs.get('Image'))
    links.new(hue.outputs.get('Image'), glare.inputs.get('Image'))
    links.new(hue.outputs.get('Image'), halation_mix.inputs.get('Color1'))
    links.new(glare.outputs.get('Image'), halation_mix.inputs.get('Color2'))

    # V10.9C2.3 hard repair. The exported C2.2 tree proved Vignette Mix had
    # no Color1/Fac links, so it evaluated its default mid-grey instead.
    c2_vmask = nodes.get(AEF109C2_PREFIX + 'Vignette Mask')
    c2_vblur = nodes.get(AEF109C2_PREFIX + 'Vignette Blur')
    c2_color1 = vignette.inputs.get('Color1')
    c2_fac = vignette.inputs.get('Fac')
    if c2_color1 is not None:
        for lk in list(c2_color1.links):
            links.remove(lk)
        links.new(halation_mix.outputs.get('Color'), c2_color1)
    if c2_vblur is not None and c2_fac is not None:
        for lk in list(c2_fac.links):
            links.remove(lk)
        links.new(c2_vblur.outputs.get('Image'), c2_fac)
    if c2_vmask is not None and c2_vblur is not None:
        c2_blur_image = c2_vblur.inputs.get('Image')
        if c2_blur_image is not None:
            for lk in list(c2_blur_image.links):
                links.remove(lk)
            links.new(c2_vmask.outputs.get('Mask'), c2_blur_image)

    links.new(vignette.outputs.get('Color'), out_socket)

    scene['AEF_V10_9C2_Enabled'] = True
    scene['AEF_V10_9C2_3_VignetteWiringFixed'] = True
    scene['AEF_V10_9C2_3_VignetteImageLinked'] = bool(c2_color1 is not None and c2_color1.is_linked)
    scene['AEF_V10_9C2_3_VignetteFacLinked'] = bool(c2_fac is not None and c2_fac.is_linked)
    scene['AEF_V10_9C2_Profile'] = str(p['profile'])
    scene['AEF_V10_9C2_AutoTune'] = bool(getattr(settings, 'auto_tune_final_anime_composite_v109c2', True))
    scene['AEF_V10_9C2_Strength'] = float(p['strength'])
    scene['AEF_V10_9C2_HighlightSoftness'] = float(p['soft'])
    scene['AEF_V10_9C2_BlackRollOff'] = float(p['black'])
    scene['AEF_V10_9C2_HalationStrength'] = float(p['halation'])
    scene['AEF_V10_9C2_HalationThreshold'] = float(p['threshold'])
    scene['AEF_V10_9C2_ChromaUnify'] = float(p['chroma'])
    scene['AEF_V10_9C2_Vignette'] = float(p['vignette'])
    scene['AEF_V10_9C2_BlackLift'] = float(black_lift)
    scene['AEF_V10_9C2_BlackContrast'] = float(black_contrast)
    scene['AEF_V10_9C2_CompatFix'] = 'Blender 5.1: BrightContrast replaces unavailable CompositorNodeGamma'
    scene['AEF_V10_9C2_Saturation'] = float(p['saturation'])
    scene['AEF_V10_9C2_4_MicroTuneEnabled'] = bool(getattr(settings, 'build_series_grade_micro_tune_v109c24', True))
    scene['AEF_V10_9C2_4_MicroTuneStrength'] = float(getattr(settings, 'series_grade_micro_tune_strength_v109c24', 1.0))
    scene['AEF_V10_9C2_4_BlurPX'] = float(blur_px)
    scene['AEF_V10_9C2_4_HalationBlend'] = str(halation_mix.blend_type)
    scene['AEF_V10_9C2_Workflow'] = 'V10 base -> black roll-off -> short line-preserving diffusion -> micro contrast/chroma -> Fog Glow MIX halation -> final vignette -> C2.2 MASTER FINAL'
    scene.render.use_compositing = True
    return 1




# =====================================================================
# V10.9C2.2 — FINAL OUTPUT ROUTING / COMPOSITE SINK
# ---------------------------------------------------------------------
# Blender 5.1 usa un CompositorNodeTree con interfaz y NodeGroupOutput en
# lugar del antiguo CompositorNodeComposite. La escena del usuario conserva
# además una rama legacy que alimenta un Viewer mediante un Reroute. El render
# final y el preview podían, por tanto, representar cadenas distintas.
#
# C2.2 NO borra esa rama. Solo crea un único MASTER FINAL SINK y conecta:
#     C2 Final Vignette -> MASTER FINAL -> Group Output (render)
#                                      -> Viewer       (preview)
# Así el Render Result y el Viewer salen de la misma imagen.
# =====================================================================
AEF109C22_PREFIX = "AEF V10.9C2.2 • Final Output • "


def _aef109c22_ensure_output_interface(tree):
    for item in tree.interface.items_tree:
        if getattr(item, 'item_type', None) == 'SOCKET' and getattr(item, 'in_out', None) == 'OUTPUT' and item.name == 'Image':
            return item
    try:
        return tree.interface.new_socket(name='Image', in_out='OUTPUT', socket_type='NodeSocketColor')
    except Exception:
        return None


def _aef109c22_find_final_source(tree):
    candidates = [
        (AEF109C2_PREFIX + 'Vignette Mix', 'Color', 'C2 final vignette'),
        (AEF109C2_PREFIX + 'Halation Mix', 'Color', 'C2 halation fallback'),
        (AEF10_PREFIX + 'Vignette Mix', 'Color', 'V10 final vignette fallback'),
        (AEF10_PREFIX + 'Final Glow', 'Image', 'V10 glow fallback'),
        ('AEF V9.1 • Shoot • Selective Bloom', 'Image', 'V9.1 fallback'),
    ]
    for node_name, socket_name, label in candidates:
        node = tree.nodes.get(node_name)
        if node is None:
            continue
        sock = node.outputs.get(socket_name)
        if sock is not None:
            return sock, label
    return None, 'none'


def _aef109c22_active_group_output(tree):
    _aef109c22_ensure_output_interface(tree)
    outputs = [n for n in tree.nodes if n.bl_idname == 'NodeGroupOutput']

    # Prefer the canonical V9.1/V10 Group Output because the existing compositor
    # builders know this name and can safely reuse/rebuild it on subsequent runs.
    group_out = tree.nodes.get('AEF V9.1 • Shoot • Group Output')
    if group_out is None or group_out.bl_idname != 'NodeGroupOutput':
        group_out = tree.nodes.get('Group Output')
    if group_out is None or group_out.bl_idname != 'NodeGroupOutput':
        for node in outputs:
            if bool(getattr(node, 'is_active_output', False)):
                group_out = node
                break
    if group_out is None and outputs:
        group_out = outputs[0]
    if group_out is None:
        group_out = tree.nodes.new(type='NodeGroupOutput')
        group_out.name = 'AEF V9.1 • Shoot • Group Output'

    try:
        group_out.is_active_output = True
    except Exception:
        pass
    # Keep the canonical name intact for idempotent rebuilds; only the label
    # advertises that C2.2 now owns the final render sink.
    group_out.label = 'V10.9C2.2 • MASTER RENDER OUTPUT'
    group_out.location = (3580, 520)

    # Any extra Group Outputs remain untouched but are explicitly inactive when
    # Blender exposes is_active_output, avoiding ambiguity over the render sink.
    for node in outputs:
        if node == group_out:
            continue
        try:
            node.is_active_output = False
        except Exception:
            pass
    return group_out


def _aef109c22_viewer(tree):
    # Prefer the user's existing Viewer so the backdrop/preview workflow stays intact.
    viewer = tree.nodes.get('Viewer')
    if viewer is None or viewer.bl_idname != 'CompositorNodeViewer':
        viewers = [n for n in tree.nodes if n.bl_idname == 'CompositorNodeViewer']
        viewer = viewers[0] if viewers else None
    if viewer is None:
        try:
            viewer = tree.nodes.new(type='CompositorNodeViewer')
        except Exception:
            return None
    viewer.name = AEF109C22_PREFIX + 'FINAL VIEWER'
    viewer.label = 'V10.9C2.2 • FINAL VIEWER'
    viewer.location = (3580, 300)
    return viewer


def build_v109c22_final_output_routing(settings):
    scene = bpy.context.scene
    if not bool(getattr(settings, 'build_final_output_routing_v109c22', True)):
        scene['AEF_V10_9C2_2_Enabled'] = False
        return {'built': 0, 'source': 'disabled', 'viewer': False, 'group': False, 'links_removed': 0}

    tree = _aef10_tree(scene)
    nodes, links = tree.nodes, tree.links

    # Idempotent cleanup of our previous C2.2 master reroute only. Viewer and
    # Group Output are reused, not deleted.
    for node in list(nodes):
        if node.name.startswith(AEF109C22_PREFIX) and node.bl_idname == 'NodeReroute':
            nodes.remove(node)

    source_socket, source_label = _aef109c22_find_final_source(tree)
    if source_socket is None:
        scene['AEF_V10_9C2_2_Enabled'] = False
        scene['AEF_V10_9C2_2_Source'] = 'none'
        return {'built': 0, 'source': 'none', 'viewer': False, 'group': False, 'links_removed': 0}

    sink = nodes.new('NodeReroute')
    sink.name = AEF109C22_PREFIX + 'MASTER FINAL SINK'
    sink.label = 'V10.9C2.2 • MASTER FINAL SINK'
    sink.location = (3370, 520)
    try:
        sink.socket_idname = 'NodeSocketColor'
    except Exception:
        pass

    group_out = _aef109c22_active_group_output(tree)
    out_socket = group_out.inputs.get('Image') if group_out else None
    if out_socket is None:
        # Interface update may need one more lookup after Group Output activation.
        _aef109c22_ensure_output_interface(tree)
        out_socket = group_out.inputs.get('Image') if group_out else None
    if out_socket is None:
        scene['AEF_V10_9C2_2_Enabled'] = False
        return {'built': 0, 'source': source_label, 'viewer': False, 'group': False, 'links_removed': 0}

    removed = 0
    # Group Output gets exactly one authoritative final input.
    for lk in list(out_socket.links):
        links.remove(lk)
        removed += 1

    viewer = None
    viewer_input = None
    mirror = bool(getattr(settings, 'mirror_final_to_viewer_v109c22', True))
    if mirror:
        viewer = _aef109c22_viewer(tree)
        viewer_input = viewer.inputs.get('Image') if viewer else None
        if viewer_input is not None and bool(getattr(settings, 'quarantine_legacy_viewer_link_v109c22', True)):
            for lk in list(viewer_input.links):
                links.remove(lk)
                removed += 1

    links.new(source_socket, sink.inputs[0])
    links.new(sink.outputs[0], out_socket)
    viewer_routed = False
    if mirror and viewer_input is not None:
        # Even when legacy-disconnect is OFF, make the master final authoritative.
        for lk in list(viewer_input.links):
            links.remove(lk)
            removed += 1
        links.new(sink.outputs[0], viewer_input)
        viewer_routed = True

    scene['AEF_V10_9C2_2_Enabled'] = True
    scene['AEF_V10_9C2_2_Source'] = str(source_label)
    scene['AEF_V10_9C2_2_MasterNode'] = sink.name
    scene['AEF_V10_9C2_2_GroupOutput'] = group_out.name if group_out else ''
    scene['AEF_V10_9C2_2_Viewer'] = viewer.name if viewer_routed and viewer else ''
    scene['AEF_V10_9C2_2_ViewerMirrored'] = bool(viewer_routed)
    scene['AEF_V10_9C2_2_LinksRemoved'] = int(removed)
    scene['AEF_V10_9C2_2_Workflow'] = 'C2 final -> MASTER FINAL SINK -> active Group Output + Viewer'
    scene.render.use_compositing = True
    return {
        'built': 1,
        'source': source_label,
        'viewer': bool(viewer_routed),
        'group': True,
        'links_removed': removed,
    }



# =====================================================================
# V10.9A2 — LIGHTING BALANCE REFINEMENT
# ---------------------------------------------------------------------
# Rig de iluminación por plano, alineado con la cámara activa. No toca
# materiales, UV ni texturas: solo crea/reutiliza luces de escena y un
# target de enfoque para que el plano lea menos "viewport uniforme" y más
# como una decisión de fotografía anime/CG.
# =====================================================================
AEF109_PREFIX = "AEF V10.9A4 • Final Lighting Cleanup • "
AEF109_COLLECTION = "AEF_V10_9A4_FinalLightingCleanup"
AEF109_LEGACY_PREFIXES = (
    "AEF V10.9A • Shot Lighting • ",
    "AEF V10.9A2 • Character Lighting • ",
    "AEF V10.9A3 • Character Light Isolation • ",
)
AEF109_STYLE = {
    "MYGO": {
        "key_energy": 102.0, "fill_ratio": 0.40, "rim_ratio": 0.21, "world": 0.022,
        "key_size": (7.2, 5.4), "fill_size": (8.4, 6.0), "rim_size": (5.8, 4.4),
        "key_color": (1.00, 0.985, 0.96), "fill_color": (0.93, 0.96, 1.00), "rim_color": (0.90, 0.93, 1.00),
        "key_side": -0.24, "fill_side": 0.34, "rim_side": 0.48,
        "key_up": 0.20, "fill_up": 0.08, "rim_up": 0.26,
        "key_depth": 0.52, "fill_depth": 0.40, "rim_depth": -0.18,
    },
    "AVE": {
        "key_energy": 132.0, "fill_ratio": 0.23, "rim_ratio": 0.47, "world": 0.007,
        "key_size": (6.4, 4.8), "fill_size": (7.6, 5.8), "rim_size": (4.8, 3.8),
        "key_color": (1.00, 0.95, 0.91), "fill_color": (0.87, 0.92, 1.00), "rim_color": (0.84, 0.89, 1.00),
        "key_side": -0.36, "fill_side": 0.44, "rim_side": 0.58,
        "key_up": 0.28, "fill_up": 0.12, "rim_up": 0.34,
        "key_depth": 0.58, "fill_depth": 0.44, "rim_depth": -0.22,
    },
}


def _aef109_scene_collection(scene):
    col = bpy.data.collections.get(AEF109_COLLECTION)
    if col is None:
        col = bpy.data.collections.new(AEF109_COLLECTION)
    if not any(c == col for c in scene.collection.children):
        scene.collection.children.link(col)
    return col


def _aef109_link_object(col, obj):
    if obj is not None and col not in obj.users_collection:
        col.objects.link(obj)


def _aef109_quarantine_legacy_rigs():
    disabled = 0
    for obj in bpy.data.objects:
        if obj.type == 'LIGHT' and any(obj.name.startswith(prefix) for prefix in AEF109_LEGACY_PREFIXES):
            try: obj.data.energy = 0.0
            except Exception: pass
            try: obj.hide_render = True
            except Exception: pass
            disabled += 1
    return disabled


def _aef109_active_camera(scene):
    cam = getattr(scene, 'camera', None)
    if cam and cam.type == 'CAMERA': return cam
    for obj in scene.objects:
        if obj.type == 'CAMERA': return obj
    return None


def _aef109_bounds_center(obj):
    try:
        if obj.type == 'MESH' and getattr(obj, 'bound_box', None):
            pts = [obj.matrix_world @ Vector(corner) for corner in obj.bound_box]
            if pts:
                acc = Vector((0.0, 0.0, 0.0))
                for p in pts: acc += p
                return acc / float(len(pts))
    except Exception: pass
    try: return obj.matrix_world.translation.copy()
    except Exception: return Vector((0.0, 0.0, 0.0))


def _aef109_focus_objects_for_character(scene, token):
    out, seen = [], set()
    for obj in scene.objects:
        if obj.type not in {'MESH','ARMATURE','EMPTY','CURVE','SURFACE'}: continue
        key = norm(obj.name)
        good = token in key
        if not good and obj.type == 'MESH':
            for slot in getattr(obj, 'material_slots', []):
                mat = getattr(slot, 'material', None)
                n = getattr(mat, 'name', '') if mat else ''
                if token == 'doloris' and n.startswith('AEF_V8_Doloris_'): good = True; break
                if token == 'oblivionis' and n.startswith('AEF_V8_Oblivionis_'): good = True; break
        if good and obj.name not in seen:
            seen.add(obj.name); out.append(obj)
    return out


def _aef109_render_receivers(objects):
    return [obj for obj in objects if obj.type in {'MESH','CURVE','SURFACE','FONT','META'}]


def _aef109_focus_objects(scene):
    out, seen = [], set()
    for token in ('doloris','oblivionis'):
        for obj in _aef109_focus_objects_for_character(scene, token):
            if obj.name not in seen: seen.add(obj.name); out.append(obj)
    return out


def _aef109_center_from_objects(objs, fallback=None):
    if not objs: return fallback.copy() if fallback is not None else Vector((0,0,0))
    acc = Vector((0.0,0.0,0.0))
    for obj in objs: acc += _aef109_bounds_center(obj)
    return acc / float(len(objs))


def _aef109_focus_center(scene):
    objs = _aef109_focus_objects(scene)
    return _aef109_center_from_objects(objs, fallback=scene.cursor.location)


def _aef109_get_or_create_focus(col, label='Focus Target'):
    name = AEF109_PREFIX + label
    obj = bpy.data.objects.get(name)
    if obj is None or obj.type != 'EMPTY':
        obj = bpy.data.objects.new(name, None); obj.empty_display_type='PLAIN_AXES'; obj.empty_display_size=0.18
    _aef109_link_object(col, obj); obj.hide_render=True
    return obj


def _aef109_get_or_create_area_light(col, short_name):
    name = AEF109_PREFIX + short_name
    obj = bpy.data.objects.get(name)
    if obj is None or obj.type != 'LIGHT':
        data = bpy.data.lights.new(name=name, type='AREA'); obj = bpy.data.objects.new(name, data)
    _aef109_link_object(col, obj)
    try: obj.hide_render=False
    except Exception: pass
    return obj


def _aef109_ensure_track_to(obj, target):
    if obj is None or target is None: return
    con = next((c for c in obj.constraints if c.type=='TRACK_TO' and c.name==(AEF109_PREFIX+'Track To Focus')), None)
    if con is None:
        con = obj.constraints.new('TRACK_TO'); con.name = AEF109_PREFIX+'Track To Focus'
    con.target=target; con.track_axis='TRACK_NEGATIVE_Z'; con.up_axis='UP_Y'


def _aef109_apply_area_settings(light_obj, energy, size_xy, color, softness, diffuse_factor=1.0, specular_factor=1.0, use_shadow=True):
    if light_obj is None or light_obj.type != 'LIGHT': return
    data = light_obj.data; data.type='AREA'
    try: data.shape='RECTANGLE'
    except Exception: pass
    try: data.energy=max(0.0,float(energy))
    except Exception: pass
    try: data.color=tuple(float(c) for c in color[:3])
    except Exception: pass
    try:
        if hasattr(data,'diffuse_factor'): data.diffuse_factor=max(0.0,float(diffuse_factor))
        if hasattr(data,'specular_factor'): data.specular_factor=max(0.0,float(specular_factor))
    except Exception: pass
    sx=float(size_xy[0])*(0.70+0.60*float(softness)); sy=float(size_xy[1])*(0.70+0.60*float(softness))
    if hasattr(data,'size'): data.size=sx
    if hasattr(data,'size_y'): data.size_y=sy
    if hasattr(data,'spread'):
        try: data.spread=math.radians(150.0+20.0*float(softness))
        except Exception: pass
    try: data.use_shadow=bool(use_shadow)
    except Exception: pass


def _aef109_set_world_lift(scene, lift):
    world=scene.world
    if world is None: world=bpy.data.worlds.new('World'); scene.world=world
    world.use_nodes=True; nt=world.node_tree
    if nt is None: return
    bg=nt.nodes.get('Background') or nt.nodes.new('ShaderNodeBackground')
    color=max(0.0,min(0.10,float(lift)))
    try: bg.inputs['Color'].default_value=(color,color,color*1.05,1.0)
    except Exception: pass
    try: bg.inputs['Strength'].default_value=1.0
    except Exception: pass


def _aef109_clear_collection_objects(coll):
    if coll is None: return
    for obj in list(coll.objects):
        try: coll.objects.unlink(obj)
        except Exception: pass


def _aef109_assign_light_linking(light_obj, objects, label):
    receivers=_aef109_render_receivers(objects)
    if not receivers: return False
    try:
        ll=getattr(light_obj,'light_linking',None)
        receiver=getattr(ll,'receiver_collection',None) if ll else None
        if receiver is None and hasattr(bpy.ops.object,'light_linking_receiver_collection_new'):
            try:
                with bpy.context.temp_override(active_object=light_obj, object=light_obj, selected_editable_objects=[light_obj]):
                    bpy.ops.object.light_linking_receiver_collection_new()
                ll=getattr(light_obj,'light_linking',None); receiver=getattr(ll,'receiver_collection',None) if ll else None
            except Exception: receiver=None
        if receiver is None: return False
        try: receiver.name=AEF109_PREFIX+label+' Receivers'
        except Exception: pass
        _aef109_clear_collection_objects(receiver)
        for obj in receivers:
            try: receiver.objects.link(obj)
            except Exception: pass
        return True
    except Exception as exc:
        log(f'V10.9A4 Light Linking fallback for {light_obj.name}: {exc}')
        return False


def _aef109_soft_auto_tune_compositor(settings):
    if not getattr(settings,'auto_tune_shot_composer_v109a',True): return False
    profile=getattr(settings,'shot_profile','AVE')
    if profile=='AVE':
        # V10.9A4: final camera balance. Never raise exposure above A3; let
        # the isolated rig carry the characters and keep bloom restrained.
        settings.final_exposure=min(float(getattr(settings,'final_exposure',0.0)),0.008)
        settings.final_contrast=max(float(getattr(settings,'final_contrast',0.0)),0.05)
        settings.final_saturation=min(float(getattr(settings,'final_saturation',0.98)),0.97)
        settings.final_bloom_strength=min(float(getattr(settings,'final_bloom_strength',0.08)),0.065)
        settings.final_bloom_threshold=max(float(getattr(settings,'final_bloom_threshold',1.25)),1.27)
        settings.final_vignette=max(float(getattr(settings,'final_vignette',0.08)),0.09)
    return True


def build_v109a_shot_lighting(settings):
    if not getattr(settings,'build_shot_lighting_v109a',True): return 0
    scene=bpy.context.scene; cam=_aef109_active_camera(scene)
    if cam is None:
        log('V10.9A4 Final Lighting Cleanup: no active camera found; skipped'); scene['AEF_V10_9A4_ShotLighting']=False; return 0
    legacy_disabled=_aef109_quarantine_legacy_rigs()
    profile=getattr(settings,'shot_profile','AVE'); style=dict(AEF109_STYLE.get(profile,AEF109_STYLE['AVE']))
    key_mult=float(getattr(settings,'key_light_strength_v109a',0.86)); fill_ratio=float(getattr(settings,'fill_ratio_v109a',style['fill_ratio']))
    rim_ratio=float(getattr(settings,'rim_ratio_v109a',style['rim_ratio'])); world_lift=float(getattr(settings,'world_lift_v109a',style['world']))
    softness=max(0.0,min(1.0,float(getattr(settings,'shadow_softness_v109a',0.60))))
    isolate=bool(getattr(settings,'build_character_light_isolation_v109a3',True)); fallback=max(0.0,min(1.0,float(getattr(settings,'isolation_fallback_scale_v109a3',0.25))))
    col=_aef109_scene_collection(scene); focus=_aef109_get_or_create_focus(col,'Focus Target'); df=_aef109_get_or_create_focus(col,'Focus Doloris'); of=_aef109_get_or_create_focus(col,'Focus Oblivionis')
    d_objects=_aef109_focus_objects_for_character(scene,'doloris'); o_objects=_aef109_focus_objects_for_character(scene,'oblivionis')
    center=_aef109_focus_center(scene); dc=_aef109_center_from_objects(d_objects,center); oc=_aef109_center_from_objects(o_objects,center)
    focus.location=center; df.location=dc; of.location=oc
    q=cam.matrix_world.to_quaternion(); forward=(q@Vector((0,0,-1))).normalized(); right=(q@Vector((1,0,0))).normalized(); up=(q@Vector((0,1,0))).normalized()
    dist=max(2.5,min(18.0,(center-cam.matrix_world.translation).length or 6.0)); char_dist=max(1.6,min(8.0,dist*0.58))
    def place(a,d,s,h,b): return a-forward*(b*d)+right*(b*s)+up*(b*h)
    key=_aef109_get_or_create_area_light(col,'Key'); fill=_aef109_get_or_create_area_light(col,'Fill'); rim=_aef109_get_or_create_area_light(col,'Rim')
    key.location=place(center,style['key_depth'],style['key_side'],style['key_up'],dist); fill.location=place(center,style['fill_depth'],style['fill_side'],style['fill_up'],dist); rim.location=place(center,style['rim_depth'],style['rim_side'],style['rim_up'],dist)
    ke=style['key_energy']*key_mult*0.95; fe=style['key_energy']*key_mult*fill_ratio*0.90; re=style['key_energy']*key_mult*rim_ratio*0.95
    _aef109_apply_area_settings(key,ke,style['key_size'],style['key_color'],softness,diffuse_factor=0.94,specular_factor=0.72,use_shadow=True); _aef109_apply_area_settings(fill,fe,style['fill_size'],style['fill_color'],min(1.0,softness+0.08),diffuse_factor=0.90,specular_factor=0.45,use_shadow=False); _aef109_apply_area_settings(rim,re,style['rim_size'],style['rim_color'],max(0.0,softness-0.08),diffuse_factor=0.88,specular_factor=0.58,use_shadow=False)
    d=_aef109_get_or_create_area_light(col,'Doloris Define'); d.location=place(dc,0.03,-0.30,0.16,char_dist); _aef109_apply_area_settings(d,ke*float(getattr(settings,'doloris_local_ratio_v109a3',0.03)),(2.55,2.15),(0.86,0.91,1.0),min(1.0,softness+0.06),diffuse_factor=0.82,specular_factor=0.30,use_shadow=False)
    orc=_aef109_get_or_create_area_light(col,'Oblivionis Recover'); orc.location=place(oc,0.24,0.13,0.18,char_dist); _aef109_apply_area_settings(orc,ke*float(getattr(settings,'oblivionis_recover_ratio_v109a3',0.065)),(2.80,2.40),(0.99,0.97,0.95),min(1.0,softness+0.12),diffuse_factor=0.86,specular_factor=0.34,use_shadow=False)
    osd=_aef109_get_or_create_area_light(col,'Oblivionis Side'); osd.location=place(oc,-0.03,0.31,0.20,char_dist); _aef109_apply_area_settings(osd,ke*float(getattr(settings,'oblivionis_side_ratio_v109a3',0.035)),(2.45,2.05),(0.85,0.90,1.0),max(0.0,softness-0.01),diffuse_factor=0.80,specular_factor=0.38,use_shadow=False)
    for obj,target in ((key,focus),(fill,focus),(rim,focus),(d,df),(orc,of),(osd,of)): _aef109_ensure_track_to(obj,target)
    dl=ol1=ol2=False
    if isolate:
        dl=_aef109_assign_light_linking(d,d_objects,'Doloris'); ol1=_aef109_assign_light_linking(orc,o_objects,'Oblivionis Recover'); ol2=_aef109_assign_light_linking(osd,o_objects,'Oblivionis Side')
        if not dl: d.data.energy*=fallback
        if not ol1: orc.data.energy*=fallback
        if not ol2: osd.data.energy*=fallback
    _aef109_set_world_lift(scene,world_lift); tuned=_aef109_soft_auto_tune_compositor(settings)
    scene['AEF_V10_9A4_ShotLighting']=True; scene['AEF_V10_9A4_LegacyLightsDisabled']=legacy_disabled; scene['AEF_V10_9A4_DolorisLinked']=dl; scene['AEF_V10_9A4_OblivionisRecoverLinked']=ol1; scene['AEF_V10_9A4_OblivionisSideLinked']=ol2
    scene['AEF_V10_9A4_Workflow']='Final cleanup: A3 rig muted, isolated locals reduced, spill/specular guarded, compositor exposure capped'; scene['AEF_V10_9A4_AutoTuneComposer']=bool(tuned)
    return 6


# =====================================================================
# V10.9B — ANIME SHOT / CAMERA MATCH
# ---------------------------------------------------------------------
# Encaja el plano desde la cámara activa ANTES de reconstruir el rig de
# iluminación V10.9A, para que el shot-driven line work/lighting mire ya
# el encuadre final y no una vista provisional de inspección.
# =====================================================================
AEF109B_PREFIX = "AEF V10.9B2 • Narrative Framing Balance • "
AEF109B_COLLECTION = "AEF_V10_9B2_NarrativeFramingBalance"


def _aef109b_scene_collection(scene):
    col = bpy.data.collections.get(AEF109B_COLLECTION)
    if col is None:
        col = bpy.data.collections.new(AEF109B_COLLECTION)
    if not any(c == col for c in scene.collection.children):
        scene.collection.children.link(col)
    return col


def _aef109b_bbox_points(objects):
    pts = []
    for obj in objects:
        try:
            if obj.type == 'MESH' and getattr(obj, 'bound_box', None):
                pts.extend([obj.matrix_world @ Vector(corner) for corner in obj.bound_box])
            else:
                pts.append(_aef109_bounds_center(obj))
        except Exception:
            try: pts.append(obj.matrix_world.translation.copy())
            except Exception: pass
    return pts


def _aef109b_bbox_center(points):
    if not points:
        return Vector((0.0, 0.0, 0.0))
    acc = Vector((0.0, 0.0, 0.0))
    for p in points: acc += p
    return acc / float(len(points))


def _aef109b_is_large_prop(obj):
    key = norm(getattr(obj, 'name', ''))
    return any(tok in key for tok in ('guitar', 'guitarra', 'ギター', 'instrument', 'bass'))


def _aef109b_target_points(objects, ignore_guitar=True):
    selected = []
    for obj in objects:
        if ignore_guitar and _aef109b_is_large_prop(obj):
            continue
        selected.append(obj)
    pts = _aef109b_bbox_points(selected)
    return pts if pts else _aef109b_bbox_points(objects)


def _aef109b_visual_anchor(points, up_axis, upper_bias=0.18):
    if not points:
        return Vector((0.0, 0.0, 0.0))
    center = _aef109b_bbox_center(points)
    vals = [(p - center).dot(up_axis) for p in points]
    height = max(0.10, max(vals) - min(vals)) if vals else 1.0
    return center + up_axis * (height * float(upper_bias))


def _aef109b_get_or_create_focus(col, label='Shot Focus'):
    name = AEF109B_PREFIX + label
    obj = bpy.data.objects.get(name)
    if obj is None or obj.type != 'EMPTY':
        obj = bpy.data.objects.new(name, None)
        obj.empty_display_type = 'SPHERE'
        obj.empty_display_size = 0.12
    _aef109_link_object(col, obj)
    obj.hide_render = True
    return obj


def _aef109b_camera_angles(cam_data):
    ax = float(getattr(cam_data, 'angle_x', 0.0) or 0.0)
    ay = float(getattr(cam_data, 'angle_y', 0.0) or 0.0)
    if ax <= 1e-6 or ay <= 1e-6:
        a = float(getattr(cam_data, 'angle', math.radians(50.0)))
        ax = ay = a
    return max(ax, math.radians(8.0)), max(ay, math.radians(8.0))


def _aef109b_fit_camera(cam, target, points, overscan=1.08, distance_bias=1.0):
    q = cam.matrix_world.to_quaternion()
    right = (q @ Vector((1, 0, 0))).normalized()
    up = (q @ Vector((0, 1, 0))).normalized()
    forward = (q @ Vector((0, 0, -1))).normalized()
    xs, ys, zs = [], [], []
    for p in points:
        d = p - target
        xs.append(d.dot(right)); ys.append(d.dot(up)); zs.append(d.dot(forward))
    if not xs:
        return max(2.0, float(distance_bias) * 4.0)
    width = max(0.12, (max(xs) - min(xs)) * float(overscan))
    height = max(0.12, (max(ys) - min(ys)) * float(overscan))
    depth = max(0.06, (max(zs) - min(zs)))
    ax, ay = _aef109b_camera_angles(cam.data)
    dx = (width * 0.5) / max(0.05, math.tan(ax * 0.5) * 0.86)
    dy = (height * 0.5) / max(0.05, math.tan(ay * 0.5) * 0.74)
    return max(dx, dy) * max(0.70, float(distance_bias)) + depth * 0.55 + 0.22


def _aef109b_auto_tune_compositor(settings):
    if not getattr(settings, 'auto_tune_compositor_v109b', True):
        return False
    profile = getattr(settings, 'shot_profile', 'AVE')
    if profile == 'AVE':
        settings.final_exposure = min(float(getattr(settings, 'final_exposure', 0.0)), 0.000)
        settings.final_contrast = max(float(getattr(settings, 'final_contrast', 0.0)), 0.08)
        settings.final_saturation = min(float(getattr(settings, 'final_saturation', 1.0)), 0.96)
        settings.final_bloom_strength = min(float(getattr(settings, 'final_bloom_strength', 0.08)), 0.050)
        settings.final_bloom_threshold = max(float(getattr(settings, 'final_bloom_threshold', 1.25)), 1.30)
        settings.final_depth_grade = True
        settings.final_depth_strength = max(float(getattr(settings, 'final_depth_strength', 0.06)), 0.08)
        settings.final_vignette = max(float(getattr(settings, 'final_vignette', 0.08)), 0.10)
    else:
        settings.final_exposure = min(float(getattr(settings, 'final_exposure', 0.0)), 0.015)
        settings.final_contrast = max(float(getattr(settings, 'final_contrast', 0.0)), 0.04)
        settings.final_saturation = min(float(getattr(settings, 'final_saturation', 1.0)), 0.98)
        settings.final_bloom_strength = min(float(getattr(settings, 'final_bloom_strength', 0.08)), 0.055)
        settings.final_bloom_threshold = max(float(getattr(settings, 'final_bloom_threshold', 1.25)), 1.22)
        settings.final_vignette = max(float(getattr(settings, 'final_vignette', 0.08)), 0.08)
    return True


def build_v109b_anime_shot_camera_match(settings):
    if not getattr(settings, 'build_anime_shot_camera_match_v109b', True):
        bpy.context.scene['AEF_V10_9B2_CameraMatch'] = False
        return 0
    scene = bpy.context.scene
    cam = _aef109_active_camera(scene)
    if cam is None or cam.type != 'CAMERA':
        log('V10.9B2 Narrative Framing Balance: no active camera found; skipped')
        scene['AEF_V10_9B2_CameraMatch'] = False
        return 0

    col = _aef109b_scene_collection(scene)
    focus = _aef109b_get_or_create_focus(col, 'Shot Focus')
    d_objects = _aef109_focus_objects_for_character(scene, 'doloris')
    o_objects = _aef109_focus_objects_for_character(scene, 'oblivionis')
    objects = d_objects + [obj for obj in o_objects if obj not in d_objects]
    points = _aef109b_bbox_points(objects)
    if not points:
        focus.location = scene.cursor.location.copy()
        log('V10.9B2 Narrative Framing Balance: no focus objects found; skipped')
        scene['AEF_V10_9B2_CameraMatch'] = False
        return 0

    q0 = cam.matrix_world.to_quaternion()
    base_right = (q0 @ Vector((1, 0, 0))).normalized()
    base_up = (q0 @ Vector((0, 1, 0))).normalized()

    # FIT and TARGET are now treated as different things.
    #   - FIT: full-body bounds (including guitar / skirt / feet) remain authoritative.
    #   - TARGET: head+torso anchors drive where the camera actually looks.
    center = _aef109b_bbox_center(points)
    xs = [(p - center).dot(base_right) for p in points]
    ys = [(p - center).dot(base_up) for p in points]
    width = max(0.10, max(xs) - min(xs)) if xs else 1.0
    height = max(0.10, max(ys) - min(ys)) if ys else 1.0

    ignore_guitar = bool(getattr(settings, 'ignore_guitar_for_target_v109b1', True))
    upper_bias = float(getattr(settings, 'upper_body_bias_v109b1', 0.18))
    duo_bias = max(-1.0, min(1.0, float(getattr(settings, 'duo_bias_v109b1', 0.05))))
    char_balance = max(-1.0, min(1.0, float(getattr(settings, 'character_balance_v109b2', -0.10))))
    guitar_weight = max(0.0, min(1.0, float(getattr(settings, 'guitar_framing_weight_v109b2', 0.24))))

    d_target_points = _aef109b_target_points(d_objects, ignore_guitar=ignore_guitar)
    o_target_points = _aef109b_target_points(o_objects, ignore_guitar=True)
    d_anchor = _aef109b_visual_anchor(d_target_points, base_up, upper_bias=upper_bias)
    o_anchor = _aef109b_visual_anchor(o_target_points, base_up, upper_bias=upper_bias)

    if d_target_points and o_target_points:
        # Base balance between both characters. Character Balance is a corrective
        # term against 3/4 drift; Duo Bias remains the artistic nudge.
        o_weight = 0.50 + char_balance * 0.16 + duo_bias * 0.18
        o_weight = max(0.28, min(0.72, o_weight))
        narrative_center = d_anchor.lerp(o_anchor, o_weight)
    elif d_target_points:
        narrative_center = d_anchor
    elif o_target_points:
        narrative_center = o_anchor
    else:
        narrative_center = center

    # Secondary guitar influence: it no longer decides the center, but it may
    # gently nudge the framing so the instrument feels intentionally included.
    if ignore_guitar and d_objects:
        guitar_objects = [obj for obj in d_objects if _aef109b_is_large_prop(obj)]
        if guitar_objects and d_target_points:
            guitar_points = _aef109b_bbox_points(guitar_objects)
            if guitar_points:
                d_body_center = _aef109b_bbox_center(d_target_points)
                guitar_center = _aef109b_bbox_center(guitar_points)
                guitar_offset = guitar_center - d_body_center
                narrative_center = narrative_center + \
                    base_right * (guitar_offset.dot(base_right) * guitar_weight * 0.28) + \
                    base_up * (guitar_offset.dot(base_up) * guitar_weight * 0.08)

    headroom = float(getattr(settings, 'headroom_v109b', 0.10))
    lead = float(getattr(settings, 'lead_room_v109b', 0.0))
    focus_bias = float(getattr(settings, 'focus_height_bias_v109b', 0.15))

    # Slightly calmer bias than B1: the upper-body anchors already do most of
    # the narrative centering, while full-body fit protects limits.
    target = narrative_center + base_right * (lead * width * 0.34) + base_up * ((focus_bias - headroom) * height * 0.14)

    try:
        cam.data.lens = float(getattr(settings, 'lens_mm_v109b', 64.0))
    except Exception:
        pass

    origin = cam.matrix_world.translation.copy()
    view_dir = (target - origin)
    if view_dir.length > 1e-6:
        try:
            cam.rotation_mode = 'XYZ'
            cam.rotation_euler = view_dir.normalized().to_track_quat('-Z', 'Y').to_euler('XYZ')
        except Exception:
            pass

    distance = _aef109b_fit_camera(
        cam, target, points,
        overscan=float(getattr(settings, 'fit_overscan_v109b', 1.045)),
        distance_bias=float(getattr(settings, 'distance_bias_v109b', 0.99)),
    )

    q = cam.matrix_world.to_quaternion()
    forward = (q @ Vector((0, 0, -1))).normalized()
    right = (q @ Vector((1, 0, 0))).normalized()
    up = (q @ Vector((0, 1, 0))).normalized()
    cam.location = target - forward * distance + right * (lead * width * 0.08) + up * (headroom * height * 0.08)

    final_dir = (target - cam.matrix_world.translation.copy())
    if final_dir.length > 1e-6:
        try:
            cam.rotation_mode = 'XYZ'
            cam.rotation_euler = final_dir.normalized().to_track_quat('-Z', 'Y').to_euler('XYZ')
        except Exception:
            pass

    focus.location = target
    try:
        dof = cam.data.dof
        dof.use_dof = bool(getattr(settings, 'enable_dof_v109b', True))
        if dof.use_dof:
            dof.focus_object = focus
            if hasattr(dof, 'aperture_fstop'):
                dof.aperture_fstop = float(getattr(settings, 'dof_fstop_v109b', 4.20))
    except Exception as exc:
        log(f'V10.9B2 DOF setup warning: {exc}')

    tuned = _aef109b_auto_tune_compositor(settings)
    scene['AEF_V10_9B2_CameraMatch'] = True
    scene['AEF_V10_9B2_LensMM'] = float(getattr(settings, 'lens_mm_v109b', 64.0))
    scene['AEF_V10_9B2_Headroom'] = float(getattr(settings, 'headroom_v109b', 0.10))
    scene['AEF_V10_9B2_LeadRoom'] = float(getattr(settings, 'lead_room_v109b', 0.0))
    scene['AEF_V10_9B2_Distance'] = float(distance)
    scene['AEF_V10_9B2_DOF'] = bool(getattr(settings, 'enable_dof_v109b', True))
    scene['AEF_V10_9B2_AutoTuneComposer'] = bool(tuned)
    scene['AEF_V10_9B2_Workflow'] = 'Narrative framing balance: 64mm lens + head/torso duo target + fit-only lower body/props + secondary guitar weight + subtle DOF'
    scene['AEF_V10_9B2_DuoBias'] = float(getattr(settings, 'duo_bias_v109b1', 0.05))
    scene['AEF_V10_9B2_UpperBodyBias'] = float(getattr(settings, 'upper_body_bias_v109b1', 0.18))
    scene['AEF_V10_9B2_CharacterBalance'] = float(getattr(settings, 'character_balance_v109b2', -0.10))
    scene['AEF_V10_9B2_GuitarWeight'] = float(getattr(settings, 'guitar_framing_weight_v109b2', 0.24))
    scene['AEF_V10_9B2_IgnoreGuitarForTarget'] = bool(getattr(settings, 'ignore_guitar_for_target_v109b1', True))
    return 1


class AEF_OT_sabershader_build_v8(bpy.types.Operator):
    bl_idname = "aef.sabershader_build_v8"
    bl_label = "Build Shaders — Final Locked Look"
    bl_description = "Legacy locked-reference builder retained internally for V11 compatibility"
    bl_options = {'REGISTER', 'UNDO'}

    def execute(self, context):
        settings = context.scene.aef_sabershader_v8

        log("=" * 96)
        log("AEF SABERSHADER — XDZR8 V10.9C2.5 UI REORGANIZATION • C2.4 FINAL GRADE LOCK")
        log(f"Blender: {bpy.app.version_string}")
        log(f"File: {bpy.data.filepath}")
        log("=" * 96)

        if not str(bpy.app.version_string).startswith("5.1"):
            self.report({'WARNING'}, f"V9.3 fue diseñada para Blender 5.1.x; detectado {bpy.app.version_string}")

        # V10.5A.1: FIRST ACTION. Remove AEF Line Art modifiers before
        # material rebuilds can invalidate/evaluate the depsgraph. This is a
        # crash quarantine, not a visual feature.
        _aef105a1_quarantine_lineart('before V10.9C2.4 material rebuild')

        restore_guitars_from_v4()
        clean_face_master_contamination()
        fix_face_master_emission_routing()
        # V8.17: old global Glossy rim is no longer added here. The local
        # per-material finisher creates a Fresnel-controlled rim instead.
        protect_master_templates()

        d = process_character("Doloris", DOLORIS, settings.assign_materials)
        o = process_character("Oblivionis", OBLIVIONIS, settings.assign_materials)

        designed_cloth = sum(
            1 for m in bpy.data.materials
            if m and (bool(m.get("AEF_V10_6B_SeriesMatchCloth", False)) or bool(m.get("AEF_V10_6A_SeriesMatchCloth", False)))
        )
        log(f"V10.6C.1 Cloth Final Polish materials: {designed_cloth}")
        transparent_count = sum(
            1 for m in bpy.data.materials
            if m and str(m.get("AEF_V10_6B_Family", "")) == "transparent"
        )
        stockings_count = sum(
            1 for m in bpy.data.materials
            if m and str(m.get("AEF_V10_6B_Family", "")) == "stockings"
        )
        ornament_count = sum(
            1 for m in bpy.data.materials
            if m and str(m.get("AEF_V10_6B_Family", "")) == "ornament"
        )
        accent_count = sum(
            1 for m in bpy.data.materials
            if m and str(m.get("AEF_V10_6B_Family", "")) == "accent"
        )
        smooth_trans_count = sum(1 for m in bpy.data.materials if m and bool(m.get("AEF_V10_6C1_SmoothTransparency", False)))
        log(f"V10.6C.1 families: transparent={transparent_count} stockings={stockings_count} ornament={ornament_count} accent={accent_count} smooth_trans={smooth_trans_count}")

        # V10.5B SAFE: do NOT create/evaluate Grease Pencil LINEART.
        # The user's Blender 5.1.1 crash occurs inside lineart_edge_from_triangle /
        # lineart_occlusion_worker (native C++), so Python try/except cannot catch it.
        line_enabled = False
        outline_d = 0
        outline_o = 0
        _aef95_set_lineart_enabled("Doloris", False)
        _aef95_set_lineart_enabled("Oblivionis", False)
        log("V10.7A.1 SAFE: Blender Line Art OFF / quarantined; using cleaned Safe Silhouette shell outline")
        safe_silhouette_d = 0
        safe_silhouette_o = 0
        safe_silhouette_skip_d = 0
        safe_silhouette_skip_o = 0
        outline_audit_result_v109b31 = None
        internal_obj_d = 0
        internal_obj_o = 0
        internal_seg_d = 0
        internal_seg_o = 0
        tertiary_markers_d = 0
        tertiary_markers_o = 0
        tertiary_finish_aux_d = 0
        tertiary_finish_aux_o = 0

        v109b_camera = build_v109b_anime_shot_camera_match(settings)
        log(f"V10.9B2 Narrative Framing Balance: built={v109b_camera} lens={settings.lens_mm_v109b:.1f}mm headroom={settings.headroom_v109b:.2f} lead={settings.lead_room_v109b:.2f} distanceBias={settings.distance_bias_v109b:.2f} duo={settings.duo_bias_v109b1:.2f} char={settings.character_balance_v109b2:.2f} guitar={settings.guitar_framing_weight_v109b2:.2f} dof={settings.enable_dof_v109b}")

        calibration = build_v95_calibration_system(settings)
        if calibration is None:
            v91 = build_v91_system(settings)
            cal_msg = "OFF"
        else:
            # Stable aggregate structure for the existing summary/logging.
            v91 = {
                'tertiary': calibration['tertiary'],
                'face': calibration['face'],
                'composite': 0,
                'v92': {'art': calibration['shadow'], 'lines': calibration['lines'], 'face': calibration['face'], 'tertiary_parent': 0},
                'v93': {'tertiary': calibration['tertiary'], 'hair': calibration['hair']},
                'v94': {'performance': calibration['face'], 'expressions': calibration['face'], 'deformation': 0, 'tertiary': calibration['tertiary'], 'lines': calibration['lines']},
            }
            cal_msg = (f"ON face={calibration['face']} hair={calibration['hair']} "
                       f"shadow={calibration['shadow']} lines={calibration['lines']} tertiary={calibration['tertiary']}")

        # V10.9C1.1: geometric proportion pass. Runs after the legacy
        # face-angle/performance keys exist, but before face/hair shading and
        # before Safe Silhouette, so the approved B3.12 outline follows it.
        v109c11 = build_v109c11_facial_proportion_eye_match(settings)
        log(f"V10.9C1.1 Facial Proportion / Eye Match: objects={v109c11['objects']} keys={v109c11['keys']} zeroed={v109c11['zeroed']} D-eye={settings.doloris_eye_compact_v109c11:.2f} D-face={settings.doloris_face_taper_v109c11:.2f} D-mask={settings.doloris_mask_compact_v109c11:.2f} D-fringe={settings.doloris_fringe_compact_v109c11:.2f} O-eye={settings.oblivionis_eye_compact_v109c11:.2f} O-face={settings.oblivionis_face_taper_v109c11:.2f} O-mask={settings.oblivionis_mask_compact_v109c11:.2f} O-fringe={settings.oblivionis_fringe_compact_v109c11:.2f}")

        # V10.9C1.2: final micro-refinement. Still before shading/Safe Silhouette.
        v109c12 = build_v109c12_facial_refinement_fringe_match(settings)
        log(f"V10.9C1.2 Facial Refinement / Fringe Match: objects={v109c12['objects']} keys={v109c12['keys']} zeroed={v109c12['zeroed']} D-eye={settings.doloris_eye_refine_v109c12:.2f} D-face={settings.doloris_face_refine_v109c12:.2f} D-mask={settings.doloris_mask_refine_v109c12:.2f} D-fringe={settings.doloris_fringe_match_v109c12:.2f} O-eye={settings.oblivionis_eye_refine_v109c12:.2f} O-face={settings.oblivionis_face_refine_v109c12:.2f} O-mask={settings.oblivionis_mask_refine_v109c12:.2f} O-fringe={settings.oblivionis_fringe_match_v109c12:.2f}")

        # V9.7: designed face shadow is a visual-only non-image stage.
        face_shadow = 0
        if settings.build_face_shadow_design and (not settings.calibration_mode or settings.calibration_face):
            face_shadow = build_v96_face_shadow_system(settings)
        log(f"V9.6 Face Shadow: count={face_shadow} strength={bpy.context.scene.get('AEF_V9_6_FaceShadowStrength', settings.face_shadow_strength):.2f}")

        hair_toon = build_v97_hair_toon_system(settings) if getattr(settings, 'build_hair_toon_design', True) and (not settings.calibration_mode or settings.calibration_hair) else 0
        log(f"V9.7 Hair Toon: count={hair_toon} toon={bpy.context.scene.get('AEF_V9_7_HairToonStrength', settings.hair_toon_strength):.2f} hi={bpy.context.scene.get('AEF_V9_7_HairHighlightStrength', settings.hair_highlight_strength):.2f}")
        log(f"V10.8A Face/Hair Series Match: enabled={settings.build_series_match_v108a} face={settings.face_series_match_strength:.2f} hair={settings.hair_series_match_strength:.2f} profile={settings.shot_profile}")
        log(f"V10.8A1 Character MicroTune: enabled={settings.build_character_micro_tune_v108a1} doloris_face={settings.doloris_face_soften_v108a1:.2f} oblivionis_hair={settings.oblivionis_hair_ribbon_v108a1:.2f}")
        log(f"V10.8B Face/Hair Graphic Separation: enabled={settings.build_graphic_separation_v108b} face={settings.face_graphic_separation_strength_v108b:.2f} hair={settings.hair_graphic_separation_strength_v108b:.2f}")
