class AEF_OT_outline_pipeline_audit_v109b31(bpy.types.Operator):
    bl_idname = "aef.outline_pipeline_audit_v109b31"
    bl_label = "Run Outline Audit Now"
    bl_description = "Compare the current locked-reference outline pipeline without applying fixes"
    bl_options = {'REGISTER'}

    def execute(self, context):
        settings = context.scene.aef_sabershader_v8
        try:
            result = _aef109b31_outline_pipeline_audit(settings, write_disk=True)
            warnings = len(result.get('warnings', []))
            path = result.get('path')
            where = path.name if path else result.get('text_name', AEF109B31_AUDIT_TEXT)
            self.report({'WARNING'} if warnings else {'INFO'}, f"Outline audit: {warnings} warnings | {where}")
            return {'FINISHED'}
        except Exception as exc:
            log(f"V10.9B3.1 Outline Audit ERROR: {exc}")
            self.report({'ERROR'}, f"Outline audit failed: {exc}")
            return {'CANCELLED'}


class AEF_OT_uma_texture_library_audit_v11932(bpy.types.Operator):
    bl_idname = 'aef.uma_texture_library_audit_v11932'
    bl_label = 'Audit UMA Textures'
    bl_description = 'Read-only UMA audit of current .blend packed/images, an external folder, or both; never unpacks or modifies source assets'
    bl_options = {'REGISTER'}

    audit_source: bpy.props.EnumProperty(
        name='Audit Source',
        items=(
            ('CURRENT_BLEND', 'Current .blend', 'Audit Image datablocks and material bindings in the currently open .blend'),
            ('EXTERNAL_FOLDER', 'External Folder', 'Audit an external UMA texture folder recursively'),
            ('BLEND_AND_FOLDER', 'Current .blend + Folder', 'Audit both and cross-check texture names'),
        ),
        default='CURRENT_BLEND',
    )

    def execute(self, context):
        settings = context.scene.aef_sabershader_v8
        source_mode = str(self.audit_source or 'CURRENT_BLEND')
        raw_folder = str(settings.uma_texture_library_folder or settings.universal_texture_folder or '').strip()
        root = None
        if source_mode in {'EXTERNAL_FOLDER', 'BLEND_AND_FOLDER'}:
            if not raw_folder:
                self.report({'WARNING'}, 'Choose an UMA Texture Library folder for Folder or Blend + Folder audit')
                return {'CANCELLED'}
            try:
                root = Path(bpy.path.abspath(raw_folder)).expanduser().resolve()
            except Exception:
                root = Path(bpy.path.abspath(raw_folder)).expanduser()
            if not root.exists() or not root.is_dir():
                self.report({'ERROR'}, f'UMA Texture Library folder not found: {root}')
                return {'CANCELLED'}

        scene = context.scene
        previous_source = str(scene.get('SaberShader_V11932_UMAAuditSource', '') or '')
        previous_fingerprint = str(scene.get('SaberShader_V11932_UMAAuditFingerprint', '') or '')
        previous_textures = int(scene.get('SaberShader_V11932_UMAAuditTextures', 0) or 0)
        previous_characters = int(scene.get('SaberShader_V11932_UMAAuditCharacters', 0) or 0)
        previous_patterns = int(scene.get('SaberShader_V11932_UMAAuditPatterns', 0) or 0)

        wm = context.window_manager
        try:
            wm.progress_begin(0, 1000)
        except Exception:
            pass

        def progress(done, total):
            try:
                factor = min(1.0, max(0.0, float(done) / max(1.0, float(total))))
                wm.progress_update(int(factor * 1000.0))
            except Exception:
                pass

        try:
            reports = []
            if source_mode in {'CURRENT_BLEND', 'BLEND_AND_FOLDER'}:
                reports.append(_xdzr8_v11932_audit_current_blend(progress_callback=progress))
            if source_mode in {'EXTERNAL_FOLDER', 'BLEND_AND_FOLDER'}:
                folder_report = _xdzr8_v11932_audit_uma_texture_library(root, progress_callback=progress)
                reports.append(_xdzr8_v11932_prepare_folder_audit_report(folder_report))
            report = _xdzr8_v11932_merge_audit_reports(reports, source_mode)
        except Exception as exc:
            self.report({'ERROR'}, f'UMA texture audit failed: {exc}')
            return {'CANCELLED'}
        finally:
            try:
                wm.progress_end()
            except Exception:
                pass

        current_fingerprint = str(report.get('fingerprint_sha256', '') or '')
        current_textures = int(report.get('texture_entries_scanned', report.get('texture_files_scanned', 0)) or 0)
        current_characters = int(report.get('characters_detected', 0) or 0)
        current_patterns = int(report.get('patterns_detected', 0) or 0)
        same_source = bool(previous_fingerprint and previous_source == source_mode)
        comparison = {
            'previous_source': previous_source,
            'previous_fingerprint': previous_fingerprint if same_source else '',
            'catalogue_changed': bool(same_source and previous_fingerprint != current_fingerprint),
            'first_audit': not same_source,
            'reset_reason': '' if same_source else ('SOURCE_MODE_CHANGED' if previous_fingerprint else 'FIRST_AUDIT'),
            'texture_delta': current_textures - previous_textures if same_source else 0,
            'character_delta': current_characters - previous_characters if same_source else 0,
            'pattern_delta': current_patterns - previous_patterns if same_source else 0,
        }
        report['comparison'] = comparison

        json_content = json.dumps(report, indent=2, ensure_ascii=False, sort_keys=False)
        txt_content = _xdzr8_v11932_audit_text_report(report)
        txt_block = _xdzr8_v11932_write_text_datablock('SaberShader_UMA_Texture_Audit.txt', txt_content)
        _xdzr8_v11932_write_text_datablock('SaberShader_UMA_Texture_Audit.json', json_content)

        report_txt_path = ''
        report_json_path = ''
        disk_error = ''
        if bool(settings.uma_texture_audit_write_disk_reports):
            try:
                configured = str(settings.uma_texture_audit_report_folder or '').strip()
                if configured:
                    out_dir = Path(bpy.path.abspath(configured)).expanduser()
                elif str(bpy.data.filepath or '').strip():
                    out_dir = Path(bpy.data.filepath).resolve().parent / 'SaberShader_Audits'
                else:
                    fallback = str(bpy.app.tempdir or (str(root) if root is not None else os.getcwd()))
                    out_dir = Path(fallback) / 'SaberShader_Audits'
                out_dir.mkdir(parents=True, exist_ok=True)
                txt_path = out_dir / 'SaberShader_UMA_Texture_Audit.txt'
                json_path = out_dir / 'SaberShader_UMA_Texture_Audit.json'
                txt_path.write_text(txt_content, encoding='utf-8')
                json_path.write_text(json_content, encoding='utf-8')
                report_txt_path = str(txt_path)
                report_json_path = str(json_path)
            except Exception as exc:
                disk_error = str(exc)

        counts = report.get('counts') or {}
        blend_stats = report.get('blend_stats') or {}
        cross = report.get('cross_source') or {}
        scene['SaberShader_V11932_UMAAuditSource'] = source_mode
        scene['SaberShader_V11932_UMAAuditRoot'] = str(report.get('root', ''))
        scene['SaberShader_V11932_UMAAuditFingerprint'] = current_fingerprint
        scene['SaberShader_V11932_UMAAuditTextures'] = current_textures
        scene['SaberShader_V11932_UMAAuditKnown'] = int(counts.get('KNOWN', 0))
        scene['SaberShader_V11932_UMAAuditPartial'] = int(counts.get('PARTIAL', 0))
        scene['SaberShader_V11932_UMAAuditUnknown'] = int(counts.get('UNKNOWN', 0))
        scene['SaberShader_V11932_UMAAuditAmbiguous'] = int(counts.get('AMBIGUOUS', 0))
        scene['SaberShader_V11932_UMAAuditIgnored'] = int(counts.get('IGNORED', 0))
        scene['SaberShader_V11932_UMAAuditCharacters'] = current_characters
        scene['SaberShader_V11932_UMAAuditPatterns'] = current_patterns
        scene['SaberShader_V11932_UMAAuditBlendImages'] = int(report.get('blend_images_scanned', 0))
        scene['SaberShader_V11932_UMAAuditFolderFiles'] = int(report.get('folder_texture_files_scanned', 0))
        scene['SaberShader_V11932_UMAAuditPackedImages'] = int(blend_stats.get('packed', 0))
        scene['SaberShader_V11932_UMAAuditUsedByModel'] = int(blend_stats.get('used_by_model', 0))
        scene['SaberShader_V11932_UMAAuditMaterialBindings'] = int(blend_stats.get('material_bindings', 0))
        scene['SaberShader_V11932_UMAAuditPresentBoth'] = int(cross.get('present_in_both_count', 0))
        scene['SaberShader_V11932_UMAAuditOnlyBlend'] = int(cross.get('only_in_blend_count', 0))
        scene['SaberShader_V11932_UMAAuditOnlyFolder'] = int(cross.get('only_in_folder_count', 0))
        scene['SaberShader_V11932_UMAAuditTextureDelta'] = int(comparison.get('texture_delta', 0))
        scene['SaberShader_V11932_UMAAuditCharacterDelta'] = int(comparison.get('character_delta', 0))
        scene['SaberShader_V11932_UMAAuditPatternDelta'] = int(comparison.get('pattern_delta', 0))
        scene['SaberShader_V11932_UMAAuditCatalogueChanged'] = bool(comparison.get('catalogue_changed', False))
        scene['SaberShader_V11932_UMAAuditFirstRun'] = bool(comparison.get('first_audit', False))
        scene['SaberShader_V11932_UMAAuditTextBlock'] = txt_block.name
        scene['SaberShader_V11932_UMAAuditTXTPath'] = report_txt_path
        scene['SaberShader_V11932_UMAAuditJSONPath'] = report_json_path
        scene['SaberShader_V11932_UMAAuditDiskError'] = disk_error
        scene['SaberShader_V11932_UMAAuditIDDrivesRoles'] = False
        scene['SaberShader_V11932_UMAAuditAssetsModified'] = False
        scene['SaberShader_V11932_UMAAuditImagesUnpacked'] = False
        scene['SaberShader_V11932_UMAAuditPixelsRead'] = False

        log(
            f'V11.9.3.2 UMA Texture Library & Packed Blend Audit: source={source_mode} entries={current_textures} '
            f'blendImages={report.get("blend_images_scanned",0)} packed={blend_stats.get("packed",0)} folderFiles={report.get("folder_texture_files_scanned",0)} '
            f'known={counts.get("KNOWN",0)} partial={counts.get("PARTIAL",0)} unknown={counts.get("UNKNOWN",0)} ambiguous={counts.get("AMBIGUOUS",0)} '
            f'characters={current_characters} patterns={current_patterns} bindings={blend_stats.get("material_bindings",0)} '
            f'fingerprint={current_fingerprint[:16]} changed={comparison.get("catalogue_changed",False)} '
            f'roleAuthority=STRUCTURE_NOT_ID unpacked=False pixelsRead=False assetsModified=False'
        )
        if disk_error:
            self.report({'WARNING'}, f'Audit complete; disk export failed ({disk_error}). Reports remain in Blender Text Editor.')
        else:
            self.report({'INFO'}, f'UMA audit complete: {current_textures} entries, {blend_stats.get("packed",0)} packed, {counts.get("UNKNOWN",0)} unknown')
        return {'FINISHED'}


class AEF_OT_uma_texture_library_open_report_v11932(bpy.types.Operator):
    bl_idname = 'aef.uma_texture_library_open_report_v11932'
    bl_label = 'Open Last UMA Audit Report'
    bl_description = 'Open the last UMA Texture Library TXT report in Blender Text Editor'

    def execute(self, context):
        name = str(context.scene.get('SaberShader_V11932_UMAAuditTextBlock', 'SaberShader_UMA_Texture_Audit.txt'))
        text_block = bpy.data.texts.get(name)
        if text_block is None:
            self.report({'WARNING'}, 'No UMA Texture Library audit report exists yet')
            return {'CANCELLED'}
        area = context.area
        if area is None:
            self.report({'WARNING'}, f'Report is available in Text Editor as {text_block.name}')
            return {'CANCELLED'}
        try:
            area.type = 'TEXT_EDITOR'
            area.spaces.active.text = text_block
        except Exception:
            self.report({'WARNING'}, f'Report is available in Text Editor as {text_block.name}')
            return {'CANCELLED'}
        return {'FINISHED'}


class AEF_OT_sabershader_save_copy_v8(bpy.types.Operator):
    bl_idname = "aef.sabershader_save_copy_v8"
    bl_label = "Save Copy Now"
    bl_description = "Save XDZR8_Sabershader_V11_9_Universal_Target_NPR_Core.blend next to the current .blend"
    bl_options = {'REGISTER'}

    @classmethod
    def poll(cls, context):
        return bool(bpy.data.filepath)

    def execute(self, context):
        out = save_copy()
        if out:
            self.report({'INFO'}, f"Copy saved: {out.name}")
